function Get-MyDeviceCacheEntry {
param([string]$Section)
if (-not $script:MyDeviceCache -or -not $script:MyDeviceCache.ContainsKey($Section)) { return $null }
$entry = $script:MyDeviceCache[$Section]
if (-not $entry -or -not $entry.Timestamp) { return $null }
if (((Get-Date) - $entry.Timestamp).TotalSeconds -gt $script:MyDeviceCacheTtlSeconds) { return $null }
return $entry.Data
}

function Set-MyDeviceCacheEntry {
param([string]$Section, $Data)
if (-not $script:MyDeviceCache) { $script:MyDeviceCache = @{} }
$script:MyDeviceCache[$Section] = [pscustomobject]@{ Timestamp = Get-Date; Data = $Data }
}

function New-MyDeviceTextBlock {
param(
    [string]$Text,
    [int]$FontSize = 13,
    [string]$Foreground = "TextSecondary",
    [string]$FontWeight = "Normal",
    [double]$MarginTop = 0
)
$tb = New-Object System.Windows.Controls.TextBlock
$tb.Text = $Text
$tb.FontSize = $FontSize
Set-WmtThemedBrush -Object $tb -Property ([System.Windows.Controls.TextBlock]::ForegroundProperty) -ColorOrKey $Foreground
$tb.TextWrapping = [System.Windows.TextWrapping]::Wrap
$tb.LineHeight = 18
if ($FontWeight -ne "Normal") {
    switch ($FontWeight) {
        "SemiBold" { $tb.FontWeight = [System.Windows.FontWeights]::SemiBold }
        "Bold" { $tb.FontWeight = [System.Windows.FontWeights]::Bold }
        default { $tb.FontWeight = [System.Windows.FontWeights]::Normal }
    }
}
if ($MarginTop -gt 0) { $tb.Margin = [System.Windows.Thickness]::new(0, $MarginTop, 0, 0) }
return $tb
}

function Get-GpuVendorFromTextBlock {
param([string]$GpuText)
if ($GpuText -match '(?im)^\s*Vendor:\s*(NVIDIA|AMD|Intel)\s*$') { return $matches[1] }
if ($GpuText -match '(?i)nvidia|ven_10de') { return "NVIDIA" }
if ($GpuText -match '(?i)amd|radeon|advanced micro devices|ven_1002') { return "AMD" }
if ($GpuText -match '(?i)intel|iris|arc|uhd graphics|ven_8086') { return "Intel" }
return "Unknown"
}

function Set-MyDeviceGpuCardsPlaceholder {
param([string]$Text)
$panel = Get-Ctrl "pnlDeviceGPUList"
if (-not $panel) { return }
$panel.Children.Clear()
[void]$panel.Children.Add((New-MyDeviceTextBlock -Text $Text))
}

function Set-MyDeviceGpuCards {
param([string]$GpuText)

$panel = Get-Ctrl "pnlDeviceGPUList"
if (-not $panel) { return }
$panel.Children.Clear()

if ([string]::IsNullOrWhiteSpace($GpuText)) {
    [void]$panel.Children.Add((New-MyDeviceTextBlock -Text "Unavailable"))
    return
}

$blocks = @($GpuText -split "(`r?`n){2,}" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
if ($blocks.Count -eq 0) { $blocks = @($GpuText) }

$index = 1
foreach ($block in $blocks) {
    $vendor = Get-GpuVendorFromTextBlock -GpuText $block
    $lines = @($block -split "`r?`n" | Where-Object { $_ -ne $null })
    $title = if ($lines.Count -gt 0 -and -not [string]::IsNullOrWhiteSpace($lines[0])) { [string]$lines[0] } else { "GPU $index" }
    $details = if ($lines.Count -gt 1) { ($lines[1..($lines.Count - 1)] -join "`n") } else { "Vendor: $vendor" }

    $card = New-Object System.Windows.Controls.Border
    Set-WmtThemedBrush -Object $card -Property ([System.Windows.Controls.Border]::BackgroundProperty) -ColorOrKey "BgPanel"
    Set-WmtThemedBrush -Object $card -Property ([System.Windows.Controls.Border]::BorderBrushProperty) -ColorOrKey "BorderBrush"
    $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $card.Padding = [System.Windows.Thickness]::new(10)
    $card.Margin = if ($index -eq 1) { [System.Windows.Thickness]::new(0, 0, 0, 8) } else { [System.Windows.Thickness]::new(0, 4, 0, 8) }
    $card.Cursor = [System.Windows.Input.Cursors]::Hand
    $card.Tag = $vendor
    $card.ToolTip = if ($vendor -eq "Unknown") { "No known GPU vendor detected for this adapter." } else { "Open $vendor control panel for this GPU." }

    $stack = New-Object System.Windows.Controls.StackPanel
    [void]$stack.Children.Add((New-MyDeviceTextBlock -Text $title -FontSize 13 -Foreground "TextPrimary" -FontWeight "SemiBold"))
    [void]$stack.Children.Add((New-MyDeviceTextBlock -Text $details -FontSize 12 -Foreground "TextSecondary" -MarginTop 3))
    $card.Child = $stack

    $card.Add_MouseLeftButtonUp({
            param($s, $e)
            $selectedVendor = [string]$s.Tag
            if ([string]::IsNullOrWhiteSpace($selectedVendor) -or $selectedVendor -eq "Unknown") {
                Write-GuiLog "No known GPU vendor detected for the clicked GPU entry."
            }
            else {
                Open-GpuVendorControlPanel -Vendors @($selectedVendor)
            }
            $e.Handled = $true
        })

    [void]$panel.Children.Add($card)
    $index++
}
}

function Set-MyDeviceSectionData {
param($Data)
if ($Data -is [System.Collections.ObjectModel.Collection[PSObject]]) { $Data = $Data[0] }
if (-not $Data) { return }
switch ([string]$Data.Section) {
    "Core" {
        if ($Data.OS) { (Get-Ctrl "txtDeviceOS").Text = $Data.OS }
        if ($Data.CPU) { (Get-Ctrl "txtDeviceCPU").Text = $Data.CPU }
        if ($Data.RAM) { (Get-Ctrl "txtDeviceRAM").Text = $Data.RAM }
        Start-MyDeviceBitLockerStatusUpdate
    }
    "GPU" { if ($Data.GPU) { Set-MyDeviceGpuCards -GpuText $Data.GPU } }
    "Motherboard" { if ($Data.MB) { (Get-Ctrl "txtDeviceMotherboard").Text = $Data.MB } }
    "Storage" {
        if ($Data.Storage) { (Get-Ctrl "txtDeviceStorage").Text = $Data.Storage }
        Set-MyDeviceStorageDetails -Devices $Data.StorageDevices
    }
    "Network" {
        if ($Data.Network) { (Get-Ctrl "txtDeviceNetwork").Text = $Data.Network }
        Set-MyDeviceNetworkDetails -Adapters $Data.NetworkAdapters
    }
    "Power" {
        (Get-Ctrl "txtBatteryHealth").Text = "Health: $($Data.BatteryHealth)"
        (Get-Ctrl "txtBatteryCharge").Text = "Charge: $($Data.BatteryCharge)"
        (Get-Ctrl "txtBatteryStatus").Text = "Status: $($Data.BatteryStatus)"
        (Get-Ctrl "txtPowerPlan").Text = "Power: $($Data.PowerPlan)"
        $batteryTimeText = [string]$Data.BatteryTime
        $batteryTimeCtrl = Get-Ctrl "txtBatteryTime"
        if ($batteryTimeCtrl) {
            if ([string]::IsNullOrWhiteSpace($batteryTimeText)) { $batteryTimeCtrl.Text = ""; $batteryTimeCtrl.Visibility = "Collapsed" }
            else { $batteryTimeCtrl.Text = "Time Remaining: $batteryTimeText"; $batteryTimeCtrl.Visibility = "Visible" }
        }
        (Get-Ctrl "txtPowerDraw").Text = "Power Draw: $($Data.PowerDraw)"
        (Get-Ctrl "txtPowerTotal").Text = "Total Power: $($Data.PowerTotal)"
        (Get-Ctrl "txtPowerElectrical").Text = "Electrical: $($Data.PowerElectrical)"
    }
}
}

function Stop-MyDeviceSectionJobs {
if ($script:StatsTimer) { try { $script:StatsTimer.Stop() } catch {} }
if ($script:MyDevicePendingSections) {
    try { $script:MyDevicePendingSections.Clear() } catch {}
}

$sectionJobs = @()
if ($script:MyDeviceSectionJobs) {
    $sectionJobs = @($script:MyDeviceSectionJobs.Values)
    try { $script:MyDeviceSectionJobs.Clear() } catch {}
}
foreach ($job in $sectionJobs) {
    if (-not $job -or -not $job.PowerShell) { continue }
    $jobName = if ($job.PSObject.Properties["Name"] -and $job.Name) { [string]$job.Name } else { "section" }
    try {
        Stop-WmtPowerShellInvocationAsync -PowerShell $job.PowerShell -Invocation $job.Async -Name "My Device $jobName refresh"
    }
    catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $job.PowerShell -Invocation $job.Async -Name "My Device $jobName refresh" } catch {}
    }
}

$oldStatsRunspace = $script:StatsRunspace
$script:StatsRunspace = $null
if ($oldStatsRunspace) {
    try {
        Stop-WmtPowerShellInvocationAsync -PowerShell $oldStatsRunspace -Invocation $null -Name "My Device legacy stats refresh"
    }
    catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $oldStatsRunspace -Invocation $null -Name "My Device legacy stats refresh" } catch {}
    }
}
}

function Start-MyDeviceQueuedSections {
if (-not $script:MyDevicePendingSections -or $script:MyDevicePendingSections.Count -eq 0) { return }

if (-not $script:MyDeviceStatsMaxConcurrent -or $script:MyDeviceStatsMaxConcurrent -lt 1) {
    $script:MyDeviceStatsMaxConcurrent = 4
}

while ($script:MyDeviceSectionJobs.Count -lt $script:MyDeviceStatsMaxConcurrent -and $script:MyDevicePendingSections.Count -gt 0) {
    $section = $script:MyDevicePendingSections[0]
    $script:MyDevicePendingSections.RemoveAt(0)
    Start-MyDeviceSectionJob -Name $section.Name -Body $section.Body
}
}

# ============================================================================
# Safe type-conversion helpers (used by My Device runspaces, tweaks, etc.)
# Must be defined BEFORE Initialize-WmtBackgroundRunspacePool so the
# pre-load check (Get-Command) succeeds when populating the runspace.
# ============================================================================
function ConvertTo-Int {
param($Value, [int]$Default = 0)
try {
    if ($null -eq $Value -or "" -eq $Value) { return $Default }
    return [int]$Value
}
catch { return $Default }
}

function ConvertTo-Str {
param($Value, [string]$Default = "")
try {
    if ($null -eq $Value) { return $Default }
    return [string]$Value
}
catch { return $Default }
}

# ============================================================================
# Safe external CLI text capture (OEM-encoding aware for non-English systems)
# PowerShell 5.1 misinterprets external CLI encoding in WPF contexts, causing
# accented characters (e.g. ì, à, è) to be garbled.  This helper uses
# System.Diagnostics.Process with explicit OEM encoding to avoid that.
# ============================================================================
function Invoke-WmtProcess {
param(
    [Parameter(Mandatory = $true)][string]$FilePath,
    [string]$Arguments = "",
    [int]$TimeoutMs = 60000,
    [ValidateSet("OEM", "UTF8", "Unicode", "Default")][string]$Encoding = "OEM",
    [bool]$CreateNoWindow = $true,
    [switch]$KillTree
)
$result = [PSCustomObject]@{
    ExitCode           = -1
    StdOut             = ""
    StdErr             = ""
    Combined           = ""
    TimedOut           = $false
    TerminationFailed  = $false
    OutputReadTimedOut = $false
    ProcessId          = 0
    Error              = ""
}
$proc = $null
try {
    $textEncoding = switch ($Encoding) {
        "UTF8"    { [System.Text.UTF8Encoding]::new($false) }
        "Unicode" { [System.Text.Encoding]::Unicode }
        "Default" { [System.Text.Encoding]::Default }
        default   { [System.Text.Encoding]::GetEncoding([System.Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage) }
    }
    $psi = [System.Diagnostics.ProcessStartInfo]::new()
    $psi.FileName = $FilePath
    $psi.Arguments = $Arguments
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $CreateNoWindow
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    try { $psi.StandardOutputEncoding = $textEncoding } catch {}
    try { $psi.StandardErrorEncoding = $textEncoding } catch {}
    $proc = [System.Diagnostics.Process]::new()
    $proc.StartInfo = $psi
    if (-not $proc.Start()) { throw "Process failed to start." }
    $result.ProcessId = $proc.Id
    $stdoutTask = $proc.StandardOutput.ReadToEndAsync()
    $stderrTask = $proc.StandardError.ReadToEndAsync()
    $exited = [bool]$proc.WaitForExit([Math]::Max(1, $TimeoutMs))
    if (-not $exited) {
        $result.TimedOut = $true
        if ($KillTree) {
            # taskkill itself can hang; a synchronous Start-Process -Wait is not safe here.
            $killProcess = $null
            try {
                $taskkill = Join-Path $env:SystemRoot "System32\taskkill.exe"
                if (Test-Path -LiteralPath $taskkill -PathType Leaf) {
                    $killProcess = Start-Process -FilePath $taskkill -ArgumentList @("/PID", "$($proc.Id)", "/T", "/F") -WindowStyle Hidden -PassThru -ErrorAction Stop
                    if ($killProcess -and -not $killProcess.WaitForExit(5000)) {
                        try { $killProcess.Kill() } catch {}
                    }
                }
            }
            catch {}
            finally { try { if ($killProcess) { $killProcess.Dispose() } } catch {} }
        }
        # Also try the root when tree termination failed or is still in progress.
        try { if (-not $proc.HasExited) { $proc.Kill() } } catch {}
        try { $exited = [bool]$proc.WaitForExit(2000) } catch { $exited = $false }
        if (-not $exited) { try { $exited = [bool]$proc.HasExited } catch {} }
        if (-not $exited) {
            $result.TerminationFailed = $true
            $result.Error = "Process timed out and termination could not be verified."
            return $result
        }
    }
    # Descendants may hold redirected handles open after the process exits.
    $readCompleted = $false
    try {
        $readCompleted = [System.Threading.Tasks.Task]::WaitAll(
            [System.Threading.Tasks.Task[]]@($stdoutTask, $stderrTask), 3000)
    }
    catch { $result.Error = "Failed reading process output: $($_.Exception.Message)" }
    if ($stdoutTask.IsCompleted -and -not $stdoutTask.IsFaulted -and -not $stdoutTask.IsCanceled) {
        try { $result.StdOut = [string]$stdoutTask.Result } catch {}
    }
    if ($stderrTask.IsCompleted -and -not $stderrTask.IsFaulted -and -not $stderrTask.IsCanceled) {
        try { $result.StdErr = [string]$stderrTask.Result } catch {}
    }
    $result.Combined = "$($result.StdOut)$($result.StdErr)"
    if (-not $readCompleted) {
        $result.OutputReadTimedOut = $true
        if ($result.TimedOut) { $result.TerminationFailed = $true }
        if ([string]::IsNullOrWhiteSpace($result.Error)) {
            $result.Error = "Process output did not finish within 3 seconds of exit; a child may still hold the pipe."
        }
        return $result
    }
    try { $result.ExitCode = [int]$proc.ExitCode } catch {}
}
catch { $result.Error = $_.Exception.Message }
finally { if ($proc) { try { $proc.Dispose() } catch {} } }
return $result
}
function Invoke-WmtCliText {
param(
    [Parameter(Mandatory = $true)][string]$FilePath,
    [string]$Arguments = "",
    [int]$TimeoutMs = 60000,
    [ValidateSet("OEM", "UTF8", "Unicode", "Default")][string]$Encoding = "OEM"
)
try {
    $result = Invoke-WmtProcess -FilePath $FilePath -Arguments $Arguments -TimeoutMs $TimeoutMs -Encoding $Encoding -KillTree
    $global:LASTEXITCODE = [int]$result.ExitCode
    if (-not [string]::IsNullOrEmpty([string]$result.Combined)) { return ([string]$result.Combined).TrimEnd() }
    return ""
}
catch { return "" }
}

function Get-WmtLegendaryCachedLibrary {
param([bool]$IncludeUe = $false)

$result = [PSCustomObject]@{ Json = ""; Count = 0; MissingTitles = 0; Error = "" }
# Use the same config precedence as Legendary; do not merge another account's
# Heroic/legacy cache into the active account's library.
$configRoot = if (-not [string]::IsNullOrWhiteSpace($env:LEGENDARY_CONFIG_PATH)) { $env:LEGENDARY_CONFIG_PATH }
elseif (-not [string]::IsNullOrWhiteSpace($env:XDG_CONFIG_HOME)) { Join-Path $env:XDG_CONFIG_HOME "legendary" }
else { Join-Path ([string]$env:USERPROFILE) ".config\legendary" }

try {
    $assetsPath = Join-Path $configRoot "assets.json"
    if (-not (Test-Path -LiteralPath $assetsPath -PathType Leaf)) { return $result }
    $assets = [System.IO.File]::ReadAllText($assetsPath) | ConvertFrom-Json -ErrorAction Stop
    $windowsAssets = $assets.Windows
    if (-not $windowsAssets) { return $result }
    if ($windowsAssets -is [System.Management.Automation.PSCustomObject]) {
        $windowsAssets = @($windowsAssets.PSObject.Properties | ForEach-Object { $_.Value })
    }

    $metadataByApp = @{}
    $metadataByCatalog = @{}
    $metadataRoot = Join-Path $configRoot "metadata"
    if (Test-Path -LiteralPath $metadataRoot -PathType Container) {
        $badMetadata = 0
        foreach ($file in Get-ChildItem -LiteralPath $metadataRoot -Filter "*.json" -File -ErrorAction Stop) {
            try {
                $game = [System.IO.File]::ReadAllText($file.FullName) | ConvertFrom-Json -ErrorAction Stop
                $appName = ([string]$game.app_name).Trim()
                if ($appName) { $metadataByApp[$appName] = $game }
                $catalogId = ([string]$game.metadata.id).Trim()
                if ($catalogId) { $metadataByCatalog[([string]$game.metadata.namespace + ':' + $catalogId)] = $game }
            }
            catch { $badMetadata++ }
        }
        if ($badMetadata) { $result.Error = "Skipped $badMetadata unreadable Legendary metadata file(s)." }
    }

    $rows = [System.Collections.Generic.List[object]]::new()
    $seen = @{}
    foreach ($asset in $windowsAssets) {
        $appName = ([string]$asset.app_name).Trim()
        if (-not $appName -or $seen.ContainsKey($appName)) { continue }
        $seen[$appName] = $true
        $game = $metadataByApp[$appName]
        if (-not $game) { $game = $metadataByCatalog[([string]$asset.namespace + ':' + [string]$asset.catalog_item_id)] }
        # New Fab assets can have a different namespace but still carry the
        # Unreal UserContent build marker. Retain the tag in the fallback JSON.
        $isUe = ([string]$asset.namespace -eq 'ue' -or [string]$asset.build_version -match '(?i)\+UE\d+-UserContent')
        if (-not $IncludeUe -and $isUe) { continue }
        # Match Legendary's top-level game list; DLC remains part of its parent.
        if ($game -and $game.metadata.mainGameItem) { continue }
        $title = ([string]$game.app_title).Trim()
        if (-not $title) { $title = ([string]$game.metadata.title).Trim() }
        if (-not $title) { $title = $appName; $result.MissingTitles++ }
        [void]$rows.Add([PSCustomObject]@{
            app_name = $appName; app_title = $title; app_version = [string]$asset.build_version
            is_ue = $isUe; metadata = @{ namespace = [string]$asset.namespace }
        })
    }
    $result.Count = $rows.Count
    if ($rows.Count) { $result.Json = ConvertTo-Json -InputObject $rows.ToArray() -Depth 4 -Compress }
}
catch { $result.Error = "Legendary local catalog read failed: $($_.Exception.Message)" }
return $result
}

function Merge-WmtLegendaryCachedDetails {
param([object[]]$Rows, [string]$CacheFile, [bool]$PreserveTitles, [bool]$PreserveInstalledState)

if (-not $PreserveTitles -and -not $PreserveInstalledState) { return }
if (-not (Test-Path -LiteralPath $CacheFile -PathType Leaf)) { return }
try {
    $previous = [System.IO.File]::ReadAllText($CacheFile) | ConvertFrom-Json -ErrorAction Stop
    $previousById = @{}
    foreach ($item in $previous) {
        if ($item -and -not [string]::IsNullOrWhiteSpace([string]$item.Id)) { $previousById[[string]$item.Id] = $item }
    }
    foreach ($row in $Rows) {
        $cached = $previousById[[string]$row.Id]
        if (-not $cached) { continue }
        if ($PreserveTitles -and $row.Title -eq $row.Id -and -not [string]::IsNullOrWhiteSpace([string]$cached.Title)) {
            $row.Title = [string]$cached.Title
        }
        if ($PreserveInstalledState) {
            foreach ($field in @('IsInstalled', 'InstalledVersion', 'InstallPath', 'Platform')) {
                if ($cached.PSObject.Properties[$field]) {
                    $row | Add-Member -MemberType NoteProperty -Name $field -Value $cached.$field -Force
                }
            }
        }
    }
}
catch { return "Legendary previous cache could not be merged: $($_.Exception.Message)" }
}

function Invoke-WmtLegendaryLibraryJson {
param(
    [Parameter(Mandatory = $true)][string]$LegendaryExe,
    [bool]$IncludeUe = $false,
    [bool]$ForceRefresh = $false,
    [int]$TimeoutMs = 30000
)

$result = [PSCustomObject]@{ ExitCode = -1; Json = ""; StdErr = ""; TimedOut = $false; Error = ""; OfflineFallback = $false; CachedCount = 0; MissingTitles = 0 }
if ([string]::IsNullOrWhiteSpace($LegendaryExe) -or -not (Test-Path -LiteralPath $LegendaryExe -PathType Leaf)) {
    $result.Error = "legendary executable was not found."
    return $result
}

$ueFlag = if ($IncludeUe) { " --include-ue" } else { "" }
$refreshFlag = if ($ForceRefresh) { " --force-refresh" } else { "" }
$arguments = "--api-timeout 30 list --json$ueFlag$refreshFlag"
$procResult = Invoke-WmtProcess -FilePath $LegendaryExe -Arguments $arguments -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree

# Legendary versions before 0.20.27 do not support --api-timeout.
if ($procResult.ExitCode -eq 2 -and ([string]$procResult.StdErr) -match '(?i)unrecognized arguments[^\r\n]*--api-timeout') {
    $arguments = "list --json$ueFlag$refreshFlag"
    $procResult = Invoke-WmtProcess -FilePath $LegendaryExe -Arguments $arguments -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree
}

$result.ExitCode = [int]$procResult.ExitCode
$result.Json = [string]$procResult.StdOut
$result.StdErr = [string]$procResult.StdErr
$result.TimedOut = [bool]$procResult.TimedOut
$result.Error = [string]$procResult.Error

$hasCatalog = $false
if ($result.ExitCode -eq 0 -and -not [string]::IsNullOrWhiteSpace($result.Json)) {
    try {
        $catalog = $result.Json | ConvertFrom-Json -ErrorAction Stop
        $hasCatalog = (@($catalog | Where-Object { $_ -and $_.app_name }).Count -gt 0)
    }
    catch { $result.Error = "Legendary library JSON parse failed: $($_.Exception.Message)" }
}
if (-not $hasCatalog) {
    # `list` always contacts Epic, even with --offline. Recover from its local
    # assets/metadata directly when the service fails or a large refresh expires.
    $cached = Get-WmtLegendaryCachedLibrary -IncludeUe:$IncludeUe
    if ($cached.Error) { $result.Error = (@($result.Error, $cached.Error) | Where-Object { $_ }) -join ' ' }
    if ($cached.Count -gt 0) {
        $result.Json = $cached.Json
        $result.OfflineFallback = $true
        $result.CachedCount = $cached.Count
        $result.MissingTitles = $cached.MissingTitles
    }
}
return $result
}

function Invoke-WmtLegendaryInstalledData {
param(
    [Parameter(Mandatory = $true)][string]$LegendaryExe,
    [bool]$CheckUpdates = $false,
    [int]$TimeoutMs = 30000
)

$result = [PSCustomObject]@{
    ExitCode = -1
    Rows = @()
    Json = ""
    Csv = ""
    StdErr = ""
    TimedOut = $false
    Error = ""
    OfflineFallback = $false
    SourceFormat = ""
}
if ([string]::IsNullOrWhiteSpace($LegendaryExe) -or -not (Test-Path -LiteralPath $LegendaryExe -PathType Leaf)) {
    $result.Error = "legendary executable was not found."
    return $result
}

function ConvertFrom-WmtLegendaryInstalledJsonRows {
param([string]$JsonText)
$rows = [System.Collections.Generic.List[object]]::new()
if ([string]::IsNullOrWhiteSpace($JsonText)) { return $rows.ToArray() }
$items = $JsonText | ConvertFrom-Json -ErrorAction Stop
foreach ($installedGame in @($items)) {
    if ($null -eq $installedGame) { continue }
    $installedId = ([string]$installedGame.app_name).Trim()
    if ([string]::IsNullOrWhiteSpace($installedId)) { continue }
    [void]$rows.Add([PSCustomObject]@{
            'App name'          = $installedId
            'App title'         = ([string]$installedGame.title).Trim()
            'Installed version' = ([string]$installedGame.version).Trim()
            'Available version' = ""
            'Update available'  = $false
            'Install size'      = [string]$installedGame.install_size
            'Install path'      = ([string]$installedGame.install_path).Trim()
            'Platform'          = ([string]$installedGame.platform).Trim()
        })
}
return $rows.ToArray()
}

# For library/install-state discovery, JSON is the authoritative local source.
# Legendary's CSV path joins each installed row to cached asset metadata and
# omits games whose asset entry is missing; JSON emits vars(InstalledGame)
# directly and therefore still reports every locally registered installation.
if (-not $CheckUpdates) {
    $procResult = Invoke-WmtProcess -FilePath $LegendaryExe -Arguments "list-installed --json" -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree
    $result.ExitCode = [int]$procResult.ExitCode
    $result.Json = [string]$procResult.StdOut
    $result.StdErr = [string]$procResult.StdErr
    $result.TimedOut = [bool]$procResult.TimedOut
    $result.Error = [string]$procResult.Error

    if ($result.ExitCode -eq 0 -and -not [string]::IsNullOrWhiteSpace($result.Json)) {
        try {
            $result.Rows = @(ConvertFrom-WmtLegendaryInstalledJsonRows -JsonText $result.Json)
            $result.SourceFormat = "json"
            return $result
        }
        catch {
            $result.Error = "Legendary installed-game JSON parse failed: $($_.Exception.Message)"
        }
    }

    # Compatibility fallback for older/unusual Legendary builds.
    $procResult = Invoke-WmtProcess -FilePath $LegendaryExe -Arguments "list-installed --csv --show-dirs" -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree
}
else {
    $procResult = Invoke-WmtProcess -FilePath $LegendaryExe -Arguments "--api-timeout 30 list-installed --check-updates --csv --show-dirs" -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree

    # Older Legendary builds reject the global --api-timeout option.
    if ($procResult.ExitCode -eq 2 -and
        ([string]$procResult.StdErr) -match '(?i)unrecognized arguments[^\r\n]*--api-timeout') {
        $procResult = Invoke-WmtProcess -FilePath $LegendaryExe -Arguments "list-installed --check-updates --csv --show-dirs" -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree
    }

    # If the online update check fails for a network reason, fall back to the
    # complete local JSON database rather than the metadata-filtered CSV path.
    if ($procResult.ExitCode -ne 0 -or [string]::IsNullOrWhiteSpace([string]$procResult.StdOut)) {
        $combinedError = (([string]$procResult.StdErr) + [Environment]::NewLine + ([string]$procResult.Error)).Trim()
        if ($procResult.TimedOut -or
            $combinedError -match '(?i)ReadTimeout|Read timed out|socket\.timeout|ConnectTimeout|ConnectionError|Connection reset|Connection aborted|NewConnectionError|MaxRetryError|HTTPSConnectionPool|getaddrinfo failed|Temporary failure in name resolution|timed out') {
            $localResult = Invoke-WmtProcess -FilePath $LegendaryExe -Arguments "list-installed --json" -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree
            $result.OfflineFallback = $true
            $result.ExitCode = [int]$localResult.ExitCode
            $result.Json = [string]$localResult.StdOut
            $result.StdErr = [string]$localResult.StdErr
            $result.TimedOut = [bool]$localResult.TimedOut
            $result.Error = [string]$localResult.Error
            if ($result.ExitCode -eq 0 -and -not [string]::IsNullOrWhiteSpace($result.Json)) {
                try {
                    $result.Rows = @(ConvertFrom-WmtLegendaryInstalledJsonRows -JsonText $result.Json)
                    $result.SourceFormat = "json"
                    return $result
                }
                catch {
                    $result.Error = "Legendary installed-game JSON parse failed: $($_.Exception.Message)"
                }
            }
            return $result
        }
    }
}

$result.ExitCode = [int]$procResult.ExitCode
$result.Csv = [string]$procResult.StdOut
$result.StdErr = [string]$procResult.StdErr
$result.TimedOut = [bool]$procResult.TimedOut
$result.Error = [string]$procResult.Error

if ($result.ExitCode -eq 0 -and -not [string]::IsNullOrWhiteSpace($result.Csv)) {
    try {
        $csvText = [string]$result.Csv
        $headerIndex = $csvText.IndexOf("App name,")
        if ($headerIndex -gt 0) { $csvText = $csvText.Substring($headerIndex) }
        $result.Rows = @($csvText | ConvertFrom-Csv -ErrorAction Stop)
        $result.SourceFormat = "csv"
    }
    catch {
        $result.Error = "Legendary installed-game CSV parse failed: $($_.Exception.Message)"
        $result.Rows = @()
    }
}

return $result
}

function Set-WmtJsonCacheFile {
param(
    [Parameter(Mandatory = $true)][string]$Path,
    [Parameter(Mandatory = $true)]$InputObject,
    [int]$Depth = 3
)

$directory = [System.IO.Path]::GetDirectoryName($Path)
if ([string]::IsNullOrWhiteSpace($directory)) { $directory = (Get-Location).Path }
if (-not [System.IO.Directory]::Exists($directory)) {
    [void][System.IO.Directory]::CreateDirectory($directory)
}

$tempPath = Join-Path $directory (".{0}.{1}.tmp" -f [System.IO.Path]::GetFileName($Path), [Guid]::NewGuid().ToString("N"))
try {
    $json = $InputObject | ConvertTo-Json -Depth $Depth
    if ($null -eq $json) { $json = "[]" }

    $utf8Bom = [System.Text.UTF8Encoding]::new($true)
    [System.IO.File]::WriteAllText($tempPath, [string]$json, $utf8Bom)

    if ([System.IO.File]::Exists($Path)) {
        try {
            [System.IO.File]::Replace($tempPath, $Path, $null, $true)
        }
        catch {
            # Replace may be unsupported by a filesystem. Copying a fully-written
            # temp file is still safer than streaming JSON directly into the live file.
            [System.IO.File]::Copy($tempPath, $Path, $true)
            [System.IO.File]::Delete($tempPath)
        }
    }
    else {
        [System.IO.File]::Move($tempPath, $Path)
    }
}
finally {
    try {
        if ([System.IO.File]::Exists($tempPath)) { [System.IO.File]::Delete($tempPath) }
    }
    catch {}
}
}

# Shared Steam parsing/discovery helpers. The same definitions are loaded into
# main scope and injected into every pooled runspace to prevent parser drift.
$script:WmtSteamCommonHelpers = @'
function ConvertFrom-WmtSteamVdfPath {
param([string]$Value)
if ([string]::IsNullOrWhiteSpace($Value)) { return "" }
$path = ([string]$Value).Trim()
$path = $path -replace '\\\\', '\'
$path = $path -replace '/', '\'
return [Environment]::ExpandEnvironmentVariables($path)
}

function Add-WmtUniqueSteamPath {
param([System.Collections.Generic.List[string]]$Paths, [string]$Path)
# Do not use "-not $Paths" here: PowerShell coerces an empty generic list to
# $false, which prevented the first Steam root from ever being inserted.
if ($null -eq $Paths -or [string]::IsNullOrWhiteSpace($Path)) { return }
$expanded = ConvertFrom-WmtSteamVdfPath -Value $Path
try {
    $full = [System.IO.Path]::GetFullPath($expanded)
    if (-not (Test-Path -LiteralPath $full)) { return }
    $alreadyAdded = $false
    foreach ($existingPath in $Paths) {
        if ([string]::Equals([string]$existingPath, $full, [System.StringComparison]::OrdinalIgnoreCase)) {
            $alreadyAdded = $true
            break
        }
    }
    if (-not $alreadyAdded) { [void]$Paths.Add($full) }
}
catch {}
}

function Get-WmtSteamManifestValue {
param([string]$Text, [string]$Key)
if ([string]::IsNullOrWhiteSpace($Text) -or [string]::IsNullOrWhiteSpace($Key)) { return "" }
$pattern = '"' + [regex]::Escape($Key) + '"\s+"([^"]*)"'
$match = [regex]::Match($Text, $pattern)
if ($match.Success) { return [string]$match.Groups[1].Value }
return ""
}

function Get-WmtSteamManifestNumber {
param([string]$Text, [string]$Key)
$value = Get-WmtSteamManifestValue -Text $Text -Key $Key
$number = [long]0
if ([long]::TryParse(([string]$value), [ref]$number)) { return $number }
return [long]0
}

function Get-WmtSteamInstallRoots {
$paths = [System.Collections.Generic.List[string]]::new()
foreach ($registryPath in @("HKCU:\Software\Valve\Steam", "HKLM:\SOFTWARE\WOW6432Node\Valve\Steam", "HKLM:\SOFTWARE\Valve\Steam")) {
    try {
        $props = Get-ItemProperty -LiteralPath $registryPath -ErrorAction Stop
        foreach ($propName in @("SteamPath", "InstallPath")) {
            if ($props.PSObject.Properties[$propName]) { Add-WmtUniqueSteamPath -Paths $paths -Path ([string]$props.$propName) }
        }
        if ($props.PSObject.Properties["SteamExe"] -and -not [string]::IsNullOrWhiteSpace([string]$props.SteamExe)) {
            Add-WmtUniqueSteamPath -Paths $paths -Path (Split-Path -Parent ([string]$props.SteamExe))
        }
    }
    catch {}
}
$pf86 = [Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFilesX86)
$pf = [Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFiles)
foreach ($candidate in @((Join-Path $pf86 "Steam"), (Join-Path $pf "Steam"), (Join-Path $env:SystemDrive "Steam"), (Join-Path $env:SystemDrive "steamcmd"))) {
    Add-WmtUniqueSteamPath -Paths $paths -Path $candidate
}
foreach ($cmdName in @("steamcmd", "steamcmd.exe")) {
    try {
        $cmd = Get-Command $cmdName -ErrorAction SilentlyContinue
        if ($cmd -and $cmd.Source) { Add-WmtUniqueSteamPath -Paths $paths -Path (Split-Path -Parent ([string]$cmd.Source)) }
    }
    catch {}
}
return $paths.ToArray()
}

function Get-WmtSteamLibraryRoots {
$paths = [System.Collections.Generic.List[string]]::new()
foreach ($root in @(Get-WmtSteamInstallRoots)) {
    if ([string]::IsNullOrWhiteSpace($root)) { continue }
    if (Test-Path -LiteralPath (Join-Path $root "steamapps")) { Add-WmtUniqueSteamPath -Paths $paths -Path $root }
    $libraryFile = Join-Path $root "steamapps\libraryfolders.vdf"
    if (-not (Test-Path -LiteralPath $libraryFile -PathType Leaf)) { continue }
    $libraryText = Get-Content -LiteralPath $libraryFile -Raw -Encoding UTF8 -ErrorAction SilentlyContinue
    if ([string]::IsNullOrWhiteSpace($libraryText)) { continue }
    foreach ($match in [regex]::Matches($libraryText, '"path"\s+"([^"]+)"')) { Add-WmtUniqueSteamPath -Paths $paths -Path $match.Groups[1].Value }
    foreach ($match in [regex]::Matches($libraryText, '"\d+"\s+"([^"]+)"')) {
        $candidate = ConvertFrom-WmtSteamVdfPath -Value $match.Groups[1].Value
        if ($candidate -match '^[A-Za-z]:\\|^\\\\') { Add-WmtUniqueSteamPath -Paths $paths -Path $candidate }
    }
}
return $paths.ToArray()
}

function Get-WmtSteamInstalledManifests {
$result = [System.Collections.Generic.List[object]]::new()
$seen = @{}
foreach ($libraryRoot in @(Get-WmtSteamLibraryRoots)) {
    $steamApps = Join-Path $libraryRoot "steamapps"
    if (-not (Test-Path -LiteralPath $steamApps)) { continue }
    foreach ($manifest in @(Get-ChildItem -LiteralPath $steamApps -Filter "appmanifest_*.acf" -File -ErrorAction SilentlyContinue)) {
        $text = Get-Content -LiteralPath $manifest.FullName -Raw -Encoding UTF8 -ErrorAction SilentlyContinue
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        $appId = Get-WmtSteamManifestValue -Text $text -Key "appid"
        if ([string]::IsNullOrWhiteSpace($appId)) { $appId = [regex]::Match($manifest.BaseName, '\d+').Value }
        if ([string]::IsNullOrWhiteSpace($appId) -or $seen.ContainsKey($appId)) { continue }
        $seen[$appId] = $true
        $name = Get-WmtSteamManifestValue -Text $text -Key "name"
        if ([string]::IsNullOrWhiteSpace($name)) { $name = "Steam App $appId" }
        [void]$result.Add([PSCustomObject]@{
            Id=$appId; Name=$name;
            BuildId=(Get-WmtSteamManifestValue -Text $text -Key "buildid");
            InstallDir=(Get-WmtSteamManifestValue -Text $text -Key "installdir");
            LibraryRoot=$libraryRoot; ManifestPath=$manifest.FullName; Text=$text
        })
    }
}
return $result.ToArray()
}

function Get-WmtSteamOwnedAppIds {
param([string]$SteamRoot)
$result = [System.Collections.Generic.List[string]]::new()
if ([string]::IsNullOrWhiteSpace($SteamRoot)) { $SteamRoot = @(Get-WmtSteamInstallRoots | Select-Object -First 1)[0] }
if ([string]::IsNullOrWhiteSpace($SteamRoot)) { return $result.ToArray() }
$userdataPath = Join-Path $SteamRoot "userdata"
if (-not (Test-Path -LiteralPath $userdataPath)) { return $result.ToArray() }
foreach ($userDir in @(Get-ChildItem -LiteralPath $userdataPath -Directory -ErrorAction SilentlyContinue)) {
    $vdfPath = Join-Path $userDir.FullName "config\localconfig.vdf"
    if (-not (Test-Path -LiteralPath $vdfPath -PathType Leaf)) { continue }
    $vdfText = Get-Content -LiteralPath $vdfPath -Raw -Encoding UTF8 -ErrorAction SilentlyContinue
    if ([string]::IsNullOrWhiteSpace($vdfText)) { continue }
    $appsIdx = $vdfText.IndexOf('"apps"', [System.StringComparison]::OrdinalIgnoreCase)
    if ($appsIdx -lt 0) { continue }
    $braceIdx = $vdfText.IndexOf('{', $appsIdx)
    if ($braceIdx -lt 0) { continue }
    $depth=0; $i=$braceIdx
    while ($i -lt $vdfText.Length) {
        $ch=$vdfText[$i]
        if ($ch -eq '{') { $depth++; $i++ }
        elseif ($ch -eq '}') { $depth--; if ($depth -le 0) { break }; $i++ }
        elseif ($ch -eq '"') {
            $endQ=$vdfText.IndexOf('"',$i+1); if ($endQ -lt 0) { break }
            $value=$vdfText.Substring($i+1,$endQ-$i-1); $i=$endQ+1
            if ($depth -eq 1) {
                $j=$i; while ($j -lt $vdfText.Length -and [char]::IsWhiteSpace($vdfText[$j])) { $j++ }
                if ($j -lt $vdfText.Length -and $vdfText[$j] -eq '{' -and -not $result.Contains($value)) { [void]$result.Add($value) }
            }
        }
        else { $i++ }
    }
}
return $result.ToArray()
}
'@

Invoke-Expression $script:WmtSteamCommonHelpers

# ============================================================================
# Shared runspace pools
# Fast UI-support work is isolated from long-running provider/network jobs so
# page status queries cannot be starved by package scans or library refreshes.
# ============================================================================
function New-WmtRunspaceInitialState {
$iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()

# Register shared helper functions structurally. The previous regex stopped at
# the first line-level closing brace inside nested try/catch/foreach blocks,
# truncating helpers such as Get-WmtSteamInstallRoots. The registration errors
# were then swallowed, so pooled workers started without the Steam helpers.
foreach ($helperBlock in @($script:MyDeviceCommonHelpers, $script:WmtSteamCommonHelpers)) {
    if ([string]::IsNullOrWhiteSpace([string]$helperBlock)) { continue }
    try {
        $tokens = $null
        $parseErrors = $null
        $helperAst = [System.Management.Automation.Language.Parser]::ParseInput(
            [string]$helperBlock,
            [ref]$tokens,
            [ref]$parseErrors
        )

        if ($parseErrors -and $parseErrors.Count -gt 0) {
            throw ("Shared helper parse failed: " + (($parseErrors | ForEach-Object { $_.Message }) -join "; "))
        }

        $helperFuncs = @($helperAst.FindAll({
                    param($node)
                    $node -is [System.Management.Automation.Language.FunctionDefinitionAst]
                }, $true))

        foreach ($funcAst in $helperFuncs) {
            # SessionStateFunctionEntry expects the function body, not a complete
            # "function Name { ... }" declaration.
            $bodyText = [string]$funcAst.Body.Extent.Text
            if ($bodyText.Length -ge 2 -and $bodyText[0] -eq '{' -and $bodyText[$bodyText.Length - 1] -eq '}') {
                $bodyText = $bodyText.Substring(1, $bodyText.Length - 2)
            }

            [void]$iss.Commands.Add(
                [System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new(
                    [string]$funcAst.Name,
                    $bodyText
                )
            )
        }
    }
    catch {
        try { Write-GuiLog "Shared runspace helper registration failed: $($_.Exception.Message)" } catch {}
        throw
    }
}

foreach ($helperName in @("ConvertTo-Int", "ConvertTo-Str", "Invoke-WmtProcess", "Invoke-WmtCliText", "Get-WmtLegendaryCachedLibrary", "Merge-WmtLegendaryCachedDetails", "Invoke-WmtLegendaryLibraryJson", "Invoke-WmtLegendaryInstalledData", "Set-WmtJsonCacheFile")) {
    try {
        $helper = Get-Command $helperName -CommandType Function -ErrorAction SilentlyContinue
        if ($helper) { [void]$iss.Commands.Add([System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new($helperName, $helper.Definition)) }
    }
    catch {}
}
return $iss
}

function Reset-WmtRunspacePool {
param([ValidateSet("Background", "UiSupport")][string]$PoolKind = "Background")
$pool = if ($PoolKind -eq "UiSupport") { $script:WmtUiSupportPool } else { $script:WmtBackgroundPool }
if ($pool) {
    if ($pool -is [System.Management.Automation.Runspaces.RunspacePool]) {
        # Closing an in-use pool waits for active invocations and can freeze WPF.
        # Fail without touching the shared reference; callers may retry later.
        try {
            $poolState = [string]$pool.RunspacePoolStateInfo.State
            if ($poolState -eq "Opened") {
                $maxRunspaces = [int]$pool.GetMaxRunspaces()
                $freeRunspaces = [int]$pool.GetAvailableRunspaces()
                if ($maxRunspaces -le 0 -or $freeRunspaces -ne $maxRunspaces) {
                    throw "The $PoolKind pool may still have active workers ($freeRunspaces of $maxRunspaces available)."
                }
            }
            elseif ($poolState -ne "Closed") {
                # Never synchronously close a pool in an uncertain state.
                throw "The $PoolKind pool is in state '$poolState'. Defer its reset."
            }
        }
        catch { throw "Cannot reset the $PoolKind runspace pool while its idle state is unconfirmed: $($_.Exception.Message)" }
    }
    try { $pool.Close() } catch {}
    try { $pool.Dispose() } catch {}
}
if ($PoolKind -eq "UiSupport") { $script:WmtUiSupportPool = $null } else { $script:WmtBackgroundPool = $null }
}

function Initialize-WmtRunspacePool {
param([ValidateSet("Background", "UiSupport")][string]$PoolKind = "Background")
$existing = if ($PoolKind -eq "UiSupport") { $script:WmtUiSupportPool } else { $script:WmtBackgroundPool }
if ($existing -is [System.Management.Automation.Runspaces.RunspacePool]) { return $existing }
if ($existing) { Reset-WmtRunspacePool -PoolKind $PoolKind }

$iss = New-WmtRunspaceInitialState
$maxWorkers = if ($PoolKind -eq "UiSupport") { 3 } else { 6 }
$pool = [runspacefactory]::CreateRunspacePool(1, $maxWorkers, $iss, $Host)
$pool.ApartmentState = "STA"
$pool.ThreadOptions = "ReuseThread"
$pool.Open()
if ($PoolKind -eq "UiSupport") { $script:WmtUiSupportPool = $pool } else { $script:WmtBackgroundPool = $pool }
return $pool
}

function Initialize-WmtBackgroundRunspacePool { return (Initialize-WmtRunspacePool -PoolKind Background) }
function Get-WmtBackgroundRunspacePool {
if (-not $script:WmtBackgroundPool) { $null = Initialize-WmtRunspacePool -PoolKind Background }
return $script:WmtBackgroundPool
}
function Get-WmtUiSupportRunspacePool {
if (-not $script:WmtUiSupportPool) { $null = Initialize-WmtRunspacePool -PoolKind UiSupport }
return $script:WmtUiSupportPool
}
function Stop-WmtBackgroundRunspacePool {
Reset-WmtRunspacePool -PoolKind Background
Reset-WmtRunspacePool -PoolKind UiSupport
}

function New-WmtPooledPowerShell {
param([ValidateSet("Background", "UiSupport")][string]$PoolKind = "Background")

$lastError = $null
for ($attempt = 1; $attempt -le 2; $attempt++) {
    try {
        $pool = if ($PoolKind -eq "UiSupport") { Get-WmtUiSupportRunspacePool } else { Get-WmtBackgroundRunspacePool }
        if ($pool -isnot [System.Management.Automation.Runspaces.RunspacePool]) {
            throw "Runspace pool initialization did not return a valid RunspacePool."
        }

        $ps = [PowerShell]::Create()
        try {
            $ps.RunspacePool = $pool
            return $ps
        }
        catch {
            $lastError = $_.Exception
            try { $ps.Dispose() } catch {}
            throw
        }
    }
    catch {
        $lastError = $_.Exception
        try { Write-GuiLog "[RunspacePool:$PoolKind] Worker creation attempt $attempt failed: $($lastError.Message)" } catch {}
        # A failed worker allocation does not imply the shared pool is idle.
        # Retry allocation without closing other operations' runspaces.
        if ($attempt -lt 2) {
            try {
                $existingPool = if ($PoolKind -eq "UiSupport") { $script:WmtUiSupportPool } else { $script:WmtBackgroundPool }
                if ($existingPool -and $existingPool.RunspacePoolStateInfo.State -ne [System.Management.Automation.Runspaces.RunspacePoolState]::Opened) {
                    Reset-WmtRunspacePool -PoolKind $PoolKind
                }
            }
            catch { try { Write-GuiLog "[RunspacePool:$PoolKind] Deferred pool reset: $($_.Exception.Message)" } catch {} }
        }
    }
}

throw "Unable to create a $PoolKind PowerShell worker after retrying worker creation. $($lastError.Message)"
}

function Start-WmtDetachedPowerShell {
param(
    [Parameter(Mandatory = $true)][System.Management.Automation.PowerShell]$PowerShell,
    [string]$Name = "BackgroundPowerShell",
    [switch]$LogOutput
)

$async = $null
try {
    $async = $PowerShell.BeginInvoke()
}
catch {
    try { $PowerShell.Dispose() } catch {}
    throw
}

$psRef = $PowerShell
$asyncRef = $async
$nameRef = $Name
$logOutputRef = [bool]$LogOutput
$operationName = "DetachedPowerShell:${Name}:$([Guid]::NewGuid().ToString('N'))"

$testComplete = {
    $asyncRef -and $asyncRef.IsCompleted
}.GetNewClosure()

$onComplete = {
    try {
        $results = @($psRef.EndInvoke($asyncRef))
        if ($logOutputRef) {
            foreach ($line in $results) {
                if ($line -is [string] -and $line.StartsWith("LOG:")) {
                    Write-GuiLog ($line.Substring(4))
                }
            }
        }
    }
    catch {
        try { Write-GuiLog "$nameRef failed: $($_.Exception.Message)" } catch {}
    }
    finally {
        try { $psRef.Dispose() } catch {}
    }
}.GetNewClosure()

$onError = {
    param($Operation, $ErrorRecord)
    try {
        if ($psRef -and $asyncRef -and -not $asyncRef.IsCompleted) {
            Stop-WmtPowerShellInvocationAsync -PowerShell $psRef -Invocation $asyncRef -Name $nameRef
        }
        else {
            try { if ($psRef -and $asyncRef) { [void]$psRef.EndInvoke($asyncRef) } } catch {}
            try { if ($psRef) { $psRef.Dispose() } } catch {}
        }
    }
    catch {
        try {
            if ($psRef -and $asyncRef -and -not $asyncRef.IsCompleted) {
                Start-WmtPowerShellCleanupDetached -PowerShell $psRef -Invocation $asyncRef -Name $nameRef
            }
            elseif ($psRef) {
                try { $psRef.Dispose() } catch {}
            }
        }
        catch {}
    }
    try { Write-GuiLog "$nameRef monitor failed: $($ErrorRecord.Exception.Message)" } catch {}
}.GetNewClosure()

try {
    Register-WmtUiPollOperation -Name $operationName -IntervalMs 500 -TestComplete $testComplete -OnComplete $onComplete -OnError $onError | Out-Null
}
catch {
    $monitorError = $_
    try {
        if ($asyncRef -and -not $asyncRef.IsCompleted) {
            Start-WmtPowerShellCleanupDetached -PowerShell $psRef -Invocation $asyncRef -Name $nameRef
        }
        else {
            try { if ($psRef -and $asyncRef) { [void]$psRef.EndInvoke($asyncRef) } } catch {}
            try { if ($psRef) { $psRef.Dispose() } } catch {}
        }
    }
    catch {}
    throw $monitorError
}
return $async
}

function Remove-WmtFileDeferred {
param(
    [Parameter(Mandatory = $true)][string]$Path,
    [int]$DelayMs = 2000
)

if ([string]::IsNullOrWhiteSpace($Path)) { return }
try {
    $cleanupPs = New-WmtPooledPowerShell -PoolKind Background
    [void]$cleanupPs.AddScript({
            param([string]$FilePath, [int]$WaitMs)
            if ($WaitMs -gt 0) { Start-Sleep -Milliseconds $WaitMs }
            Remove-Item -LiteralPath $FilePath -Force -ErrorAction SilentlyContinue
        }).AddArgument($Path).AddArgument([Math]::Max(0, $DelayMs))
    [void](Start-WmtDetachedPowerShell -PowerShell $cleanupPs -Name "Deferred temp-file cleanup")
}
catch {
    try { if ($script:WmtDebug) { Write-GuiLog "Deferred temp-file cleanup could not start for '$Path': $($_.Exception.Message)" } } catch {}
}
}

function Start-WmtPowerShellCleanupDetached {
param(
    [System.Management.Automation.PowerShell]$PowerShell,
    [System.IAsyncResult]$Invocation,
    [System.Management.Automation.Runspaces.Runspace]$Runspace,
    [string]$Name = "PowerShell invocation",
    [hashtable]$CompletionState
)

if (-not $PowerShell) { return }
if ($CompletionState) {
    $CompletionState.CleanupSchedulingFailed = $false
    $CompletionState.CleanupError = ""
}

if (-not (Get-Variable -Name WmtDetachedCleanupWorkers -Scope Script -ErrorAction SilentlyContinue) -or -not $script:WmtDetachedCleanupWorkers) {
    $script:WmtDetachedCleanupWorkers = [System.Collections.ArrayList]::new()
}

# GetNewClosure() creates a dynamic module, so capture the actual main-script
# tracker object instead of referring to $script: from delayed callbacks.
$cleanupWorkers = $script:WmtDetachedCleanupWorkers
foreach ($existing in @($cleanupWorkers)) {
    try {
        if ($existing -and $existing.Async -and $existing.Async.IsCompleted) {
            try { [void]$existing.PowerShell.EndInvoke($existing.Async) } catch {}
            try { $existing.PowerShell.Dispose() } catch {}
            [void]$cleanupWorkers.Remove($existing)
        }
    }
    catch {}
}

$cleanupPs = [System.Management.Automation.PowerShell]::Create()
$cleanupAsync = $null
try {
    [void]$cleanupPs.AddScript({
            param(
                [System.Management.Automation.PowerShell]$TargetPowerShell,
                [System.IAsyncResult]$TargetInvocation,
                [System.Management.Automation.Runspaces.Runspace]$TargetRunspace,
                [hashtable]$CleanupState
            )
            try {
                $finished = $false
                if ($TargetInvocation) {
                    try { $finished = [bool]$TargetInvocation.IsCompleted } catch {}
                }
                else {
                    try {
                        $state = [string]$TargetPowerShell.InvocationStateInfo.State
                        $finished = @("Completed", "Failed", "Stopped") -contains $state
                    }
                    catch {}
                }

                if (-not $finished) { try { $TargetPowerShell.Stop() } catch {} }

                if ($TargetInvocation) {
                    try {
                        if (-not $TargetInvocation.IsCompleted) { [void]$TargetInvocation.AsyncWaitHandle.WaitOne(5000) }
                    }
                    catch {}
                    try {
                        if ($TargetInvocation.IsCompleted) { [void]$TargetPowerShell.EndInvoke($TargetInvocation) }
                    }
                    catch [System.Management.Automation.PipelineStoppedException] {}
                    catch {}
                }
            }
            finally {
                try { $TargetPowerShell.Dispose() } catch {}
                if ($TargetRunspace) {
                    try { $TargetRunspace.Close() } catch {}
                    try { $TargetRunspace.Dispose() } catch {}
                }
                if ($CleanupState) { $CleanupState.CleanupCompleted = $true }
            }
        }).AddArgument($PowerShell).AddArgument($Invocation).AddArgument($Runspace).AddArgument($CompletionState)

    $cleanupAsync = $cleanupPs.BeginInvoke()
    if ($CompletionState) { $CompletionState.CleanupScheduled = $true }
    $worker = [PSCustomObject]@{ PowerShell = $cleanupPs; Async = $cleanupAsync; Name = $Name }
    [void]$cleanupWorkers.Add($worker)

    $workerRef = $worker
    $operationName = "DetachedCleanup:$($Name):$([Guid]::NewGuid().ToString('N'))"
    try {
        Register-WmtUiPollOperation -Name $operationName -IntervalMs 500 -TestComplete {
            $workerRef.Async -and $workerRef.Async.IsCompleted
        }.GetNewClosure() -OnComplete {
            try { [void]$workerRef.PowerShell.EndInvoke($workerRef.Async) } catch {}
            try { $workerRef.PowerShell.Dispose() } catch {}
            try { [void]$cleanupWorkers.Remove($workerRef) } catch {}
        }.GetNewClosure() -OnError {
            param($Operation, $ErrorRecord)
            try { Write-GuiLog "$Name detached cleanup monitor failed: $($ErrorRecord.Exception.Message)" } catch {}
        }.GetNewClosure() | Out-Null
    }
    catch {
        # The cleanup worker itself is already running. Keep it in the captured
        # tracker so a later cleanup request can reap it even without a monitor.
        try { Write-GuiLog "$Name cleanup monitor could not be registered: $($_.Exception.Message)" } catch {}
    }
}
catch {
    if (-not $cleanupAsync) { try { $cleanupPs.Dispose() } catch {} }
    if ($CompletionState -and -not $cleanupAsync) {
        $CompletionState.CleanupSchedulingFailed = $true
        $CompletionState.CleanupError = $_.Exception.Message
    }
    try { Write-GuiLog "$Name cleanup could not be scheduled off the UI thread: $($_.Exception.Message)" } catch {}
}
}

function Stop-WmtPowerShellInvocationAsync {
param(
    [System.Management.Automation.PowerShell]$PowerShell,
    [System.IAsyncResult]$Invocation,
    [string]$Name = "PowerShell invocation"
)

if (-not $PowerShell) { return }

$psRef = $PowerShell
$invokeRef = $Invocation
$nameRef = $Name
$stopRef = $null

$isInvocationFinished = {
    if ($invokeRef) {
        try { return [bool]$invokeRef.IsCompleted } catch { return $false }
    }
    try {
        $state = [string]$psRef.InvocationStateInfo.State
        return (@("Completed", "Failed", "Stopped") -contains $state)
    }
    catch {}
    return $false
}.GetNewClosure()

$canFinalize = {
    if (-not (& $isInvocationFinished)) { return $false }
    if ($stopRef) {
        try { return [bool]$stopRef.IsCompleted } catch { return $false }
    }
    return $true
}.GetNewClosure()

$finalizeCompleted = {
    try {
        if ($stopRef -and $stopRef.IsCompleted) {
            try { $psRef.EndStop($stopRef) } catch [System.Management.Automation.PipelineStoppedException] {} catch {}
        }
        if ($invokeRef -and $invokeRef.IsCompleted) { [void]$psRef.EndInvoke($invokeRef) }
    }
    catch [System.Management.Automation.PipelineStoppedException] {}
    catch { try { Write-GuiLog "$nameRef stop finalization reported: $($_.Exception.Message)" } catch {} }
    finally { try { $psRef.Dispose() } catch {} }
}.GetNewClosure()

try { $stopRef = $psRef.BeginStop($null, $null) }
catch {
    if (& $isInvocationFinished) { & $finalizeCompleted }
    else { Start-WmtPowerShellCleanupDetached -PowerShell $psRef -Invocation $invokeRef -Name $nameRef }
    return
}

if (-not $stopRef) {
    if (& $isInvocationFinished) { & $finalizeCompleted }
    else { Start-WmtPowerShellCleanupDetached -PowerShell $psRef -Invocation $invokeRef -Name $nameRef }
    return
}

$operationName = "StopPowerShell:$($Name):$([Guid]::NewGuid().ToString('N'))"
$testComplete = { & $canFinalize }.GetNewClosure()
$onComplete = { & $finalizeCompleted }.GetNewClosure()
$onTimeout = {
    param($Operation)
    if (& $canFinalize) { & $finalizeCompleted; return }
    try { Write-GuiLog "$nameRef did not fully stop within 10 seconds; cleanup is continuing off the UI thread." } catch {}
    Start-WmtPowerShellCleanupDetached -PowerShell $psRef -Invocation $invokeRef -Name $nameRef
}.GetNewClosure()
$onError = {
    param($Operation, $ErrorRecord)
    if (& $canFinalize) { & $finalizeCompleted }
    else { Start-WmtPowerShellCleanupDetached -PowerShell $psRef -Invocation $invokeRef -Name $nameRef }
    try { Write-GuiLog "$nameRef stop monitor failed: $($ErrorRecord.Exception.Message)" } catch {}
}.GetNewClosure()

try {
    Register-WmtUiPollOperation -Name $operationName -IntervalMs 250 -TimeoutMs 10000 -TestComplete $testComplete -OnComplete $onComplete -OnTimeout $onTimeout -OnError $onError | Out-Null
}
catch {
    if (& $canFinalize) { & $finalizeCompleted }
    else { Start-WmtPowerShellCleanupDetached -PowerShell $psRef -Invocation $invokeRef -Name $nameRef }
}
}

# ============================================================================
# Shared UI async-operation poller
# Replaces one DispatcherTimer per background operation with one 200ms timer.
# Debounce, animation, and one-shot timers remain independent by design.
# ============================================================================
$script:WmtUiPollOperations = [ordered]@{}
$script:WmtUiPollTimer = $null

function Initialize-WmtUiPollTimer {
if (-not $script:WmtUiPollTimer) {
    $script:WmtUiPollTimer = [System.Windows.Threading.DispatcherTimer]::new()
    $script:WmtUiPollTimer.Interval = [TimeSpan]::FromMilliseconds(200)
    $script:WmtUiPollTimer.Add_Tick({
        foreach ($name in @($script:WmtUiPollOperations.Keys)) {
            if (-not $script:WmtUiPollOperations.Contains($name)) { continue }
            $op = $script:WmtUiPollOperations[$name]
            if (-not $op) { continue }
            try {
                $nowUtc = [DateTime]::UtcNow
                if ($op.IntervalMs -gt 0 -and $op.LastTickUtc -and (($nowUtc - $op.LastTickUtc).TotalMilliseconds -lt $op.IntervalMs)) { continue }
                $op.LastTickUtc = $nowUtc
                $phase = "Tick"
                if ($op.OnTick) { & $op.OnTick $op }
                # OnTick can unregister/replace itself. Never act on stale operations.
                if (-not $script:WmtUiPollOperations.Contains($name) -or
                    -not [object]::ReferenceEquals($script:WmtUiPollOperations[$name], $op)) { continue }
                $phase = "TestComplete"
                $complete = $false
                if ($op.TestComplete) { $complete = [bool](& $op.TestComplete $op) }
                if ($complete) {
                    [void]$script:WmtUiPollOperations.Remove($name)
                    $phase = "OnComplete"
                    if ($op.OnComplete) { & $op.OnComplete $op }
                    continue
                }
                # Prefer a completed worker over a timeout when dispatcher ticks arrive late.
                $timedOut = ($op.TimeoutMs -gt 0 -and ((($nowUtc - $op.StartedAt).TotalMilliseconds) -ge $op.TimeoutMs))
                if ($timedOut) {
                    [void]$script:WmtUiPollOperations.Remove($name)
                    $phase = "OnTimeout"
                    if ($op.OnTimeout) { & $op.OnTimeout $op }
                }
            }
            catch {
                $monitorError = $_
                if (-not $op.PSObject.Properties["LastErrorLogUtc"]) {
                    $op | Add-Member -NotePropertyName LastErrorLogUtc -NotePropertyValue ([DateTime]::MinValue)
                }
                if (([DateTime]::UtcNow - $op.LastErrorLogUtc).TotalSeconds -ge 10) {
                    $op.LastErrorLogUtc = [DateTime]::UtcNow
                    try { Write-GuiLog "[Async] $name $phase failed: $($monitorError.Exception.Message)" } catch {}
                }
                # Do not discard a still-running operation merely because observing it failed.
                # Missing/failed error handlers must not orphan the worker.
                if ($op.OnError) {
                    try {
                        & $op.OnError $op $monitorError
                        if ($script:WmtUiPollOperations.Contains($name) -and
                            [object]::ReferenceEquals($script:WmtUiPollOperations[$name], $op)) {
                            [void]$script:WmtUiPollOperations.Remove($name)
                        }
                    }
                    catch {
                        try { Write-GuiLog "[Async] $name recovery failed; will retry: $($_.Exception.Message)" } catch {}
                    }
                }
                elseif ($phase -eq "OnComplete" -or $phase -eq "OnTimeout") {
                    # Completion callbacks may have side effects. Do not rerun them blindly.
                    try { Write-GuiLog "[Async] $name completion requires manual recovery (no error callback)." } catch {}
                }
                # In Tick/TestComplete failure without OnError, retain and retry next tick.
            }
        }
        if ($script:WmtUiPollOperations.Count -eq 0 -and $script:WmtUiPollTimer) { $script:WmtUiPollTimer.Stop() }
    })
}
if (-not $script:WmtUiPollTimer.IsEnabled) { $script:WmtUiPollTimer.Start() }
}

function Register-WmtUiPollOperation {
param(
    [Parameter(Mandatory = $true)][string]$Name,
    [Parameter(Mandatory = $true)][scriptblock]$TestComplete,
    [scriptblock]$OnComplete,
    [scriptblock]$OnTick,
    [int]$IntervalMs = 200,
    [int]$TimeoutMs = 0,
    [scriptblock]$OnTimeout,
    [scriptblock]$OnError
)
if ([string]::IsNullOrWhiteSpace($Name)) { throw "Async operation name cannot be empty." }
if ($script:WmtUiPollOperations.Contains($Name)) {
    # Never silently abandon an older operation. Callers that intentionally
    # replace work must first reconcile/unregister the existing monitor and
    # clean up the resource it owns.
    throw "Async operation '$Name' is already registered. Complete or explicitly unregister and clean up the existing operation before registering a replacement."
}
$op = [PSCustomObject]@{
    Name = $Name
    StartedAt = [DateTime]::UtcNow
    TimeoutMs = [Math]::Max(0, $TimeoutMs)
    IntervalMs = [Math]::Max(0, $IntervalMs)
    LastTickUtc = $null
    TestComplete = $TestComplete
    OnComplete = $OnComplete
    OnTick = $OnTick
    OnTimeout = $OnTimeout
    OnError = $OnError
}
$script:WmtUiPollOperations[$Name] = $op
try {
    Initialize-WmtUiPollTimer
}
catch {
    # Registration is atomic: if timer initialization fails after this operation
    # was inserted, remove only the operation object created by this call.
    try {
        if ($script:WmtUiPollOperations.Contains($Name) -and
            [object]::ReferenceEquals($script:WmtUiPollOperations[$Name], $op)) {
            [void]$script:WmtUiPollOperations.Remove($Name)
        }
    }
    catch {}
    throw
}
return $op
}

function Test-WmtUiPollOperation {
param([Parameter(Mandatory = $true)][string]$Name)
return [bool]($script:WmtUiPollOperations -and $script:WmtUiPollOperations.Contains($Name))
}

function Unregister-WmtUiPollOperation {
param([Parameter(Mandatory = $true)][string]$Name)
if ($script:WmtUiPollOperations -and $script:WmtUiPollOperations.Contains($Name)) { [void]$script:WmtUiPollOperations.Remove($Name) }
if ($script:WmtUiPollOperations.Count -eq 0 -and $script:WmtUiPollTimer) { $script:WmtUiPollTimer.Stop() }
}

# Independently track already-started processes if the shared poller fails.
# Never discard the Process handle or run completion bookkeeping before exit.
function Start-WmtFallbackUiMonitor {
param(
    [Parameter(Mandatory = $true)][string]$Name,
    [Parameter(Mandatory = $true)][scriptblock]$TestComplete,
    [Parameter(Mandatory = $true)][scriptblock]$OnComplete,
    [scriptblock]$OnTick,
    [int]$IntervalMs = 1000
)
if (-not $script:WmtFallbackUiMonitors) { $script:WmtFallbackUiMonitors = @{} }
$monitors = $script:WmtFallbackUiMonitors
$key = "$Name-$([Guid]::NewGuid().ToString('N'))"
$timer = [System.Windows.Threading.DispatcherTimer]::new()
$timer.Interval = [TimeSpan]::FromMilliseconds([Math]::Max(200, $IntervalMs))
$state = [PSCustomObject]@{
    Key = $key
    Timer = $timer
    TestComplete = $TestComplete
    OnComplete = $OnComplete
    OnTick = $OnTick
    ExitObserved = $false
    CompletionAttempts = 0
    LastErrorLogUtc = [DateTime]::MinValue
}
$timer.Add_Tick({
    param($timerSource, $tickEvent)
    $monitor = $state
    if (-not $monitor) { $timerSource.Stop(); return }
    try {
        if (-not $monitor.ExitObserved) {
            if ($monitor.OnTick) { & $monitor.OnTick $null }
            if (-not [bool](& $monitor.TestComplete $null)) { return }
            $monitor.ExitObserved = $true
        }
        # Completion may partially succeed. Callbacks must be retry-safe.
        $monitor.CompletionAttempts++
        & $monitor.OnComplete $null
        $timerSource.Stop()
        [void]$monitors.Remove($monitor.Key)
    }
    catch {
        if (([DateTime]::UtcNow - $monitor.LastErrorLogUtc).TotalSeconds -ge 10) {
            $monitor.LastErrorLogUtc = [DateTime]::UtcNow
            try { Write-GuiLog "[Async] $Name fallback attempt $($monitor.CompletionAttempts) failed: $($_.Exception.Message); retrying." } catch {}
        }
        # Observation errors cannot prove process exit; retain the handle/timer.
    }
}.GetNewClosure())
$monitors[$key] = $state
$timer.Start()
return $state
}

function Stop-WmtUiPoller {
if ($script:WmtUiPollTimer) { try { $script:WmtUiPollTimer.Stop() } catch {} }
if ($script:WmtUiPollOperations) { $script:WmtUiPollOperations.Clear() }
}

function Start-MyDeviceSectionJob {
param(
    [Parameter(Mandatory = $true)][string]$Name,
    [Parameter(Mandatory = $true)][string]$Body
)
$ps = New-WmtPooledPowerShell -PoolKind UiSupport

# Bulletproof fix: Inject the helper functions directly into the script block.
# This completely bypasses the fragile regex parser that was failing to load them.
$fullScript = $script:MyDeviceCommonHelpers + "`n" + $Body
[void]$ps.AddScript($fullScript)

$async = $ps.BeginInvoke()
$script:MyDeviceSectionJobs[$Name] = [pscustomobject]@{
    Name       = $Name
    PowerShell = $ps
    Async      = $async
    StartedAt  = Get-Date
}
}

function Update-MyDeviceStats {
param([switch]$ForceRefresh, [switch]$Preload)
$script:MyDeviceStatsStarted = $true
# Remember whether this load ran with background jobs disabled: the section
# collector timer only starts when jobs are enabled, so a disabled-mode load
# leaves "scanning is disabled" placeholders on screen (queue never drains).
$script:MyDeviceStatsLastDisabled = [bool](Get-WmtDisableBackgroundJobs)
$script:StatsStartedAt = Get-Date
$script:MyDeviceStatsPreloadMode = [bool]$Preload
$script:MyDeviceStatsMaxConcurrent = 4
Stop-MyDeviceSectionJobs
$script:MyDevicePendingSections = [System.Collections.ArrayList]::new()
Set-MyDeviceUiPlaceholders

$sections = @(
    [pscustomobject]@{ Name = "Core"; Body = $script:MyDeviceCoreBody },
    [pscustomobject]@{ Name = "GPU"; Body = $script:MyDeviceGpuBody },
    [pscustomobject]@{ Name = "Motherboard"; Body = $script:MyDeviceMotherboardBody },
    [pscustomobject]@{ Name = "Storage"; Body = $script:MyDeviceStorageBody },
    [pscustomobject]@{ Name = "Network"; Body = $script:MyDeviceNetworkBody },
    [pscustomobject]@{ Name = "Power"; Body = $script:MyDevicePowerBody }
)

foreach ($section in $sections) {
    $cached = if (-not $ForceRefresh) { Get-MyDeviceCacheEntry -Section $section.Name } else { $null }
    if ($cached) {
        Set-MyDeviceSectionData -Data $cached
        if (-not $Preload) { Write-GuiLog "[My Device] Loaded $($section.Name) from RAM cache." }
    }
    else {
        [void]$script:MyDevicePendingSections.Add($section)
    }
}

Start-MyDeviceQueuedSections

$hasPendingSections = ($script:MyDevicePendingSections -and $script:MyDevicePendingSections.Count -gt 0)
if ($script:MyDeviceSectionJobs.Count -eq 0 -and -not $hasPendingSections) {
    if (-not $Preload) { Write-GuiLog "[My Device] All sections loaded from RAM cache." }
    $script:MyDeviceStatsPreloadMode = $false
    return
}

$script:StatsTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:StatsTimer.Interval = [TimeSpan]::FromMilliseconds(200)
$script:StatsTimer.Add_Tick({
        if (-not $script:MyDeviceSectionJobs) { $script:MyDeviceSectionJobs = @{} }
        if ($script:MyDeviceSectionJobs.Count -eq 0) { Start-MyDeviceQueuedSections }

        foreach ($key in @($script:MyDeviceSectionJobs.Keys)) {
            $job = $script:MyDeviceSectionJobs[$key]
            if (-not $job -or -not $job.Async) { continue }
            if ($job.Async.IsCompleted) {
                try {
                    $data = $job.PowerShell.EndInvoke($job.Async)
                    if ($data -is [System.Collections.ObjectModel.Collection[PSObject]] -and $data.Count -gt 0) { $data = $data[-1] }
                    if ($data) {
                        Set-MyDeviceSectionData -Data $data
                        Set-MyDeviceCacheEntry -Section $key -Data $data
                        $elapsed = [math]::Round(((Get-Date) - $job.StartedAt).TotalSeconds, 1)
                        if (-not $script:MyDeviceStatsPreloadMode) { Write-GuiLog "[My Device] $key loaded in ${elapsed}s." }
                    }
                    else {
                        $errStream = $job.PowerShell.Streams.Error | ForEach-Object { $_.ToString() }
                        $errMsg = ($errStream -join "; ")
                        if (-not $errMsg) { $errMsg = "(no error output)" }
                        Write-GuiLog "[My Device] $key returned no data. Error: $errMsg"
                    }
                }
                catch {
                    Write-GuiLog "[My Device] $key load failed: $($_.Exception.Message)"
                }
                finally {
                    try { $job.PowerShell.Dispose() } catch {}
                    $script:MyDeviceSectionJobs.Remove($key)
                }
            }
        }

        Start-MyDeviceQueuedSections

        $hasPendingSections = ($script:MyDevicePendingSections -and $script:MyDevicePendingSections.Count -gt 0)
        if ($script:MyDeviceSectionJobs.Count -eq 0 -and -not $hasPendingSections) {
            try { $script:StatsTimer.Stop() } catch {}
            if (-not $script:MyDeviceStatsPreloadMode -and $script:StatsStartedAt) {
                $elapsed = [math]::Round(((Get-Date) - $script:StatsStartedAt).TotalSeconds, 1)
                Write-GuiLog "[My Device] Progressive stats load finished in ${elapsed}s."
            }
            $script:MyDeviceStatsPreloadMode = $false
            return
        }
    })
if (-not (Get-WmtDisableBackgroundJobs)) { $script:StatsTimer.Start() }
}

function Start-MyDeviceBitLockerStatusUpdate {
$osText = Get-Ctrl "txtDeviceOS"
if (-not $osText) { return }

try { Unregister-WmtUiPollOperation -Name "BitLockerStatus" } catch {}
if ($script:BitLockerStatusRunspace) {
    $oldBitLockerPs = $script:BitLockerStatusRunspace
    $oldBitLockerAsync = $script:BitLockerStatusAsyncResult
    $script:BitLockerStatusRunspace = $null
    $script:BitLockerStatusAsyncResult = $null
    try {
        Stop-WmtPowerShellInvocationAsync -PowerShell $oldBitLockerPs -Invocation $oldBitLockerAsync -Name "BitLocker status refresh"
    }
    catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $oldBitLockerPs -Invocation $oldBitLockerAsync -Name "BitLocker status refresh" } catch {}
    }
}

try {
$script:BitLockerStatusRunspace = (New-WmtPooledPowerShell -PoolKind UiSupport).AddScript({
        function Get-BitLockerStatusTextFast {
            $systemDrive = $env:SystemDrive
            if ([string]::IsNullOrWhiteSpace($systemDrive)) { return "Unavailable" }

            try {
                if (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue) {
                    $volume = Get-BitLockerVolume -MountPoint $systemDrive -ErrorAction Stop | Select-Object -First 1
                    if ($volume) { return "$($volume.ProtectionStatus) ($($volume.VolumeStatus))" }
                }
            }
            catch {}

            try {
                $volume = Get-CimInstance -Namespace "root\cimv2\Security\MicrosoftVolumeEncryption" -ClassName Win32_EncryptableVolume -ErrorAction Stop |
                Where-Object { $_.DriveLetter -eq $systemDrive } |
                Select-Object -First 1

                if ($volume) {
                    $protection = switch ([int]$volume.ProtectionStatus) {
                        0 { "Off" }
                        1 { "On" }
                        2 { "Unknown" }
                        default { "Unknown" }
                    }
                    $conversion = switch ([int]$volume.ConversionStatus) {
                        0 { "Fully Decrypted" }
                        1 { "Fully Encrypted" }
                        2 { "Encryption in Progress" }
                        3 { "Decryption in Progress" }
                        4 { "Encryption Paused" }
                        5 { "Decryption Paused" }
                        default { "Unknown" }
                    }
                    return "$protection ($conversion)"
                }
            }
            catch {}

            return "Unavailable"
        }

        Get-BitLockerStatusTextFast
    })
$script:BitLockerStatusAsyncResult = $script:BitLockerStatusRunspace.BeginInvoke()
}
catch {
    Write-GuiLog "[My Device] BitLocker status background query failed to start: $($_.Exception.Message)"
    try { if ($script:BitLockerStatusRunspace) { $script:BitLockerStatusRunspace.Dispose() } } catch {}
    $script:BitLockerStatusRunspace = $null
    $script:BitLockerStatusAsyncResult = $null
    $script:BitLockerStatusStartedAt = $null
    return
}
$script:BitLockerStatusStartedAt = Get-Date
$script:BitLockerStatusTimer = $null
Register-WmtUiPollOperation -Name "BitLockerStatus" -IntervalMs 500 -TestComplete { $false } -OnTick {
        $timedOut = $script:BitLockerStatusStartedAt -and (((Get-Date) - $script:BitLockerStatusStartedAt).TotalSeconds -gt 20)
        if (($script:BitLockerStatusAsyncResult -and $script:BitLockerStatusAsyncResult.IsCompleted) -or $timedOut) {
            Unregister-WmtUiPollOperation -Name "BitLockerStatus"
            $disposeBitLockerNow = $true
            $bitLockerPs = $script:BitLockerStatusRunspace
            $bitLockerAsync = $script:BitLockerStatusAsyncResult
            try {
                if ($timedOut) {
                    $status = "Timed out"
                    $disposeBitLockerNow = $false
                    try {
                        Stop-WmtPowerShellInvocationAsync -PowerShell $bitLockerPs -Invocation $bitLockerAsync -Name "BitLocker status timeout"
                    }
                    catch {
                        try { if ($bitLockerPs) { Start-WmtPowerShellCleanupDetached -PowerShell $bitLockerPs -Invocation $bitLockerAsync -Name "BitLocker status timeout" } } catch {}
                    }
                }
                else {
                    $status = $bitLockerPs.EndInvoke($bitLockerAsync)
                    if ($status -is [System.Collections.ObjectModel.Collection[PSObject]] -and $status.Count -gt 0) { $status = [string]$status[-1] }
                }
                if ([string]::IsNullOrWhiteSpace([string]$status)) { $status = "Unavailable" }

                $ctrl = Get-Ctrl "txtDeviceOS"
                if ($ctrl) {
                    $replacement = "BitLocker: $status"
                    if ($ctrl.Text -match "(?m)^BitLocker:") {
                        $ctrl.Text = [regex]::Replace($ctrl.Text, "(?m)^BitLocker:.*$", $replacement)
                    }
                    else {
                        $ctrl.Text = "$($ctrl.Text)`n$replacement"
                    }
                }
            }
            catch {}
            if ($disposeBitLockerNow) { try { if ($bitLockerPs) { $bitLockerPs.Dispose() } } catch {} }
            $script:BitLockerStatusRunspace = $null
            $script:BitLockerStatusAsyncResult = $null
            $script:BitLockerStatusStartedAt = $null
        }
    } | Out-Null
}

function Resolve-WmtThemeResourceKey {
param([string]$ColorOrKey)

if ([string]::IsNullOrWhiteSpace($ColorOrKey)) { return $null }
$value = $ColorOrKey.Trim()

if ($script:ThemePalettes) {
    foreach ($theme in @($script:ThemePalettes.Keys)) {
        if ($script:ThemePalettes[$theme].ContainsKey($value)) { return $value }
    }
}

switch -Regex ($value.ToUpperInvariant()) {
    "^#0D1117$" { return "BgDark" }
    "^#161B22$" { return "BgPanel" }
    "^#1C1C1E$" { return "BgPanel" }
    "^#141416$" { return "BgPanel" }
    "^#21262D$" { return "BgElevated" }
    "^#252526$" { return "BgElevated" }
    "^#30363D$" { return "BorderBrush" }
    "^#2C2C2E$" { return "BorderBrush" }
    "^#58A6FF$" { return "Accent" }
    "^#0078D7$" { return "Accent" }
    "^#1A0078D7$" { return "BgElevated" }
    "^#79C0FF$" { return "AccentHover" }
    "^#E6EDF3$" { return "TextPrimary" }
    "^#EBEBF5$" { return "TextPrimary" }
    "^#8B949E$" { return "TextSecondary" }
    "^#98989D$" { return "TextSecondary" }
    "^#6E7681$" { return "TextMuted" }
    "^#6E6E73$" { return "TextMuted" }
    "^#238636$" { return "Success" }
    "^#3FB950$" { return "SuccessHover" }
    "^#2EA043$" { return "SuccessHover" }
    "^#DA3633$" { return "Danger" }
    "^#F85149$" { return "DangerHover" }
    "^#D29922$" { return "Warning" }
    "^#E3B341$" { return "WarningHover" }
    "^#FFFFFF$" { return "AccentText" }
    "^WHITE$" { return "AccentText" }
    "^BLACK$" { return "BgDark" }
    default { return $null }
}
}

function New-WmtBrush {
param([string]$ColorOrKey)

$resourceKey = Resolve-WmtThemeResourceKey $ColorOrKey
if ($resourceKey -and $window -and $window.Resources[$resourceKey]) {
    return $window.Resources[$resourceKey]
}

if (-not $script:WmtBrushConverter) {
    $script:WmtBrushConverter = [System.Windows.Media.BrushConverter]::new()
}

try { return $script:WmtBrushConverter.ConvertFromString($ColorOrKey) }
catch { return $script:WmtBrushConverter.ConvertFromString("#8B949E") }
}

function Set-WmtThemeResources {
param(
    [System.Windows.FrameworkElement]$Element,
    [hashtable]$Palette
)

if (-not $Element -or -not $Palette) { return }
foreach ($key in $Palette.Keys) {
    $color = [System.Windows.Media.ColorConverter]::ConvertFromString($Palette[$key])
    $brush = [System.Windows.Media.SolidColorBrush]::new($color)
    $brush.Freeze()
    $Element.Resources[$key] = $brush
}

# Native selection templates also use system brushes when keyboard focus leaves
# the list. Keep both states paired with the current theme's accent text.
$Element.Resources[[System.Windows.SystemColors]::HighlightBrushKey] = $Element.Resources["Accent"]
$Element.Resources[[System.Windows.SystemColors]::HighlightTextBrushKey] = $Element.Resources["AccentText"]
$Element.Resources[[System.Windows.SystemColors]::InactiveSelectionHighlightBrushKey] = $Element.Resources["Accent"]
$Element.Resources[[System.Windows.SystemColors]::InactiveSelectionHighlightTextBrushKey] = $Element.Resources["AccentText"]
# Native ScrollViewer corners must follow the panel rather than system chrome.
$Element.Resources[[System.Windows.SystemColors]::ControlBrushKey] = $Element.Resources["BgPanel"]
Add-WmtListSelectionResources -Element $Element
}

function Add-WmtListSelectionResources {
param([System.Windows.FrameworkElement]$Element)

if (-not $Element -or $Element.Resources.Contains("__WmtListSelectionResourcesApplied")) { return }
[xml]$selectionXaml = @'
<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
    <Style TargetType="{x:Type ListBoxItem}">
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
        <Setter Property="Padding" Value="6,4"/>
        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ListBoxItem}">
                    <Border Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}"
                            BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}"
                            SnapsToDevicePixels="True">
                        <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                          VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                          TextElement.Foreground="{TemplateBinding Foreground}"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="{DynamicResource Accent}"/>
                <Setter Property="Foreground" Value="{DynamicResource AccentText}"/>
            </Trigger>
            <Trigger Property="IsSelected" Value="True">
                <Setter Property="Background" Value="{DynamicResource Accent}"/>
                <Setter Property="Foreground" Value="{DynamicResource AccentText}"/>
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.55"/>
            </Trigger>
        </Style.Triggers>
    </Style>
</ResourceDictionary>
'@
$reader = [System.Xml.XmlNodeReader]::new($selectionXaml)
[void]$Element.Resources.MergedDictionaries.Add([Windows.Markup.XamlReader]::Load($reader))
$Element.Resources["__WmtListSelectionResourcesApplied"] = $true
}

function Set-WmtThemedBrush {
param(
    [System.Windows.DependencyObject]$Object,
    [System.Windows.DependencyProperty]$Property,
    [string]$ColorOrKey,
    [string]$FallbackKey = "TextSecondary"
)

if (-not $Object -or -not $Property) { return }

$resourceKey = Resolve-WmtThemeResourceKey $ColorOrKey
if (-not $resourceKey) { $resourceKey = $FallbackKey }

if ($resourceKey -and $Object -is [System.Windows.FrameworkElement]) {
    $Object.SetResourceReference($Property, $resourceKey)
    return
}
if ($resourceKey -and $Object -is [System.Windows.FrameworkContentElement]) {
    $Object.SetResourceReference($Property, $resourceKey)
    return
}

$Object.SetValue($Property, (New-WmtBrush $ColorOrKey))
}

function Set-WmtWindowOwner {
param([System.Windows.Window]$Child)

if (-not $Child) { return }
try {
    if ($window -and [object]::ReferenceEquals($Child, $window) -eq $false -and $window.IsVisible) {
        $Child.Owner = $window
    }
}
catch {}
}

function Get-WmtWpfResourceXaml {
# One embedded dictionary keeps direct launches and PS2EXE builds identical.
[xml]$runtimeResourcesXaml = @'
<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
<Style TargetType="{x:Type TextBlock}">
    <!-- Inherit the containing control's foreground, including selected rows. -->
    <Setter Property="TextWrapping" Value="Wrap"/>
</Style>

<!-- Empty status text must not reserve a line or its margin. -->
<Style x:Key="WmtOptionalTextStyle" TargetType="{x:Type TextBlock}" BasedOn="{StaticResource {x:Type TextBlock}}">
    <Style.Triggers>
        <Trigger Property="Text" Value=""><Setter Property="Visibility" Value="Collapsed"/></Trigger>
    </Style.Triggers>
</Style>

<!-- Title/search content stays above status content, which always spans the card. -->
<Style x:Key="WmtPageHeaderStyle" TargetType="{x:Type HeaderedContentControl}">
    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
    <Setter Property="VerticalContentAlignment" Value="Top"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type HeaderedContentControl}">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                    </Grid.RowDefinitions>
                    <ContentPresenter ContentSource="Header" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"/>
                    <ContentPresenter Grid.Row="1" ContentSource="Content" Margin="0,8,0,0"
                                      HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                      VerticalAlignment="{TemplateBinding VerticalContentAlignment}"/>
                </Grid>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type Button}">
    <Setter Property="Height" Value="34"/>
    <Setter Property="MinWidth" Value="86"/>
    <Setter Property="Padding" Value="14,0"/>
    <Setter Property="Background" Value="{DynamicResource BgElevated}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="BorderThickness" Value="1"/>
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <Setter Property="UseLayoutRounding" Value="True"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type Button}">
                <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                        BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="4">
                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/>
                </Border>
                <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True">
                        <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BgHover}"/>
                        <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource TextSecondary}"/>
                    </Trigger>
                    <Trigger Property="IsPressed" Value="True">
                        <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BorderBrush}"/>
                    </Trigger>
                    <Trigger Property="IsEnabled" Value="False">
                        <Setter Property="Opacity" Value="0.55"/>
                        <Setter Property="Cursor" Value="Arrow"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type TextBox}">
    <Setter Property="Background" Value="{DynamicResource BgDark}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="BorderThickness" Value="1"/>
    <Setter Property="Padding" Value="9,6"/>
    <Setter Property="SelectionBrush" Value="{DynamicResource Accent}"/>
    <Setter Property="CaretBrush" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <Style.Triggers>
        <Trigger Property="IsFocused" Value="True">
            <Setter Property="BorderBrush" Value="{DynamicResource Accent}"/>
        </Trigger>
    </Style.Triggers>
</Style>

<Style x:Key="WmtComboBoxStyle" TargetType="{x:Type ComboBox}">
    <Setter Property="MinHeight" Value="32"/>
    <Setter Property="Background" Value="{DynamicResource BgDark}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="BorderThickness" Value="1"/>
    <Setter Property="Padding" Value="10,0,32,0"/>
    <Setter Property="VerticalContentAlignment" Value="Center"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <!-- The default Aero ComboBox template paints the closed selection box
         with its own static white brushes and ignores the Background/Border
         setters, leaving a light box in the dark theme. This template themes
         the closed box and hosts the themed dropdown surface itself; items
         inside are themed by the implicit ComboBoxItem style below. Hover
         only changes the border so combos with explicit light colors keep
         their readable background. -->
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type ComboBox}">
                <Grid x:Name="templateRoot" SnapsToDevicePixels="True">
                    <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="4">
                        <Grid>
                            <ContentPresenter x:Name="contentPresenter" Content="{TemplateBinding SelectionBoxItem}" ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}" Margin="{TemplateBinding Padding}" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="{TemplateBinding VerticalContentAlignment}" TextElement.Foreground="{TemplateBinding Foreground}" IsHitTestVisible="False"/>
                            <TextBox x:Name="PART_EditableTextBox"
                                     Text="{Binding Text, RelativeSource={RelativeSource TemplatedParent}, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}"
                                     Background="Transparent" Foreground="{TemplateBinding Foreground}"
                                     BorderThickness="0" Padding="0"
                                     Margin="{TemplateBinding Padding}"
                                     HorizontalContentAlignment="Left"
                                     VerticalContentAlignment="{TemplateBinding VerticalContentAlignment}"
                                     CaretBrush="{TemplateBinding Foreground}"
                                     IsReadOnly="{TemplateBinding IsReadOnly}"
                                     Visibility="Collapsed"/>
                            <Path x:Name="Arrow" Data="M 0 0 L 4 4 L 8 0" Stroke="{TemplateBinding Foreground}" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,1,9,0" IsHitTestVisible="False"/>
                        </Grid>
                    </Border>
                    <!-- Do not let the platform's native ToggleButton chrome paint over
                         the themed ComboBox while the popup is hovered/pressed/open. -->
                    <ToggleButton x:Name="toggleButton"
                                  Background="Transparent"
                                  BorderBrush="Transparent"
                                  BorderThickness="0"
                                  IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}"
                                  Focusable="False"
                                  FocusVisualStyle="{x:Null}"
                                  OverridesDefaultStyle="True"
                                  ClickMode="Press">
                        <ToggleButton.Template>
                            <ControlTemplate TargetType="{x:Type ToggleButton}">
                                <Border Background="Transparent"/>
                            </ControlTemplate>
                        </ToggleButton.Template>
                    </ToggleButton>
                    <Popup x:Name="PART_Popup" AllowsTransparency="True" Focusable="False" IsOpen="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}" Placement="Bottom" PopupAnimation="Fade">
                        <Border x:Name="DropDownBorder" Background="{DynamicResource BgPanel}" BorderBrush="{DynamicResource BorderBrush}" BorderThickness="1" CornerRadius="4" Margin="0,2,0,0" Padding="0,4" MinWidth="{Binding ActualWidth, ElementName=templateRoot}" MaxHeight="{TemplateBinding MaxDropDownHeight}">
                            <ScrollViewer VerticalScrollBarVisibility="Auto">
                                <ItemsPresenter KeyboardNavigation.DirectionalNavigation="Contained"/>
                            </ScrollViewer>
                        </Border>
                    </Popup>
                </Grid>
                <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True">
                        <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource TextSecondary}"/>
                    </Trigger>
                    <Trigger Property="IsDropDownOpen" Value="True">
                        <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource Accent}"/>
                        <Setter TargetName="Arrow" Property="LayoutTransform">
                            <Setter.Value>
                                <RotateTransform Angle="180"/>
                            </Setter.Value>
                        </Setter>
                    </Trigger>
                    <Trigger Property="IsEditable" Value="True">
                        <Setter TargetName="contentPresenter" Property="Visibility" Value="Collapsed"/>
                        <Setter TargetName="PART_EditableTextBox" Property="Visibility" Value="Visible"/>
                        <Setter TargetName="toggleButton" Property="HorizontalAlignment" Value="Right"/>
                        <Setter TargetName="toggleButton" Property="Width" Value="32"/>
                    </Trigger>
                    <Trigger Property="IsEnabled" Value="False">
                        <Setter Property="Opacity" Value="0.55"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>
<Style TargetType="{x:Type ComboBox}" BasedOn="{StaticResource WmtComboBoxStyle}"/>

<!-- The default ComboBoxItem template paints SystemColors.Window (white) and
     generated items inherit the combo's light foreground - light-on-white,
     unreadable. Give items an opaque themed surface and use the same
     Accent/AccentText highlight inversion as selected list rows. -->
<Style TargetType="{x:Type ComboBoxItem}">
    <Setter Property="Background" Value="{DynamicResource BgPanel}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="Padding" Value="9,5"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type ComboBoxItem}">
                <Border x:Name="Bd" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
                    <ContentPresenter TextElement.Foreground="{TemplateBinding Foreground}"/>
                </Border>
                <ControlTemplate.Triggers>
                    <Trigger Property="IsHighlighted" Value="True">
                        <Setter Property="Background" Value="{DynamicResource BgHover}"/>
                        <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
                    </Trigger>
                    <Trigger Property="IsSelected" Value="True">
                        <Setter Property="Background" Value="{DynamicResource Accent}"/>
                        <Setter Property="Foreground" Value="{DynamicResource AccentText}"/>
                    </Trigger>
                    <Trigger Property="IsEnabled" Value="False">
                        <Setter Property="Opacity" Value="0.55"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type CheckBox}">
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="VerticalAlignment" Value="Center"/>
</Style>
<Style x:Key="WmtWrappingCheckBoxStyle" TargetType="{x:Type CheckBox}" BasedOn="{StaticResource {x:Type CheckBox}}">
    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
    <Setter Property="ContentTemplate">
        <Setter.Value>
            <DataTemplate><TextBlock Text="{Binding}" TextWrapping="Wrap"/></DataTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type RadioButton}">
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="VerticalAlignment" Value="Center"/>
</Style>

<Style x:Key="WmtNoGutterMenuItemStyle" TargetType="{x:Type MenuItem}">
    <Setter Property="OverridesDefaultStyle" Value="True"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="Padding" Value="10,7"/>
    <Setter Property="MinWidth" Value="150"/>
    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type MenuItem}">
                <Border x:Name="Bd" Background="{TemplateBinding Background}" SnapsToDevicePixels="True">
                    <Grid Margin="{TemplateBinding Padding}">
                        <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                        <TextBlock x:Name="CheckMark" Text="&#x2713;" Width="18" Visibility="Collapsed" Opacity="0" VerticalAlignment="Center"/>
                        <ContentPresenter Grid.Column="1" ContentSource="Header" RecognizesAccessKey="True"
                                          VerticalAlignment="Center" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"/>
                    </Grid>
                </Border>
                <ControlTemplate.Triggers>
                    <Trigger Property="IsCheckable" Value="True"><Setter TargetName="CheckMark" Property="Visibility" Value="Visible"/></Trigger>
                    <Trigger Property="IsChecked" Value="True"><Setter TargetName="CheckMark" Property="Opacity" Value="1"/></Trigger>
                    <Trigger Property="IsHighlighted" Value="True">
                        <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BgHover}"/>
                    </Trigger>
                    <Trigger Property="IsEnabled" Value="False">
                        <Setter Property="Opacity" Value="0.55"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type MenuItem}" BasedOn="{StaticResource WmtNoGutterMenuItemStyle}"/>

<Style x:Key="WmtNoGutterSeparatorStyle" TargetType="{x:Type Separator}">
    <Setter Property="OverridesDefaultStyle" Value="True"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type Separator}">
                <Border Height="1" Margin="6,4" Background="{DynamicResource BorderBrush}"/>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type Separator}" BasedOn="{StaticResource WmtNoGutterSeparatorStyle}"/>

<Style TargetType="{x:Type ContextMenu}">
    <Setter Property="Background" Value="{DynamicResource BgElevated}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="BorderThickness" Value="1"/>
    <Setter Property="Padding" Value="4"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <Setter Property="ItemContainerStyle" Value="{StaticResource WmtNoGutterMenuItemStyle}"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type ContextMenu}">
                <Border Background="{TemplateBinding Background}"
                        BorderBrush="{TemplateBinding BorderBrush}"
                        BorderThickness="{TemplateBinding BorderThickness}"
                        Padding="{TemplateBinding Padding}"
                        SnapsToDevicePixels="True">
                    <ScrollViewer Focusable="False" CanContentScroll="True">
                        <ItemsPresenter KeyboardNavigation.DirectionalNavigation="Cycle"/>
                    </ScrollViewer>
                </Border>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type ListBox}">
    <Setter Property="Background" Value="{DynamicResource BgDark}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type ListBox}">
                <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                        BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}">
                    <ScrollViewer Focusable="False" CanContentScroll="True"
                                  HorizontalScrollBarVisibility="{TemplateBinding ScrollViewer.HorizontalScrollBarVisibility}"
                                  VerticalScrollBarVisibility="{TemplateBinding ScrollViewer.VerticalScrollBarVisibility}">
                        <ItemsPresenter/>
                    </ScrollViewer>
                </Border>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style x:Key="WmtListViewItemStyle" TargetType="{x:Type ListViewItem}">
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="Background" Value="Transparent"/>
    <!-- GridView already lays out cells within the declared column widths.
         Extra horizontal row padding shifts the last cell past its header. -->
    <Setter Property="Padding" Value="0,6"/>
    <Setter Property="Margin" Value="2,1"/>
    <Setter Property="BorderThickness" Value="0"/>
    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <Setter Property="UseLayoutRounding" Value="True"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type ListViewItem}">
                <Border Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}"
                        BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}">
                    <Grid>
                        <GridViewRowPresenter x:Name="GridRow" Content="{TemplateBinding Content}"
                            Columns="{Binding View.Columns, RelativeSource={RelativeSource AncestorType={x:Type ListView}}}"
                            VerticalAlignment="{TemplateBinding VerticalContentAlignment}"/>
                        <ContentPresenter x:Name="PlainRow" Visibility="Collapsed"
                            HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                            VerticalAlignment="{TemplateBinding VerticalContentAlignment}"/>
                    </Grid>
                </Border>
                <ControlTemplate.Triggers>
                    <DataTrigger Binding="{Binding View, RelativeSource={RelativeSource AncestorType={x:Type ListView}}}" Value="{x:Null}">
                        <Setter TargetName="GridRow" Property="Visibility" Value="Collapsed"/>
                        <Setter TargetName="PlainRow" Property="Visibility" Value="Visible"/>
                    </DataTrigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
    <Style.Triggers>
        <DataTrigger Binding="{Binding View, RelativeSource={RelativeSource AncestorType={x:Type ListView}}}" Value="{x:Null}">
            <Setter Property="Padding" Value="12,6"/>
        </DataTrigger>
        <Trigger Property="ItemsControl.AlternationIndex" Value="0"><Setter Property="Background" Value="{DynamicResource BgPanel}"/></Trigger>
        <Trigger Property="ItemsControl.AlternationIndex" Value="1"><Setter Property="Background" Value="{DynamicResource BgDark}"/></Trigger>
        <Trigger Property="IsMouseOver" Value="True"><Setter Property="Background" Value="{DynamicResource BgHover}"/></Trigger>
        <Trigger Property="IsSelected" Value="True">
            <Setter Property="Background" Value="{DynamicResource Accent}"/>
            <Setter Property="Foreground" Value="{DynamicResource AccentText}"/>
        </Trigger>
        <Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.55"/></Trigger>
    </Style.Triggers>
</Style>
<Style TargetType="{x:Type ListViewItem}" BasedOn="{StaticResource WmtListViewItemStyle}"/>
<Style x:Key="WmtListViewStyle" TargetType="{x:Type ListView}">
    <Setter Property="Background" Value="{DynamicResource BgDark}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="Padding" Value="0"/>
    <Setter Property="AlternationCount" Value="2"/>
    <Setter Property="ItemContainerStyle" Value="{StaticResource WmtListViewItemStyle}"/>
    <Setter Property="ScrollViewer.CanContentScroll" Value="True"/>
    <Setter Property="VirtualizingPanel.IsVirtualizing" Value="True"/>
    <Setter Property="VirtualizingPanel.VirtualizationMode" Value="Recycling"/>
</Style>
<Style TargetType="{x:Type ListView}" BasedOn="{StaticResource WmtListViewStyle}"/>
<!-- Both table types share column chrome; templates only supply native WPF parts. -->
<Style x:Key="WmtColumnHeaderStyle" TargetType="{x:Type Control}">
    <Setter Property="Background" Value="{DynamicResource BgPanel}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextSecondary}"/>
    <!-- GridViewRowPresenter supplies six pixels of horizontal cell spacing. -->
    <Setter Property="Padding" Value="6,8"/>
    <Setter Property="BorderThickness" Value="0"/>
    <Setter Property="FontWeight" Value="Normal"/>
    <Setter Property="HorizontalContentAlignment" Value="Left"/>
    <Style.Triggers>
        <Trigger Property="IsMouseOver" Value="True">
            <Setter Property="Background" Value="{DynamicResource BgHover}"/>
            <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
        </Trigger>
    </Style.Triggers>
</Style>
<Style x:Key="WmtColumnHeaderGripperStyle" TargetType="{x:Type Thumb}">
    <Setter Property="Width" Value="5"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="Cursor" Value="SizeWE"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type Thumb}">
                <Border x:Name="HeaderSeparator" Background="{TemplateBinding Background}"
                        BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="0,0,0.5,0"
                        Opacity="0.5" UseLayoutRounding="False" SnapsToDevicePixels="False"/>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>
<Style TargetType="{x:Type GridViewColumnHeader}" BasedOn="{StaticResource WmtColumnHeaderStyle}">
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type GridViewColumnHeader}">
                <Grid>
                    <Border x:Name="HeaderBorder" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center"/>
                    </Border>
                    <Thumb x:Name="PART_HeaderGripper" HorizontalAlignment="Right" Style="{StaticResource WmtColumnHeaderGripperStyle}"/>
                </Grid>
                <ControlTemplate.Triggers>
                    <!-- WPF adds a filler header after the real columns. It has
                         no data column and must not look or act like one. -->
                    <Trigger Property="Role" Value="Padding">
                        <Setter TargetName="PART_HeaderGripper" Property="Visibility" Value="Collapsed"/>
                        <Setter TargetName="HeaderBorder" Property="Background" Value="Transparent"/>
                        <Setter Property="IsHitTestVisible" Value="False"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type ProgressBar}">
    <Setter Property="Height" Value="10"/>
    <Setter Property="Background" Value="{DynamicResource BgPanel}"/>
    <Setter Property="Foreground" Value="{DynamicResource Accent}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="BorderThickness" Value="1"/>
</Style>

<Style x:Key="WmtDataGridStyle" TargetType="{x:Type DataGrid}">
    <Setter Property="Background" Value="{DynamicResource BgDark}"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="BorderThickness" Value="0"/>
    <Setter Property="GridLinesVisibility" Value="None"/>
    <Setter Property="MinRowHeight" Value="30"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <Setter Property="UseLayoutRounding" Value="True"/>
    <Setter Property="RowBackground" Value="{DynamicResource BgDark}"/>
    <Setter Property="AlternatingRowBackground" Value="{DynamicResource BgPanel}"/>
    <Setter Property="HeadersVisibility" Value="Column"/>
    <Setter Property="SelectionMode" Value="Extended"/>
    <Setter Property="SelectionUnit" Value="FullRow"/>
    <Setter Property="AutoGenerateColumns" Value="False"/>
    <Setter Property="ColumnWidth" Value="*"/>
    <Setter Property="CanUserAddRows" Value="False"/>
    <Setter Property="CanUserDeleteRows" Value="False"/>
    <Setter Property="ClipboardCopyMode" Value="IncludeHeader"/>
    <Setter Property="AlternationCount" Value="2"/>
</Style>
<Style TargetType="{x:Type DataGrid}" BasedOn="{StaticResource WmtDataGridStyle}"/>

<Style TargetType="{x:Type DataGridColumnHeader}" BasedOn="{StaticResource WmtColumnHeaderStyle}">
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type DataGridColumnHeader}">
                <Grid>
                    <Border x:Name="HeaderBorder" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
                        <Grid>
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center"/>
                            <Path x:Name="SortIndicator" Grid.Column="1" Width="8" Height="4" Margin="6,0,0,0"
                                  VerticalAlignment="Center" Fill="{DynamicResource TextSecondary}" Visibility="Collapsed"/>
                        </Grid>
                    </Border>
                    <Thumb x:Name="PART_LeftHeaderGripper" HorizontalAlignment="Left" BorderBrush="Transparent" Style="{StaticResource WmtColumnHeaderGripperStyle}"/>
                    <Thumb x:Name="PART_RightHeaderGripper" HorizontalAlignment="Right" Style="{StaticResource WmtColumnHeaderGripperStyle}"/>
                </Grid>
                <ControlTemplate.Triggers>
                    <Trigger Property="SortDirection" Value="Ascending">
                        <Setter TargetName="SortIndicator" Property="Visibility" Value="Visible"/>
                        <Setter TargetName="SortIndicator" Property="Data" Value="M0,4 L4,0 L8,4 Z"/>
                    </Trigger>
                    <Trigger Property="SortDirection" Value="Descending">
                        <Setter TargetName="SortIndicator" Property="Visibility" Value="Visible"/>
                        <Setter TargetName="SortIndicator" Property="Data" Value="M0,0 L8,0 L4,4 Z"/>
                    </Trigger>
                    <!-- Column is assigned after template creation and does not
                         notify bindings; identify WPF's filler by its part name. -->
                    <Trigger Property="Name" Value="PART_FillerColumnHeader">
                        <Setter TargetName="HeaderBorder" Property="Background" Value="Transparent"/>
                        <Setter TargetName="PART_LeftHeaderGripper" Property="Visibility" Value="Collapsed"/>
                        <Setter TargetName="PART_RightHeaderGripper" Property="Visibility" Value="Collapsed"/>
                        <Setter Property="IsHitTestVisible" Value="False"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style TargetType="{x:Type DataGridCell}">
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Setter Property="BorderThickness" Value="0"/>
    <Setter Property="Padding" Value="6,6"/>
    <Setter Property="VerticalContentAlignment" Value="Center"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type DataGridCell}">
                <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                        BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}">
                    <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                      VerticalAlignment="{TemplateBinding VerticalContentAlignment}"/>
                </Border>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
    <Style.Triggers>
        <Trigger Property="IsSelected" Value="True">
            <Setter Property="Background" Value="{DynamicResource Accent}"/>
            <Setter Property="Foreground" Value="{DynamicResource AccentText}"/>
        </Trigger>
    </Style.Triggers>
</Style>

<Style TargetType="{x:Type DataGridRow}">
    <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
    <Style.Triggers>
        <Trigger Property="IsMouseOver" Value="True"><Setter Property="Background" Value="{DynamicResource BgHover}"/></Trigger>
        <Trigger Property="IsSelected" Value="True">
            <Setter Property="Background" Value="{DynamicResource Accent}"/>
            <Setter Property="Foreground" Value="{DynamicResource AccentText}"/>
        </Trigger>
    </Style.Triggers>
</Style>

<Style x:Key="TransparentScrollRepeatButton" TargetType="{x:Type RepeatButton}">
    <Setter Property="Focusable" Value="False"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="BorderThickness" Value="0"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type RepeatButton}">
                <Border Background="Transparent"/>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>

<Style x:Key="WmtScrollBarStyle" TargetType="{x:Type ScrollBar}">
    <Setter Property="Width" Value="12"/>
    <Setter Property="MinWidth" Value="12"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="{x:Type ScrollBar}">
                <Grid Background="{TemplateBinding Background}" SnapsToDevicePixels="True">
                    <Track x:Name="PART_Track" IsDirectionReversed="True">
                        <Track.DecreaseRepeatButton>
                            <RepeatButton x:Name="PageDecreaseButton" Command="{x:Static ScrollBar.PageUpCommand}" Style="{StaticResource TransparentScrollRepeatButton}"/>
                        </Track.DecreaseRepeatButton>
                        <Track.Thumb>
                            <Thumb x:Name="ScrollThumb" MinHeight="28" Background="{DynamicResource TextMuted}">
                                <Thumb.Template>
                                    <ControlTemplate TargetType="{x:Type Thumb}">
                                        <Border Background="{TemplateBinding Background}" CornerRadius="4" Margin="2"/>
                                    </ControlTemplate>
                                </Thumb.Template>
                            </Thumb>
                        </Track.Thumb>
                        <Track.IncreaseRepeatButton>
                            <RepeatButton x:Name="PageIncreaseButton" Command="{x:Static ScrollBar.PageDownCommand}" Style="{StaticResource TransparentScrollRepeatButton}"/>
                        </Track.IncreaseRepeatButton>
                    </Track>
                </Grid>
                <ControlTemplate.Triggers>
                    <Trigger Property="Orientation" Value="Horizontal">
                        <Setter Property="Width" Value="Auto"/>
                        <Setter Property="MinWidth" Value="0"/>
                        <Setter Property="Height" Value="12"/>
                        <Setter Property="MinHeight" Value="12"/>
                        <Setter TargetName="PART_Track" Property="IsDirectionReversed" Value="False"/>
                        <Setter TargetName="ScrollThumb" Property="MinWidth" Value="28"/>
                        <Setter TargetName="ScrollThumb" Property="MinHeight" Value="0"/>
                        <Setter TargetName="PageDecreaseButton" Property="Command" Value="{x:Static ScrollBar.PageLeftCommand}"/>
                        <Setter TargetName="PageIncreaseButton" Property="Command" Value="{x:Static ScrollBar.PageRightCommand}"/>
                    </Trigger>
                    <Trigger Property="IsMouseOver" Value="True">
                        <Setter TargetName="ScrollThumb" Property="Background" Value="{DynamicResource TextSecondary}"/>
                    </Trigger>
                    <Trigger SourceName="ScrollThumb" Property="IsDragging" Value="True">
                        <Setter TargetName="ScrollThumb" Property="Background" Value="{DynamicResource Accent}"/>
                    </Trigger>
                    <Trigger Property="IsEnabled" Value="False">
                        <Setter Property="Opacity" Value="0.4"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>
<Style TargetType="{x:Type ScrollBar}" BasedOn="{StaticResource WmtScrollBarStyle}"/>

<Style x:Key="ModernSearchBoxStyle" TargetType="Border">
    <Setter Property="Background" Value="{DynamicResource BgDark}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    <Setter Property="BorderThickness" Value="1"/>
    <Setter Property="CornerRadius" Value="8"/>
    <Setter Property="Height" Value="40"/>
    <Setter Property="SnapsToDevicePixels" Value="True"/>
    <Setter Property="UseLayoutRounding" Value="True"/>
    <Style.Triggers>
        <Trigger Property="IsMouseOver" Value="True">
            <Setter Property="BorderBrush" Value="{DynamicResource TextMuted}"/>
        </Trigger>
    </Style.Triggers>
</Style>

<Style x:Key="SearchClearBtnStyle" TargetType="Button">
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Foreground" Value="{DynamicResource TextMuted}"/>
    <Setter Property="BorderThickness" Value="0"/>
    <Setter Property="Padding" Value="0"/>
    <Setter Property="FontSize" Value="14"/>
    <Setter Property="FontWeight" Value="Bold"/>
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
    <Setter Property="Template">
        <Setter.Value>
            <ControlTemplate TargetType="Button">
                <Border x:Name="Bd" Background="{TemplateBinding Background}"
                        CornerRadius="6" Padding="4" SnapsToDevicePixels="True">
                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True">
                        <Setter TargetName="Bd" Property="Background" Value="{DynamicResource BgHover}"/>
                        <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
                    </Trigger>
                </ControlTemplate.Triggers>
            </ControlTemplate>
        </Setter.Value>
    </Setter>
</Style>
</ResourceDictionary>
'@
return ,$runtimeResourcesXaml
}

function Add-WmtWpfRuntimeResources {
param([System.Windows.FrameworkElement]$Element)
if (-not $Element -or $Element.Resources.Contains("__WmtRuntimeResourcesApplied")) { return }
    $runtimeResourcesXaml = Get-WmtWpfResourceXaml
    $reader = [System.Xml.XmlNodeReader]::new($runtimeResourcesXaml)
    try { $runtimeResources = [Windows.Markup.XamlReader]::Load($reader) }
    finally { $reader.Close() }
    [void]$Element.Resources.MergedDictionaries.Add($runtimeResources)
    $Element.Resources["__WmtRuntimeResourcesApplied"] = $true
}

function Add-WmtThemeResources {
param([System.Windows.FrameworkElement]$Element)

if (-not $Element -or -not $script:ThemePalettes) { return }
$theme = if ($script:CurrentTheme -and $script:ThemePalettes.ContainsKey($script:CurrentTheme)) { $script:CurrentTheme } else { "dark" }
$palette = $script:ThemePalettes[$theme]
Set-WmtThemeResources -Element $Element -Palette $palette
Add-WmtWpfRuntimeResources -Element $Element

if (-not $script:WmtThemedElements) {
    $script:WmtThemedElements = [System.Collections.ArrayList]::new()
}

$alreadyTracked = $false
foreach ($tracked in @($script:WmtThemedElements)) {
    if ([object]::ReferenceEquals($tracked, $Element)) {
        $alreadyTracked = $true
        break
    }
}

if (-not $alreadyTracked) {
    [void]$script:WmtThemedElements.Add($Element)
    if ($Element -is [System.Windows.Window]) {
        $Element.Add_Closed({
                param($s, $e)
                $null = $e
                try { [void]$script:WmtThemedElements.Remove($s) } catch {}
            })
    }
}
}

function Set-WmtContextMenuChrome {
param([System.Windows.Controls.ContextMenu]$ContextMenu)

if (-not $ContextMenu) { return }
Add-WmtThemeResources -Element $ContextMenu
Set-WmtThemedBrush -Object $ContextMenu -Property ([System.Windows.Controls.Control]::BackgroundProperty) -ColorOrKey "BgElevated"
Set-WmtThemedBrush -Object $ContextMenu -Property ([System.Windows.Controls.Control]::ForegroundProperty) -ColorOrKey "TextPrimary"
Set-WmtThemedBrush -Object $ContextMenu -Property ([System.Windows.Controls.Control]::BorderBrushProperty) -ColorOrKey "BorderBrush"
try {
    $contextMenuStyle = $ContextMenu.TryFindResource([System.Windows.Controls.ContextMenu])
    if ($contextMenuStyle) { $ContextMenu.Style = $contextMenuStyle }
}
catch {}

$applyNoGutterChrome = {
    $menuItemStyle = $null
    $separatorStyle = $null
    try { $menuItemStyle = $ContextMenu.TryFindResource("WmtNoGutterMenuItemStyle") } catch {}
    try { $separatorStyle = $ContextMenu.TryFindResource("WmtNoGutterSeparatorStyle") } catch {}

    if ($menuItemStyle) {
        try { $ContextMenu.ItemContainerStyle = $menuItemStyle } catch {}
    }

    foreach ($item in @($ContextMenu.Items)) {
        if ($item -is [System.Windows.Controls.MenuItem]) {
            try { $item.Icon = $null } catch {}
            if ($menuItemStyle) { try { $item.Style = $menuItemStyle } catch {} }
        }
        elseif ($item -is [System.Windows.Controls.Separator]) {
            if ($separatorStyle) { try { $item.Style = $separatorStyle } catch {} }
        }
    }
}.GetNewClosure()

& $applyNoGutterChrome
try {
    $notifyItems = [System.Collections.Specialized.INotifyCollectionChanged]$ContextMenu.Items
    $notifyItems.add_CollectionChanged({ & $applyNoGutterChrome }.GetNewClosure())
}
catch {}
$ContextMenu.Add_Opened({ & $applyNoGutterChrome }.GetNewClosure())
}

function Invoke-WmtDispatcherPump {
param([System.Windows.Threading.Dispatcher]$Dispatcher = $null)

try {
    if (-not $Dispatcher) { $Dispatcher = [System.Windows.Threading.Dispatcher]::CurrentDispatcher }
    $Dispatcher.Invoke([Action] {}, [System.Windows.Threading.DispatcherPriority]::Background)
}
catch {}
}

function Show-WmtMessageBox {
param(
    [string]$Message,
    [string]$Title = "Windows Maintenance Tool",
    [System.Windows.MessageBoxButton]$Button = [System.Windows.MessageBoxButton]::OK,
    [System.Windows.MessageBoxImage]$Image = [System.Windows.MessageBoxImage]::None,
    [System.Windows.Window]$Owner = $null
)

try {
    if (-not $Owner -and $window -and $window.IsVisible) { $Owner = $window }
    if ($Owner) {
        return [System.Windows.MessageBox]::Show($Owner, $Message, $Title, $Button, $Image)
    }
}
catch {}
return [System.Windows.MessageBox]::Show($Message, $Title, $Button, $Image)
}

function Set-WmtBusyCursor {
param([switch]$Busy)

try {
    [System.Windows.Input.Mouse]::OverrideCursor = if ($Busy) { [System.Windows.Input.Cursors]::Wait } else { $null }
}
catch {}
}

function New-WmtWindowFromXaml {
param(
    [Parameter(Mandatory = $true)][string]$Title,
    [Parameter(Mandatory = $true)][string]$ContentXaml,
    [double]$Width = 640,
    [double]$Height = 420,
    [double]$MinWidth = 0,
    [double]$MinHeight = 0,
    [switch]$NoResize,
    [switch]$NoOwner
)

$escapedTitle = [System.Security.SecurityElement]::Escape($Title)
$resizeMode = if ($NoResize) { "NoResize" } else { "CanResize" }
$minWidthText = if ($MinWidth -gt 0) { " MinWidth=`"$MinWidth`"" } else { "" }
$minHeightText = if ($MinHeight -gt 0) { " MinHeight=`"$MinHeight`"" } else { "" }
[xml]$windowXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    Title="$escapedTitle" Width="$Width" Height="$Height"$minWidthText$minHeightText
    ResizeMode="$resizeMode" WindowStartupLocation="CenterOwner"
    Background="{DynamicResource BgDark}" Foreground="{DynamicResource TextPrimary}"
    FontFamily="Segoe UI Variable Display, Segoe UI, Arial" FontSize="13">
$ContentXaml
</Window>
"@

return New-WmtWindowFromFullXaml -Xaml $windowXaml -NoOwner:$NoOwner
}

function Get-WmtColumnMinimumWidth {
param([System.Windows.Controls.Control]$Table, [object]$Header, [switch]$Compact)

$text = if ($Header -is [System.Windows.Controls.ContentControl]) { [string]$Header.Content } else { [string]$Header }
$text = [regex]::Replace($text, '\s+[\u25B2\u25BC]$', '')
$typeface = [System.Windows.Media.Typeface]::new($Table.FontFamily, $Table.FontStyle, $Table.FontWeight, $Table.FontStretch)
$formatted = [System.Windows.Media.FormattedText]::new($text, [Globalization.CultureInfo]::CurrentCulture,
    $Table.FlowDirection, $typeface, $Table.FontSize, [System.Windows.Media.Brushes]::Black)
# Reserve cell spacing and sorting, without the text-column floor for selectors.
$spacing = 28.0
$minimum = if ($Compact) { 0.0 } else { 64.0 }
return [Math]::Max($minimum, [Math]::Ceiling($formatted.WidthIncludingTrailingWhitespace + $spacing))
}

function Set-WmtResponsiveColumnWidths {
param([System.Windows.Controls.Control]$Table)

if (-not $Table -or $Table.ActualWidth -le 0) { return }
$state = $Table.Resources['__WmtResponsiveColumns']
if (-not $state) { return }
$isDataGrid = $Table -is [System.Windows.Controls.DataGrid]
if (-not $isDataGrid -and -not ($Table.View -is [System.Windows.Controls.GridView])) { return }
$columns = if ($isDataGrid) { ,$Table.Columns } else { ,$Table.View.Columns }
foreach ($vC in @($state.Columns.Keys)) {
    if (-not $columns.Contains($vC)) { $state.Columns.Remove($vC) }
}
if ($columns.Count -eq 0) { return }
if (-not $state.Viewer) {
    $state.Viewer = Get-WmtVisualDescendant -Element $Table -DescendantType ([System.Windows.Controls.ScrollViewer])
}
$viewer = $state.Viewer
if (-not $viewer -or $viewer.ViewportWidth -le 0) { return }
$inset = 0.0
if (-not $isDataGrid) {
    $header = Get-WmtVisualDescendant -Element $Table -DescendantType ([System.Windows.Controls.GridViewHeaderRowPresenter])
    # GridView presenters add two pixels beyond the declared columns.
    $inset = 2.0 + $(if ($header) { $header.Margin.Left + $header.Margin.Right } else { 4.0 })
}
$available = [Math]::Max(0.0, [Math]::Floor($viewer.ViewportWidth - $inset))
$total = 0.0
$elastic = [System.Collections.Generic.List[object]]::new()
foreach ($vC in $columns) {
    if ($isDataGrid -and $vC.Visibility -ne [System.Windows.Visibility]::Visible) { continue }
    $auto = if ($isDataGrid) { -not $vC.Width.IsAbsolute } else { [double]::IsNaN($vC.Width) }
    $current = if ($isDataGrid) { $vC.Width.Value } else { $vC.Width }
    if (-not $state.Columns.ContainsKey($vC)) {
        $initial = if ($auto) { [Math]::Max(140.0, $vC.ActualWidth) } else { $current }
        $fixed = -not $auto -and $initial -le 48
        $minimum = if ($fixed) {
            if ($isDataGrid -or $initial -eq 0) { $initial } else { [Math]::Max($initial, (Get-WmtColumnMinimumWidth -Table $Table -Header $vC.Header -Compact)) }
        } else { Get-WmtColumnMinimumWidth -Table $Table -Header $vC.Header }
        $weight = if ($isDataGrid -and $vC.Width.IsStar) { $vC.Width.Value * 100.0 } else { [Math]::Max(1.0, $initial - $minimum) }
        $state.Columns[$vC] = @{
            Minimum = $minimum; Fixed = $fixed
            Weight = $weight; LastWidth = $null; ManualWidth = $null
        }
    }
    $spec = $state.Columns[$vC]
    $maximum = if ($isDataGrid) { $vC.MaxWidth } else { [double]::PositiveInfinity }
    $nativeMinimum = if ($isDataGrid) { $vC.MinWidth } else { 0.0 }
    $minimum = if ($spec.Fixed) { $spec.Minimum } else { Get-WmtColumnMinimumWidth -Table $Table -Header $vC.Header }
    $spec.Maximum = $maximum
    $spec.Minimum = [Math]::Min($maximum, [Math]::Max($nativeMinimum, $minimum))
    # Native pixel widths permit drags beyond the viewport. Detect changes from
    # our last allocation so manually resized columns survive window resizing.
    if ($auto) {
        $spec.ManualWidth = $null
    } elseif ($null -ne $spec.LastWidth -and [Math]::Abs($current - $spec.LastWidth) -gt 0.1) {
        $spec.ManualWidth = $current
    }
    $spec.AllocatedWidth = if ($null -ne $spec.ManualWidth) {
        [Math]::Min($maximum, [Math]::Max($nativeMinimum, $spec.ManualWidth))
    } else { $spec.Minimum }
    $total += $spec.AllocatedWidth
    if (-not $spec.Fixed -and $null -eq $spec.ManualWidth -and $spec.AllocatedWidth -lt $maximum) { $elastic.Add($vC) }
}
$remaining = [Math]::Max(0.0, $available - $total)
while ($remaining -ge 1 -and $elastic.Count -gt 0) {
    $weightTotal = 0.0
    foreach ($vC in $elastic) { $weightTotal += $state.Columns[$vC].Weight }
    $allocated = 0.0
    foreach ($vC in @($elastic)) {
        $spec = $state.Columns[$vC]
        $share = [Math]::Min($spec.Maximum - $spec.AllocatedWidth, [Math]::Floor($remaining * $spec.Weight / $weightTotal))
        $spec.AllocatedWidth += $share
        $allocated += $share
        if ($spec.AllocatedWidth -ge $spec.Maximum) { [void]$elastic.Remove($vC) }
    }
    $remaining -= $allocated
    if ($allocated -lt 1 -and $elastic.Count -gt 0) {
        # Assign rounding remainder to real columns instead of a blank filler.
        $vC = $elastic[$elastic.Count - 1]
        $spec = $state.Columns[$vC]
        $share = [Math]::Min($remaining, $spec.Maximum - $spec.AllocatedWidth)
        $spec.AllocatedWidth += $share
        $remaining -= $share
        [void]$elastic.Remove($vC)
    }
}
foreach ($vC in $columns) {
    if ($isDataGrid -and $vC.Visibility -ne [System.Windows.Visibility]::Visible) { continue }
    $spec = $state.Columns[$vC]
    $width = $spec.AllocatedWidth
    $spec.LastWidth = $width
    if ($isDataGrid) {
        if (-not $vC.Width.IsAbsolute -or [Math]::Abs($vC.Width.Value - $width) -gt 0.1) {
            $vC.Width = [System.Windows.Controls.DataGridLength]::new($width)
        }
    } elseif ([double]::IsNaN($vC.Width) -or [Math]::Abs($vC.Width - $width) -gt 0.1) { $vC.Width = $width }
}
}

function Request-WmtResponsiveColumnResize {
param([System.Windows.Controls.Control]$Table)

$state = $Table.Resources['__WmtResponsiveColumns']
if (-not $state -or $state.Closed -or $state.Operation) { return }
# Coalesce table, column, and viewport notifications after layout has settled.
$state.Operation = $Table.Dispatcher.BeginInvoke([Action]{
    $state.Operation = $null
    Set-WmtResponsiveColumnWidths -Table $Table
}.GetNewClosure(), [System.Windows.Threading.DispatcherPriority]::Loaded)
}

function Connect-WmtColumnWidthResets {
param([System.Windows.Controls.Control]$Table)

$state = $Table.Resources['__WmtResponsiveColumns']
if (-not $state -or $state.Closed) { return }
$isDataGrid = $Table -is [System.Windows.Controls.DataGrid]
$columns = if ($isDataGrid) { ,$Table.Columns } else { ,$Table.View.Columns }
foreach ($vC in @($state.WidthResetHandlers.Keys)) {
    if (-not $columns.Contains($vC)) {
        $watch = $state.WidthResetHandlers[$vC]
        $watch.Descriptor.RemoveValueChanged($vC, $watch.Handler)
        $state.WidthResetHandlers.Remove($vC)
    }
}
$widthProperty = if ($isDataGrid) { [System.Windows.Controls.DataGridColumn]::WidthProperty } else { [System.Windows.Controls.GridViewColumn]::WidthProperty }
$columnType = if ($isDataGrid) { [System.Windows.Controls.DataGridColumn] } else { [System.Windows.Controls.GridViewColumn] }
$descriptor = [System.ComponentModel.DependencyPropertyDescriptor]::FromProperty($widthProperty, $columnType)
foreach ($vC in $columns) {
    if ($state.WidthResetHandlers.ContainsKey($vC)) { continue }
    $handler = [System.EventHandler]{
        param($s)
        $auto = if ($s -is [System.Windows.Controls.DataGridColumn]) { -not $s.Width.IsAbsolute } else { [double]::IsNaN($s.Width) }
        # Header auto-sizing must resume filling without a window resize.
        # Our pixel allocations do not queue another sizing operation.
        if ($auto) { Request-WmtResponsiveColumnResize -Table $Table }
    }.GetNewClosure()
    $descriptor.AddValueChanged($vC, $handler)
    $state.WidthResetHandlers[$vC] = @{ Descriptor = $descriptor; Handler = $handler }
}
}

function Connect-WmtResponsiveColumns {
param([System.Windows.Controls.Control]$Table, [System.Windows.Window]$Owner)

if (-not ($Table -is [System.Windows.Controls.DataGrid]) -and
    -not ($Table -is [System.Windows.Controls.ListView] -and $Table.View -is [System.Windows.Controls.GridView])) { return }
if ($Owner -and -not $Owner.Resources.Contains('__WmtResponsiveTables')) {
    $Owner.Resources['__WmtResponsiveTables'] = [System.Collections.ArrayList]::new()
    $Owner.Add_Closed({
        foreach ($table in $Owner.Resources['__WmtResponsiveTables']) {
            $state = $table.Resources['__WmtResponsiveColumns']
            $state.Closed = $true
            if ($state.Operation) { [void]$state.Operation.Abort(); $state.Operation = $null }
            foreach ($vC in @($state.WidthResetHandlers.Keys)) {
                $watch = $state.WidthResetHandlers[$vC]
                $watch.Descriptor.RemoveValueChanged($vC, $watch.Handler)
            }
            $state.WidthResetHandlers.Clear()
        }
    }.GetNewClosure())
}
if ($Table.Resources.Contains('__WmtResponsiveColumns')) {
    if ($Owner -and -not $Owner.Resources['__WmtResponsiveTables'].Contains($Table)) {
        [void]$Owner.Resources['__WmtResponsiveTables'].Add($Table)
    }
    return
}
$state = @{ Columns = @{}; WidthResetHandlers = @{}; Viewer = $null; Operation = $null; Closed = $false }
$Table.Resources['__WmtResponsiveColumns'] = $state
if ($Owner) { [void]$Owner.Resources['__WmtResponsiveTables'].Add($Table) }
$Table.Add_SizeChanged({
    param($s, $e)
    if ($e.WidthChanged) { Request-WmtResponsiveColumnResize -Table $s }
}.GetNewClosure())
$Table.Add_Loaded({
    # A grid may be populated while detached, then inserted into a loaded window.
    Connect-WmtResponsiveColumns -Table $Table -Owner ([System.Windows.Window]::GetWindow($Table))
    Request-WmtResponsiveColumnResize -Table $Table
}.GetNewClosure())
$Table.Add_Unloaded({
    if ($state.Operation) { [void]$state.Operation.Abort(); $state.Operation = $null }
}.GetNewClosure())
$Table.AddHandler([System.Windows.Controls.ScrollViewer]::ScrollChangedEvent,
    [System.Windows.Controls.ScrollChangedEventHandler]{
        param($s, $e)
        if ($e.ViewportWidthChange -ne 0) { Request-WmtResponsiveColumnResize -Table $s }
    }.GetNewClosure())
$columns = if ($Table -is [System.Windows.Controls.DataGrid]) { ,$Table.Columns } else { ,$Table.View.Columns }
([System.Collections.Specialized.INotifyCollectionChanged]$columns).Add_CollectionChanged({
    Connect-WmtColumnWidthResets -Table $Table
    Request-WmtResponsiveColumnResize -Table $Table
}.GetNewClosure())
Connect-WmtColumnWidthResets -Table $Table
Request-WmtResponsiveColumnResize -Table $Table
}

function Connect-WmtResponsiveTables {
param([System.Windows.DependencyObject]$Element, [System.Windows.Window]$Owner)

if ($Element -is [System.Windows.Window] -and -not $Owner) {
    $Owner = $Element
    # Also cover controls constructed between window creation and its first load.
    $Owner.Add_Loaded({ Connect-WmtResponsiveTables -Element $Owner -Owner $Owner }.GetNewClosure())
}
if ($Element -is [System.Windows.Controls.Control]) { Connect-WmtResponsiveColumns -Table $Element -Owner $Owner }
foreach ($child in [System.Windows.LogicalTreeHelper]::GetChildren($Element)) {
    if ($child -is [System.Windows.DependencyObject]) { Connect-WmtResponsiveTables -Element $child -Owner $Owner }
}
}

function New-WmtWindowFromFullXaml {
param(
    [Parameter(Mandatory = $true)]$Xaml,
    [switch]$NoOwner
)

$xamlDoc = if ($Xaml -is [System.Xml.XmlDocument]) { $Xaml.Clone() } else { [xml]([string]$Xaml) }
# Merge before Load: StaticResource references in the window must be resolvable
# during construction, including styles based on shared control styles.
$ns = 'http://schemas.microsoft.com/winfx/2006/xaml/presentation'
$root = $xamlDoc.DocumentElement
$resources = $root.SelectSingleNode("*[local-name()='Window.Resources']")
if (-not $resources) {
    $resources = $xamlDoc.CreateElement('Window.Resources', $ns)
    [void]$root.PrependChild($resources)
}
$dictionary = $resources.SelectSingleNode("*[local-name()='ResourceDictionary']")
if (-not $dictionary) {
    $dictionary = $xamlDoc.CreateElement('ResourceDictionary', $ns)
    foreach ($node in @($resources.ChildNodes)) { [void]$dictionary.AppendChild($node) }
    [void]$resources.AppendChild($dictionary)
}
$merged = $dictionary.SelectSingleNode("*[local-name()='ResourceDictionary.MergedDictionaries']")
if (-not $merged) {
    $merged = $xamlDoc.CreateElement('ResourceDictionary.MergedDictionaries', $ns)
    [void]$dictionary.PrependChild($merged)
}
$shared = Get-WmtWpfResourceXaml
[void]$merged.PrependChild($xamlDoc.ImportNode($shared.DocumentElement, $true))
$reader = [System.Xml.XmlNodeReader]::new($xamlDoc)
try { $dialog = [Windows.Markup.XamlReader]::Load($reader) }
finally { $reader.Close() }
$dialog.Resources['__WmtRuntimeResourcesApplied'] = $true
Add-WmtThemeResources -Element $dialog
Connect-WmtResponsiveTables -Element $dialog
if (-not $NoOwner) { Set-WmtWindowOwner -Child $dialog }
return $dialog
}

function Connect-WmtPathPicker {
param(
    [Parameter(Mandatory = $true)][System.Windows.Controls.TextBox]$TextBox,
    [Parameter(Mandatory = $true)][System.Windows.Controls.Button]$BrowseButton,
    [string]$Description = 'Select folder',
    [System.Windows.Window]$Owner
)
$BrowseButton.Add_Click({
    $initial = ([string]$TextBox.Text).Trim()
    # A destination may not exist yet. Walk to its nearest existing ancestor,
    # using literal paths so brackets and other wildcard characters are safe.
    while (-not [string]::IsNullOrWhiteSpace($initial) -and -not (Test-Path -LiteralPath $initial -PathType Container)) {
        try { $parent = [System.IO.Path]::GetDirectoryName($initial) } catch { $parent = '' }
        if ($parent -eq $initial) { break }
        $initial = $parent
    }
    if ([string]::IsNullOrWhiteSpace($initial)) { $initial = $env:USERPROFILE }
    $pickerOwner = if ($Owner) { $Owner } else { [System.Windows.Window]::GetWindow($TextBox) }
    $selected = Select-WmtExplorerFolder -Description $Description -InitialDirectory $initial -Owner $pickerOwner
    if (-not [string]::IsNullOrWhiteSpace([string]$selected)) { $TextBox.Text = [string]$selected }
}.GetNewClosure())
}

function New-WmtPathPicker {
param(
    [System.Windows.Window]$Owner,
    [string]$TextBoxName = '',
    [string]$BrowseButtonName = '',
    [string]$Label = '',
    [string]$Description = 'Select folder',
    [string]$InitialPath = '',
    [double]$LabelWidth = 150
)
$grid = [System.Windows.Controls.Grid]::new()
$fieldColumn = [System.Windows.Controls.ColumnDefinition]::new()
$fieldColumn.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
if ($Label) {
    $labelColumn = [System.Windows.Controls.ColumnDefinition]::new()
    $labelColumn.Width = [System.Windows.GridLength]::new($LabelWidth)
    [void]$grid.ColumnDefinitions.Add($labelColumn)
    $caption = [System.Windows.Controls.TextBlock]::new()
    $caption.Text = $Label
    $caption.TextWrapping = 'Wrap'
    $caption.VerticalAlignment = 'Center'
    $caption.Margin = '0,0,8,0'
    $caption.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextSecondary')
    [void]$grid.Children.Add($caption)
}
[void]$grid.ColumnDefinitions.Add($fieldColumn)
$browseColumn = [System.Windows.Controls.ColumnDefinition]::new()
$browseColumn.Width = [System.Windows.GridLength]::Auto
[void]$grid.ColumnDefinitions.Add($browseColumn)
$text = [System.Windows.Controls.TextBox]::new()
$text.Text = $InitialPath
$text.MinHeight = 34
$text.VerticalContentAlignment = 'Center'
$text.Margin = '0,0,8,0'
$text.ToolTip = $Description
[System.Windows.Controls.Grid]::SetColumn($text, $grid.ColumnDefinitions.Count - 2)
[void]$grid.Children.Add($text)
$browse = [System.Windows.Controls.Button]::new()
$browse.Content = 'Browse...'
$browse.MinWidth = 92
[System.Windows.Controls.Grid]::SetColumn($browse, $grid.ColumnDefinitions.Count - 1)
[void]$grid.Children.Add($browse)
if ($TextBoxName) { $text.Name = $TextBoxName; if ($Owner) { $Owner.RegisterName($TextBoxName, $text) } }
if ($BrowseButtonName) { $browse.Name = $BrowseButtonName; if ($Owner) { $Owner.RegisterName($BrowseButtonName, $browse) } }
Connect-WmtPathPicker -TextBox $text -BrowseButton $browse -Description $Description -Owner $Owner
return $grid
}

function New-WmtActionButtonPanel {
param(
    [System.Windows.Window]$Owner,
    [Parameter(Mandatory = $true)][hashtable[]]$Buttons
)
$border = [System.Windows.Controls.Border]::new()
$border.Padding = '0,8,0,0'
$panel = [System.Windows.Controls.WrapPanel]::new()
$panel.HorizontalAlignment = 'Right'
$border.Child = $panel
foreach ($spec in $Buttons) {
    $button = [System.Windows.Controls.Button]::new()
    $button.Content = $spec.Content
    $button.MinHeight = 34
    $button.Padding = '14,4'
    $button.Margin = '8,4,0,4'
    if ($spec.Name) { $button.Name = $spec.Name; if ($Owner) { $Owner.RegisterName($spec.Name, $button) } }
    if ($spec.ContainsKey('IsDefault')) { $button.IsDefault = [bool]$spec.IsDefault }
    if ($spec.ContainsKey('IsCancel')) { $button.IsCancel = [bool]$spec.IsCancel }
    if ($spec.ContainsKey('IsEnabled')) { $button.IsEnabled = [bool]$spec.IsEnabled }
    if ($spec.Background) { $button.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty, $spec.Background) }
    if ($spec.Foreground) { $button.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty, $spec.Foreground) }
    if ($spec.ToolTip) { $button.ToolTip = $spec.ToolTip }
    if ($spec.Action) { $button.Add_Click($spec.Action) }
    [void]$panel.Children.Add($button)
}
return $border
}

function New-WmtInstallerDialog {
param(
    [Parameter(Mandatory = $true)][string]$Title,
    [string]$Description = '',
    [Parameter(Mandatory = $true)][string]$OptionsXaml,
    [string]$PathLabel = 'Install root',
    [string]$PathDescription = 'Choose game library folder',
    [double]$Width = 700,
    [double]$Height = 700
)
$content = @"
<Grid Margin="16">
    <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <ScrollViewer Name="InstallerScroll" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel Margin="0,0,8,0">
            <TextBlock Name="lblTitle" FontSize="18" FontWeight="SemiBold"/>
            <TextBlock Name="lblDescription" Margin="0,5,0,0" Foreground="{DynamicResource TextSecondary}"/>
            <TextBlock Name="lblMetadata" Margin="0,5,0,12" Foreground="{DynamicResource Warning}"/>
            <ContentControl Name="InstallerPathHost" Margin="0,0,0,10"/>
            $OptionsXaml
            <StackPanel Margin="150,8,0,0">
                <CheckBox Name="chkKeepOpen" Style="{StaticResource WmtWrappingCheckBoxStyle}" Margin="0,0,0,5" Content="Keep console open after a successful download" ToolTip="Failures always pause so the final error stays visible."/>
                <CheckBox Name="chkDesktopShortcut" Style="{StaticResource WmtWrappingCheckBoxStyle}" Margin="0,0,0,5" Content="Create a desktop shortcut after install"/>
                <CheckBox Name="chkStartMenuShortcut" Style="{StaticResource WmtWrappingCheckBoxStyle}" Content="Create a Start menu entry after install" ToolTip="Creates an entry under Start menu &gt; Programs &gt; WMT Games after a successful install."/>
            </StackPanel>
        </StackPanel>
    </ScrollViewer>
    <StackPanel Grid.Row="1">
        <ScrollViewer MaxHeight="72" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
            <TextBlock Name="lblError" Margin="0,8,0,0" Foreground="{DynamicResource Danger}"/>
        </ScrollViewer>
        <ContentControl Name="InstallerActionsHost"/>
    </StackPanel>
</Grid>
"@
$workArea = [System.Windows.SystemParameters]::WorkArea
$dialog = New-WmtWindowFromXaml -Title $Title -ContentXaml $content `
    -Width ([Math]::Min($Width, $workArea.Width)) -Height ([Math]::Min($Height, $workArea.Height)) `
    -MinWidth ([Math]::Min(420, $workArea.Width)) -MinHeight ([Math]::Min(280, $workArea.Height))
$dialog.FindName('lblDescription').Text = $Description
$dialog.FindName('InstallerPathHost').Content = New-WmtPathPicker -Owner $dialog -TextBoxName 'txtRoot' -BrowseButtonName 'btnBrowse' -Label $PathLabel -Description $PathDescription
$dialog.FindName('InstallerActionsHost').Content = New-WmtActionButtonPanel -Owner $dialog -Buttons @(
    @{ Name='btnCancel'; Content='Cancel'; IsCancel=$true },
    @{ Name='btnInstall'; Content='Install'; IsDefault=$true; Background='Accent'; Foreground='AccentText' })
Set-WmtNativeWindowTheme -Window $dialog
$dialog.Add_ContentRendered({
    $field = $dialog.FindName('txtRoot'); [void]$field.Focus(); $field.SelectAll()
}.GetNewClosure())
return $dialog
}

function New-WmtContextMenu {
param(
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Items,
    [System.Windows.Controls.Control]$Target
)
$menu = [System.Windows.Controls.ContextMenu]::new()
Set-WmtContextMenuChrome -ContextMenu $menu
foreach ($spec in $Items) {
    if ($spec -is [System.Windows.Controls.MenuItem] -or $spec -is [System.Windows.Controls.Separator]) {
        [void]$menu.Items.Add($spec)
        continue
    }
    if ($spec.Separator) { [void]$menu.Items.Add([System.Windows.Controls.Separator]::new()); continue }
    $item = [System.Windows.Controls.MenuItem]::new()
    $item.Header = $spec.Header
    $item.Tag = $spec.Tag
    if ($spec.ContainsKey('IsEnabled')) { $item.IsEnabled = [bool]$spec.IsEnabled }
    if ($spec.ContainsKey('IsCheckable')) { $item.IsCheckable = [bool]$spec.IsCheckable }
    if ($spec.ContainsKey('IsChecked')) { $item.IsChecked = [bool]$spec.IsChecked }
    if ($spec.Action) { $item.Add_Click($spec.Action) }
    [void]$menu.Items.Add($item)
}
if ($Target) { $Target.ContextMenu = $menu }
return $menu
}

function New-WmtAsyncProgress {
param(
    [System.Windows.Window]$Owner,
    [System.Windows.Controls.Control[]]$BusyControls = @()
)
$view = [System.Windows.Controls.Grid]::new()
[void]$view.RowDefinitions.Add([System.Windows.Controls.RowDefinition]::new())
foreach ($unused in 1..2) {
    $row = [System.Windows.Controls.RowDefinition]::new()
    $row.Height = [System.Windows.GridLength]::Auto
    [void]$view.RowDefinitions.Add($row)
}
$status = [System.Windows.Controls.TextBlock]::new()
$status.TextWrapping = 'Wrap'
$status.Margin = '0,0,0,8'
$statusScroll = [System.Windows.Controls.ScrollViewer]::new()
$statusScroll.VerticalScrollBarVisibility = 'Auto'
$statusScroll.HorizontalScrollBarVisibility = 'Disabled'
$statusScroll.Content = $status
$bar = [System.Windows.Controls.ProgressBar]::new()
$bar.Minimum = 0
$bar.Maximum = 100
$bar.MinHeight = 10
$cancel = [System.Windows.Controls.Button]::new()
$cancel.Content = 'Cancel'
$cancel.HorizontalAlignment = 'Right'
$cancel.Margin = '0,12,0,0'
$cancel.IsEnabled = $false
[System.Windows.Controls.Grid]::SetRow($bar, 1)
[System.Windows.Controls.Grid]::SetRow($cancel, 2)
[void]$view.Children.Add($statusScroll)
[void]$view.Children.Add($bar)
[void]$view.Children.Add($cancel)
$progress = [PSCustomObject]@{
    View=$view; Status=$status; Bar=$bar; CancelButton=$cancel
    State='Idle'; Name=''; Owner=$Owner; OwnsWindow=$false
    BusyControls=@($BusyControls); SavedStates=@(); ClosedHandler=$null
}
$cancel.Add_Click({
    if ($progress.State -eq 'Running') { Stop-WmtUiBackgroundCommand -Name $progress.Name }
    elseif ($progress.OwnsWindow -and $progress.Owner) { $progress.Owner.Close() }
}.GetNewClosure())
return $progress
}

function New-WmtAsyncProgressDialog {
param([string]$Title = 'Processing...')
$dialog = New-WmtWindowFromXaml -Title $Title -ContentXaml '<ContentControl Name="ProgressHost" Margin="20"/>' -Width 540 -Height 210 -MinWidth 420 -MinHeight 190
$progress = New-WmtAsyncProgress -Owner $dialog
$progress.OwnsWindow = $true
$dialog.FindName('ProgressHost').Content = $progress.View
Set-WmtNativeWindowTheme -Window $dialog
$dialog.Show()
return $progress
}

function Set-WmtAsyncProgressState {
param(
    [Parameter(Mandatory = $true)]$Progress,
    [Parameter(Mandatory = $true)][ValidateSet('Idle','Running','Succeeded','Failed','Cancelled')][string]$State,
    [string]$Message = '',
    [double]$Percent = [double]::NaN
)
if ($State -eq 'Running' -and $Progress.State -ne 'Running') {
    $Progress.SavedStates = @(foreach ($control in $Progress.BusyControls) {
        [PSCustomObject]@{ Control=$control; IsEnabled=$control.IsEnabled }
        $control.SetCurrentValue([System.Windows.UIElement]::IsEnabledProperty, $false)
    })
    if ($Progress.Owner) {
        $component = $Progress
        $Progress.ClosedHandler = [System.EventHandler]{
            if ($component.State -eq 'Running') { Stop-WmtUiBackgroundCommand -Name $component.Name }
        }.GetNewClosure()
        $Progress.Owner.Add_Closed($Progress.ClosedHandler)
    }
}
$Progress.State = $State
$Progress.Status.Text = $Message
$Progress.Status.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $(if ($State -eq 'Failed') { 'Danger' } else { 'TextSecondary' }))
$Progress.Bar.IsIndeterminate = ($State -eq 'Running' -and [double]::IsNaN($Percent))
if (-not [double]::IsNaN($Percent)) { $Progress.Bar.Value = [Math]::Max(0, [Math]::Min(100, $Percent)) }
$Progress.CancelButton.IsEnabled = ($State -eq 'Running' -or $Progress.OwnsWindow)
$Progress.CancelButton.Content = if ($State -eq 'Running') { 'Cancel' } else { 'Close' }
if ($State -ne 'Running') {
    foreach ($saved in $Progress.SavedStates) { $saved.Control.SetCurrentValue([System.Windows.UIElement]::IsEnabledProperty, $saved.IsEnabled) }
    $Progress.SavedStates = @()
    if ($Progress.Owner -and $Progress.ClosedHandler) { $Progress.Owner.Remove_Closed($Progress.ClosedHandler); $Progress.ClosedHandler = $null }
    if ($State -eq 'Succeeded' -and $Progress.OwnsWindow -and $Progress.Owner) { $Progress.Owner.Close() }
}
}

function Stop-WmtUiBackgroundCommand {
param([Parameter(Mandatory = $true)][string]$Name)
if (-not $script:WmtUiBackgroundCommands -or -not $script:WmtUiBackgroundCommands.ContainsKey($Name)) { return }
$job = $script:WmtUiBackgroundCommands[$Name]
Unregister-WmtUiPollOperation -Name ("UiCommand:" + $Name)
[void]$script:WmtUiBackgroundCommands.Remove($Name)
if ($job.Progress) { Set-WmtAsyncProgressState -Progress $job.Progress -State Cancelled -Message 'Cancelled.' }
Stop-WmtPowerShellInvocationAsync -PowerShell $job.PowerShell -Invocation $job.Async -Name "Background operation '$Name'"
}

function Show-WmtInputDialog {
param(
    [string]$Title,
    [string]$Prompt,
    [string]$DefaultValue = "",
    [switch]$ReadOnly
)

$content = @'
<Grid Margin="18">
    <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <TextBlock Name="lblPrompt" TextWrapping="Wrap" Margin="0,0,0,10"/>
    <TextBox Name="txtValue" Grid.Row="1" Height="34" VerticalContentAlignment="Center"/>
    <ContentControl Name="InputActionsHost" Grid.Row="2"/>
</Grid>
'@
$dialog = New-WmtWindowFromXaml -Title $Title -ContentXaml $content -Width 460 -Height 190 -MinWidth 380 -MinHeight 170 -NoResize
$dialog.FindName('InputActionsHost').Content = New-WmtActionButtonPanel -Owner $dialog -Buttons @(
    @{Name='btnCancel'; Content='Cancel'; IsCancel=$true},
    @{Name='btnOk'; Content='OK'; IsDefault=$true; Background='Accent'; Foreground='AccentText'})
$lblPrompt = $dialog.FindName("lblPrompt")
$txtValue = $dialog.FindName("txtValue")
$btnOk = $dialog.FindName("btnOk")
$btnCancel = $dialog.FindName("btnCancel")

$lblPrompt.Text = $Prompt
$txtValue.Text = $DefaultValue
$txtValue.IsReadOnly = [bool]$ReadOnly
$result = @{ Value = $null }
$btnOk.Add_Click({
        $result.Value = [string]$txtValue.Text
        $dialog.DialogResult = $true
    }.GetNewClosure())
$btnCancel.Add_Click({ $dialog.Close() }.GetNewClosure())
$dialog.Add_ContentRendered({
        $txtValue.Focus() | Out-Null
        $txtValue.SelectAll()
    }.GetNewClosure())

$dialog.ShowDialog() | Out-Null
return $result.Value
}

# Explorer-style folder chooser used where the old Shell.BrowseForFolder tree
# dialog is too limited. This uses the Windows Common Item Dialog in
# FOS_PICKFOLDERS mode, so users get the normal Explorer navigation pane,
# breadcrumbs, address bar, search box, drives, pinned locations, and New Folder.
function Select-WmtExplorerFolder {
param(
    [string]$Description = "Select folder",
    [string]$InitialDirectory = "",
    [Alias("OwnerWindow")][System.Windows.Window]$Owner
)

try {
    if (-not ("Wmt.Native.ModernFolderPicker" -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

namespace Wmt.Native
{
    [ComImport]
    [Guid("DC1C5A9C-E88A-4DDE-A5A1-60F82A20AEF7")]
    internal class FileOpenDialog
    {
    }

    [ComImport]
    [Guid("42F85136-DB7E-439C-85F1-E4075D135FC8")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    internal interface IFileDialog
    {
        [PreserveSig] int Show(IntPtr parent);
        [PreserveSig] int SetFileTypes(uint cFileTypes, IntPtr rgFilterSpec);
        [PreserveSig] int SetFileTypeIndex(uint iFileType);
        [PreserveSig] int GetFileTypeIndex(out uint piFileType);
        [PreserveSig] int Advise(IntPtr pfde, out uint pdwCookie);
        [PreserveSig] int Unadvise(uint dwCookie);
        [PreserveSig] int SetOptions(uint fos);
        [PreserveSig] int GetOptions(out uint pfos);
        [PreserveSig] int SetDefaultFolder(IShellItem psi);
        [PreserveSig] int SetFolder(IShellItem psi);
        [PreserveSig] int GetFolder(out IShellItem ppsi);
        [PreserveSig] int GetCurrentSelection(out IShellItem ppsi);
        [PreserveSig] int SetFileName([MarshalAs(UnmanagedType.LPWStr)] string pszName);
        [PreserveSig] int GetFileName(out IntPtr pszName);
        [PreserveSig] int SetTitle([MarshalAs(UnmanagedType.LPWStr)] string pszTitle);
        [PreserveSig] int SetOkButtonLabel([MarshalAs(UnmanagedType.LPWStr)] string pszText);
        [PreserveSig] int SetFileNameLabel([MarshalAs(UnmanagedType.LPWStr)] string pszLabel);
        [PreserveSig] int GetResult(out IShellItem ppsi);
    }

    [ComImport]
    [Guid("43826D1E-E718-42EE-BC55-A1E261C37BFE")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    internal interface IShellItem
    {
        [PreserveSig] int BindToHandler(IntPtr pbc, ref Guid bhid, ref Guid riid, out IntPtr ppv);
        [PreserveSig] int GetParent(out IShellItem ppsi);
        [PreserveSig] int GetDisplayName(uint sigdnName, out IntPtr ppszName);
    }

    public static class ModernFolderPicker
    {
        private const uint FOS_PICKFOLDERS = 0x00000020;
        private const uint FOS_FORCEFILESYSTEM = 0x00000040;
        private const uint FOS_PATHMUSTEXIST = 0x00000800;
        private const uint SIGDN_FILESYSPATH = 0x80058000;
        private const int ERROR_CANCELLED = unchecked((int)0x800704C7);

        [DllImport("shell32.dll", CharSet = CharSet.Unicode, PreserveSig = true)]
        private static extern int SHCreateItemFromParsingName(
            [MarshalAs(UnmanagedType.LPWStr)] string pszPath,
            IntPtr pbc,
            ref Guid riid,
            [MarshalAs(UnmanagedType.Interface)] out IShellItem ppv);

        public static string PickFolder(IntPtr owner, string title, string initialPath)
        {
            IFileDialog dialog = null;
            IShellItem initialItem = null;
            IShellItem resultItem = null;

            try
            {
                dialog = (IFileDialog)new FileOpenDialog();

                uint options;
                int hr = dialog.GetOptions(out options);
                if (hr < 0) Marshal.ThrowExceptionForHR(hr);

                hr = dialog.SetOptions(options | FOS_PICKFOLDERS | FOS_FORCEFILESYSTEM | FOS_PATHMUSTEXIST);
                if (hr < 0) Marshal.ThrowExceptionForHR(hr);

                if (!String.IsNullOrWhiteSpace(title))
                {
                    dialog.SetTitle(title);
                    dialog.SetOkButtonLabel("Select folder");
                }

                if (!String.IsNullOrWhiteSpace(initialPath))
                {
                    Guid shellItemGuid = typeof(IShellItem).GUID;
                    hr = SHCreateItemFromParsingName(initialPath, IntPtr.Zero, ref shellItemGuid, out initialItem);
                    if (hr >= 0 && initialItem != null)
                        dialog.SetFolder(initialItem);
                }

                hr = dialog.Show(owner);
                if (hr == ERROR_CANCELLED) return null;
                if (hr < 0) Marshal.ThrowExceptionForHR(hr);

                hr = dialog.GetResult(out resultItem);
                if (hr < 0) Marshal.ThrowExceptionForHR(hr);

                IntPtr displayName = IntPtr.Zero;
                try
                {
                    hr = resultItem.GetDisplayName(SIGDN_FILESYSPATH, out displayName);
                    if (hr < 0) Marshal.ThrowExceptionForHR(hr);
                    return Marshal.PtrToStringUni(displayName);
                }
                finally
                {
                    if (displayName != IntPtr.Zero) Marshal.FreeCoTaskMem(displayName);
                }
            }
            finally
            {
                if (resultItem != null) Marshal.FinalReleaseComObject(resultItem);
                if (initialItem != null) Marshal.FinalReleaseComObject(initialItem);
                if (dialog != null) Marshal.FinalReleaseComObject(dialog);
            }
        }
    }
}
'@
    }

    $initial = ([string]$InitialDirectory).Trim()
    if (-not [string]::IsNullOrWhiteSpace($initial) -and -not (Test-Path -LiteralPath $initial -PathType Container)) {
        try {
            $candidate = Split-Path -Parent $initial
            if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Container)) { $initial = $candidate }
            else { $initial = "" }
        }
        catch { $initial = "" }
    }

    $ownerHandle = [IntPtr]::Zero
    if ($Owner) {
        try { $ownerHandle = [System.Windows.Interop.WindowInteropHelper]::new($Owner).Handle } catch {}
    }

    $selected = [Wmt.Native.ModernFolderPicker]::PickFolder($ownerHandle, $Description, $initial)
    if (-not [string]::IsNullOrWhiteSpace([string]$selected)) { return [string]$selected }
    return $null
}
catch {
    # Rare fallback for systems where the shell COM dialog is unavailable.
    # This is still the Explorer-style common file dialog rather than the old
    # BrowseForFolder tree.
    try {
        $dlg = [Microsoft.Win32.OpenFileDialog]::new()
        $dlg.Title = $Description
        $dlg.CheckFileExists = $false
        $dlg.CheckPathExists = $true
        $dlg.ValidateNames = $false
        $dlg.FileName = "Select this folder"
        if (-not [string]::IsNullOrWhiteSpace($InitialDirectory) -and (Test-Path -LiteralPath $InitialDirectory -PathType Container)) {
            $dlg.InitialDirectory = $InitialDirectory
        }
        $accepted = if ($Owner) { $dlg.ShowDialog($Owner) } else { $dlg.ShowDialog() }
        if ($accepted -eq $true) {
            $folder = [System.IO.Path]::GetDirectoryName([string]$dlg.FileName)
            if (-not [string]::IsNullOrWhiteSpace($folder)) { return $folder }
        }
    }
    catch {}
}
return $null
}

# Make the non-client/title-bar area follow WMT's current light/dark theme.
# WPF themes the client area itself; DWM owns the native title bar.
function Set-WmtNativeWindowTheme {
param([System.Windows.Window]$Window)

if (-not $Window) { return }
try {
    if (-not ("Wmt.Native.DwmTheme" -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

namespace Wmt.Native
{
    public static class DwmTheme
    {
        [DllImport("dwmapi.dll")]
        private static extern int DwmSetWindowAttribute(IntPtr hwnd, int attribute, ref int value, int valueSize);

        public static void SetDarkMode(IntPtr hwnd, bool enabled)
        {
            if (hwnd == IntPtr.Zero) return;
            int value = enabled ? 1 : 0;

            // DWMWA_USE_IMMERSIVE_DARK_MODE is 20 on current Windows 10/11;
            // 19 covers older Windows 10 builds that exposed the attribute.
            DwmSetWindowAttribute(hwnd, 20, ref value, sizeof(int));
            DwmSetWindowAttribute(hwnd, 19, ref value, sizeof(int));
        }
    }
}
'@
    }

    $useDark = ([string]$script:CurrentTheme -ne "light")
    $applyNativeTheme = {
        param($s, $e)
        try {
            $handle = [System.Windows.Interop.WindowInteropHelper]::new($Window).Handle
            [Wmt.Native.DwmTheme]::SetDarkMode($handle, $useDark)
        }
        catch {}
    }.GetNewClosure()

    if ($Window.IsSourceInitialized) { & $applyNativeTheme $Window $null }
    else { $Window.Add_SourceInitialized($applyNativeTheme) }
}
catch {}
}

function New-WmtDataTable {
param(
    [string[]]$Columns,
    [object[]]$Rows = @()
)

$table = [System.Data.DataTable]::new()
foreach ($column in $Columns) { [void]$table.Columns.Add($column) }
foreach ($item in @($Rows)) {
    $row = $table.NewRow()
    foreach ($column in $Columns) {
        $value = $null
        if ($item -is [System.Data.DataRow]) {
            if ($item.Table.Columns.Contains($column)) { $value = $item[$column] }
        }
        elseif ($item -is [System.Collections.IDictionary]) {
            if ($item.Contains($column)) { $value = $item[$column] }
        }
        else {
            $prop = $item.PSObject.Properties[$column]
            if ($prop) { $value = $prop.Value }
        }
        $row[$column] = if ($null -eq $value) { "" } else { [string]$value }
    }
    [void]$table.Rows.Add($row)
}
return $table
}

function Get-WmtDataGridSelectedRows {
param([System.Windows.Controls.DataGrid]$DataGrid)

$rows = @()
if (-not $DataGrid) { return $rows }
foreach ($item in @($DataGrid.SelectedItems)) {
    if ($item -is [System.Data.DataRowView]) { $rows += $item.Row }
    else { $rows += $item }
}
return $rows
}

function Add-WmtStatusTextTriggers {
param(
    [System.Windows.Style]$Style,
    [string]$BindingPath,
    [string[]]$Values,
    [string]$ColorKey
)

if (-not $Style -or [string]::IsNullOrWhiteSpace($BindingPath)) { return }
$brush = New-WmtBrush $ColorKey
$fontWeight = [System.Windows.FontWeights]::SemiBold
$seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)

foreach ($value in @($Values)) {
    if ([string]::IsNullOrWhiteSpace($value)) { continue }
    foreach ($variant in @($value, $value.ToLowerInvariant(), $value.ToUpperInvariant())) {
        if (-not $seen.Add($variant)) { continue }

        $trigger = [System.Windows.DataTrigger]::new()
        $trigger.Binding = [System.Windows.Data.Binding]::new($BindingPath)
        $trigger.Value = $variant
        [void]$trigger.Setters.Add([System.Windows.Setter]::new([System.Windows.Controls.TextBlock]::ForegroundProperty, $brush))
        [void]$trigger.Setters.Add([System.Windows.Setter]::new([System.Windows.Controls.TextBlock]::FontWeightProperty, $fontWeight))
        [void]$Style.Triggers.Add($trigger)
    }
}
}

function New-WmtStatusTextStyle {
param([string]$BindingPath)

$style = [System.Windows.Style]::new([System.Windows.Controls.TextBlock])
[void]$style.Setters.Add([System.Windows.Setter]::new([System.Windows.Controls.TextBlock]::TextTrimmingProperty, [System.Windows.TextTrimming]::CharacterEllipsis))

Add-WmtStatusTextTriggers -Style $style -BindingPath $BindingPath -ColorKey "SuccessHover" -Values @(
    "Yes", "True", "Enabled", "Enable", "Allowed", "Allow", "Running", "Ready",
    "Automatic", "Auto", "Boot", "System", "Success", "OK", "Healthy", "Online",
    "Connected", "Up", "Installed", "Protected", "Active", "On"
)
Add-WmtStatusTextTriggers -Style $style -BindingPath $BindingPath -ColorKey "DangerHover" -Values @(
    "No", "False", "Disabled", "Disable", "Denied", "Deny", "Disallowed", "Not Allowed",
    "Blocked", "Block", "Stopped", "Failed", "Failure", "Error", "Access Denied",
    "Critical", "Unhealthy", "Offline", "Disconnected", "Not Present", "Unavailable", "Off"
)
Add-WmtStatusTextTriggers -Style $style -BindingPath $BindingPath -ColorKey "WarningHover" -Values @(
    "Manual", "Unknown", "Pending", "Queued", "Warning", "Degraded", "Limited",
    "Paused", "Starting", "Stopping", "Partially Enabled"
)

# Selection takes precedence over semantic status colors on either theme.
$selectionTrigger = [System.Windows.DataTrigger]::new()
$selectionTrigger.Binding = [System.Windows.Data.Binding]::new('IsSelected')
$selectionTrigger.Binding.RelativeSource = [System.Windows.Data.RelativeSource]::new(
    [System.Windows.Data.RelativeSourceMode]::FindAncestor, [System.Windows.Controls.DataGridRow], 1)
$selectionTrigger.Value = $true
[void]$selectionTrigger.Setters.Add([System.Windows.Setter]::new(
    [System.Windows.Controls.TextBlock]::ForegroundProperty, [System.Windows.DynamicResourceExtension]::new('AccentText')))
[void]$style.Triggers.Add($selectionTrigger)

return $style
}

function Set-WmtDataGridColumns {
param(
    [System.Windows.Controls.DataGrid]$DataGrid,
    [string[]]$Columns,
    [hashtable]$Widths = @{},
    [string[]]$Hidden = @(),
    [string[]]$StatusColumns = @("Enabled", "State", "Status", "StartType", "Action", "Protection", "Result")
)

if (-not $DataGrid) { return }
$DataGrid.AutoGenerateColumns = $false
$DataGrid.Columns.Clear()
foreach ($column in $Columns) {
    $col = [System.Windows.Controls.DataGridTextColumn]::new()
    $col.Header = $column
    $col.Binding = [System.Windows.Data.Binding]::new($column)
    $col.IsReadOnly = $true
    if ($StatusColumns -contains $column) {
        $col.ElementStyle = New-WmtStatusTextStyle -BindingPath $column
    }
    if ($Widths -and $Widths.ContainsKey($column)) {
        $widthValue = $Widths[$column]
        if ([string]$widthValue -match '^(?<weight>\d+(?:\.\d+)?)?\*$') {
            $weight = if ($matches["weight"]) { [double]$matches["weight"] } else { 1.0 }
            $col.Width = [System.Windows.Controls.DataGridLength]::new($weight, [System.Windows.Controls.DataGridLengthUnitType]::Star)
        }
        else {
            $col.Width = [double]$widthValue
        }
    }
    [void]$DataGrid.Columns.Add($col)
    if ($Hidden -contains $column) { $col.Visibility = [System.Windows.Visibility]::Collapsed }
}
# My Device and other grids add their columns after window construction.
Connect-WmtResponsiveColumns -Table $DataGrid -Owner ([System.Windows.Window]::GetWindow($DataGrid))
}

# --- SCHEDULED TASKS ENGINE (native Task Scheduler COM API) ---
# Every scheduled-task view and toggle in this tool goes through the Task
# Scheduler's own COM interface (Schedule.Service) - the same API schtasks.exe
# uses. The ScheduledTasks module cmdlets wrap a CIM layer that fails wholesale
# on some Windows 10 machines ("Value cannot be null. Parameter name: key"),
# which used to blank the task lists and fail every telemetry toggle even
# though the Task Scheduler service itself was healthy. The COM API does
# exact-path lookups in milliseconds and never depends on WMI/CIM health.
function New-WmtTaskSchedulerService {
if ($script:WmtTaskService) {
    # Re-validate a cached connection (the service may have been stopped or
    # its RCW released since the last call); fall through to a fresh connect.
    try { [void]$script:WmtTaskService.GetFolder("\"); return $script:WmtTaskService } catch { $script:WmtTaskService = $null }
}

try {
    $service = New-Object -ComObject "Schedule.Service"
    $service.Connect()
    $script:WmtTaskService = $service
    return $service
}
catch {
    $script:WmtTaskService = $null
    return $null
}
}

function ConvertTo-WmtScheduledTaskIdentity {
param(
    [string]$FullName = "",
    [string]$TaskName = "",
    [string]$TaskPath = ""
)

if ([string]::IsNullOrWhiteSpace($TaskName) -and -not [string]::IsNullOrWhiteSpace($FullName)) {
    $normalized = ([string]$FullName).Trim() -replace '/', '\'
    if (-not $normalized.StartsWith("\")) { $normalized = "\$normalized" }
    $parts = @($normalized.Trim("\") -split '\\' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($parts.Count -gt 0) {
        $TaskName = $parts[$parts.Count - 1]
        if ($parts.Count -gt 1) { $TaskPath = "\" + (($parts[0..($parts.Count - 2)]) -join "\") + "\" }
        else { $TaskPath = "\" }
    }
}

$TaskName = ([string]$TaskName).Trim()
$TaskPath = ([string]$TaskPath).Trim() -replace '/', '\'
if ([string]::IsNullOrWhiteSpace($TaskPath)) { $TaskPath = "\" }
if (-not $TaskPath.StartsWith("\")) { $TaskPath = "\$TaskPath" }
if (-not $TaskPath.EndsWith("\")) { $TaskPath = "$TaskPath\" }

$full = if ($TaskPath -eq "\") { "\$TaskName" } else { "$TaskPath$TaskName" }
[PSCustomObject]@{
    TaskName = $TaskName
    TaskPath = $TaskPath
    FullName = $full
}
}

function ConvertFrom-WmtRegisteredTask {
param(
    $Task,
    [string]$FallbackTaskName = "",
    [string]$FallbackTaskPath = "\"
)

# Property reads on a registered task can throw for tasks with damaged XML or
# locked-down principals, so every read is guarded and the identity falls back
# to caller-supplied values when the object will not cooperate.
$taskName = ([string]$FallbackTaskName).Trim()
try { $taskName = ([string]$Task.Name).Trim() } catch {}

$taskPath = ""
try { $taskPath = ([string]$Task.Path).Trim() } catch {}

$id = if (-not [string]::IsNullOrWhiteSpace($taskPath)) {
    ConvertTo-WmtScheduledTaskIdentity -FullName $taskPath
}
else {
    ConvertTo-WmtScheduledTaskIdentity -TaskName $taskName -TaskPath $FallbackTaskPath
}

$state = "Unknown"
try {
    switch ([int]$Task.State) {
        0 { $state = "Unknown" }
        1 { $state = "Disabled" }
        2 { $state = "Queued" }
        3 { $state = "Ready" }
        4 { $state = "Running" }
        default { $state = "Unknown" }
    }
}
catch {}

$enabled = ($state -ne "Disabled")
try { $enabled = [bool]$Task.Enabled } catch {}

$author = ""
try { $author = [string]$Task.Definition.RegistrationInfo.Author } catch {}
$description = ""
try { $description = [string]$Task.Definition.RegistrationInfo.Description } catch {}

[PSCustomObject]@{
    TaskName    = [string]$id.TaskName
    TaskPath    = [string]$id.TaskPath
    State       = $state
    Enabled     = $enabled
    Author      = $author
    Description = $description
    FullName    = [string]$id.FullName
}
}

function Get-WmtAllRegisteredTasks {
param([Parameter(Mandatory = $true)]$Service)

# Iterative walk of the task folder tree. GetTasks(1) also lists hidden tasks
# (matching what the module cmdlets returned); a folder that refuses
# enumeration is skipped instead of aborting the whole listing.
$tasks = [System.Collections.ArrayList]::new()
$stack = [System.Collections.Generic.Stack[object]]::new()
try { $stack.Push($Service.GetFolder("\")) } catch { return @($tasks) }
while ($stack.Count -gt 0) {
    $folder = $stack.Pop()
    try {
        foreach ($task in @($folder.GetTasks(1))) { [void]$tasks.Add($task) }
    }
    catch {}
    try {
        foreach ($subFolder in @($folder.GetFolders(0))) { $stack.Push($subFolder) }
    }
    catch {}
}
return @($tasks)
}

function Get-WmtScheduledTaskRows {
param(
    [string[]]$FullPaths = @(),
    [string[]]$TaskPaths = @(),
    [string[]]$TelemetryFolders = @()
)

$raw = @()
$service = New-WmtTaskSchedulerService

if (-not $service) {
    # No Task Scheduler connection: keep explicit rows for every requested
    # task so the grid always shows what was asked for (and why it failed).
    foreach ($fullPath in @($FullPaths)) {
        $id = ConvertTo-WmtScheduledTaskIdentity -FullName $fullPath
        if ([string]::IsNullOrWhiteSpace($id.TaskName)) { continue }
        $raw += [PSCustomObject]@{
            TaskName    = [string]$id.TaskName
            TaskPath    = [string]$id.TaskPath
            State       = "ReadError"
            Enabled     = $false
            Author      = ""
            Description = "Task Scheduler service is unavailable."
            FullName    = [string]$id.FullName
        }
    }
    if (@($FullPaths).Count -eq 0) {
        $raw += [PSCustomObject]@{
            TaskName    = "Task Scheduler unavailable"
            TaskPath    = ""
            State       = "ReadError"
            Enabled     = $false
            Author      = ""
            Description = "Could not connect to the Task Scheduler COM service. Run WMT elevated and verify the Task Scheduler service is running."
            FullName    = ""
        }
    }
}
elseif ($TelemetryFolders -and $TelemetryFolders.Count -gt 0) {
    # Live "invoke the Task Scheduler" enumeration: walk every telemetry
    # folder and list ALL tasks the scheduler actually has there (GetTasks(1)
    # includes hidden tasks) instead of assuming a fixed name list - Windows
    # builds vary; machines are missing some of the canonical nine while
    # carrying extra CEIP/Appraiser/Siuf sub-tasks no fixed list knows.
    # Folders that do not exist on this install raise 0x80070002 and are
    # simply skipped (no tasks registered there). The Office folder mixes
    # telemetry agents with unrelated servicing tasks, so its tasks are
    # name-filtered at read time.
    $seen = @{}
    foreach ($folderPath in @($TelemetryFolders)) {
        try {
            # GetFolder takes the path WITHOUT a trailing backslash.
            $folder = $service.GetFolder(([string]$folderPath).TrimEnd("\"))
            $isOffice = (([string]$folderPath).TrimEnd("\") -eq "\Microsoft\Office")
            foreach ($task in @($folder.GetTasks(1))) {
                if ($isOffice) {
                    $officeName = ""
                    try { $officeName = [string]$task.Name } catch {}
                    if ($officeName -notmatch "(?i)telemetry|apphealth|crash|consent") { continue }
                }
                $row = ConvertFrom-WmtRegisteredTask -Task $task
                $key = ([string]$row.FullName).ToLowerInvariant()
                if ([string]::IsNullOrWhiteSpace($key) -or $seen.ContainsKey($key)) { continue }
                $seen[$key] = $true
                $raw += $row
            }
        }
        catch {}
    }
    # Merge the canonical button paths (deduped against the walk: tasks the
    # walk already returned are listed from their live folder state; only the
    # ones this machine is missing are new here, as explicit NotFound /
    # ReadError rows so the grid always explains what the buttons target).
    foreach ($fullPath in @($FullPaths)) {
        $id = ConvertTo-WmtScheduledTaskIdentity -FullName $fullPath
        if ([string]::IsNullOrWhiteSpace($id.TaskName)) { continue }
        $key = ([string]$id.FullName).ToLowerInvariant()
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        try {
            $canonicalFolder = ([string]$id.TaskPath).TrimEnd("\")
            if ([string]::IsNullOrWhiteSpace($canonicalFolder)) { $canonicalFolder = "\" }
            $folder = $service.GetFolder($canonicalFolder)
            $task = $folder.GetTask([string]$id.TaskName)
            if ($task) {
                $raw += ConvertFrom-WmtRegisteredTask -Task $task -FallbackTaskName $id.TaskName -FallbackTaskPath $id.TaskPath
            }
            else {
                $raw += [PSCustomObject]@{
                    TaskName    = [string]$id.TaskName
                    TaskPath    = [string]$id.TaskPath
                    State       = "NotFound"
                    Enabled     = $false
                    Author      = ""
                    Description = "Task is not registered on this system."
                    FullName    = [string]$id.FullName
                }
            }
        }
        catch {
            $hr = 0
            try { $hr = $_.Exception.HResult } catch {}
            $message = [string]$_.Exception.Message
            $notFound = ($hr -eq -2147024894 -or $message -match '(?i)(cannot find|not found|does not exist|0x80070002)')
            $raw += [PSCustomObject]@{
                TaskName    = [string]$id.TaskName
                TaskPath    = [string]$id.TaskPath
                State       = if ($notFound) { "NotFound" } else { "ReadError" }
                Enabled     = $false
                Author      = ""
                Description = if ($notFound) { "Task is not registered on this system." } else { $message }
                FullName    = [string]$id.FullName
            }
        }
    }
    # Sort by folder then name so related tasks read as a block.
    $raw = @($raw | Sort-Object TaskPath, TaskName)
}
elseif ($FullPaths -and $FullPaths.Count -gt 0) {
    foreach ($fullPath in @($FullPaths)) {
        $id = ConvertTo-WmtScheduledTaskIdentity -FullName $fullPath
        if ([string]::IsNullOrWhiteSpace($id.TaskName)) { continue }
        try {
            # Exact-path COM lookup: no wildcard layer, no full-store scan.
            # ITaskService has no GetTask member - tasks are opened through
            # their folder (the same two-step the device-health probe uses).
            # A missing folder raises 0x80070002, classified as NotFound below.
            # GetFolder's documented path format carries NO trailing backslash
            # ("Do not use a backslash following the last folder name in the
            # path" - ITaskService::GetFolder), while the identity's TaskPath
            # keeps one for display; strip it before every folder open.
            $folderPath = ([string]$id.TaskPath).TrimEnd("\")
            if ([string]::IsNullOrWhiteSpace($folderPath)) { $folderPath = "\" }
            $folder = $service.GetFolder($folderPath)
            $task = $folder.GetTask([string]$id.TaskName)
            if ($task) {
                $raw += ConvertFrom-WmtRegisteredTask -Task $task -FallbackTaskName $id.TaskName -FallbackTaskPath $id.TaskPath
            }
            else {
                $raw += [PSCustomObject]@{
                    TaskName    = [string]$id.TaskName
                    TaskPath    = [string]$id.TaskPath
                    State       = "NotFound"
                    Enabled     = $false
                    Author      = ""
                    Description = "Task is not registered on this system."
                    FullName    = [string]$id.FullName
                }
            }
        }
        catch {
            # Missing or unreadable tasks stay visible as explicit rows instead
            # of silently vanishing; the classification matches the task probe
            # used by the device-health scan (HRESULT 0x80070002 family or a
            # not-found message means absent, anything else is a read error).
            $hr = 0
            try { $hr = $_.Exception.HResult } catch {}
            $message = [string]$_.Exception.Message
            $notFound = ($hr -eq -2147024894 -or $message -match '(?i)(cannot find|not found|does not exist|0x80070002)')
            $raw += [PSCustomObject]@{
                TaskName    = [string]$id.TaskName
                TaskPath    = [string]$id.TaskPath
                State       = if ($notFound) { "NotFound" } else { "ReadError" }
                Enabled     = $false
                Author      = ""
                Description = if ($notFound) { "Task is not registered on this system." } else { $message }
                FullName    = [string]$id.FullName
            }
        }
    }
}
else {
    try {
        $comTasks = @(Get-WmtAllRegisteredTasks -Service $service)
        if ($TaskPaths -and $TaskPaths.Count -gt 0) {
            $normalizedPaths = @($TaskPaths | ForEach-Object { (ConvertTo-WmtScheduledTaskIdentity -TaskPath $_ -TaskName "_").TaskPath })
            $comTasks = @($comTasks | Where-Object {
                    $taskPath = ""
                    try { $taskPath = ([string]$_.Path).Trim() } catch {}
                    if ([string]::IsNullOrWhiteSpace($taskPath)) { $false }
                    else {
                        $taskId = ConvertTo-WmtScheduledTaskIdentity -FullName $taskPath
                        $taskId.TaskPath -in $normalizedPaths
                    }
                })
        }
        foreach ($task in @($comTasks)) {
            $raw += ConvertFrom-WmtRegisteredTask -Task $task
        }
        if ($comTasks.Count -eq 0 -and @($TaskPaths).Count -eq 0) {
            $raw += [PSCustomObject]@{
                TaskName    = "No scheduled tasks returned"
                TaskPath    = ""
                State       = "ReadError"
                Enabled     = $false
                Author      = ""
                Description = "Task Scheduler returned no tasks. Check COM access, permissions, and the Task Scheduler service."
                FullName    = ""
            }
        }
    }
    catch {
        $raw = @()
    }
}

# Project the raw rows into the display shape the grids expect (Enabled as
# Yes/No), keeping placeholder rows explicit so telemetry tasks stay listed
# even when they are missing or unreadable.
foreach ($task in @($raw)) {
    $state = [string]$task.State
    $enabledText = "-"
    if ($state -ne "NotFound" -and $state -ne "ReadError") {
        if ($task.Enabled -is [bool]) {
            $enabledText = if ($task.Enabled) { "Yes" } else { "No" }
        }
        elseif ($state -eq "Disabled") { $enabledText = "No" }
        else { $enabledText = "Yes" }
    }
    [PSCustomObject]@{
        TaskName    = [string]$task.TaskName
        TaskPath    = [string]$task.TaskPath
        State       = $state
        Enabled     = $enabledText
        Author      = [string]$task.Author
        Description = [string]$task.Description
        FullName    = [string]$task.FullName
    }
}
}

function Invoke-WmtScheduledTaskAction {
param(
    [ValidateSet("Enable", "Disable", "Delete")][string]$Action,
    [string]$FullName = "",
    [string]$TaskName = "",
    [string]$TaskPath = ""
)

$id = ConvertTo-WmtScheduledTaskIdentity -FullName $FullName -TaskName $TaskName -TaskPath $TaskPath
if ([string]::IsNullOrWhiteSpace($id.TaskName)) {
    return [PSCustomObject]@{ Success = $false; Task = $id.FullName; Message = "Task name is missing." }
}

try {
    $service = New-WmtTaskSchedulerService
    if (-not $service) { throw "The Task Scheduler service is unavailable." }

    $task = $null
    $openError = ""
    # ITaskService has no GetTask member: open the task's folder, then fetch
    # the task by name (the same two-step the device-health probe uses).
    try {
        # Same contract as the row lookup: GetFolder must not receive a
        # trailing backslash, so strip the display-form TaskPath here too.
        $folderPath = ([string]$id.TaskPath).TrimEnd("\")
        if ([string]::IsNullOrWhiteSpace($folderPath)) { $folderPath = "\" }
        $folder = $service.GetFolder($folderPath)
        $task = $folder.GetTask([string]$id.TaskName)
    } catch { $openError = [string]$_.Exception.Message }
    if (-not $task) {
        if (-not [string]::IsNullOrWhiteSpace($openError)) { throw "Could not open task $($id.FullName): $openError" }
        throw "Task not found: $($id.FullName)"
    }

    switch ($Action) {
        # Flipping IRegisteredTask.Enabled persists immediately - the same
        # switch the schtasks /Change command flips - without any CIM layer.
        "Enable" { $task.Enabled = $true }
        "Disable" { $task.Enabled = $false }
        "Delete" {
            $folderPath = ([string]$id.TaskPath).TrimEnd("\")
            if ([string]::IsNullOrWhiteSpace($folderPath)) { $folderPath = "\" }
            $folder = $service.GetFolder($folderPath)
            $folder.DeleteTask([string]$id.TaskName, 0)
        }
    }

    [PSCustomObject]@{ Success = $true; Task = $id.FullName; Message = "$Action succeeded." }
}
catch {
    [PSCustomObject]@{ Success = $false; Task = $id.FullName; Message = $_.Exception.Message }
}
}

function Show-WmtScheduledTasksDialog {
param(
    [string]$Title = "Scheduled Tasks",
    [string[]]$FullPaths = @(),
    [string[]]$TaskPaths = @(),
    [string[]]$TelemetryFolders = @()
)

# Guard for the one caller contract this dialog has: show the live state
# of the exact tasks the two telemetry buttons toggle. The View Tasks
# button already passes that list ($script:TelemetryTasks, nine paths);
# if a future caller or a scope surprise ever reaches the dialog with no
# paths at all, fall back to the canonical telemetry list so the grid can
# never open empty.
if (@($FullPaths).Count -eq 0 -and @($TaskPaths).Count -eq 0 -and $script:TelemetryTasks) {
    $FullPaths = @($script:TelemetryTasks)
}
if (@($TelemetryFolders).Count -eq 0 -and $script:WmtTelemetryTaskFolders) {
    # No folders passed: default to the live all-telemetry enumeration.
    $TelemetryFolders = @($script:WmtTelemetryTaskFolders)
}
$enumerateNote = if (@($TelemetryFolders).Count -gt 0) { " + live enumeration of $(@($TelemetryFolders).Count) telemetry folder(s)" } else { "" }
Write-GuiLog "[Scheduled Tasks] Dialog '$Title' opened with $(@($FullPaths).Count) path(s)$enumerateNote."

$content = @'
<Grid Margin="16">
    <Grid.RowDefinitions>
        <RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <DataGrid Name="dgTasks" IsReadOnly="True" SelectionMode="Extended" CanUserAddRows="False" CanUserDeleteRows="False" AlternationCount="2"/>
    <TextBlock Name="lblStatus" Grid.Row="1" Foreground="{DynamicResource TextSecondary}" Margin="0,10,0,0"/>
    <ContentControl Name="TaskActionsHost" Grid.Row="2"/>
</Grid>
'@
$dialog = New-WmtWindowFromXaml -Title $Title -ContentXaml $content -Width 960 -Height 560 -MinWidth 760 -MinHeight 420
$dialog.FindName('TaskActionsHost').Content = New-WmtActionButtonPanel -Owner $dialog -Buttons @(
    @{Name='btnOpenScheduler'; Content='Open Task Scheduler'},
    @{Name='btnRefresh'; Content='Refresh'; Background='Accent'; Foreground='AccentText'},
    @{Name='btnEnable'; Content='Enable'; Background='Success'; Foreground='SuccessText'},
    @{Name='btnDisable'; Content='Disable'; Background='Warning'; Foreground='WarningText'},
    @{Name='btnClose'; Content='Close'; IsCancel=$true})
$dg = $dialog.FindName("dgTasks")
$lblStatus = $dialog.FindName("lblStatus")
$btnOpenScheduler = $dialog.FindName("btnOpenScheduler")
$btnRefresh = $dialog.FindName("btnRefresh")
$btnEnable = $dialog.FindName("btnEnable")
$btnDisable = $dialog.FindName("btnDisable")
$btnClose = $dialog.FindName("btnClose")

# Two reads of the same exact paths: the direct synchronous one first
# (milliseconds), and - only if it comes back empty or throws - the
# background transport (Start-WmtScheduledTaskViewQuery), which re-reads
# the paths through the pooled-runspace mechanism the Disable/Restore
# telemetry buttons use: the one scheduled-task transport that is
# field-proven on every machine this tool has been reported from. Every
# failure mode lands somewhere visible: missing or unreadable tasks
# become explicit rows (NotFound / ReadError), and a total read failure
# goes to the status line instead of an eternal spinner.
Set-WmtDataGridColumns -DataGrid $dg -Columns @("TaskName", "TaskPath", "State", "Enabled", "Author", "Description", "FullName") -Widths @{ TaskName = "*"; TaskPath = 260; State = 100; Enabled = 80; Author = 180; Description = "2*" } -Hidden @("FullName")

$load = {
    try {
        Set-WmtBusyCursor -Busy
        $lblStatus.Text = "Loading tasks..."
        $rows = @(Get-WmtScheduledTaskRows -FullPaths $FullPaths -TaskPaths $TaskPaths -TelemetryFolders $TelemetryFolders)
        $dg.ItemsSource = @($rows)
        Write-GuiLog "[Scheduled Tasks] View loaded $($rows.Count) row(s)."
        if ($rows.Count -gt 0) {
            $lblStatus.Text = "$($rows.Count) task(s)"
        }
        else {
            # A zero-row direct read should be impossible (every requested
            # path yields at least a NotFound/ReadError row); treat it as
            # a failed read and retry through the background transport.
            $lblStatus.Text = "Direct read returned nothing - querying in background..."
            Start-WmtScheduledTaskViewQuery -FullPaths @($FullPaths) -TelemetryFolders @($TelemetryFolders) -DataGrid $dg -StatusBlock $lblStatus
        }
    }
    catch {
        # The direct UI-thread read threw: retry through the transport the
        # Disable/Restore buttons use before declaring failure.
        Write-GuiLog "[Scheduled Tasks] Direct read failed, retrying in background: $($_.Exception.Message)"
        try {
            $lblStatus.Text = "Retrying in background: $($_.Exception.Message)"
            Start-WmtScheduledTaskViewQuery -FullPaths @($FullPaths) -TelemetryFolders @($TelemetryFolders) -DataGrid $dg -StatusBlock $lblStatus
        }
        catch {
            Write-GuiLog "[Scheduled Tasks] Load failed: $($_.Exception.Message)"
            $lblStatus.Text = "Failed to load tasks: $($_.Exception.Message)"
        }
    }
    finally {
        Set-WmtBusyCursor
    }
}.GetNewClosure()
$apply = {
    param([string]$Action)
    $selected = @(Get-WmtDataGridSelectedRows -DataGrid $dg)
    if ($selected.Count -eq 0) { return }
    $failures = @()
    try {
        Set-WmtBusyCursor -Busy
        foreach ($row in $selected) {
            $result = Invoke-WmtScheduledTaskAction -Action $Action -TaskName ([string]$row.TaskName) -TaskPath ([string]$row.TaskPath)
            if ($result.Success) {
                Write-GuiLog "[Scheduled Tasks] $($Action)d: $($result.Task)"
            }
            else {
                $failures += "$($result.Task): $($result.Message)"
            }
        }
    }
    finally {
        Set-WmtBusyCursor
    }
    # Flip the task, then re-read everything from Task Scheduler: flipping
    # IRegisteredTask.Enabled is exactly what schtasks /Change does, but the
    # grid should show what the scheduler reports now, not what we asked it
    # to do.
    & $load
    if ($failures.Count -gt 0) {
        Show-WmtMessageBox -Owner $dialog -Message ($failures -join "`r`n") -Title "Scheduled Tasks" -Image Warning | Out-Null
    }
}.GetNewClosure()

$btnOpenScheduler.Add_Click({
    # The dialog lists everything itself, but one click also hands over the
    # real Task Scheduler (taskschd.msc) for anyone who wants the native
    # view. The console cannot be deep-linked to a specific task from the
    # command line - taskschd.msc's only documented switches are the remote
    # /s /u /p, and it ignores anything else - so it always opens on the
    # root view and the user navigates to the task from there.
    try {
        Start-Process -FilePath "taskschd.msc" -ErrorAction Stop
        Write-GuiLog "[Scheduled Tasks] Opened Windows Task Scheduler (taskschd.msc)."
    }
    catch {
        Write-GuiLog "[Scheduled Tasks] Could not open Task Scheduler: $($_.Exception.Message)"
        Show-WmtMessageBox -Owner $dialog -Message "Could not open Task Scheduler: $($_.Exception.Message)" -Title "Scheduled Tasks" -Image Warning | Out-Null
    }
}.GetNewClosure())
$btnRefresh.Add_Click({ & $load }.GetNewClosure())
$btnEnable.Add_Click({ & $apply "Enable" }.GetNewClosure())
$btnDisable.Add_Click({ & $apply "Disable" }.GetNewClosure())
$btnClose.Add_Click({ $dialog.Close() }.GetNewClosure())
# Bind one dispatcher turn after the window has been realized. WPF DataGrid
# can throw while measuring DataView rows during the initial layout pass.
$dialog.Add_ContentRendered({
    $dialog.Dispatcher.BeginInvoke(
        [Action] { & $load },
        [System.Windows.Threading.DispatcherPriority]::Background
    ) | Out-Null
}.GetNewClosure())
$dialog.ShowDialog() | Out-Null
}

function Start-WmtScheduledTaskBatchAction {
param(
    [Parameter(Mandatory = $true)][ValidateSet("Enable", "Disable")][string]$Action,
    [Parameter(Mandatory = $true)][string[]]$FullPaths,
    [Parameter(Mandatory = $true)][string]$StartMessage,
    [Parameter(Mandatory = $true)][string]$DoneMessage
)

# Enable/Disable for a batch of tasks (telemetry toggles) runs in a background
# runspace through the COM engine (exact-path lookups, no CIM layer) and
# streams its results back through a collector timer.
if ($script:WmtTaskBatchAsync) {
    Write-GuiLog "[Scheduled Tasks] A task action is already in progress."
    return
}

# The background runspace cannot see this script's scope, so the helper
# functions are handed over as text. ${function:X} yields the body only (no
# "function NAME" wrapper), so each definition is re-wrapped here; reading the
# live definitions keeps the copies in sync automatically.
$taskHelpers = @(
    "function ConvertTo-WmtScheduledTaskIdentity {",
    ${function:ConvertTo-WmtScheduledTaskIdentity},
    "}",
    "function New-WmtTaskSchedulerService {",
    ${function:New-WmtTaskSchedulerService},
    "}",
    "function Invoke-WmtScheduledTaskAction {",
    ${function:Invoke-WmtScheduledTaskAction},
    "}"
) -join "`r`n"

Write-GuiLog $StartMessage
Set-WmtBusyCursor -Busy

try {
    $ps = New-WmtPooledPowerShell
    [void]$ps.AddScript({
        param($Helpers, [string]$Action, $Tasks)
        # Dot-source the helper definitions into this runspace.
        if ($Helpers) { . ([scriptblock]::Create($Helpers)) }
        foreach ($task in @($Tasks)) {
            $result = Invoke-WmtScheduledTaskAction -Action $Action -FullName $task
            if ($result.Success) {
                Write-Output "LOG:$($Action)d: $($result.Task)"
            }
            else {
                Write-Output "LOG:Failed to $($Action.ToLower()) $($result.Task): $($result.Message)"
            }
        }
    }).AddArgument($taskHelpers).AddArgument($Action).AddArgument($FullPaths)
    $script:WmtTaskBatchPs = $ps
    $script:WmtTaskBatchAsync = $ps.BeginInvoke()
}
catch {
    Write-GuiLog "[Scheduled Tasks] Failed to start task action: $($_.Exception.Message)"
    try { if ($script:WmtTaskBatchPs) { $script:WmtTaskBatchPs.Dispose() } } catch {}
    $script:WmtTaskBatchPs = $null
    $script:WmtTaskBatchAsync = $null
    Set-WmtBusyCursor
    return
}

$script:WmtTaskBatchTimer = $null
$script:WmtTaskBatchDoneMessage = $DoneMessage
Register-WmtUiPollOperation -Name "ScheduledTaskBatch" `
    -TestComplete { $script:WmtTaskBatchAsync -and $script:WmtTaskBatchAsync.IsCompleted } `
    -OnComplete {
        try {
            $results = @($script:WmtTaskBatchPs.EndInvoke($script:WmtTaskBatchAsync))
            foreach ($line in $results) {
                if ($line -is [string] -and $line.StartsWith("LOG:")) { Write-GuiLog $line.Substring(4) }
            }
            Write-GuiLog $script:WmtTaskBatchDoneMessage
        }
        catch { Write-GuiLog "[Scheduled Tasks] Task action failed: $($_.Exception.Message)" }
        finally {
            try { if ($script:WmtTaskBatchPs) { $script:WmtTaskBatchPs.Dispose() } } catch {}
            $script:WmtTaskBatchPs = $null
            $script:WmtTaskBatchAsync = $null
            $script:WmtTaskBatchDoneMessage = $null
            Set-WmtBusyCursor
        }
    } -OnError {
        param($Operation, $ErrorRecord)
        Write-GuiLog "[Scheduled Tasks] Batch monitor failed: $($ErrorRecord.Exception.Message)"
        $failedPs = $script:WmtTaskBatchPs
        $failedAsync = $script:WmtTaskBatchAsync
        $script:WmtTaskBatchPs = $null
        $script:WmtTaskBatchAsync = $null
        $script:WmtTaskBatchDoneMessage = $null
        Set-WmtBusyCursor
        if ($failedPs) { Stop-WmtPowerShellInvocationAsync -PowerShell $failedPs -Invocation $failedAsync -Name "Scheduled task batch monitor" }
    } | Out-Null
}

function Start-WmtScheduledTaskViewQuery {
param(
    [string[]]$FullPaths = @(),
    [string[]]$TelemetryFolders = @(),
    $DataGrid,
    $StatusBlock
)

# Background fallback for the View Tasks dialog. The synchronous UI-thread
# read normally answers in milliseconds, but if it ever returns zero rows or
# throws, this query re-reads the same exact paths through the SAME transport
# the Disable/Restore telemetry buttons use (pooled runspace, helper functions
# handed over as text, 250ms collector timer): the scheduled-task path that is
# field-proven on machines where the UI-thread read has never been confirmed.
# Each row comes back as one compact JSON string, so no live object crosses
# the runspace boundary.
if (@($FullPaths).Count -eq 0 -and @($TelemetryFolders).Count -eq 0) { return }
if (-not $DataGrid) { return }
if ($script:WmtTaskViewAsync) { return }

$taskHelpers = @(
    "function ConvertTo-WmtScheduledTaskIdentity {",
    ${function:ConvertTo-WmtScheduledTaskIdentity},
    "}",
    "function New-WmtTaskSchedulerService {",
    ${function:New-WmtTaskSchedulerService},
    "}",
    "function ConvertFrom-WmtRegisteredTask {",
    ${function:ConvertFrom-WmtRegisteredTask},
    "}",
    "function Get-WmtAllRegisteredTasks {",
    ${function:Get-WmtAllRegisteredTasks},
    "}",
    "function Get-WmtScheduledTaskRows {",
    ${function:Get-WmtScheduledTaskRows},
    "}"
) -join "`r`n"

$script:WmtTaskViewGrid = $DataGrid
$script:WmtTaskViewStatus = $StatusBlock

Write-GuiLog "[Scheduled Tasks] Background view query started for $(@($FullPaths).Count) path(s), $(@($TelemetryFolders).Count) telemetry folder(s)."

try {
    $ps = New-WmtPooledPowerShell
    [void]$ps.AddScript({
        param($Helpers, $Tasks, $Folders)
        # Dot-source the helper definitions into this runspace.
        if ($Helpers) { . ([scriptblock]::Create($Helpers)) }
        try {
            $rows = @(Get-WmtScheduledTaskRows -FullPaths $Tasks -TelemetryFolders $Folders)
            foreach ($row in @($rows)) {
                Write-Output ("ROW:" + ($row | ConvertTo-Json -Compress))
            }
        }
        catch {
            Write-Output ("ERR:" + [string]$_.Exception.Message)
        }
    }).AddArgument($taskHelpers).AddArgument($FullPaths).AddArgument($TelemetryFolders)
    $script:WmtTaskViewPs = $ps
    $script:WmtTaskViewAsync = $ps.BeginInvoke()
}
catch {
    Write-GuiLog "[Scheduled Tasks] Failed to start background view query: $($_.Exception.Message)"
    try { if ($script:WmtTaskViewPs) { $script:WmtTaskViewPs.Dispose() } } catch {}
    $script:WmtTaskViewPs = $null
    $script:WmtTaskViewAsync = $null
    $script:WmtTaskViewGrid = $null
    $script:WmtTaskViewStatus = $null
    return
}

$script:WmtTaskViewTimer = $null
Register-WmtUiPollOperation -Name "ScheduledTaskView" `
    -TestComplete { $script:WmtTaskViewAsync -and $script:WmtTaskViewAsync.IsCompleted } `
    -OnComplete {
        try {
            $results = @($script:WmtTaskViewPs.EndInvoke($script:WmtTaskViewAsync))
            $rowObjects = @()
            foreach ($line in $results) {
                if ($line -isnot [string]) { continue }
                if ($line.StartsWith("ROW:")) {
                    try { $rowObjects += ($line.Substring(4) | ConvertFrom-Json) } catch {}
                }
                elseif ($line.StartsWith("ERR:")) {
                    Write-GuiLog "[Scheduled Tasks] Background view query failed: $($line.Substring(4))"
                }
            }
            $dg = $script:WmtTaskViewGrid
            $lbl = $script:WmtTaskViewStatus
            if ($dg) { $dg.ItemsSource = @($rowObjects) }
            if ($lbl) {
                $lbl.Text = if ($rowObjects.Count -gt 0) { "$($rowObjects.Count) task(s) (background)" } else { "No scheduled tasks found. Try running WMT as administrator." }
            }
            Write-GuiLog "[Scheduled Tasks] View loaded $($rowObjects.Count) row(s) via background query."
        }
        catch { Write-GuiLog "[Scheduled Tasks] Background view result failed: $($_.Exception.Message)" }
        finally {
            try { if ($script:WmtTaskViewPs) { $script:WmtTaskViewPs.Dispose() } } catch {}
            $script:WmtTaskViewPs = $null
            $script:WmtTaskViewAsync = $null
            $script:WmtTaskViewGrid = $null
            $script:WmtTaskViewStatus = $null
        }
    } -OnError {
        param($Operation, $ErrorRecord)
        Write-GuiLog "[Scheduled Tasks] View monitor failed: $($ErrorRecord.Exception.Message)"
        $failedPs = $script:WmtTaskViewPs
        $failedAsync = $script:WmtTaskViewAsync
        $script:WmtTaskViewPs = $null
        $script:WmtTaskViewAsync = $null
        $script:WmtTaskViewGrid = $null
        $script:WmtTaskViewStatus = $null
        if ($failedPs) { Stop-WmtPowerShellInvocationAsync -PowerShell $failedPs -Invocation $failedAsync -Name "Scheduled task view monitor" }
    } | Out-Null
}

function Get-WmtThemeHex {
param(
    [string]$Key,
    [string]$Fallback = "#8B949E"
)

$resourceKey = Resolve-WmtThemeResourceKey $Key
if (-not $resourceKey) { $resourceKey = $Key }

if ($script:ThemePalettes) {
    $theme = if ($script:CurrentTheme -and $script:ThemePalettes.ContainsKey($script:CurrentTheme)) { $script:CurrentTheme } else { "dark" }
    $palette = $script:ThemePalettes[$theme]
    if ($palette -and $palette.ContainsKey($resourceKey)) { return $palette[$resourceKey] }
}

$darkFallback = @{
    BgDark        = "#0D1117"
    BgPanel       = "#161B22"
    BgElevated    = "#21262D"
    BgHover       = "#30363D"
    BorderBrush   = "#30363D"
    Accent        = "#58A6FF"
    AccentHover   = "#79C0FF"
    TextPrimary   = "#E6EDF3"
    TextSecondary = "#8B949E"
    TextMuted     = "#6E7681"
    Success       = "#238636"
    SuccessHover  = "#2EA043"
    Danger        = "#DA3633"
    DangerHover   = "#F85149"
    Warning       = "#D29922"
    WarningHover  = "#E3B341"
    Info          = "#1F6FEB"
    AccentText    = "#0D1117"
    SuccessText   = "#F6FFFA"
    DangerText    = "#FFF5F5"
    WarningText   = "#0D1117"
    InfoText      = "#F0F6FC"
}

if ($darkFallback.ContainsKey($resourceKey)) { return $darkFallback[$resourceKey] }
if ($Key -match "^#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$") { return $Key }
return $Fallback
}

function New-WmtStorageTextBlock {
param(
    [string]$Text,
    [string]$Color = "TextSecondary",
    [double]$FontSize = 12,
    [string]$FontWeight = "Normal",
    [string]$Margin = "0"
)

$tb = New-Object System.Windows.Controls.TextBlock
$tb.Text = $Text
Set-WmtThemedBrush -Object $tb -Property ([System.Windows.Controls.TextBlock]::ForegroundProperty) -ColorOrKey $Color
$tb.FontSize = $FontSize
$tb.Margin = $Margin
$tb.TextWrapping = "Wrap"
$tb.LineHeight = 17
if ($FontWeight -eq "SemiBold") { $tb.FontWeight = [System.Windows.FontWeights]::SemiBold }
elseif ($FontWeight -eq "Bold") { $tb.FontWeight = [System.Windows.FontWeights]::Bold }
return $tb
}

function Open-MyDeviceDriveRoot {
param([string]$Drive)

if ([string]::IsNullOrWhiteSpace($Drive)) { return }
$driveRoot = if ($Drive.EndsWith("\")) { $Drive } elseif ($Drive.EndsWith(":")) { "$Drive\" } else { "$Drive\" }

if (-not (Test-Path -LiteralPath $driveRoot)) {
    Write-GuiLog "[Storage] Drive root not found: $driveRoot"
    return
}

try {
    Start-Process -FilePath "explorer.exe" -ArgumentList "`"$driveRoot`""
    Write-GuiLog "[Storage] Opened $driveRoot"
}
catch {
    Write-GuiLog "[Storage] Failed to open $driveRoot`: $($_.Exception.Message)"
}
}

function Set-MyDeviceStorageDetails {
param($Devices)

$panel = Get-Ctrl "pnlDeviceStorageList"
$summary = Get-Ctrl "txtDeviceStorage"
if (-not $panel) { return }

$panel.Children.Clear()
$deviceList = @($Devices)

if (-not $deviceList -or $deviceList.Count -eq 0) {
    if ($summary) { $summary.Text = "No fixed storage volumes found." }
    return
}

if ($summary) { $summary.Text = "Fixed volumes detected: $($deviceList.Count)" }

for ($i = 0; $i -lt $deviceList.Count; $i++) {
    $d = $deviceList[$i]

    $header = New-Object System.Windows.Controls.Grid
    $header.Margin = if ($i -eq 0) { "0,8,0,0" } else { "0,12,0,0" }
    $colMain = New-Object System.Windows.Controls.ColumnDefinition
    $colMain.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    $colHealth = New-Object System.Windows.Controls.ColumnDefinition
    $colHealth.Width = [System.Windows.GridLength]::Auto
    [void]$header.ColumnDefinitions.Add($colMain)
    [void]$header.ColumnDefinitions.Add($colHealth)

    $driveRoot = if ([string]$d.Drive -match "\\$") { [string]$d.Drive } else { "$($d.Drive)\" }
    $header.Cursor = [System.Windows.Input.Cursors]::Hand
    $header.ToolTip = "Open $driveRoot"
    $header.Add_MouseLeftButtonUp({ Open-MyDeviceDriveRoot -Drive $driveRoot }.GetNewClosure())

    $driveTitle = New-WmtStorageTextBlock -Text ("{0}  {1}" -f $d.Drive, $d.Label) -Color "Accent" -FontSize 13 -FontWeight "SemiBold"
    [void]$header.Children.Add($driveTitle)

    $healthText = New-WmtStorageTextBlock -Text $d.Health -Color $d.HealthBrush -FontSize 12 -FontWeight "SemiBold" -Margin "8,0,0,0"
    [System.Windows.Controls.Grid]::SetColumn($healthText, 1)
    [void]$header.Children.Add($healthText)
    [void]$panel.Children.Add($header)

    [void]$panel.Children.Add((New-WmtStorageTextBlock -Text $d.Hardware -Color "TextPrimary" -FontSize 12 -Margin "0,4,0,0"))
    [void]$panel.Children.Add((New-WmtStorageTextBlock -Text $d.Meta -Color "TextSecondary" -FontSize 11 -Margin "0,2,0,0"))
    [void]$panel.Children.Add((New-WmtStorageTextBlock -Text $d.Operational -Color "TextMuted" -FontSize 11 -Margin "0,2,0,0"))

    $bar = New-Object System.Windows.Controls.ProgressBar
    $bar.Minimum = 0
    $bar.Maximum = 100
    $bar.Value = [double]$d.FreePercent
    $bar.Height = 7
    $bar.Margin = "0,7,0,2"
    Set-WmtThemedBrush -Object $bar -Property ([System.Windows.Controls.Control]::ForegroundProperty) -ColorOrKey $d.FreeBrush -FallbackKey "Accent"
    Set-WmtThemedBrush -Object $bar -Property ([System.Windows.Controls.Control]::BackgroundProperty) -ColorOrKey "BorderBrush"
    [void]$panel.Children.Add($bar)

    [void]$panel.Children.Add((New-WmtStorageTextBlock -Text $d.FreeText -Color $d.FreeBrush -FontSize 12 -FontWeight "SemiBold" -Margin "0,2,0,0"))

    if ($i -lt ($deviceList.Count - 1)) {
        $separator = New-Object System.Windows.Controls.Border
        $separator.Height = 1
        Set-WmtThemedBrush -Object $separator -Property ([System.Windows.Controls.Border]::BackgroundProperty) -ColorOrKey "BorderBrush"
        $separator.Margin = "0,10,0,0"
        [void]$panel.Children.Add($separator)
    }
}
}

