}

function ConvertTo-WmtUpdateRowClipboardText {
param([object[]]$Items)

$rows = @($Items | Where-Object { $null -ne $_ })
if ($rows.Count -eq 0) { return "" }

$preferredProperties = @(
    "Source",
    "Name",
    "Id",
    "Version",
    "Available",
    "IsChecked",
    "WUIsOptional",
    "VersionSort",
    "AvailableSort",
    "RawAvailable",
    "LibraryPath",
    "InstallDir",
    "ManifestPath",
    "ExecutablePath",
    "Platform"
)
$preferredSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach ($propertyName in $preferredProperties) { [void]$preferredSet.Add($propertyName) }

$formatValue = {
    param($Value)
    if ($null -eq $Value) { return "" }
    if ($Value -is [System.Array]) {
        return ((@($Value) | ForEach-Object { [string]$_ }) -join ", ") -replace '\r?\n', ' '
    }
    return (([string]$Value) -replace '\r?\n', ' ').Trim()
}

$lines = [System.Collections.Generic.List[string]]::new()
[void]$lines.Add("WMT Update Row Data")
[void]$lines.Add("Count: $($rows.Count)")
[void]$lines.Add("Copied: $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))")

$rowIndex = 0
foreach ($row in $rows) {
    $rowIndex++
    [void]$lines.Add("")
    [void]$lines.Add("Row $rowIndex")

    foreach ($propertyName in $preferredProperties) {
        $property = $row.PSObject.Properties[$propertyName]
        if (-not $property) { continue }
        [void]$lines.Add("${propertyName}: $(& $formatValue $property.Value)")
    }

    $extraProperties = @($row.PSObject.Properties | Where-Object { -not $preferredSet.Contains($_.Name) } | Sort-Object Name)
    foreach ($property in $extraProperties) {
        [void]$lines.Add("$($property.Name): $(& $formatValue $property.Value)")
    }
}

return [string]::Join([Environment]::NewLine, $lines)
}

function Copy-WmtUpdateSelectedRowsToClipboard {
param(
    [System.Windows.Controls.ListView]$ListView = $lstWinget
)

if (-not $ListView) { return $false }
$selectedRows = @($ListView.SelectedItems | Where-Object { $null -ne $_ })
if ($selectedRows.Count -eq 0 -and $ListView.SelectedItem) {
    $selectedRows = @($ListView.SelectedItem)
}
if ($selectedRows.Count -eq 0) {
    Write-GuiLog "Copy row data skipped: no update row selected."
    return $false
}

$text = ConvertTo-WmtUpdateRowClipboardText -Items $selectedRows
if ([string]::IsNullOrWhiteSpace($text)) { return $false }

try {
    [System.Windows.Clipboard]::SetText($text)
    Write-GuiLog "Copied $($selectedRows.Count) update row(s) to clipboard."
    return $true
}
catch {
    Write-GuiLog "ERROR: Could not copy update row data: $($_.Exception.Message)"
    return $false
}
}

function Copy-WmtLibrarySelectedRowsToClipboard {
param([System.Windows.Controls.ListView]$ListView = $lstLibrary)

# Ctrl+C support for the Your Library list: copies the selected row(s) as
# tab-separated lines (Source, Name, ID, Installed, Latest, IsUe) that
# paste cleanly into any editor or spreadsheet - the trailing IsUe column
# (True/False on Epic rows) makes the UE/Fab tagging verifiable straight
# from a paste. Falls back to the focused row
# when nothing is selected. Set-Clipboard can lose a race with another
# app holding the clipboard open, so the write is retried briefly.
if (-not $ListView) { return $false }
$selectedRows = @($ListView.SelectedItems | Where-Object { $null -ne $_ })
if ($selectedRows.Count -eq 0 -and $ListView.SelectedItem) { $selectedRows = @($ListView.SelectedItem) }
if ($selectedRows.Count -eq 0) {
    Write-GuiLog "Copy skipped: no library row selected."
    return $false
}

$columns = @("Source", "Name", "Id", "Version", "Available", "IsUe")
$lines = [System.Collections.Generic.List[string]]::new()
foreach ($row in $selectedRows) {
    $cells = @()
    foreach ($column in $columns) {
        $value = ""
        try {
            $property = $row.PSObject.Properties[$column]
            if ($property) { $value = [string]$property.Value }
        }
        catch {}
        $cells += (($value -replace '\r?\n', ' ').Trim())
    }
    [void]$lines.Add(($cells -join "`t"))
}
if ($lines.Count -eq 0) { return $false }
$text = [string]::Join([Environment]::NewLine, $lines)

for ($attempt = 1; $attempt -le 5; $attempt++) {
    try {
        [System.Windows.Clipboard]::SetText($text)
        Write-GuiLog "Copied $($lines.Count) library line(s) to clipboard."
        return $true
    }
    catch {
        if ($attempt -eq 5) {
            Write-GuiLog "ERROR: Could not copy library lines: $($_.Exception.Message)"
            return $false
        }
        Start-Sleep -Milliseconds 40
    }
}
return $false
}

function ConvertTo-WmtProcessArgument {
param([string]$Value)

if ($null -eq $Value) { return '""' }
return '"' + ($Value -replace '"', '\"') + '"'
}

function Show-WingetPackageManifest {
param([object]$Item)

if (-not (Test-WingetManifestSupportedItem $Item)) {
    [System.Windows.MessageBox]::Show(
        "App manifests are only available for winget and Microsoft Store packages.",
        "Manifest Unavailable",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Information
    ) | Out-Null
    return
}

$name = [string]$Item.Name
$id = [string]$Item.Id
$source = ([string]$Item.Source).ToLowerInvariant()
if ([string]::IsNullOrWhiteSpace($name)) { $name = $id }

Write-GuiLog "Loading app manifest for $name ($id) from $source..."
if ($lblWingetStatus) {
    $lblWingetStatus.Text = "Loading manifest for $name..."
    $lblWingetStatus.Visibility = "Visible"
}
Set-WmtBusyCursor -Busy

$finishManifestUi = {
    Set-WmtBusyCursor
    if ($lblWingetStatus) {
        $lblWingetStatus.Text = "Ready"
        $lblWingetStatus.Visibility = "Hidden"
    }
}.GetNewClosure()

$manifestComplete = {
    param($results)
    try {
        $payload = @($results | Where-Object { $_ -and $_.PSObject.Properties["Text"] } | Select-Object -Last 1)
        if ($payload.Count -eq 0) {
            Write-GuiLog "Manifest lookup failed for $id (no result)."
            return
        }

        $result = $payload[0]
        if ([bool]$result.Success) {
            Write-GuiLog "Manifest loaded for $id."
        }
        else {
            Write-GuiLog "Manifest lookup failed for $id."
        }

        $header = "Package: $name`r`nID: $id`r`nSource: $source`r`nCommand: winget show --id `"$id`" --source $source --exact`r`n"
        $separator = ("-" * 80)
        & $finishManifestUi
        Show-TextDialog -Title "App Manifest - $name" -Text "$header`r`n$separator`r`n`r`n$($result.Text)"
    }
    finally {
        & $finishManifestUi
    }
}.GetNewClosure()

$manifestError = {
    param($err)
    & $finishManifestUi
    $message = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }
    Write-GuiLog ("Manifest lookup failed for " + $id + ": " + $message)
}.GetNewClosure()

$workerArgs = [object[]]@($id, $source)
Invoke-WmtUiBackgroundCommand -Name ("WingetManifest_" + [guid]::NewGuid().ToString("N")) -Msg "Loading app manifest for $name..." -TimeoutMs 50000 -SuppressResultLog -Sb {
    param(
        [string]$PackageId,
        [string]$PackageSource
    )

    $quote = [char]34
    $argsLine = "show --id " + $quote + $PackageId + $quote +
        " --source " + $quote + $PackageSource + $quote +
        " --exact --accept-source-agreements --disable-interactivity"

    $proc = $null
    try {
        $pInfo = [System.Diagnostics.ProcessStartInfo]::new()
        $pInfo.FileName = "winget"
        $pInfo.Arguments = $argsLine
        $pInfo.RedirectStandardOutput = $true
        $pInfo.RedirectStandardError = $true
        $pInfo.UseShellExecute = $false
        $pInfo.CreateNoWindow = $true
        $pInfo.StandardOutputEncoding = [System.Text.UTF8Encoding]::new($false)
        $pInfo.StandardErrorEncoding = [System.Text.UTF8Encoding]::new($false)

        $proc = [System.Diagnostics.Process]::Start($pInfo)
        $outTask = $proc.StandardOutput.ReadToEndAsync()
        $errTask = $proc.StandardError.ReadToEndAsync()

        if (-not $proc.WaitForExit(45000)) {
            try { $proc.Kill() } catch {}
            try { [void]$proc.WaitForExit(2000) } catch {}
            return [PSCustomObject]@{
                Success  = $false
                ExitCode = $null
                Text     = "Timed out while loading the manifest for $PackageId."
            }
        }

        $out = $outTask.GetAwaiter().GetResult()
        $err = $errTask.GetAwaiter().GetResult()
        $parts = @()
        if (-not [string]::IsNullOrWhiteSpace($out)) { $parts += $out.TrimEnd() }
        if (-not [string]::IsNullOrWhiteSpace($err)) { $parts += $err.TrimEnd() }
        $manifestText = ($parts -join "`r`n`r`n")
        if ([string]::IsNullOrWhiteSpace($manifestText)) {
            $manifestText = "No manifest output was returned for $PackageId."
        }

        [PSCustomObject]@{
            Success  = ($proc.ExitCode -eq 0)
            ExitCode = $proc.ExitCode
            Text     = $manifestText
        }
    }
    catch {
        [PSCustomObject]@{
            Success  = $false
            ExitCode = $null
            Text     = "Failed to load manifest for $PackageId.`r`n`r`n$($_.Exception.Message)"
        }
    }
    finally {
        if ($proc) { try { $proc.Dispose() } catch {} }
    }
} -ArgumentList $workerArgs -OnComplete $manifestComplete -OnError $manifestError | Out-Null
}

function Test-ChocoManifestSupportedItem {
param([object]$Item)

if (-not $Item) { return $false }
$id = [string]$Item.Id
$source = ([string]$Item.Source).ToLowerInvariant()
if ([string]::IsNullOrWhiteSpace($id)) { return $false }
return ($source -in @("chocolatey", "choco"))
}

function Get-WmtChocolateyLibRoot {
# Resolve chocolatey's install root (the folder that contains the lib folder)
$candidates = @()
if (-not [string]::IsNullOrWhiteSpace($env:ChocolateyInstall)) { $candidates += $env:ChocolateyInstall }
if (-not [string]::IsNullOrWhiteSpace($env:ProgramData)) { $candidates += (Join-Path $env:ProgramData "chocolatey") }
$candidates += "C:\ProgramData\chocolatey"
foreach ($candidate in $candidates) {
    if (Test-Path -LiteralPath $candidate -PathType Container) { return $candidate }
}
return $null
}

function Get-ChocoManifestPath {
param([object]$Item)

if (-not (Test-ChocoManifestSupportedItem $Item)) { return $null }
$id = ([string]$Item.Id).Trim()
if ([string]::IsNullOrWhiteSpace($id)) { return $null }
$libRoot = Get-WmtChocolateyLibRoot
if ([string]::IsNullOrWhiteSpace($libRoot)) { return $null }
$pkgDir = Join-Path (Join-Path $libRoot "lib") $id
if (-not (Test-Path -LiteralPath $pkgDir -PathType Container)) { return $null }

# Standard layout: lib\<id>\<id>.nuspec
$primary = Join-Path $pkgDir "$id.nuspec"
if (Test-Path -LiteralPath $primary -PathType Leaf) { return $primary }

# Side-by-side or versioned layouts keep the nuspec deeper in the package folder
try {
    $found = @(Get-ChildItem -LiteralPath $pkgDir -Filter "*.nuspec" -Recurse -File -ErrorAction SilentlyContinue | Select-Object -First 1)
    if ($found.Count -gt 0) { return $found[0].FullName }
}
catch {}
return $null
}

function Get-ChocoCommunityPageUrl {
param([object]$Item)

if (-not (Test-ChocoManifestSupportedItem $Item)) { return $null }
$id = ([string]$Item.Id).Trim()
if ([string]::IsNullOrWhiteSpace($id)) { return $null }
try { return "https://community.chocolatey.org/packages/$([System.Uri]::EscapeDataString($id))" }
catch { return "https://community.chocolatey.org/packages/$id" }
}


function Get-WmtPackagePageUrl {
param([object]$Item)

if (-not $Item) { return $null }
$source = ([string]$Item.Source).Trim().ToLowerInvariant()
$id = ([string]$Item.Id).Trim()
$name = ([string]$Item.Name).Trim()
if ([string]::IsNullOrWhiteSpace($id) -and [string]::IsNullOrWhiteSpace($name)) { return $null }

$encodedId = [uri]::EscapeDataString($id)
$encodedName = [uri]::EscapeDataString($name)
switch ($source) {
    "winget"     { return "https://github.com/microsoft/winget-pkgs/search?q=$encodedId&type=code" }
    "msstore"    { return "https://apps.microsoft.com/detail/$encodedId" }
    "chocolatey" { return Get-ChocoCommunityPageUrl -Item $Item }
    "choco"      { return Get-ChocoCommunityPageUrl -Item $Item }
    "npm"        { return "https://www.npmjs.com/package/$encodedId" }
    "dotnet"     { return "https://www.nuget.org/packages/$encodedId" }
    "psmodule"   { return "https://www.powershellgallery.com/packages/$encodedId" }
    "composer"   { return "https://packagist.org/packages/$id" }
    "pip"        { return "https://pypi.org/project/$encodedId/" }
    "scoop"      { return "https://scoop.sh/#/apps?q=$encodedId" }
    "cargo"      { return "https://crates.io/crates/$encodedId" }
    "rust"       { return "https://crates.io/crates/$encodedId" }
    "gem"        { return "https://rubygems.org/gems/$encodedId" }
    "ruby"       { return "https://rubygems.org/gems/$encodedId" }
    "steam"      { return "https://store.steampowered.com/app/$encodedId" }
    "epic"       { return "https://store.epicgames.com/en-US/browse?q=$encodedName&sortBy=relevancy&sortDir=DESC&count=40" }
    "legendary"  { return "https://store.epicgames.com/en-US/browse?q=$encodedName&sortBy=relevancy&sortDir=DESC&count=40" }
    "gog"        { return "https://www.gog.com/en/games?query=$encodedName" }
    "gogdl"      { return "https://www.gog.com/en/games?query=$encodedName" }
}
return $null
}

function Open-WmtPackagePage {
param([object]$Item)

$url = Get-WmtPackagePageUrl -Item $Item
if ([string]::IsNullOrWhiteSpace([string]$url)) {
    Show-WmtMessageBox -Message "No package/store page is known for this provider." -Title "Page Unavailable" -Image Information | Out-Null
    return
}
try { Start-Process $url }
catch {
    Show-WmtMessageBox -Message "Could not open the package page: $($_.Exception.Message)" -Title "Open Page Failed" -Image Warning | Out-Null
}
}

function Test-WmtProviderMetadataSupportedItem {
param([object]$Item)

if (-not $Item) { return $false }
$source = ([string]$Item.Source).Trim().ToLowerInvariant()
$id = ([string]$Item.Id).Trim()
if ([string]::IsNullOrWhiteSpace($id)) { return $false }
return ($source -in @("winget","msstore","chocolatey","choco","npm","dotnet","psmodule","composer","pip","scoop","cargo","rust","gem","ruby"))
}

function Show-WmtPackageProviderMetadata {
param([object]$Item)

if (-not (Test-WmtProviderMetadataSupportedItem -Item $Item)) {
    Show-WmtMessageBox -Message "This provider does not expose a package manifest/metadata view through WMT." -Title "Metadata Unavailable" -Image Information | Out-Null
    return
}

$source = ([string]$Item.Source).Trim().ToLowerInvariant()
$id = ([string]$Item.Id).Trim()
$name = ([string]$Item.Name).Trim()
if ([string]::IsNullOrWhiteSpace($name)) { $name = $id }

if ($source -in @("winget","msstore")) {
    Show-WingetPackageManifest -Item $Item
    return
}

$isInstalled = $false
try { if ($Item.PSObject.Properties["IsInstalled"]) { $isInstalled = [bool]$Item.IsInstalled } } catch {}
if ($source -in @("chocolatey","choco") -and $isInstalled) {
    $localManifest = Find-ChocoPackageManifestPath -Item $Item
    if (-not [string]::IsNullOrWhiteSpace([string]$localManifest)) {
        Show-ChocoPackageManifest -Item $Item
        return
    }
}

Write-GuiLog "Loading provider metadata for $name ($id) from $source..."
if ($lblWingetStatus) {
    $lblWingetStatus.Text = "Loading $source metadata for $name..."
    $lblWingetStatus.Visibility = "Visible"
}

$complete = {
    param($results)
    if ($lblWingetStatus) {
        $lblWingetStatus.Text = "Ready"
        $lblWingetStatus.Visibility = "Hidden"
    }
    $payload = @($results | Where-Object { $_ -and $_.PSObject.Properties["Text"] } | Select-Object -Last 1)
    if ($payload.Count -eq 0) {
        Show-WmtMessageBox -Message "The provider returned no metadata." -Title "Metadata Unavailable" -Image Information | Out-Null
        return
    }
    Show-TextDialog -Title "Package Metadata - $name" -Text ([string]$payload[0].Text)
}.GetNewClosure()

$errorHandler = {
    param($err)
    if ($lblWingetStatus) {
        $lblWingetStatus.Text = "Ready"
        $lblWingetStatus.Visibility = "Hidden"
    }
    $message = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }
    Write-GuiLog "Provider metadata lookup failed for $name ($source / $id): $message"
}.GetNewClosure()

Invoke-WmtUiBackgroundCommand -Name ("PackageMetadata_" + [guid]::NewGuid().ToString("N")) -Msg "Loading $source metadata for $name..." -TimeoutMs 60000 -SuppressResultLog -Sb {
    param([string]$Provider, [string]$PackageId)

    function Invoke-Captured {
        param([string]$FileName, [string]$Arguments)
        $proc = $null
        try {
            $psi = [System.Diagnostics.ProcessStartInfo]::new()
            $psi.FileName = $FileName
            $psi.Arguments = $Arguments
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $psi.StandardOutputEncoding = [System.Text.UTF8Encoding]::new($false)
            $psi.StandardErrorEncoding = [System.Text.UTF8Encoding]::new($false)
            $proc = [System.Diagnostics.Process]::Start($psi)
            $outTask = $proc.StandardOutput.ReadToEndAsync()
            $errTask = $proc.StandardError.ReadToEndAsync()
            if (-not $proc.WaitForExit(50000)) {
                try { $proc.Kill() } catch {}
                return "Metadata command timed out."
            }
            $out = [string]$outTask.GetAwaiter().GetResult()
            $err = [string]$errTask.GetAwaiter().GetResult()
            $text = (($out.TrimEnd()) + $(if (-not [string]::IsNullOrWhiteSpace($err)) { "`r`n`r`n" + $err.TrimEnd() } else { "" })).Trim()
            if ([string]::IsNullOrWhiteSpace($text)) { $text = "The provider returned no metadata." }
            return $text
        }
        catch { return "Metadata lookup failed: $($_.Exception.Message)" }
        finally { if ($proc) { try { $proc.Dispose() } catch {} } }
    }

    $providerKey = $Provider.Trim().ToLowerInvariant()
    $quote = [char]34
    $quotedId = $quote + $PackageId + $quote
    $text = ""
    switch ($providerKey) {
        "chocolatey" { $text = Invoke-Captured -FileName "choco" -Arguments ("info " + $quotedId + " --limit-output") }
        "choco"      { $text = Invoke-Captured -FileName "choco" -Arguments ("info " + $quotedId + " --limit-output") }
        "npm"        { $text = Invoke-Captured -FileName "cmd" -Arguments ("/c npm view " + $quotedId + " --json") }
        "dotnet"     { $text = Invoke-Captured -FileName "dotnet" -Arguments ("tool search " + $quotedId + " --detail --take 1") }
        "composer"   { $text = Invoke-Captured -FileName "cmd" -Arguments ("/c composer show " + $quotedId + " --all") }
        "scoop"      { $text = Invoke-Captured -FileName "powershell.exe" -Arguments ("-NoProfile -Command scoop info " + $quotedId) }
        "cargo"      { $text = Invoke-Captured -FileName "cargo" -Arguments ("info " + $quotedId) }
        "rust"       { $text = Invoke-Captured -FileName "cargo" -Arguments ("info " + $quotedId) }
        "gem"        { $text = Invoke-Captured -FileName "gem" -Arguments ("specification " + $quotedId + " --remote") }
        "ruby"       { $text = Invoke-Captured -FileName "gem" -Arguments ("specification " + $quotedId + " --remote") }
        "psmodule" {
            try {
                $module = Find-Module -Name $PackageId -Repository PSGallery -ErrorAction Stop
                $text = ($module | Format-List Name,Version,Description,Author,CompanyName,ProjectUri,LicenseUri,Repository,PublishedDate,Tags | Out-String -Width 220).Trim()
            }
            catch { $text = "PowerShell Gallery metadata lookup failed: $($_.Exception.Message)" }
        }
        "pip" {
            try {
                $uri = "https://pypi.org/pypi/" + [uri]::EscapeDataString($PackageId) + "/json"
                $response = Invoke-RestMethod -Uri $uri -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop
                $info = $response.info
                $summary = [ordered]@{
                    name             = $info.name
                    version          = $info.version
                    summary          = $info.summary
                    author           = $info.author
                    maintainer       = $info.maintainer
                    license          = $info.license
                    project_url      = $info.project_url
                    package_url      = $info.package_url
                    home_page        = $info.home_page
                    requires_python  = $info.requires_python
                    requires_dist    = $info.requires_dist
                    classifiers      = $info.classifiers
                }
                $text = $summary | ConvertTo-Json -Depth 5
            }
            catch { $text = "PyPI metadata lookup failed: $($_.Exception.Message)" }
        }
        default { $text = "No provider metadata adapter is available." }
    }

    [PSCustomObject]@{ Text = $text }
} -ArgumentList $source, $id -OnComplete $complete -OnError $errorHandler | Out-Null
}

function Open-ChocoCommunityPage {
param([object]$Item)

$url = Get-ChocoCommunityPageUrl -Item $Item
if ([string]::IsNullOrWhiteSpace($url)) {
    [System.Windows.MessageBox]::Show(
        "The Chocolatey community page is only available for Chocolatey packages.",
        "Community Page Unavailable",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Information
    ) | Out-Null
    return
}

$name = [string]$Item.Name
if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$Item.Id }
Write-GuiLog "Opening Chocolatey community page for $name..."
try {
    Start-Process $url
}
catch {
    Write-GuiLog "ERROR: Could not open Chocolatey community page: $($_.Exception.Message)"
    Show-WmtMessageBox -Message "Could not open the community page.`r`n`r`n$url" -Title "Chocolatey Community Page" -Image Warning | Out-Null
}
}

function Get-WmtNuspecSummary {
# Builds a winget-show style summary from nuspec XML text. Children are
# matched by LocalName because choco's nuspecs declare a default XML namespace
# (which makes direct property access like $xml.package.metadata return null).
param([string]$NuspecText)

if ([string]::IsNullOrWhiteSpace($NuspecText)) { return $null }
try {
    $xml = [xml]$NuspecText
    $meta = $null
    if ($xml.DocumentElement) {
        foreach ($node in $xml.DocumentElement.ChildNodes) {
            if ($node -is [System.Xml.XmlElement] -and $node.LocalName -eq "metadata") { $meta = $node; break }
        }
    }
    if ($meta) {
        $childMap = @{}
        foreach ($node in $meta.ChildNodes) {
            if ($node -is [System.Xml.XmlElement]) { $childMap[$node.LocalName.ToLowerInvariant()] = $node }
        }
        $getProp = {
            param([string]$Name)
            $node = $childMap[$Name.ToLowerInvariant()]
            if ($node) { return (([string]$node.InnerText) -replace '\r?\n', "`r`n").Trim() }
            return ""
        }
        $getDeps = {
            $parts = @()
            try {
                $depsNode = $childMap["dependencies"]
                if ($depsNode) {
                    foreach ($node in $depsNode.ChildNodes) {
                        if ($node -is [System.Xml.XmlElement] -and $node.LocalName -eq "dependency") {
                            $depId = [string]$node.GetAttribute("id")
                            $depVersion = [string]$node.GetAttribute("version")
                            if ([string]::IsNullOrWhiteSpace($depId)) { continue }
                            if ([string]::IsNullOrWhiteSpace($depVersion)) { $parts += $depId }
                            else { $parts += "$depId ($depVersion)" }
                        }
                    }
                }
            }
            catch {}
            return ($parts -join ", ")
        }
        $addLine = {
            param([string]$Label, [string]$Value)
            if (-not [string]::IsNullOrWhiteSpace($Value)) { [void]$lines.Add("$($Label): $Value") }
        }

        $lines = [System.Collections.Generic.List[string]]::new()
        [void]$lines.Add("--- Package Metadata ---")
        & $addLine "Title"       (& $getProp "title")
        & $addLine "Version"     (& $getProp "version")
        & $addLine "Authors"     (& $getProp "authors")
        & $addLine "Owners"      (& $getProp "owners")
        & $addLine "Project URL" (& $getProp "projectUrl")
        & $addLine "Source URL"  (& $getProp "projectSourceUrl")
        & $addLine "Docs URL"    (& $getProp "docsUrl")
        & $addLine "Bug Tracker" (& $getProp "bugTrackerUrl")
        & $addLine "License URL" (& $getProp "licenseUrl")
        & $addLine "Icon URL"    (& $getProp "iconUrl")
        & $addLine "Tags"        (& $getProp "tags")
        & $addLine "Dependencies" (& $getDeps)

        $summaryText = & $getProp "summary"
        $description = & $getProp "description"
        $releaseNotes = & $getProp "releaseNotes"
        if (-not [string]::IsNullOrWhiteSpace($summaryText)) {
            [void]$lines.Add("")
            [void]$lines.Add("Summary:")
            [void]$lines.Add($summaryText)
        }
        if (-not [string]::IsNullOrWhiteSpace($description)) {
            [void]$lines.Add("")
            [void]$lines.Add("Description:")
            [void]$lines.Add($description)
        }
        if (-not [string]::IsNullOrWhiteSpace($releaseNotes)) {
            [void]$lines.Add("")
            [void]$lines.Add("Release Notes:")
            [void]$lines.Add($releaseNotes)
        }

        if ($lines.Count -gt 1) { return [string]::Join("`r`n", $lines) }
    }
}
catch { return $null }
return $null
}

function Get-ChocoRemoteNuspec {
# Downloads the package's nuspec from the chocolatey community repository
# (NuGet v2 protocol) for rows that are not installed locally - e.g. search
# results for packages that have never been downloaded. The nuspec is read
# straight out of the downloaded .nupkg (zip) in a temp file.
param([object]$Item)

$id = ([string]$Item.Id).Trim()
if ([string]::IsNullOrWhiteSpace($id)) {
    return [PSCustomObject]@{ Success = $false; ManifestPath = $null; Raw = $null; Text = "No package id was available." }
}

$url = "https://community.chocolatey.org/api/v2/package/$([System.Uri]::EscapeDataString($id))"
$version = ([string]$Item.Version).Trim()
if ($version -match '^\d[\w\.\-\+]*$') { $url = "$url/$version" }

$tmpFile = $null
try {
    try {
        $wmtTlsProtocols = [Net.ServicePointManager]::SecurityProtocol
        if ($wmtTlsProtocols -ne [Net.SecurityProtocolType]::SystemDefault -and
            ($wmtTlsProtocols -band [Net.SecurityProtocolType]::Tls12) -ne [Net.SecurityProtocolType]::Tls12) {
            [Net.ServicePointManager]::SecurityProtocol = $wmtTlsProtocols -bor [Net.SecurityProtocolType]::Tls12
        }
    }
    catch {}
    $tmpFile = [System.IO.Path]::GetTempFileName()
    $oldProgress = $ProgressPreference
    $ProgressPreference = 'SilentlyContinue'
    try {
        Invoke-WebRequest -Uri $url -OutFile $tmpFile -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop | Out-Null
    }
    finally {
        $ProgressPreference = $oldProgress
    }

    if (-not (Test-Path -LiteralPath $tmpFile -PathType Leaf)) { throw "The package download failed." }
    if ((Get-Item -LiteralPath $tmpFile).Length -lt 64) { throw "The downloaded package is empty or invalid." }

    Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue
    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    $zip = [System.IO.Compression.ZipFile]::OpenRead($tmpFile)
    try {
        $nuspecEntry = @($zip.Entries | Where-Object { $_.Name -like "*.nuspec" } | Select-Object -First 1)
        if ($nuspecEntry.Count -eq 0) { throw "No .nuspec entry was found inside the downloaded package." }
        $reader = New-Object System.IO.StreamReader($nuspecEntry[0].Open(), [System.Text.Encoding]::UTF8)
        try { $nuspecText = $reader.ReadToEnd() } finally { $reader.Dispose() }
    }
    finally { $zip.Dispose() }

    if ([string]::IsNullOrWhiteSpace($nuspecText)) { throw "The nuspec inside the downloaded package is empty." }

    return [PSCustomObject]@{
        Success      = $true
        ManifestPath = "$url (fetched from the chocolatey community repository)"
        Raw          = $nuspecText
        Text         = $null
    }
}
catch {
    return [PSCustomObject]@{
        Success      = $false
        ManifestPath = $null
        Raw          = $null
        Text         = "Could not fetch the manifest from the chocolatey community repository.`r`n`r`nURL: $url`r`nReason: $($_.Exception.Message)"
    }
}
finally {
    if ($tmpFile) { try { Remove-Item -LiteralPath $tmpFile -Force -ErrorAction SilentlyContinue } catch {} }
}
}

function Get-ChocoManifestText {
# Resolves the nuspec (the chocolatey equivalent of a winget manifest) for the
# selected row. Installed packages are read from chocolatey's lib folder; rows
# that were never downloaded (search results) fall back to fetching the nuspec
# from the community repository.
param([object]$Item)

if (-not (Test-ChocoManifestSupportedItem $Item)) {
    return [PSCustomObject]@{
        Success      = $false
        ManifestPath = $null
        Summary      = $null
        Raw          = $null
        Text         = "Chocolatey manifests are only available for Chocolatey packages."
    }
}

$id = [string]$Item.Id

# 1) Installed package -> read the nuspec chocolatey stored in its lib folder
$path = Get-ChocoManifestPath -Item $Item
if (-not [string]::IsNullOrWhiteSpace($path)) {
    try {
        $raw = Get-Content -LiteralPath $path -Raw -Encoding UTF8
        if ([string]::IsNullOrWhiteSpace($raw)) { throw "The manifest file is empty." }
        return [PSCustomObject]@{
            Success      = $true
            ManifestPath = $path
            Summary      = (Get-WmtNuspecSummary -NuspecText $raw)
            Raw          = $raw.TrimEnd()
            Text         = $null
        }
    }
    catch {
        return [PSCustomObject]@{
            Success      = $false
            ManifestPath = $path
            Summary      = $null
            Raw          = $null
            Text         = "Failed to read the chocolatey manifest for $id.`r`n`r`nFile: $path`r`n`r`n$($_.Exception.Message)"
        }
    }
}

# 2) Never downloaded (e.g. a search result) -> fetch the nuspec from the community repository
$remote = Get-ChocoRemoteNuspec -Item $Item
if ($remote.Success) {
    return [PSCustomObject]@{
        Success      = $true
        ManifestPath = $remote.ManifestPath
        Summary      = (Get-WmtNuspecSummary -NuspecText $remote.Raw)
        Raw          = $remote.Raw.TrimEnd()
        Text         = $null
    }
}

# 3) Neither local nor remote -> explain both paths
$libRoot = Get-WmtChocolateyLibRoot
$libHint = if ($libRoot) { "$libRoot\lib\$id" } else { "<ChocolateyInstall>\lib\$id" }
return [PSCustomObject]@{
    Success      = $false
    ManifestPath = $null
    Summary      = $null
    Raw          = $null
    Text         = "No chocolatey manifest (nuspec) is available for $id.`r`n`r`nInstalled packages keep their manifest at: $libHint`r`n`r`n$($remote.Text)`r`n`r`nUse ""Open Chocolatey Community Page"" for the online package details."
}
}

function Show-ChocoPackageManifest {
param([object]$Item)

if (-not (Test-ChocoManifestSupportedItem $Item)) {
    [System.Windows.MessageBox]::Show(
        "Chocolatey manifests are only available for Chocolatey packages.",
        "Manifest Unavailable",
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Information
    ) | Out-Null
    return
}

$name = [string]$Item.Name
$id = [string]$Item.Id
if ([string]::IsNullOrWhiteSpace($name)) { $name = $id }

Write-GuiLog "Loading chocolatey manifest for $name ($id)..."
if ($lblWingetStatus) {
    $lblWingetStatus.Text = "Loading chocolatey manifest for $name..."
    $lblWingetStatus.Visibility = "Visible"
}

Set-WmtBusyCursor -Busy
try {
    $result = Get-ChocoManifestText -Item $Item
    if (-not $result.Success) {
        Write-GuiLog "Chocolatey manifest unavailable for $id."
    }
    else {
        Write-GuiLog "Chocolatey manifest loaded for $id."
    }

    $body = $result.Text
    if ($result.Success) {
        $installed = [string]$Item.Version
        $available = [string]$Item.Available
        if ([string]::IsNullOrWhiteSpace($installed)) { $installed = "-" }
        if ([string]::IsNullOrWhiteSpace($available)) { $available = "-" }
        $header = "Package: $name`r`nID: $id`r`nInstalled: $installed`r`nAvailable: $available`r`nSource: chocolatey`r`nManifest: $($result.ManifestPath)`r`n"
        $separator = ("-" * 80)
        $parts = @("$header`r`n$separator")
        if (-not [string]::IsNullOrWhiteSpace($result.Summary)) { $parts += $result.Summary }
        $manifestFile = [System.IO.Path]::GetFileName($result.ManifestPath)
        $parts += "--- Raw Manifest ($manifestFile) ---`r`n"
        $parts += $result.Raw
        $body = [string]::Join("`r`n`r`n", $parts)
    }

    # Clear the busy cursor BEFORE opening the dialog
    Set-WmtBusyCursor
    Show-TextDialog -Title "Chocolatey Manifest - $name" -Text $body
}
finally {
    Set-WmtBusyCursor
    if ($lblWingetStatus) {
        $lblWingetStatus.Text = "Ready"
        $lblWingetStatus.Visibility = "Hidden"
    }
}
}

# --- SETTINGS MANAGER ---
# Initialize cache variables
$script:WmtSettingsCache = $null
$script:WmtSettingsCacheStamp = $null
$script:WmtSettingsWriteMutexName = "Local\Chaython_WindowsMaintenanceTool_Settings_v2"

function Get-WmtSettingsFileStamp {
param([string]$Path)
try {
    if ([string]::IsNullOrWhiteSpace($Path) -or -not [System.IO.File]::Exists($Path)) { return "<missing>" }
    $fi = [System.IO.FileInfo]::new($Path)
    return "$($fi.Length):$($fi.LastWriteTimeUtc.Ticks)"
}
catch { return "<unknown>" }
}

function Test-WmtSettingsMember {
param($Settings, [Parameter(Mandatory = $true)][string]$Name)
if ($null -eq $Settings) { return $false }
if ($Settings -is [System.Collections.IDictionary]) { return [bool]$Settings.Contains($Name) }
try { return [bool]$Settings.PSObject.Properties[$Name] } catch { return $false }
}

function Get-WmtSettingsMember {
param($Settings, [Parameter(Mandatory = $true)][string]$Name, $Default = $null)
if (-not (Test-WmtSettingsMember -Settings $Settings -Name $Name)) { return $Default }
try {
    if ($Settings -is [System.Collections.IDictionary]) { return $Settings[$Name] }
    return $Settings.$Name
}
catch { return $Default }
}

function ConvertTo-WmtSettingsBoolean {
param($Value, [bool]$Default = $false)
if ($null -eq $Value) { return $Default }
if ($Value -is [bool]) { return [bool]$Value }
if ($Value -is [string]) {
    switch ($Value.Trim().ToLowerInvariant()) {
        "true" { return $true }
        "false" { return $false }
        "1" { return $true }
        "0" { return $false }
        "yes" { return $true }
        "no" { return $false }
        "on" { return $true }
        "off" { return $false }
        default { return $Default }
    }
}
try { return [System.Convert]::ToBoolean($Value) } catch { return $Default }
}

function Test-WmtFiniteDouble {
param($Value)
try {
    $d = [double]$Value
    return (-not [double]::IsNaN($d) -and -not [double]::IsInfinity($d))
}
catch { return $false }
}

function Move-WmtCorruptSettingsFile {
param([Parameter(Mandatory = $true)][string]$Path)
if (-not [System.IO.File]::Exists($Path)) { return $null }
try {
    $dir = [System.IO.Path]::GetDirectoryName($Path)
    $stamp = [DateTime]::UtcNow.ToString("yyyyMMdd-HHmmssfff")
    $archive = Join-Path $dir "settings.corrupt-$stamp.json"
    [System.IO.File]::Move($Path, $archive)
    return $archive
}
catch { return $null }
}

function Write-WmtSettingsFileAtomic {
param(
    [Parameter(Mandatory = $true)][string]$Path,
    [Parameter(Mandatory = $true)][string]$Json
)

$mutex = $null
$lockTaken = $false
$tempPath = $null
try {
    $mutex = [System.Threading.Mutex]::new($false, $script:WmtSettingsWriteMutexName)
    try { $lockTaken = $mutex.WaitOne([TimeSpan]::FromSeconds(10)) }
    catch [System.Threading.AbandonedMutexException] { $lockTaken = $true }
    if (-not $lockTaken) { throw "Timed out waiting for the settings file lock." }

    $dir = [System.IO.Path]::GetDirectoryName($Path)
    if (-not [System.IO.Directory]::Exists($dir)) {
        [void][System.IO.Directory]::CreateDirectory($dir)
    }

    $tempPath = Join-Path $dir ("settings.{0}.{1}.tmp" -f $PID, [Guid]::NewGuid().ToString("N"))
    [System.IO.File]::WriteAllText($tempPath, $Json, [System.Text.UTF8Encoding]::new($false))

    # Never replace the user's settings with JSON we cannot parse back.
    $check = Get-Content -LiteralPath $tempPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
    if ($null -eq $check) { throw "Serialized settings unexpectedly parsed as null." }

    if ([System.IO.File]::Exists($Path)) {
        $backupPath = "$Path.bak"
        try {
            if ([System.IO.File]::Exists($backupPath)) { [System.IO.File]::Delete($backupPath) }
            [System.IO.File]::Replace($tempPath, $Path, $backupPath, $true)
            $tempPath = $null
        }
        catch {
            # File.Replace may be unavailable on some removable/non-NTFS media.
            # Keep a known-good previous copy, then use same-directory Move-Item.
            try { [System.IO.File]::Copy($Path, $backupPath, $true) } catch {}
            Move-Item -LiteralPath $tempPath -Destination $Path -Force -ErrorAction Stop
            $tempPath = $null
        }
    }
    else {
        [System.IO.File]::Move($tempPath, $Path)
        $tempPath = $null
    }
}
finally {
    if ($tempPath -and [System.IO.File]::Exists($tempPath)) {
        try { [System.IO.File]::Delete($tempPath) } catch {}
    }
    if ($lockTaken -and $mutex) {
        try { $mutex.ReleaseMutex() } catch {}
    }
    if ($mutex) { try { $mutex.Dispose() } catch {} }
}
}

function Copy-WmtSettingsValue {
param([AllowNull()]$Value)

if ($null -eq $Value) { return $null }
if ($Value -is [string] -or $Value.GetType().IsValueType) { return $Value }

if ($Value -is [System.Collections.IDictionary]) {
    $copy = @{}
    foreach ($key in @($Value.Keys)) {
        $copy[$key] = Copy-WmtSettingsValue -Value $Value[$key]
    }
    return $copy
}

if ($Value -is [System.Management.Automation.PSCustomObject]) {
    $copy = [ordered]@{}
    foreach ($prop in @($Value.PSObject.Properties)) {
        $copy[$prop.Name] = Copy-WmtSettingsValue -Value $prop.Value
    }
    return [PSCustomObject]$copy
}

if ($Value -is [System.Collections.IEnumerable]) {
    $items = [System.Collections.Generic.List[object]]::new()
    foreach ($item in $Value) {
        [void]$items.Add((Copy-WmtSettingsValue -Value $item))
    }
    return ,$items.ToArray()
}

return $Value
}

function Copy-WmtSettings {
param($Settings)
if ($null -eq $Settings) { return $null }
return (Copy-WmtSettingsValue -Value $Settings)
}

function Save-WmtSettings {
param($Settings)
$path = Join-Path (Get-DataPath) "settings.json"
try {
    if ($null -eq $Settings) { throw "Settings object is null." }

    $theme = [string](Get-WmtSettingsMember -Settings $Settings -Name "Theme" -Default "dark")
    if ($theme -notin @("dark", "light")) { $theme = "dark" }

    $windowState = [string](Get-WmtSettingsMember -Settings $Settings -Name "WindowState" -Default "Normal")
    if ($windowState -notin @("Normal", "Maximized")) { $windowState = "Normal" }

    $windowBounds = Get-WmtSettingsMember -Settings $Settings -Name "WindowBounds" -Default $null
    if ($windowBounds) {
        $top = Get-WmtSettingsMember -Settings $windowBounds -Name "Top" -Default 0
        $left = Get-WmtSettingsMember -Settings $windowBounds -Name "Left" -Default 0
        $width = Get-WmtSettingsMember -Settings $windowBounds -Name "Width" -Default 1280
        $height = Get-WmtSettingsMember -Settings $windowBounds -Name "Height" -Default 820
        if ((Test-WmtFiniteDouble $top) -and (Test-WmtFiniteDouble $left) -and
            (Test-WmtFiniteDouble $width) -and (Test-WmtFiniteDouble $height) -and
            [double]$width -ge 320 -and [double]$height -ge 240) {
            $windowBounds = @{
                Top = [double]$top
                Left = [double]$left
                Width = [double]$width
                Height = [double]$height
            }
        }
        else { $windowBounds = $null }
    }

    # Convert Hashtable/OrderedDictionary to a stable explicit schema.
    $saveObj = [PSCustomObject]@{
        TempCleanup                = (Get-WmtSettingsMember -Settings $Settings -Name "TempCleanup" -Default @{})
        RegistryScan               = (Get-WmtSettingsMember -Settings $Settings -Name "RegistryScan" -Default @{})
        WingetIgnore               = @(Get-WmtSettingsMember -Settings $Settings -Name "WingetIgnore" -Default @("228980"))
        WingetIncludeUnknown       = [bool](Get-WmtWingetIncludeUnknown -Settings $Settings)
        CustomUpdateCommands       = @(Get-WmtCustomUpdateCommands -Settings $Settings)
        UpdateAutoScanMinutes      = [Math]::Max(0, (ConvertTo-Int (Get-WmtUpdateAutoScanMinutes -Settings $Settings) 0))
        UpdateNotificationsEnabled = [bool](Get-WmtUpdateNotificationsEnabled -Settings $Settings)
        UpdateSilentInstallEnabled = [bool](Get-WmtUpdateSilentInstallEnabled -Settings $Settings)
        UpdateAutoInstallEnabled   = [bool](Get-WmtUpdateAutoInstallEnabled -Settings $Settings)
        RunInTrayOnClose           = [bool](Get-WmtRunInTrayOnClose -Settings $Settings)
        ReduceRamInTray            = [bool](Get-WmtReduceRamInTray -Settings $Settings)
        DisableBackgroundJobs      = [bool](Get-WmtDisableBackgroundJobs -Settings $Settings)
        DebugMode                  = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "DebugMode" -Default $false) $false
        UpdateScansDisabled        = [bool](Get-WmtUpdateScansDisabled -Settings $Settings)
        LaunchMinimized            = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "LaunchMinimized" -Default $false) $false
        HideLegendaryUeAssets      = [bool](Get-WmtHideLegendaryUeAssets -Settings $Settings)
        SavedUpdateAutoScanMinutes = [Math]::Max(0, (ConvertTo-Int (Get-WmtSavedUpdateAutoScanMinutes -Settings $Settings) 0))
        LoadWinapp2                = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "LoadWinapp2" -Default $false) $false
        LoadWinapp3                = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "LoadWinapp3" -Default $false) $false
        LoadCleanerML              = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "LoadCleanerML" -Default $false) $false
        LoadCleanerMLPending       = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "LoadCleanerMLPending" -Default $false) $false
        SkipRuleDownloads          = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "SkipRuleDownloads" -Default $false) $false
        CacheOnly                  = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "CacheOnly" -Default $false) $false
        # Use the type-safe getters. The old PSObject.Properties checks failed
        # for the hashtable returned by Get-WmtSettings and reset these values.
        CleanerLocalRefreshMinutes = [int](Get-WmtCleanerLocalRefreshMinutes -Settings $Settings)
        CleanerRemoteCheckMinutes  = [int](Get-WmtCleanerRemoteCheckMinutes -Settings $Settings)
        CleanerAutoCleanMinutes    = [int](Get-WmtCleanerAutoCleanMinutes -Settings $Settings)
        EnabledProviders           = @(Get-WmtSettingsMember -Settings $Settings -Name "EnabledProviders" -Default @("winget"))
        ProviderToggles            = (Get-WmtSettingsMember -Settings $Settings -Name "ProviderToggles" -Default @{})
        ProviderExecutionOverrides = (Get-WmtSettingsMember -Settings $Settings -Name "ProviderExecutionOverrides" -Default @{})
        WuCategoryToggles          = (Get-WmtSettingsMember -Settings $Settings -Name "WuCategoryToggles" -Default @{})
        CustomDnsServers           = @(Get-WmtSettingsMember -Settings $Settings -Name "CustomDnsServers" -Default @())
        CustomDohTemplate          = [string](Get-WmtSettingsMember -Settings $Settings -Name "CustomDohTemplate" -Default "")
        CustomDohEnabled           = ConvertTo-WmtSettingsBoolean (Get-WmtSettingsMember -Settings $Settings -Name "CustomDohEnabled" -Default $false) $false
        Theme                      = $theme
        WindowState                = $windowState
        WindowBounds               = $windowBounds
    }

    $json = $saveObj | ConvertTo-Json -Depth 8
    Write-WmtSettingsFileAtomic -Path $path -Json $json

    # Cache only after disk persistence succeeds, and cache the normalized form
    # that was actually written rather than the caller's possibly malformed input.
    $script:WmtSettingsCache = Copy-WmtSettings -Settings $saveObj
    $script:WmtSettingsCacheStamp = Get-WmtSettingsFileStamp -Path $path
}
catch {
    # A failed write must not make memory claim a setting was persisted.
    try { Write-GuiLog "Settings save failed: $($_.Exception.Message)" } catch {}
    Write-Warning "Failed to save settings: $($_.Exception.Message)"
}
}

function Get-WmtSettings {
$path = Join-Path (Get-DataPath) "settings.json"

# Keep the fast in-process cache, but invalidate it if settings.json changed
# outside this process (manual edit, another WMT process, recovery, etc.).
$currentStamp = Get-WmtSettingsFileStamp -Path $path
if ($script:WmtSettingsCache -and $script:WmtSettingsCacheStamp -eq $currentStamp) {
    return (Copy-WmtSettings -Settings $script:WmtSettingsCache)
}
if ($script:WmtSettingsCache) {
    $script:WmtSettingsCache = $null
    $script:WmtSettingsCacheStamp = $null
}

# Default Structure
$defaults = @{
    TempCleanup                = @{}
    RegistryScan               = @{}
    WingetIgnore               = @("228980") # Filter false positive updates for Steamworks Redist
    WingetIncludeUnknown       = $true
    CustomUpdateCommands       = @()
    UpdateAutoScanMinutes      = 0
    UpdateNotificationsEnabled = $true
    UpdateSilentInstallEnabled = $false
    UpdateAutoInstallEnabled   = $false
    RunInTrayOnClose           = $false
    ReduceRamInTray            = $true
    DisableBackgroundJobs      = $false
    DebugMode                  = $false
    UpdateScansDisabled         = $false
    LaunchMinimized             = $false
    HideLegendaryUeAssets      = $true
    SavedUpdateAutoScanMinutes = 0
    LoadWinapp2                = $false 
    LoadWinapp3                = $false
    LoadCleanerML              = $false
    LoadCleanerMLPending       = $false
    SkipRuleDownloads          = $false
    CacheOnly                  = $false
    CleanerLocalRefreshMinutes = 60
    CleanerRemoteCheckMinutes  = 1440
    CleanerAutoCleanMinutes    = 0
    EnabledProviders           = @("winget", "msstore", "windowsupdate", "pip", "npm", "pnpm", "dotnet", "psmodule", "composer", "chocolatey", "scoop", "gem", "cargo", "steam", "legendary", "gogdl")
    WuCategoryToggles          = @{}
    ProviderToggles            = @{}
    ProviderExecutionOverrides = @{}
    CustomDnsServers           = @()
    CustomDohTemplate          = ""
    CustomDohEnabled           = $false
    Theme                      = "dark"
    WindowState                = "Normal"
    WindowBounds               = @{
        Top    = 0
        Left   = 0
        Width  = 1280
        Height = 820
    }
}

$json = $null
if (Test-Path -LiteralPath $path -PathType Leaf) {
    try {
        $rawSettings = Get-Content -LiteralPath $path -Raw -ErrorAction Stop
        if ([string]::IsNullOrWhiteSpace($rawSettings)) { throw "settings.json is empty." }
        $json = $rawSettings | ConvertFrom-Json -ErrorAction Stop
        if ($null -eq $json) { throw "settings.json contains no settings object." }
    }
    catch {
        $primaryError = $_.Exception.Message
        $backupPath = "$path.bak"
        $backupJson = $null

        if (Test-Path -LiteralPath $backupPath -PathType Leaf) {
            try {
                $backupRaw = Get-Content -LiteralPath $backupPath -Raw -ErrorAction Stop
                if ([string]::IsNullOrWhiteSpace($backupRaw)) { throw "settings backup is empty." }
                $backupJson = $backupRaw | ConvertFrom-Json -ErrorAction Stop
                if ($null -eq $backupJson) { throw "settings backup contains no settings object." }
            }
            catch {
                try { Write-GuiLog "Settings backup is also invalid: $($_.Exception.Message)" } catch {}
                $backupJson = $null
            }
        }

        $archived = Move-WmtCorruptSettingsFile -Path $path
        if ($backupJson) {
            $json = $backupJson
            try { [System.IO.File]::Copy($backupPath, $path, $true) } catch {}
            try {
                $where = if ($archived) { " Corrupt copy: $archived" } else { "" }
                Write-GuiLog "Recovered settings.json from backup after load failure: $primaryError$where"
            }
            catch {}
        }
        else {
            try {
                $where = if ($archived) { " Corrupt copy: $archived" } else { "" }
                Write-GuiLog "Settings file was invalid; defaults will be used. $primaryError$where"
            }
            catch {}
        }
    }
}

if ($json) {
    try {
        if ($json.TempCleanup) { 
            foreach ($p in $json.TempCleanup.PSObject.Properties) { $defaults.TempCleanup[$p.Name] = $p.Value } 
        }
        if ($json.RegistryScan) { 
            foreach ($p in $json.RegistryScan.PSObject.Properties) { $defaults.RegistryScan[$p.Name] = $p.Value } 
        }
        if ($json.PSObject.Properties["WingetIgnore"]) {
            $raw = $json.WingetIgnore
            $clean = New-Object System.Collections.ArrayList
            if ($raw) { foreach ($item in $raw) { [void]$clean.Add("$item".Trim()) } }
            $defaults.WingetIgnore = $clean.ToArray()
        }
        if ($json.PSObject.Properties["WingetIncludeUnknown"]) { $defaults.WingetIncludeUnknown = ConvertTo-WmtSettingsBoolean $json.WingetIncludeUnknown $true }
        if ($json.PSObject.Properties["CustomUpdateCommands"]) {
            $customUpdateCommands = New-Object System.Collections.Generic.List[object]
            foreach ($entry in @($json.CustomUpdateCommands)) {
                $source = ([string]$entry.Source).Trim()
                $id = ([string]$entry.Id).Trim()
                $command = ([string]$entry.Command).Trim()
                if ([string]::IsNullOrWhiteSpace($source) -or [string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($command)) { continue }
                [void]$customUpdateCommands.Add([PSCustomObject]@{
                        Source  = $source
                        Id      = $id
                        Name    = ([string]$entry.Name).Trim()
                        Command = $command
                    })
            }
            $defaults.CustomUpdateCommands = $customUpdateCommands.ToArray()
        }
        if ($json.PSObject.Properties["UpdateAutoScanMinutes"]) {
            try { $defaults.UpdateAutoScanMinutes = [int]$json.UpdateAutoScanMinutes } catch { $defaults.UpdateAutoScanMinutes = 0 }
            if ($defaults.UpdateAutoScanMinutes -lt 0) { $defaults.UpdateAutoScanMinutes = 0 }
        }
        if ($json.PSObject.Properties["UpdateNotificationsEnabled"]) { $defaults.UpdateNotificationsEnabled = ConvertTo-WmtSettingsBoolean $json.UpdateNotificationsEnabled $true }
        if ($json.PSObject.Properties["UpdateSilentInstallEnabled"]) { $defaults.UpdateSilentInstallEnabled = ConvertTo-WmtSettingsBoolean $json.UpdateSilentInstallEnabled $false }
        if ($json.PSObject.Properties["UpdateAutoInstallEnabled"]) { $defaults.UpdateAutoInstallEnabled = ConvertTo-WmtSettingsBoolean $json.UpdateAutoInstallEnabled $false }
        if ($json.PSObject.Properties["RunInTrayOnClose"]) { $defaults.RunInTrayOnClose = ConvertTo-WmtSettingsBoolean $json.RunInTrayOnClose $false }
        if ($json.PSObject.Properties["ReduceRamInTray"]) { $defaults.ReduceRamInTray = ConvertTo-WmtSettingsBoolean $json.ReduceRamInTray $true }
        if ($json.PSObject.Properties["DisableBackgroundJobs"]) { $defaults.DisableBackgroundJobs = ConvertTo-WmtSettingsBoolean $json.DisableBackgroundJobs $false }
        if ($json.PSObject.Properties["DebugMode"]) { $defaults.DebugMode = ConvertTo-WmtSettingsBoolean $json.DebugMode $false }
        if ($json.PSObject.Properties["UpdateScansDisabled"]) { $defaults.UpdateScansDisabled = ConvertTo-WmtSettingsBoolean $json.UpdateScansDisabled $false }
        if ($json.PSObject.Properties["LaunchMinimized"]) { $defaults.LaunchMinimized = ConvertTo-WmtSettingsBoolean $json.LaunchMinimized $false }
        if ($json.PSObject.Properties["HideLegendaryUeAssets"]) { $defaults.HideLegendaryUeAssets = ConvertTo-WmtSettingsBoolean $json.HideLegendaryUeAssets $true }
        if ($json.PSObject.Properties["SavedUpdateAutoScanMinutes"]) {
            try { $defaults.SavedUpdateAutoScanMinutes = [int]$json.SavedUpdateAutoScanMinutes } catch { $defaults.SavedUpdateAutoScanMinutes = 0 }
            if ($defaults.SavedUpdateAutoScanMinutes -lt 0) { $defaults.SavedUpdateAutoScanMinutes = 0 }
        }
        if ($json.PSObject.Properties["LoadWinapp2"]) { $defaults.LoadWinapp2 = ConvertTo-WmtSettingsBoolean $json.LoadWinapp2 $false }
        if ($json.PSObject.Properties["LoadWinapp3"]) { $defaults.LoadWinapp3 = ConvertTo-WmtSettingsBoolean $json.LoadWinapp3 $false }
        if ($json.PSObject.Properties["LoadCleanerML"]) { $defaults.LoadCleanerML = ConvertTo-WmtSettingsBoolean $json.LoadCleanerML $false }
        if ($json.PSObject.Properties["LoadCleanerMLPending"]) { $defaults.LoadCleanerMLPending = ConvertTo-WmtSettingsBoolean $json.LoadCleanerMLPending $false }
        if ($json.PSObject.Properties["SkipRuleDownloads"]) { $defaults.SkipRuleDownloads = ConvertTo-WmtSettingsBoolean $json.SkipRuleDownloads $false }
        if ($json.PSObject.Properties["CacheOnly"]) { $defaults.CacheOnly = ConvertTo-WmtSettingsBoolean $json.CacheOnly $false }
        if ($json.PSObject.Properties["CleanerLocalRefreshMinutes"]) {
            try { $defaults.CleanerLocalRefreshMinutes = [Math]::Max(1, [Math]::Min(525600, [int]$json.CleanerLocalRefreshMinutes)) } catch {}
        }
        if ($json.PSObject.Properties["CleanerRemoteCheckMinutes"]) {
            try { $defaults.CleanerRemoteCheckMinutes = [Math]::Max(0, [Math]::Min(525600, [int]$json.CleanerRemoteCheckMinutes)) } catch {}
        }
        if ($json.PSObject.Properties["CleanerAutoCleanMinutes"]) {
            try { $defaults.CleanerAutoCleanMinutes = [Math]::Max(0, [Math]::Min(525600, [int]$json.CleanerAutoCleanMinutes)) } catch {}
        }
        if ($json.PSObject.Properties["EnabledProviders"]) { $defaults.EnabledProviders = $json.EnabledProviders }
        if ($json.PSObject.Properties["ProviderToggles"]) {
            # Normalize the legacy provider-toggle object to the three ordinary
            # provider controls. Headless/AutoUpdate now live exclusively in
            # ProviderExecutionOverrides so there is only one execution source.
            $normalizedProviderToggles = [ordered]@{}
            if ($json.ProviderToggles) {
                foreach ($providerProp in @($json.ProviderToggles.PSObject.Properties)) {
                    $rawEntry = $providerProp.Value
                    $cleanEntry = [ordered]@{}
                    if ($rawEntry) {
                        foreach ($toggleName in @("Search", "Scan", "Logs")) {
                            try {
                                if ($rawEntry.PSObject.Properties[$toggleName]) {
                                    $cleanEntry[$toggleName] = ConvertTo-WmtSettingsBoolean $rawEntry.$toggleName $false
                                }
                            }
                            catch {}
                        }
                    }
                    $normalizedProviderToggles[[string]$providerProp.Name] = $cleanEntry
                }
            }
            $defaults.ProviderToggles = $normalizedProviderToggles
        }
        if ($json.PSObject.Properties["ProviderExecutionOverrides"]) {
            $defaults.ProviderExecutionOverrides = $json.ProviderExecutionOverrides
        }
        elseif ($json.PSObject.Properties["ProviderToggles"] -and $json.ProviderToggles) {
            # Before per-provider execution settings were wired, every provider row
            # persisted Headless=false / AutoUpdate=false by default. Those false
            # values were display state, not intentional overrides. Migrate only
            # legacy true opt-ins; false values inherit the global setting.
            $migratedExecutionOverrides = [ordered]@{}
            foreach ($providerProp in @($json.ProviderToggles.PSObject.Properties)) {
                $legacyEntry = $providerProp.Value
                if (-not $legacyEntry) { continue }
                $overrideEntry = [ordered]@{}
                try {
                    if ($legacyEntry.PSObject.Properties["Headless"] -and
                        (ConvertTo-WmtSettingsBoolean $legacyEntry.Headless $false)) {
                        $overrideEntry["Headless"] = $true
                    }
                    if ($legacyEntry.PSObject.Properties["AutoUpdate"] -and
                        (ConvertTo-WmtSettingsBoolean $legacyEntry.AutoUpdate $false)) {
                        $overrideEntry["AutoUpdate"] = $true
                    }
                }
                catch {}
                if ($overrideEntry.Count -gt 0) {
                    $migratedExecutionOverrides[[string]$providerProp.Name] = $overrideEntry
                }
            }
            $defaults.ProviderExecutionOverrides = $migratedExecutionOverrides
        }
        if ($json.PSObject.Properties["WuCategoryToggles"]) { $defaults.WuCategoryToggles = $json.WuCategoryToggles }
        if ($json.PSObject.Properties["CustomDnsServers"]) {
            $customDnsServers = @()
            foreach ($server in @($json.CustomDnsServers)) {
                $serverText = ([string]$server).Trim()
                if (-not [string]::IsNullOrWhiteSpace($serverText)) { $customDnsServers += $serverText }
            }
            $defaults.CustomDnsServers = $customDnsServers
        }
        if ($json.PSObject.Properties["CustomDohTemplate"]) { $defaults.CustomDohTemplate = [string]$json.CustomDohTemplate }
        if ($json.PSObject.Properties["CustomDohEnabled"]) { $defaults.CustomDohEnabled = ConvertTo-WmtSettingsBoolean $json.CustomDohEnabled $false }
        if ($json.PSObject.Properties["Theme"] -and $json.Theme) { $defaults.Theme = [string]$json.Theme }
        if ($json.PSObject.Properties["WindowState"] -and $json.WindowState) {
            $loadedWindowState = [string]$json.WindowState
            if ($loadedWindowState -in @("Normal", "Maximized")) { $defaults.WindowState = $loadedWindowState }
        }
        if ($json.PSObject.Properties["WindowBounds"] -and $json.WindowBounds) {
            $bt = $json.WindowBounds.Top
            $bl = $json.WindowBounds.Left
            $bw = $json.WindowBounds.Width
            $bh = $json.WindowBounds.Height
            if ((Test-WmtFiniteDouble $bt) -and (Test-WmtFiniteDouble $bl) -and
                (Test-WmtFiniteDouble $bw) -and (Test-WmtFiniteDouble $bh) -and
                [double]$bw -ge 320 -and [double]$bh -ge 240) {
                $defaults.WindowBounds = @{
                    Top    = [double]$bt
                    Left   = [double]$bl
                    Width  = [double]$bw
                    Height = [double]$bh
                }
            }
        }
    }
    catch {
        try { Write-GuiLog "Error normalizing settings: $($_.Exception.Message)" } catch {}
    }
}
$normalizedProviders = New-Object System.Collections.Generic.List[string]
foreach ($provider in @($defaults.EnabledProviders)) {
    $providerKey = ([string]$provider).Trim().ToLowerInvariant()
    if ([string]::IsNullOrWhiteSpace($providerKey)) { continue }
    if ($providerKey -eq "comet") { $providerKey = "gogdl" }
    if (-not $normalizedProviders.Contains($providerKey)) {
        [void]$normalizedProviders.Add($providerKey)
    }
}
if ($normalizedProviders.Count -eq 0) {
    [void]$normalizedProviders.Add("winget")
}
$defaults.EnabledProviders = $normalizedProviders.ToArray()

# Cache an isolated copy and remember the file generation it came from.
$script:WmtSettingsCache = Copy-WmtSettings -Settings $defaults
$script:WmtSettingsCacheStamp = Get-WmtSettingsFileStamp -Path $path
return (Copy-WmtSettings -Settings $script:WmtSettingsCache)
}

function Get-WmtWingetIncludeUnknown {
param($Settings)

if (-not $Settings) { $Settings = Get-WmtSettings }

if ($Settings -is [System.Collections.IDictionary] -and $Settings.Contains("WingetIncludeUnknown")) {
    return [bool]$Settings["WingetIncludeUnknown"]
}
if ($Settings.PSObject.Properties["WingetIncludeUnknown"]) {
    return [bool]$Settings.WingetIncludeUnknown
}

return $true
}

function Set-WmtWingetIncludeUnknown {
param([bool]$IncludeUnknown)

$settings = Get-WmtSettings
if ($settings -is [System.Collections.IDictionary]) {
    $settings["WingetIncludeUnknown"] = $IncludeUnknown
}
elseif ($settings.PSObject.Properties["WingetIncludeUnknown"]) {
    $settings.WingetIncludeUnknown = $IncludeUnknown
}
else {
    $settings | Add-Member -MemberType NoteProperty -Name "WingetIncludeUnknown" -Value $IncludeUnknown -Force
}
Save-WmtSettings -Settings $settings
}

function Get-WmtCustomUpdateCommands {
param($Settings)
if (-not $Settings) { $Settings = Get-WmtSettings }
try {
    if ($Settings -is [System.Collections.IDictionary] -and $Settings.Contains("CustomUpdateCommands")) { return @($Settings["CustomUpdateCommands"]) }
    if ($Settings.PSObject.Properties["CustomUpdateCommands"]) { return @($Settings.CustomUpdateCommands) }
}
catch {}
return @()
}

function Get-WmtCustomUpdateCommand {
param([string]$Source, [string]$Id, $Settings)
$sourceKey = ([string]$Source).Trim().ToLowerInvariant()
$idKey = ([string]$Id).Trim().ToLowerInvariant()
if ([string]::IsNullOrWhiteSpace($sourceKey) -or [string]::IsNullOrWhiteSpace($idKey)) { return "" }

foreach ($entry in @(Get-WmtCustomUpdateCommands -Settings $Settings)) {
    if (-not $entry) { continue }
    if (([string]$entry.Source).Trim().ToLowerInvariant() -eq $sourceKey -and ([string]$entry.Id).Trim().ToLowerInvariant() -eq $idKey) {
        return ([string]$entry.Command).Trim()
    }
}
return ""
}

function Set-WmtCustomUpdateCommand {
param([string]$Source, [string]$Id, [string]$Name, [string]$Command)
$sourceValue = ([string]$Source).Trim()
$idValue = ([string]$Id).Trim()
$commandValue = ([string]$Command).Trim()
if ([string]::IsNullOrWhiteSpace($sourceValue) -or [string]::IsNullOrWhiteSpace($idValue)) { throw "A package source and ID are required." }
if ([string]::IsNullOrWhiteSpace($commandValue)) { Remove-WmtCustomUpdateCommand -Source $sourceValue -Id $idValue; return }

$settings = Get-WmtSettings
$updated = New-Object System.Collections.Generic.List[object]
foreach ($entry in @(Get-WmtCustomUpdateCommands -Settings $settings)) {
    if (-not $entry) { continue }
    if (([string]$entry.Source).Trim().ToLowerInvariant() -eq $sourceValue.ToLowerInvariant() -and ([string]$entry.Id).Trim().ToLowerInvariant() -eq $idValue.ToLowerInvariant()) { continue }
    [void]$updated.Add($entry)
}
[void]$updated.Add([PSCustomObject]@{ Source = $sourceValue; Id = $idValue; Name = ([string]$Name).Trim(); Command = $commandValue })
if ($settings -is [System.Collections.IDictionary]) { $settings["CustomUpdateCommands"] = $updated.ToArray() }
else { $settings | Add-Member -MemberType NoteProperty -Name "CustomUpdateCommands" -Value $updated.ToArray() -Force }
Save-WmtSettings -Settings $settings
}

function Remove-WmtCustomUpdateCommand {
param([string]$Source, [string]$Id)
$sourceKey = ([string]$Source).Trim().ToLowerInvariant()
$idKey = ([string]$Id).Trim().ToLowerInvariant()
if ([string]::IsNullOrWhiteSpace($sourceKey) -or [string]::IsNullOrWhiteSpace($idKey)) { return }

$settings = Get-WmtSettings
$updated = New-Object System.Collections.Generic.List[object]
foreach ($entry in @(Get-WmtCustomUpdateCommands -Settings $settings)) {
    if (-not $entry) { continue }
    if (([string]$entry.Source).Trim().ToLowerInvariant() -eq $sourceKey -and ([string]$entry.Id).Trim().ToLowerInvariant() -eq $idKey) { continue }
    [void]$updated.Add($entry)
}
if ($settings -is [System.Collections.IDictionary]) { $settings["CustomUpdateCommands"] = $updated.ToArray() }
else { $settings | Add-Member -MemberType NoteProperty -Name "CustomUpdateCommands" -Value $updated.ToArray() -Force }
Save-WmtSettings -Settings $settings
}

function Show-WmtCustomUpdateCommandDialog {
param([Parameter(Mandatory = $true)]$Item, [System.Windows.Window]$Owner = $null)

$source = ([string]$Item.Source).Trim()
$id = ([string]$Item.Id).Trim()
$name = ([string]$Item.Name).Trim()
if ([string]::IsNullOrWhiteSpace($source) -or [string]::IsNullOrWhiteSpace($id)) {
    Show-WmtMessageBox -Message "This row does not have a stable package source and ID, so a custom update command cannot be attached to it." -Title "Custom Update Command" -Image Information | Out-Null
    return
}

# The generic input dialog is too short for command help and a multiline editor.
# Keep the actions outside the scrolling areas so they remain reachable on resize.
$content = @'
<Grid Margin="18">
    <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <ScrollViewer MaxHeight="130" VerticalScrollBarVisibility="Auto" Margin="0,0,0,12">
        <StackPanel>
            <TextBlock Name="lblPackage" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,8"/>
            <TextBlock Text="Run this PowerShell command instead of the normal provider command when this package has a pending update." TextWrapping="Wrap" Margin="0,0,0,8"/>
            <TextBlock Text="Optional placeholders: {id}, {name}, {source}, {version}, {available}." TextWrapping="Wrap"/>
        </StackPanel>
    </ScrollViewer>
    <TextBox Name="txtCommand" Grid.Row="1" MinHeight="100" AcceptsReturn="True" AcceptsTab="True"
             TextWrapping="NoWrap" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto"
             FontFamily="Consolas" FontSize="13" Padding="8" VerticalContentAlignment="Top"/>
    <TextBlock Grid.Row="2" Text="Save an empty command to restore the normal provider update command."
               TextWrapping="Wrap" Margin="0,10,0,0"/>
    <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,16,0,0">
        <Button Name="btnCancel" Content="Cancel" Width="94" IsCancel="True" Margin="0,0,8,0"/>
        <Button Name="btnSave" Content="Save" Width="94" IsDefault="True" Background="{DynamicResource Accent}" Foreground="{DynamicResource AccentText}"/>
    </StackPanel>
</Grid>
'@
$dialog = New-WmtWindowFromXaml -Title "Custom Update Command - $name" -ContentXaml $content -Width 720 -Height 480 -MinWidth 560 -MinHeight 400
if ($Owner) { $dialog.Owner = $Owner }
$dialog.FindName("lblPackage").Text = "$name ($source / $id)"
$txtCommand = $dialog.FindName("txtCommand")
$txtCommand.Text = Get-WmtCustomUpdateCommand -Source $source -Id $id
$result = @{ Command = $null }
$dialog.FindName("btnSave").Add_Click({
        $result.Command = [string]$txtCommand.Text
        $dialog.DialogResult = $true
    }.GetNewClosure())
$dialog.FindName("btnCancel").Add_Click({ $dialog.Close() }.GetNewClosure())
$dialog.Add_ContentRendered({
        $txtCommand.Focus() | Out-Null
        $txtCommand.CaretIndex = $txtCommand.Text.Length
    }.GetNewClosure())

$dialog.ShowDialog() | Out-Null
if ($null -eq $result.Command) { return }
if ([string]::IsNullOrWhiteSpace([string]$result.Command)) {
    Remove-WmtCustomUpdateCommand -Source $source -Id $id
    Write-GuiLog "Removed custom update command for $name ($source / $id)."
}
else {
    Set-WmtCustomUpdateCommand -Source $source -Id $id -Name $name -Command $result.Command
    Write-GuiLog "Saved custom update command for $name ($source / $id)."
}
}

function Show-WmtCustomUpdateCommandManager {
param($SelectedPackage = $null)

$content = @'
<Grid Margin="18">
    <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <TextBlock Text="Saved custom update commands. Select an entry to edit it, or remove it to restore the normal provider command."
               TextWrapping="Wrap" Margin="0,0,0,12"/>
    <Grid Grid.Row="1">
        <DataGrid Name="dgCommands" AutoGenerateColumns="False" IsReadOnly="True" CanUserAddRows="False"
                  CanUserDeleteRows="False" SelectionMode="Single" SelectionUnit="FullRow" HeadersVisibility="Column">
            <DataGrid.Columns>
                <DataGridTextColumn Header="Source" Binding="{Binding Source}" Width="100"/>
                <DataGridTextColumn Header="Package" Binding="{Binding Name}" Width="170"/>
                <DataGridTextColumn Header="ID" Binding="{Binding Id}" Width="180"/>
                <DataGridTextColumn Header="Command" Binding="{Binding Command}" Width="*" MinWidth="140">
                    <DataGridTextColumn.ElementStyle>
                        <Style TargetType="TextBlock">
                            <Setter Property="TextWrapping" Value="NoWrap"/>
                            <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
                            <Setter Property="MaxHeight" Value="22"/>
                            <Setter Property="ToolTip" Value="{Binding Command}"/>
                        </Style>
                    </DataGridTextColumn.ElementStyle>
                </DataGridTextColumn>
            </DataGrid.Columns>
        </DataGrid>
        <TextBlock Name="lblEmpty" Text="No custom update commands saved yet." Visibility="Collapsed"
                   HorizontalAlignment="Center" VerticalAlignment="Center" IsHitTestVisible="False"/>
    </Grid>
    <TextBlock Name="lblSelectedPackage" Grid.Row="2" TextWrapping="Wrap" MaxHeight="44" Margin="0,10,0,0"/>
    <WrapPanel Grid.Row="3" HorizontalAlignment="Right" Margin="0,12,0,0">
        <Button Name="btnSetPackage" Content="Set for Selected Package..." MinWidth="200" Margin="0,0,8,6"/>
        <Button Name="btnEdit" Content="Edit..." Width="94" IsEnabled="False" Margin="0,0,8,6"/>
        <Button Name="btnRemove" Content="Remove" Width="94" IsEnabled="False" Margin="0,0,8,6"/>
        <Button Name="btnClose" Content="Close" Width="94" IsCancel="True" Margin="0,0,0,6"/>
    </WrapPanel>
</Grid>
'@
$dialog = New-WmtWindowFromXaml -Title "Custom Update Commands" -ContentXaml $content -Width 900 -Height 500 -MinWidth 700 -MinHeight 360
$grid = $dialog.FindName("dgCommands")
$lblEmpty = $dialog.FindName("lblEmpty")
$btnEdit = $dialog.FindName("btnEdit")
$btnRemove = $dialog.FindName("btnRemove")
$btnSetPackage = $dialog.FindName("btnSetPackage")
$canSetPackage = ($null -ne $SelectedPackage -and
    -not [string]::IsNullOrWhiteSpace([string]$SelectedPackage.Source) -and
    -not [string]::IsNullOrWhiteSpace([string]$SelectedPackage.Id))
$btnSetPackage.IsEnabled = $canSetPackage
$dialog.FindName("lblSelectedPackage").Text = if ($canSetPackage) {
    "Selected in Updates: $($SelectedPackage.Name) ($($SelectedPackage.Source) / $($SelectedPackage.Id))"
} else {
    "Select one package in the Updates list to add a custom command for it."
}

$reload = {
    param($PreferredItem = $null)
    if (-not $PreferredItem) { $PreferredItem = $grid.SelectedItem }
    $entries = @(Get-WmtCustomUpdateCommands | Sort-Object Source, Name, Id)
    $grid.ItemsSource = $entries
    $lblEmpty.Visibility = if ($entries.Count -eq 0) { "Visible" } else { "Collapsed" }
    $grid.SelectedItem = $null
    if ($PreferredItem) {
        foreach ($entry in $entries) {
            if ($entry.Source -ieq $PreferredItem.Source -and $entry.Id -ieq $PreferredItem.Id) {
                $grid.SelectedItem = $entry
                break
            }
        }
    }
    if (-not $grid.SelectedItem -and $entries.Count -gt 0) { $grid.SelectedIndex = 0 }
    $btnEdit.IsEnabled = ($null -ne $grid.SelectedItem)
    $btnRemove.IsEnabled = ($null -ne $grid.SelectedItem)
}.GetNewClosure()
$grid.Add_SelectionChanged({
    $btnEdit.IsEnabled = ($null -ne $grid.SelectedItem)
    $btnRemove.IsEnabled = ($null -ne $grid.SelectedItem)
}.GetNewClosure())
$btnEdit.Add_Click({
    $entry = $grid.SelectedItem
    if (-not $entry) { return }
    Show-WmtCustomUpdateCommandDialog -Item $entry -Owner $dialog
    & $reload $entry
}.GetNewClosure())
$btnSetPackage.Add_Click({
    if (-not $canSetPackage) { return }
    Show-WmtCustomUpdateCommandDialog -Item $SelectedPackage -Owner $dialog
    & $reload $SelectedPackage
}.GetNewClosure())
$btnRemove.Add_Click({
    $entry = $grid.SelectedItem
    if (-not $entry) { return }
    Remove-WmtCustomUpdateCommand -Source $entry.Source -Id $entry.Id
    Write-GuiLog "Removed custom update command for $($entry.Name) ($($entry.Source) / $($entry.Id))."
    & $reload
}.GetNewClosure())
$dialog.FindName("btnClose").Add_Click({ $dialog.Close() }.GetNewClosure())
& $reload $SelectedPackage
$dialog.ShowDialog() | Out-Null
}

function Get-WmtUpdateAutoScanMinutes {
param($Settings)

if (-not $Settings) { $Settings = Get-WmtSettings }

$value = 0
try {
    if ($Settings -is [System.Collections.IDictionary] -and $Settings.Contains("UpdateAutoScanMinutes")) {
        $value = [int]$Settings["UpdateAutoScanMinutes"]
    }
    elseif ($Settings.PSObject.Properties["UpdateAutoScanMinutes"]) {
        $value = [int]$Settings.UpdateAutoScanMinutes
    }
}
catch {
    $value = 0
}

if ($value -lt 0) { return 0 }
if ($value -gt 1440) { return 1440 }
return $value
}

function Set-WmtUpdateAutoScanMinutes {
param([int]$Minutes)

if ($Minutes -lt 0) { $Minutes = 0 }
if ($Minutes -gt 1440) { $Minutes = 1440 }

$settings = Get-WmtSettings
if ($settings -is [System.Collections.IDictionary]) {
    $settings["UpdateAutoScanMinutes"] = $Minutes
}
elseif ($settings.PSObject.Properties["UpdateAutoScanMinutes"]) {
    $settings.UpdateAutoScanMinutes = $Minutes
}
else {
    $settings | Add-Member -MemberType NoteProperty -Name "UpdateAutoScanMinutes" -Value $Minutes -Force
}
Save-WmtSettings -Settings $settings
}

