$script:WmtMemoryTrimBusy = $false

function Optimize-WmtLogMemory {
param([int]$MaxLines = $script:WmtMaxLogLines)

try {
    if (-not $script:LogBox) { return }
    if ($MaxLines -lt 50) { $MaxLines = 50 }

    $text = [string]$script:LogBox.Text
    if ([string]::IsNullOrEmpty($text)) { return }
    $lines = $text -split "`r?`n"
    if ($lines.Count -le $MaxLines) { return }

    $keep = $lines | Select-Object -Last $MaxLines
    $script:LogBox.Text = (($keep -join "`r`n").TrimEnd() + "`r`n")
    try { $script:LogBox.ScrollToEnd() } catch {}
}
catch {}
}

$script:WmtTrayMemoryTimer = $null
$script:WmtTrayMemoryTimerHandler = $null
$script:WmtTrayMemoryLastTrim = [DateTime]::MinValue

function Test-WmtAggressiveTrayMemoryMode {
try {
    return [bool]($script:WmtHiddenToTray -and (Get-WmtReduceRamInTray))
}
catch {
    return $false
}
}

function Test-WmtCleanerRuleMemoryCacheEnabled {
# Parsed cleaner definitions are one of WMT's largest managed-memory caches.
# Do not retain or recreate them while Reduce RAM in Tray is actively hiding WMT.
try {
    return -not (Test-WmtAggressiveTrayMemoryMode)
}
catch {
    return $true
}
}

function Clear-WmtCleanerRuleMemoryCaches {
# Keep all cleaner providers symmetrical. Disk JSON/INI caches remain intact;
# only the large parsed in-process object graphs are discarded.
$script:CleanerMlRulesMemoryCache = $null
$script:Winapp2RulesMemoryCache = $null
$script:Winapp3RulesMemoryCache = $null
}

function Test-WmtTrayMemoryBusy {
try {
    if (Get-Command Test-WmtUpdateScanEngineBusy -ErrorAction SilentlyContinue) {
        if (Test-WmtUpdateScanEngineBusy) { return $true }
    }
}
catch {}
try { if ($script:WmtUiBackgroundCommands -and $script:WmtUiBackgroundCommands.Count -gt 0) { return $true } } catch {}
try { if ($script:WmtRegistryCleanupActive) { return $true } } catch {}
try { if ($script:WmtLibraryCacheRunspace -or $script:WmtLibraryScanRunspace) { return $true } } catch {}
try { if ($script:WmtAppxLoadRunspace) { return $true } } catch {}
try { if ($script:FirewallLoadInProgress -or $script:FirewallDetailJob) { return $true } } catch {}
try { if ($script:DriverLoadInProgress) { return $true } } catch {}
try { if ($script:TweakStatesBgPS -or $script:FeaturesCheckPS) { return $true } } catch {}
try { if ($script:MyDeviceSectionJobs -and $script:MyDeviceSectionJobs.Count -gt 0) { return $true } } catch {}
return $false
}

function Stop-WmtTrayMemoryTimer {
if ($script:WmtTrayMemoryTimer) {
    try { $script:WmtTrayMemoryTimer.Stop() } catch {}
    try {
        if ($script:WmtTrayMemoryTimerHandler) {
            $script:WmtTrayMemoryTimer.Remove_Tick($script:WmtTrayMemoryTimerHandler)
        }
    }
    catch {}
}
$script:WmtTrayMemoryTimer = $null
$script:WmtTrayMemoryTimerHandler = $null
}

function Start-WmtTrayMemoryTimer {
Stop-WmtTrayMemoryTimer
if (-not (Test-WmtAggressiveTrayMemoryMode)) { return }

# A scheduled scan can recreate a runspace while WMT is hidden. Re-check every
# ten seconds and trim again as soon as the work is idle, but do nothing when
# the process is already near the low-memory target.
$script:WmtTrayMemoryLastTrim = [DateTime]::MinValue
$script:WmtTrayMemoryTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:WmtTrayMemoryTimer.Interval = [TimeSpan]::FromSeconds(10)
$script:WmtTrayMemoryTimerHandler = [System.EventHandler] {
    param($s, $e)
    if (-not (Test-WmtAggressiveTrayMemoryMode)) {
        Stop-WmtTrayMemoryTimer
        return
    }
    if (Test-WmtTrayMemoryBusy) { return }

    $proc = $null
    try {
        $proc = [System.Diagnostics.Process]::GetCurrentProcess()
        $proc.Refresh()
        if ($proc.WorkingSet64 -gt 32MB) {
            $now = Get-Date
            if (($now - $script:WmtTrayMemoryLastTrim).TotalSeconds -ge 60) {
                $script:WmtTrayMemoryLastTrim = $now
                Invoke-WmtMemoryTrim -Reason "tray-idle"
            }
        }
    }
    catch {}
    finally { try { if ($proc) { $proc.Dispose() } } catch {} }
}
$script:WmtTrayMemoryTimer.Add_Tick($script:WmtTrayMemoryTimerHandler)
$script:WmtTrayMemoryTimer.Start()
}

function Stop-WmtTrayTransientWorkers {
# Reduce-RAM mode is intentionally an idle shell while hidden. Keep scheduled
# update/cleaner timers, but cancel jobs whose only purpose is warming GUI pages.
if (-not (Test-WmtAggressiveTrayMemoryMode)) { return }

try {
    if ($script:preloadDeferTimer) {
        $script:preloadDeferTimer.Stop()
        $script:preloadDeferTimer = $null
    }
}
catch {}
try {
    if ($script:bootCacheTimer) {
        $script:bootCacheTimer.Stop()
        $script:bootCacheTimer = $null
    }
}
catch {}

try { Stop-WmtStartupBackgroundPreload } catch {}
try {
    Stop-MyDeviceSectionJobs
    $script:MyDeviceStatsStarted = $false
    $script:MyDeviceStatsPreloadMode = $false
}
catch {}

try { Stop-FirewallDetailLoad } catch {}
try { Stop-FirewallRuleLoad } catch {}
try { Stop-DriverLoad } catch {}

try { Unregister-WmtUiPollOperation -Name "AppxBackgroundLoad" } catch {}
$oldAppxPs = $script:WmtAppxLoadRunspace
$oldAppxAsync = $script:WmtAppxLoadAsyncResult
$script:WmtAppxLoadRunspace = $null
$script:WmtAppxLoadAsyncResult = $null
if ($oldAppxPs) {
    try { Stop-WmtPowerShellInvocationAsync -PowerShell $oldAppxPs -Invocation $oldAppxAsync -Name "AppX background load" } catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $oldAppxPs -Invocation $oldAppxAsync -Name "AppX background load" } catch {}
    }
}
$script:AppxListLoaded = $false

try { Unregister-WmtUiPollOperation -Name "LibraryCacheBuilder" } catch {}
$oldLibraryCachePs = $script:WmtLibraryCacheRunspace
$oldLibraryCacheAsync = $script:WmtLibraryCacheAsyncResult
$script:WmtLibraryCacheRunspace = $null
$script:WmtLibraryCacheAsyncResult = $null
if ($oldLibraryCachePs) {
    try { Stop-WmtPowerShellInvocationAsync -PowerShell $oldLibraryCachePs -Invocation $oldLibraryCacheAsync -Name "Library cache builder" } catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $oldLibraryCachePs -Invocation $oldLibraryCacheAsync -Name "Library cache builder" } catch {}
    }
}

try { Unregister-WmtUiPollOperation -Name "LibraryScan" } catch {}
$oldLibraryScanPs = $script:WmtLibraryScanRunspace
$oldLibraryScanAsync = $script:WmtLibraryScanAsyncResult
$script:WmtLibraryScanRunspace = $null
$script:WmtLibraryScanAsyncResult = $null
$script:WmtLibraryScanTimer = $null
if ($oldLibraryScanPs) {
    try { Stop-WmtPowerShellInvocationAsync -PowerShell $oldLibraryScanPs -Invocation $oldLibraryScanAsync -Name "Library scan" } catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $oldLibraryScanPs -Invocation $oldLibraryScanAsync -Name "Library scan" } catch {}
    }
}

try { Unregister-WmtUiPollOperation -Name "TweakStatesLoad" } catch {}
if ($script:TweakStatesBgTimeout) {
    try { $script:TweakStatesBgTimeout.Stop() } catch {}
    $script:TweakStatesBgTimeout = $null
}
$oldTweakPs = $script:TweakStatesBgPS
$oldTweakAsync = $script:TweakStatesBgAsync
$script:TweakStatesBgPS = $null
$script:TweakStatesBgAsync = $null
if ($oldTweakPs) {
    try { Stop-WmtPowerShellInvocationAsync -PowerShell $oldTweakPs -Invocation $oldTweakAsync -Name "Tweak state preload" } catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $oldTweakPs -Invocation $oldTweakAsync -Name "Tweak state preload" } catch {}
    }
}
$script:TweakStatesBgStarted = $false
$script:TweakStatesReady = $false

try { Unregister-WmtUiPollOperation -Name "OptionalFeaturesCheck" } catch {}
$oldFeaturesPs = $script:FeaturesCheckPS
$oldFeaturesAsync = $script:FeaturesCheckAsync
$script:FeaturesCheckPS = $null
$script:FeaturesCheckAsync = $null
if ($oldFeaturesPs) {
    try { Stop-WmtPowerShellInvocationAsync -PowerShell $oldFeaturesPs -Invocation $oldFeaturesAsync -Name "Optional features check" } catch {
        try { Start-WmtPowerShellCleanupDetached -PowerShell $oldFeaturesPs -Invocation $oldFeaturesAsync -Name "Optional features check" } catch {}
    }
}
$script:OptionalFeaturesReady = $false
$script:OptionalFeaturesCheckStarted = $false
}

function Enter-WmtAggressiveTrayMode {
if (-not (Test-WmtAggressiveTrayMemoryMode)) { return }
Stop-WmtTrayTransientWorkers
Invoke-WmtMemoryTrim -Reason "aggressive-tray"
Start-WmtTrayMemoryTimer
}

function Restore-WmtAggressiveTrayPage {
# Reload only whichever top-level page was active before hiding.
try {
    foreach ($buttonName in @($script:WmtTabTargetByButton.Keys)) {
        $panel = $script:WmtTabTargetByButton[$buttonName]
        if ($panel -and $panel.Visibility -eq [System.Windows.Visibility]::Visible) {
            $button = Get-Ctrl $buttonName
            if ($button) {
                $button.RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent))
            }
            break
        }
    }
}
catch {}
}

function Stop-WmtIdleRunspacePools {
# PowerShell runspaces retain loaded modules/session state even when no command is
# running. Close only completely idle pools; New-WmtPooledPowerShell recreates
# them lazily the next time a scheduled/background action actually needs one.
foreach ($poolKind in @("Background", "UiSupport")) {
    $pool = if ($poolKind -eq "UiSupport") { $script:WmtUiSupportPool } else { $script:WmtBackgroundPool }
    if (-not $pool) { continue }

    $idle = $false
    try {
        $max = [int]$pool.GetMaxRunspaces()
        $available = [int]$pool.GetAvailableRunspaces()
        $idle = ($max -gt 0 -and $available -ge $max)
    }
    catch {}

    if ($idle) {
        try { Reset-WmtRunspacePool -PoolKind $poolKind } catch {}
    }
}
}

function Clear-WmtTrayReloadableData {
# These collections are UI caches, not durable state. Dropping them while the
# window is hidden substantially reduces retained WPF/PowerShell objects. Their
# tabs already reload on demand when the user opens WMT again.
if (-not $script:WmtHiddenToTray) { return }

if (-not $script:FirewallLoadInProgress) {
    $script:AllFw = @()
    $script:FirewallRulesLoaded = $false
    $script:FirewallDetailCache = @{}
    try { if ($lstFw) { $lstFw.Items.Clear() } } catch {}
}

if (-not $script:DriverLoadInProgress) {
    try { if ($script:DriverPackages -and $script:DriverPackages.PSObject.Methods["Clear"]) { $script:DriverPackages.Clear() } } catch {}
    $script:DriverDeviceMap = @{}
    $script:DriverServiceMap = $null
    $script:DriverUsageLoaded = $false
    $script:DriverCacheLoaded = $false
    $script:DriverCacheLoadedAt = [DateTime]::MinValue
    try { if ($script:DriverCollectionView) { $script:DriverCollectionView.Refresh() } } catch {}
}

if (-not $script:WmtLibraryScanRunspace) {
    $script:WmtLibraryScanResults = $null
    try { if ($lstLibrary) { $lstLibrary.Items.Clear() } } catch {}
}

if (-not $script:WmtAppxLoadRunspace) {
    $script:AppxListLoaded = $false
    try { if ($lstAppxPackages) { $lstAppxPackages.Items.Clear() } } catch {}
}

# Quick Find results are disposable and can retain references into several
# page models even after the search flyout is no longer visible.
try { if ($lstSearchResults) { $lstSearchResults.Items.Clear() } } catch {}
}

function Invoke-WmtMemoryTrim {
param([string]$Reason = "manual")

if ($script:WmtMemoryTrimBusy) { return }
$script:WmtMemoryTrimBusy = $true
try {
    Stop-WmtStartupBackgroundPreload
    if (Test-WmtAggressiveTrayMemoryMode) {
        Stop-WmtTrayTransientWorkers
    }

    if ($script:MyDeviceCache) {
        try { $script:MyDeviceCache.Clear() } catch { $script:MyDeviceCache = @{} }
    }

    # Release parsed cleaner rule caches. Winapp3 must be dropped too;
    # these remain reloadable from the on-disk caches on the next Cleaner visit.
    Clear-WmtCleanerRuleMemoryCaches

    # Release game library caches (can be 30-80MB)
    $script:LegendaryLibraryCache = $null
    $script:WmtGogLibraryCache = $null
    $script:SteamLibraryCache = $null

    # Release firewall detail cache (can grow to 10-30MB)
    $script:FirewallDetailCache = $null

    # Release tweak state caches (re-loaded on next tab visit)
    $script:TweakButtonStatesCache = $null
    $script:TweakNonRegDataCache = $null
    $script:TweakSupportChecksCache = $null
    $script:TweakButtonStatesPathChecks = $null
    $script:TweakStatesReady = $false
    $script:TweakStatesBgStarted = $false
    $script:TweakStatesUpdating = $false
    $script:OptionalFeaturesReady = $false
    $script:OptionalFeaturesCheckStarted = $false
    # Cancel any tweak-state worker that survived the transient-worker cleanup.
    if ($script:TweakStatesBgPS) {
        $trimTweakPs = $script:TweakStatesBgPS
        $trimTweakAsync = $script:TweakStatesBgAsync
        $script:TweakStatesBgPS = $null
        $script:TweakStatesBgAsync = $null
        try { Stop-WmtPowerShellInvocationAsync -PowerShell $trimTweakPs -Invocation $trimTweakAsync -Name "Memory trim tweak-state cleanup" } catch {
            try { Start-WmtPowerShellCleanupDetached -PowerShell $trimTweakPs -Invocation $trimTweakAsync -Name "Memory trim tweak-state cleanup" } catch {}
        }
    }
    try { Unregister-WmtUiPollOperation -Name "TweakStatesLoad" } catch {}; $script:TweakStatesBgTimer = $null
    if ($script:TweakStatesBgTimeout) { try { $script:TweakStatesBgTimeout.Stop() } catch {}; $script:TweakStatesBgTimeout = $null }
    if ($script:TweakStatesDebounceTimer) { try { $script:TweakStatesDebounceTimer.Stop() } catch {}; $script:TweakStatesDebounceTimer = $null }
    # Cancel any optional-features worker that survived the transient-worker cleanup.
    if ($script:FeaturesCheckPS) {
        $trimFeaturesPs = $script:FeaturesCheckPS
        $trimFeaturesAsync = $script:FeaturesCheckAsync
        $script:FeaturesCheckPS = $null
        $script:FeaturesCheckAsync = $null
        try { Stop-WmtPowerShellInvocationAsync -PowerShell $trimFeaturesPs -Invocation $trimFeaturesAsync -Name "Memory trim optional-features cleanup" } catch {
            try { Start-WmtPowerShellCleanupDetached -PowerShell $trimFeaturesPs -Invocation $trimFeaturesAsync -Name "Memory trim optional-features cleanup" } catch {}
        }
    }
    try { Unregister-WmtUiPollOperation -Name "OptionalFeaturesCheck" } catch {}; $script:FeaturesCheckTimer = $null

    # Clear completed update ID tracking
    $script:WmtCompletedWindowsUpdateIds = $null
    $script:WmtCompletedWindowsUpdateIds = @{}

    if ($script:WmtHiddenToTray) {
        Clear-WmtTrayReloadableData
        # Completed work can leave large module/session-state graphs in the two
        # shared pools. Reclaim them only when every runspace in a pool is idle.
        Stop-WmtIdleRunspacePools
        Optimize-WmtLogMemory -MaxLines 150
    }
    else {
        Optimize-WmtLogMemory -MaxLines $script:WmtMaxLogLines
    }

    # Compact the LOH before the full blocking collection. Cleaner definitions,
    # package metadata and library JSON can allocate large temporary arrays that
    # otherwise keep committed heap segments around after their objects die.
    try {
        [System.Runtime.GCSettings]::LargeObjectHeapCompactionMode = [System.Runtime.GCLargeObjectHeapCompactionMode]::CompactOnce
    }
    catch {}
    try {
        [System.GC]::Collect([System.GC]::MaxGeneration, [System.GCCollectionMode]::Forced, $true, $true)
    }
    catch {
        [System.GC]::Collect()
    }
    [System.GC]::WaitForPendingFinalizers()
    [System.GC]::Collect()

    try {
        if (-not ("WmtMemoryNative" -as [type])) {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class WmtMemoryNative {
[DllImport("psapi.dll")]
public static extern bool EmptyWorkingSet(IntPtr hProcess);
}
"@ -ErrorAction Stop
        }
        $trimProcess = $null
        try {
            $trimProcess = [System.Diagnostics.Process]::GetCurrentProcess()
            [void][WmtMemoryNative]::EmptyWorkingSet($trimProcess.Handle)
        }
        finally { try { if ($trimProcess) { $trimProcess.Dispose() } } catch {} }
    }
    catch {}
}
finally {
    $script:WmtMemoryTrimBusy = $false
}
}
$script:WmtApplication = $null

function Get-WmtNotificationLaunchInfo {
$targetPath = $script:WmtProcessPath
$arguments = ""
$workingDirectory = $script:WmtRootPath
$iconPath = $script:WmtProcessPath

try {
    if (-not $script:WmtIsCompiledExe) {
        $pwsh = Get-Command "pwsh.exe" -ErrorAction SilentlyContinue
        $powershell = Get-Command "powershell.exe" -ErrorAction SilentlyContinue
        if ($pwsh) { $targetPath = $pwsh.Source }
        elseif ($powershell) { $targetPath = $powershell.Source }
        else { $targetPath = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe" }

        if (-not [string]::IsNullOrWhiteSpace($script:WmtScriptPath)) {
            $arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$script:WmtScriptPath`""
        }
        $iconPath = $targetPath
    }

    if ([string]::IsNullOrWhiteSpace($workingDirectory) -and -not [string]::IsNullOrWhiteSpace($targetPath)) {
        $workingDirectory = Split-Path -Parent $targetPath
    }
}
catch {}

return [PSCustomObject]@{
    TargetPath       = $targetPath
    Arguments        = $arguments
    WorkingDirectory = $workingDirectory
    IconPath         = $iconPath
}
}

function Initialize-WmtNativeToastSupport {
if ($script:WmtNativeToastReady) { return $true }
if ($script:WmtNativeToastUnavailable) { return $false }

try {
    if (-not $IsWindows -and $PSVersionTable.PSEdition -eq "Core") { return $false }
}
catch {}

try {
    [void][Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime]
    [void][Windows.UI.Notifications.ToastNotification, Windows.UI.Notifications, ContentType = WindowsRuntime]
    [void][Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom.XmlDocument, ContentType = WindowsRuntime]
}
catch {
    Write-GuiLog "Native toast API is unavailable: $($_.Exception.Message)"
    return $false
}

try {
    if (-not ([System.Management.Automation.PSTypeName]'WmtNotifications.DesktopToastShortcut').Type) {
        Add-Type -TypeDefinition @"
using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;

namespace WmtNotifications {
[ComImport]
[Guid("00021401-0000-0000-C000-000000000046")]
public class CShellLink {}

[ComImport]
[InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
[Guid("000214F9-0000-0000-C000-000000000046")]
public interface IShellLinkW {
    void GetPath([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszFile, int cchMaxPath, IntPtr pfd, uint fFlags);
    void GetIDList(out IntPtr ppidl);
    void SetIDList(IntPtr pidl);
    void GetDescription([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszName, int cchMaxName);
    void SetDescription([MarshalAs(UnmanagedType.LPWStr)] string pszName);
    void GetWorkingDirectory([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszDir, int cchMaxPath);
    void SetWorkingDirectory([MarshalAs(UnmanagedType.LPWStr)] string pszDir);
    void GetArguments([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszArgs, int cchMaxPath);
    void SetArguments([MarshalAs(UnmanagedType.LPWStr)] string pszArgs);
    void GetHotkey(out short pwHotkey);
    void SetHotkey(short wHotkey);
    void GetShowCmd(out int piShowCmd);
    void SetShowCmd(int iShowCmd);
    void GetIconLocation([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszIconPath, int cchIconPath, out int piIcon);
    void SetIconLocation([MarshalAs(UnmanagedType.LPWStr)] string pszIconPath, int iIcon);
    void SetRelativePath([MarshalAs(UnmanagedType.LPWStr)] string pszPathRel, uint dwReserved);
    void Resolve(IntPtr hwnd, uint fFlags);
    void SetPath([MarshalAs(UnmanagedType.LPWStr)] string pszFile);
}

[ComImport]
[InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
[Guid("0000010b-0000-0000-C000-000000000046")]
public interface IPersistFile {
    void GetClassID(out Guid pClassID);
    [PreserveSig]
    int IsDirty();
    void Load([MarshalAs(UnmanagedType.LPWStr)] string pszFileName, uint dwMode);
    void Save([MarshalAs(UnmanagedType.LPWStr)] string pszFileName, bool fRemember);
    void SaveCompleted([MarshalAs(UnmanagedType.LPWStr)] string pszFileName);
    void GetCurFile([MarshalAs(UnmanagedType.LPWStr)] out string ppszFileName);
}

[ComImport]
[InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
[Guid("00000138-0000-0000-C000-000000000046")]
public interface IPropertyStore {
    void GetCount(out uint cProps);
    void GetAt(uint iProp, out PROPERTYKEY pkey);
    void GetValue(ref PROPERTYKEY key, out PROPVARIANT pv);
    void SetValue(ref PROPERTYKEY key, ref PROPVARIANT pv);
    void Commit();
}

[StructLayout(LayoutKind.Sequential, Pack = 4)]
public struct PROPERTYKEY {
    public Guid fmtid;
    public uint pid;
    public PROPERTYKEY(Guid fmtid, uint pid) { this.fmtid = fmtid; this.pid = pid; }
}

[StructLayout(LayoutKind.Sequential, Pack = 4)]
public struct PROPVARIANT {
    public ushort vt;
    public ushort wReserved1;
    public ushort wReserved2;
    public ushort wReserved3;
    public IntPtr p;

    public static PROPVARIANT FromString(string value) {
        PROPVARIANT pv = new PROPVARIANT();
        pv.vt = 31; // VT_LPWSTR
        pv.p = Marshal.StringToCoTaskMemUni(value);
        return pv;
    }

    public void Clear() {
        PropVariantClear(ref this);
    }

    [DllImport("Ole32.dll")]
    private static extern int PropVariantClear(ref PROPVARIANT pvar);
}

public class ShortcutResult {
    public string ShortcutPath { get; set; }
    public bool AppIdSet { get; set; }
    public string Warning { get; set; }
}

public static class DesktopToastShortcut {
    private const uint GPS_READWRITE = 0x00000002;

    [DllImport("Shell32.dll", CharSet = CharSet.Unicode, PreserveSig = false)]
    private static extern void SHGetPropertyStoreFromParsingName(
        [MarshalAs(UnmanagedType.LPWStr)] string pszPath,
        IntPtr pbc,
        uint flags,
        ref Guid riid,
        out IPropertyStore ppv);

    private static bool TrySetAppId(IPropertyStore propStore, string appId, out string warning) {
        warning = null;
        if (propStore == null) {
            warning = "Property store was not available.";
            return false;
        }

        PROPERTYKEY appUserModelId = new PROPERTYKEY(new Guid("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3"), 5);
        PROPVARIANT pv = PROPVARIANT.FromString(appId);
        try {
            propStore.SetValue(ref appUserModelId, ref pv);
            propStore.Commit();
            return true;
        }
        catch (Exception ex) {
            warning = ex.Message;
            return false;
        }
        finally {
            pv.Clear();
        }
    }

    public static ShortcutResult EnsureShortcut(string shortcutName, string appId, string targetPath, string arguments, string workingDirectory, string iconPath) {
        string programsPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu), "Programs");
        Directory.CreateDirectory(programsPath);
        string shortcutPath = Path.Combine(programsPath, shortcutName + ".lnk");
        bool appIdSet = false;
        string warning = null;

        object shellLinkObject = new CShellLink();
        IShellLinkW link = (IShellLinkW)shellLinkObject;
        link.SetPath(targetPath);
        if (!String.IsNullOrEmpty(arguments)) { link.SetArguments(arguments); }
        if (!String.IsNullOrEmpty(workingDirectory)) { link.SetWorkingDirectory(workingDirectory); }
        if (!String.IsNullOrEmpty(iconPath)) { link.SetIconLocation(iconPath, 0); }
        link.SetDescription("Windows Maintenance Tool");

        try {
            appIdSet = TrySetAppId((IPropertyStore)shellLinkObject, appId, out warning);
        }
        catch (Exception ex) {
            warning = ex.Message;
        }

        IPersistFile file = (IPersistFile)shellLinkObject;
        file.Save(shortcutPath, true);

        if (!appIdSet) {
            try {
                Guid propertyStoreGuid = new Guid("00000138-0000-0000-C000-000000000046");
                IPropertyStore shortcutFileStore;
                SHGetPropertyStoreFromParsingName(shortcutPath, IntPtr.Zero, GPS_READWRITE, ref propertyStoreGuid, out shortcutFileStore);
                string secondaryWarning;
                if (TrySetAppId(shortcutFileStore, appId, out secondaryWarning)) {
                    appIdSet = true;
                    warning = null;
                }
                else if (!String.IsNullOrEmpty(secondaryWarning)) {
                    warning = secondaryWarning;
                }
            }
            catch (Exception ex) {
                warning = ex.Message;
            }
        }

        return new ShortcutResult { ShortcutPath = shortcutPath, AppIdSet = appIdSet, Warning = warning };
    }
}
}
"@
    }

    $launch = Get-WmtNotificationLaunchInfo
    if ([string]::IsNullOrWhiteSpace($launch.TargetPath) -or -not (Test-Path -LiteralPath $launch.TargetPath)) {
        # Non-fatal: fall back to the tray balloon path without showing a startup error.
        $script:WmtNativeToastUnavailable = $true
        return $false
    }

    $shortcutResult = [WmtNotifications.DesktopToastShortcut]::EnsureShortcut(
        "Windows Maintenance Tool",
        $script:WmtNotificationAppId,
        $launch.TargetPath,
        $launch.Arguments,
        $launch.WorkingDirectory,
        $launch.IconPath
    )

    if (-not $shortcutResult.AppIdSet) {
        # Non-fatal on some Windows/PowerShell COM combinations. The tray balloon path
        # still produces a native Windows notification, so keep startup logs clean.
        $script:WmtNativeToastUnavailable = $true
        return $false
    }

    $script:WmtNativeToastReady = $true
    return $true
}
catch {
    # Non-fatal: do not show a scary startup error when native toast registration fails.
    # The fallback notification path is expected to handle these environments.
    $script:WmtNativeToastUnavailable = $true
    return $false
}
}

function Show-WmtMainWindowFromTray {
try {
    if (-not $window) { return }
    $showAction = [Action] {
        try {
            if ($window.ShowInTaskbar -eq $false) { $window.ShowInTaskbar = $true }
            if ($window.Visibility -ne [System.Windows.Visibility]::Visible) { $window.Show() }
            if ($window.WindowState -eq [System.Windows.WindowState]::Minimized) {
                $window.WindowState = [System.Windows.WindowState]::Normal
            }
            $wasAggressiveTray = Test-WmtAggressiveTrayMemoryMode
            $script:WmtHiddenToTray = $false
            Stop-WmtTrayMemoryTimer
            $window.Activate() | Out-Null
            $window.Topmost = $true
            $window.Topmost = $false
            if ($wasAggressiveTray) {
                Restore-WmtAggressiveTrayPage
            }
            Write-GuiLog "WMT restored from the system tray."
        }
        catch {
            Write-GuiLog "Tray restore failed: $($_.Exception.Message)"
        }
    }

    if ($window.Dispatcher.CheckAccess()) { $showAction.Invoke() }
    else { [void]$window.Dispatcher.BeginInvoke($showAction) }
}
catch {}
}

function Start-WmtSingleInstanceActivationListener {
if (-not $script:WmtSingleInstanceActivationEvent -or $script:WmtSingleInstanceActivationTimer) { return }

$script:WmtSingleInstanceActivationTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:WmtSingleInstanceActivationTimer.Interval = [TimeSpan]::FromMilliseconds(350)
$script:WmtSingleInstanceActivationTimer.Add_Tick({
        try {
            if ($script:WmtSingleInstanceActivationEvent.WaitOne(0)) {
                Show-WmtMainWindowFromTray
            }
        }
        catch {}
    })
$script:WmtSingleInstanceActivationTimer.Start()
}

function Stop-WmtSingleInstanceActivationListener {
if ($script:WmtSingleInstanceActivationTimer) {
    try { $script:WmtSingleInstanceActivationTimer.Stop() } catch {}
    $script:WmtSingleInstanceActivationTimer = $null
}
}

function Show-WmtTrayPage {
param(
    [Parameter(Mandatory = $true)][string]$ButtonName,
    [string]$PageName = "page"
)

try {
    if (-not $window) { return }
    $pageAction = {
        try {
            Show-WmtMainWindowFromTray
            $tabButton = Get-Ctrl $ButtonName
            if ($tabButton -and $tabButton.IsEnabled) {
                $tabButton.RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent))
            }
            else {
                Write-GuiLog "Tray shortcut could not open $PageName because its navigation button is unavailable."
            }
        }
        catch {
            Write-GuiLog "Tray shortcut failed to open ${PageName}: $($_.Exception.Message)"
        }
    }.GetNewClosure()

    if ($window.Dispatcher.CheckAccess()) { & $pageAction }
    else { [void]$window.Dispatcher.BeginInvoke([Action]$pageAction) }
}
catch {}
}

function Invoke-WmtTrayThemeToggle {
try {
    if (-not $window) { return }
    $themeAction = [Action] {
        try {
            $nextTheme = if ($script:CurrentTheme -eq "dark") { "light" } else { "dark" }
            Set-WmtThemePreference -Theme $nextTheme
        }
        catch {
            Write-GuiLog "Tray theme toggle failed: $($_.Exception.Message)"
        }
    }

    if ($window.Dispatcher.CheckAccess()) { $themeAction.Invoke() }
    else { [void]$window.Dispatcher.BeginInvoke($themeAction) }
}
catch {}
}

function Invoke-WmtTrayUpdateScan {
try {
    if (-not $window) { return }
    if (Get-WmtUpdateScansDisabled) {
        Write-GuiLog "Tray update scan skipped because update scans are disabled."
        return
    }
    $scanAction = [Action] {
        try {
            Show-WmtMainWindowFromTray
            $updatesTab = Get-Ctrl "btnTabUpdates"
            if ($updatesTab) {
                $updatesTab.RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent))
            }

            $scanButton = Get-Ctrl "btnWingetScan"
            if ($scanButton -and $scanButton.IsEnabled) {
                $scanButton.RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent))
            }
            else {
                Write-GuiLog "Tray update scan skipped because an update scan is already running."
            }
        }
        catch {
            Write-GuiLog "Tray update scan failed: $($_.Exception.Message)"
        }
    }

    if ($window.Dispatcher.CheckAccess()) { $scanAction.Invoke() }
    else { [void]$window.Dispatcher.BeginInvoke($scanAction) }
}
catch {}
}

function Invoke-WmtFinalExitFromTray {
param($Window)

try {
    $exitAction = [Action] {
        try {
            $script:WmtAllowFinalClose = $true
            $script:WmtHiddenToTray = $false

            # Hide the tray icon immediately so Windows does not leave a stale/ghost icon.
            try { if ($script:WmtTrayIcon) { $script:WmtTrayIcon.Visible = $false } } catch {}

            # A hidden WPF window does not always terminate reliably from a WinForms tray callback.
            # Make it visible just long enough for Close() to run the normal cleanup path.
            if ($Window) {
                try { $Window.ShowInTaskbar = $true } catch {}
                try {
                    if ($Window.Visibility -ne [System.Windows.Visibility]::Visible) { $Window.Show() }
                }
                catch {}
                try { $Window.Close() }
                catch { Write-GuiLog "Tray exit window close failed: $($_.Exception.Message)" }
            }

            # Explicit shutdown is the important part: it prevents the script from staying alive
            # if WPF does not treat the hidden window close as the last-window shutdown.
            try {
                $app = $script:WmtApplication
                if (-not $app) { $app = [System.Windows.Application]::Current }
                if ($app) { $app.Shutdown() }
            }
            catch {
                Write-GuiLog "Tray exit application shutdown failed: $($_.Exception.Message)"
            }
        }
        catch {
            Write-GuiLog "Tray exit failed: $($_.Exception.Message)"
        }
    }

    if ($Window -and $Window.Dispatcher) {
        if ($Window.Dispatcher.CheckAccess()) { $exitAction.Invoke() }
        else { [void]$Window.Dispatcher.Invoke($exitAction) }
    }
    else {
        $exitAction.Invoke()
    }
}
catch {
    try { Write-GuiLog "Tray exit dispatch failed: $($_.Exception.Message)" } catch {}
}
}

function Get-WmtTrayIconImage {
try {
    if (
        $script:WmtIsCompiledExe -and
        -not [string]::IsNullOrWhiteSpace($script:WmtProcessPath) -and
        (Test-Path -LiteralPath $script:WmtProcessPath -PathType Leaf)
    ) {
        return [System.Drawing.Icon]::ExtractAssociatedIcon($script:WmtProcessPath)
    }
}
catch {}

return $null
}

function Set-WmtTrayMenuTheme {
param($Menu = $script:WmtTrayMenu)
if (-not $Menu) { return }

try {
    $background = [System.Drawing.ColorTranslator]::FromHtml((Get-WmtThemeHex -Key "BgPanel" -Fallback "#161B22"))
    $hover = [System.Drawing.ColorTranslator]::FromHtml((Get-WmtThemeHex -Key "BgHover" -Fallback "#30363D"))
    $border = [System.Drawing.ColorTranslator]::FromHtml((Get-WmtThemeHex -Key "BorderBrush" -Fallback "#30363D"))
    $foreground = [System.Drawing.ColorTranslator]::FromHtml((Get-WmtThemeHex -Key "TextPrimary" -Fallback "#E6EDF3"))
    $muted = [System.Drawing.ColorTranslator]::FromHtml((Get-WmtThemeHex -Key "TextMuted" -Fallback "#6E7681"))

    if (-not $Menu.Tag -or -not $Menu.Tag.PSObject.Properties["Background"]) {
        $Menu.Tag = [PSCustomObject]@{
            Background = $background
            Hover      = $hover
            Border     = $border
            Foreground = $foreground
            Muted      = $muted
        }
    }
    else {
        $Menu.Tag.Background = $background
        $Menu.Tag.Hover = $hover
        $Menu.Tag.Border = $border
        $Menu.Tag.Foreground = $foreground
        $Menu.Tag.Muted = $muted
    }

    $Menu.BackColor = $background
    $Menu.ForeColor = $foreground
    $Menu.ShowImageMargin = $false
    $Menu.ShowCheckMargin = $false

    foreach ($item in @($Menu.Items)) {
        if (-not $item) { continue }
        $item.BackColor = $background
        $item.ForeColor = $foreground
    }

    $Menu.Invalidate()
}
catch {
    try { Write-GuiLog "Tray menu theme update failed: $($_.Exception.Message)" } catch {}
}
}

function New-WmtTrayMenuRenderer {
param($Menu)

$renderer = New-Object System.Windows.Forms.ToolStripProfessionalRenderer
$renderer.RoundedEdges = $false

$renderer.Add_RenderToolStripBackground({
        param($s, $e)
        try {
            $state = $e.ToolStrip.Tag
            if (-not $state) { return }
            $brush = [System.Drawing.SolidBrush]::new($state.Background)
            try { $e.Graphics.FillRectangle($brush, $e.AffectedBounds) } finally { $brush.Dispose() }
        }
        catch {}
    }.GetNewClosure())

$renderer.Add_RenderMenuItemBackground({
        param($s, $e)
        try {
            $state = $e.Item.Owner.Tag
            if (-not $state) { return }
            $fill = if ($e.Item.Selected) { $state.Hover } else { $state.Background }
            $brush = [System.Drawing.SolidBrush]::new($fill)
            try { $e.Graphics.FillRectangle($brush, [System.Drawing.Rectangle]::new(0, 0, $e.Item.Width, $e.Item.Height)) } finally { $brush.Dispose() }
        }
        catch {}
    }.GetNewClosure())

$renderer.Add_RenderItemText({
        param($s, $e)
        try {
            $state = $e.Item.Owner.Tag
            if ($state) {
                $e.TextColor = if ($e.Item.Enabled) { $state.Foreground } else { $state.Muted }
            }
        }
        catch {}
    }.GetNewClosure())

$renderer.Add_RenderSeparator({
        param($s, $e)
        try {
            $state = $e.Item.Owner.Tag
            if (-not $state) { return }
            $pen = [System.Drawing.Pen]::new($state.Border)
            try {
                $y = [Math]::Floor($e.Item.Height / 2)
                $e.Graphics.DrawLine($pen, 8, $y, [Math]::Max(8, $e.Item.Width - 8), $y)
            }
            finally { $pen.Dispose() }
        }
        catch {}
    }.GetNewClosure())

$renderer.Add_RenderToolStripBorder({
        param($s, $e)
        try {
            $state = $e.ToolStrip.Tag
            if (-not $state) { return }
            $pen = [System.Drawing.Pen]::new($state.Border)
            try {
                $rect = [System.Drawing.Rectangle]::new(0, 0, [Math]::Max(0, $e.ToolStrip.Width - 1), [Math]::Max(0, $e.ToolStrip.Height - 1))
                $e.Graphics.DrawRectangle($pen, $rect)
            }
            finally { $pen.Dispose() }
        }
        catch {}
    }.GetNewClosure())

return $renderer
}

function Initialize-WmtTrayIcon {
param($Window)

if ($script:WmtTrayIcon) {
    try {
        Set-WmtTrayMenuTheme -Menu $script:WmtTrayMenu
        $script:WmtTrayIcon.Visible = $true
    }
    catch {}
    return $true
}

$trayIconImage = $null
try {
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
    Add-Type -AssemblyName System.Drawing -ErrorAction SilentlyContinue

    $menu = New-Object System.Windows.Forms.ContextMenuStrip
    $menu.ShowImageMargin = $false
    $menu.ShowCheckMargin = $false

    $openItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Open WMT"
    $updatesItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Open Updates"
    $scanItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Scan updates now"
    $healthItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Open System Health"
    $cleanupItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Open Cleanup"
    $driversItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Open Drivers"
    $utilsItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Open Utilities"
    $themeItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Toggle WMT theme"
    $themeItem.Name = "WmtThemeToggle"
    $exitItem = New-Object System.Windows.Forms.ToolStripMenuItem -ArgumentList "Exit WMT"

    [void]$menu.Items.Add($openItem)
    [void]$menu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    [void]$menu.Items.Add($updatesItem)
    [void]$menu.Items.Add($scanItem)
    [void]$menu.Items.Add($healthItem)
    [void]$menu.Items.Add($cleanupItem)
    [void]$menu.Items.Add($driversItem)
    [void]$menu.Items.Add($utilsItem)
    [void]$menu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    [void]$menu.Items.Add($themeItem)
    [void]$menu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    [void]$menu.Items.Add($exitItem)

    $menu.Renderer = New-WmtTrayMenuRenderer -Menu $menu
    Set-WmtTrayMenuTheme -Menu $menu
    $menu.Add_Opening({
            param($s, $e)
            try {
                # Do not use GetNewClosure here: a closure creates a dynamic module,
                # which gives $script:CurrentTheme a different script scope and can
                # make the tray label report the opposite theme.
                $themeToggle = $null
                foreach ($item in @($s.Items)) {
                    if ($item -and $item.Name -eq "WmtThemeToggle") {
                        $themeToggle = $item
                        break
                    }
                }
                if ($themeToggle) {
                    $themeToggle.Text = if ($script:CurrentTheme -eq "dark") { "Switch to light theme" } else { "Switch to dark theme" }
                }
                Set-WmtTrayMenuTheme -Menu $s
            }
            catch {}
        })

    $notifyIcon = New-Object System.Windows.Forms.NotifyIcon
    $trayIconImage = Get-WmtTrayIconImage
    $notifyIcon.Icon = if ($trayIconImage) { $trayIconImage } else { [System.Drawing.SystemIcons]::Application }
    $notifyIcon.Text = "Windows Maintenance Tool"
    $notifyIcon.ContextMenuStrip = $menu
    $notifyIcon.Visible = $true

    $openItem.Add_Click({ Show-WmtMainWindowFromTray }.GetNewClosure())
    $updatesItem.Add_Click({ Show-WmtTrayPage -ButtonName "btnTabUpdates" -PageName "Updates" }.GetNewClosure())
    $scanItem.Add_Click({ Invoke-WmtTrayUpdateScan }.GetNewClosure())
    $healthItem.Add_Click({ Show-WmtTrayPage -ButtonName "btnTabHealth" -PageName "System Health" }.GetNewClosure())
    $cleanupItem.Add_Click({ Show-WmtTrayPage -ButtonName "btnTabCleanup" -PageName "Cleanup" }.GetNewClosure())
    $driversItem.Add_Click({ Show-WmtTrayPage -ButtonName "btnTabDrivers" -PageName "Drivers" }.GetNewClosure())
    $utilsItem.Add_Click({ Show-WmtTrayPage -ButtonName "btnTabUtils" -PageName "Utilities" }.GetNewClosure())
    $themeItem.Add_Click({ Invoke-WmtTrayThemeToggle }.GetNewClosure())
    $exitItem.Add_Click({
            Invoke-WmtFinalExitFromTray -Window $Window
        }.GetNewClosure())

    $notifyIcon.Add_DoubleClick({ Show-WmtMainWindowFromTray }.GetNewClosure())
    $notifyIcon.Add_MouseDoubleClick({ Show-WmtMainWindowFromTray }.GetNewClosure())
    $notifyIcon.Add_MouseClick({
            param($s, $e)
            try {
                if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
                    Show-WmtMainWindowFromTray
                }
            }
            catch {}
        }.GetNewClosure())
    $notifyIcon.Add_BalloonTipClicked({ Show-WmtMainWindowFromTray }.GetNewClosure())

    $script:WmtTrayIcon = $notifyIcon
    $script:WmtTrayIconImage = $trayIconImage
    $trayIconImage = $null
    $script:WmtTrayMenu = $menu
    return $true
}
catch {
    try { if ($trayIconImage) { $trayIconImage.Dispose() } } catch {}
    Write-GuiLog "System tray initialization failed: $($_.Exception.Message)"
    return $false
}
}

function Show-WmtTrayHiddenBalloon {
try {
    if (-not $script:WmtTrayIcon) { return }
    if ($script:WmtTrayHideNotificationShown) { return }
    $script:WmtTrayHideNotificationShown = $true
    $script:WmtTrayIcon.BalloonTipTitle = "WMT is still running"
    $script:WmtTrayIcon.BalloonTipText = "Background update scans and notifications will continue from the system tray. Right-click the tray icon for shortcuts, theme controls, or Exit."
    $script:WmtTrayIcon.BalloonTipIcon = [System.Windows.Forms.ToolTipIcon]::Info
    $script:WmtTrayIcon.ShowBalloonTip(7000)
}
catch {}
}

function Remove-WmtTrayIcon {
try {
    if ($script:WmtTrayIcon) {
        $script:WmtTrayIcon.Visible = $false
        $script:WmtTrayIcon.Dispose()
    }
}
catch {}
try {
    if ($script:WmtTrayMenu) { $script:WmtTrayMenu.Dispose() }
}
catch {}
try {
    if ($script:WmtTrayIconImage) { $script:WmtTrayIconImage.Dispose() }
}
catch {}
$script:WmtTrayIcon = $null
$script:WmtTrayIconImage = $null
$script:WmtTrayMenu = $null
}

function Show-WmtNotificationFallbackBalloon {
param(
    [string]$Title,
    [string]$Message,
    [ValidateSet("Info", "Warning", "Error")][string]$Kind = "Info"
)

try {
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
    Add-Type -AssemblyName System.Drawing -ErrorAction SilentlyContinue

    $notifyIcon = New-Object System.Windows.Forms.NotifyIcon
    switch ($Kind) {
        "Warning" { $notifyIcon.Icon = [System.Drawing.SystemIcons]::Warning }
        "Error" { $notifyIcon.Icon = [System.Drawing.SystemIcons]::Error }
        default { $notifyIcon.Icon = [System.Drawing.SystemIcons]::Information }
    }
    $notifyIcon.Text = "Windows Maintenance Tool"
    $notifyIcon.BalloonTipTitle = $Title
    $notifyIcon.BalloonTipText = $Message
    switch ($Kind) {
        "Warning" { $notifyIcon.BalloonTipIcon = [System.Windows.Forms.ToolTipIcon]::Warning }
        "Error" { $notifyIcon.BalloonTipIcon = [System.Windows.Forms.ToolTipIcon]::Error }
        default { $notifyIcon.BalloonTipIcon = [System.Windows.Forms.ToolTipIcon]::Info }
    }
    $notifyIcon.Visible = $true
    $notifyIcon.ShowBalloonTip(9000)

    $disposeTimer = New-Object System.Windows.Threading.DispatcherTimer
    $disposeTimer.Interval = [TimeSpan]::FromSeconds(12)
    $notificationFallbackTimers = $script:WmtNotificationFallbackTimers
    $disposeTimer.Add_Tick({
            try { $this.Stop() } catch {}
            try { $notifyIcon.Visible = $false; $notifyIcon.Dispose() } catch {}
            try { [void]$notificationFallbackTimers.Remove($this) } catch {}
        }.GetNewClosure())
    [void]$notificationFallbackTimers.Add($disposeTimer)
    $disposeTimer.Start()
    return $true
}
catch {
    Write-GuiLog "Notification fallback failed: $($_.Exception.Message)"
    return $false
}
}

function Show-WmtNativeNotification {
param(
    [string]$Title,
    [string]$Message,
    [ValidateSet("Info", "Warning", "Error")][string]$Kind = "Info",
    [switch]$IgnoreSetting
)

if (-not $IgnoreSetting -and -not (Get-WmtUpdateNotificationsEnabled)) { return $false }
if ([string]::IsNullOrWhiteSpace($Title)) { $Title = "Windows Maintenance Tool" }
if ([string]::IsNullOrWhiteSpace($Message)) { return $false }

try {
    if (Initialize-WmtNativeToastSupport) {
        $template = [Windows.UI.Notifications.ToastTemplateType]::ToastText02
        $xml = [Windows.UI.Notifications.ToastNotificationManager]::GetTemplateContent($template)
        $textNodes = $xml.GetElementsByTagName("text")
        [void]$textNodes.Item(0).AppendChild($xml.CreateTextNode($Title))
        [void]$textNodes.Item(1).AppendChild($xml.CreateTextNode($Message))

        $toast = [Windows.UI.Notifications.ToastNotification]::new($xml)
        try { $toast.ExpirationTime = [DateTimeOffset]::Now.AddMinutes(15) } catch {}
        $notifier = [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier($script:WmtNotificationAppId)
        $notifier.Show($toast)
        Write-GuiLog "Native notification sent: $Title"
        return $true
    }
}
catch {
    Write-GuiLog "Native toast failed: $($_.Exception.Message)"
}

return (Show-WmtNotificationFallbackBalloon -Title $Title -Message $Message -Kind $Kind)
}

function Stop-WmtNotificationFallbackTimers {
try {
    foreach ($timer in @($script:WmtNotificationFallbackTimers)) {
        try { $timer.Stop() } catch {}
    }
    $script:WmtNotificationFallbackTimers.Clear()
}
catch {}
}

function Show-WmtUpdateScanNotification {
param(
    [int]$UpdateCount,
    [int]$ErrorCount = 0,
    [switch]$TimedOut
)

if (-not (Get-WmtUpdateNotificationsEnabled)) { return }

if ($TimedOut) {
    [void](Show-WmtNativeNotification -Title "Update scan timed out" -Message "One or more package providers did not respond within 120 seconds." -Kind Warning)
    return
}

if ($UpdateCount -gt 0) {
    $noun = if ($UpdateCount -eq 1) { "update" } else { "updates" }
    [void](Show-WmtNativeNotification -Title "Updates available" -Message "WMT found $UpdateCount available $noun. Open the Updates page to review them." -Kind Info)
    return
}

if ($ErrorCount -gt 0) {
    $noun = if ($ErrorCount -eq 1) { "provider" } else { "providers" }
    [void](Show-WmtNativeNotification -Title "Update scan incomplete" -Message "$ErrorCount package $noun returned an error. Check the WMT log for details." -Kind Warning)
}
}

function Show-WmtBackgroundInstallNotification {
param(
    [ValidateSet("Started", "Completed", "Interrupted")][string]$Status,
    [int]$TotalCount = 0,
    [int]$SuccessCount = 0,
    [int]$SkippedCount = 0,
    [int]$FailedCount = 0
)

if (-not (Get-WmtUpdateNotificationsEnabled)) { return }

if ($Status -eq "Started") {
    $noun = if ($TotalCount -eq 1) { "update" } else { "updates" }
    [void](Show-WmtNativeNotification -Title "Background updates installing" -Message "WMT is automatically installing $TotalCount available $noun." -Kind Info)
    return
}

if ($Status -eq "Interrupted") {
    [void](Show-WmtNativeNotification -Title "Background updates interrupted" -Message "Automatic update installation stopped because the WMT update monitor encountered an error. Check the WMT log for details." -Kind Warning)
    return
}

if ($FailedCount -gt 0) {
    $message = "Background installation finished: $SuccessCount succeeded, $SkippedCount skipped, and $FailedCount failed. Check the WMT log for details."
    [void](Show-WmtNativeNotification -Title "Background updates completed with failures" -Message $message -Kind Warning)
    return
}

$message = "Background installation finished: $SuccessCount succeeded"
if ($SkippedCount -gt 0) { $message += " and $SkippedCount skipped" }
$message += "."
[void](Show-WmtNativeNotification -Title "Background updates complete" -Message $message -Kind Info)
}

function Show-DownloadStats {
$done = {
    param($results)
    $msg = [string](@($results | Select-Object -Last 1)[0])
    if ([string]::IsNullOrWhiteSpace($msg)) { $msg = "No release data returned." }
    Show-WmtMessageBox -Message $msg -Title "Latest Release Downloads" -Image Information | Out-Null
}.GetNewClosure()
$failed = {
    param($errorRecord)
    $msg = if ($errorRecord -and $errorRecord.Exception) { "Failed to fetch download stats: $($errorRecord.Exception.Message)" } else { "Failed to fetch download stats: $errorRecord" }
    Show-WmtMessageBox -Message $msg -Title "Latest Release Downloads" -Image Error | Out-Null
}.GetNewClosure()
Invoke-WmtUiBackgroundCommand -Name "ReleaseDownloadStats" -Msg "Fetching latest release download counts..." -SuppressResultLog -Sb {
    $repo = "ios12checker/Windows-Maintenance-Tool"
    $rel = Invoke-RestMethod -Uri "https://api.github.com/repos/$repo/releases/latest" -UseBasicParsing -ErrorAction Stop
    if (-not $rel -or -not $rel.assets) { throw "No release data returned." }
    $total = ($rel.assets | Measure-Object download_count -Sum).Sum
    $lines = @("Release: $($rel.name)", "Total downloads: $total", "")
    foreach ($a in $rel.assets) { $lines += ("{0} : {1}" -f $a.name, $a.download_count) }
    $lines -join "`r`n"
} -OnComplete $done -OnError $failed | Out-Null
}

# --- UPDATE CHECKER ---
function Start-UpdateCheckBackground {
# 1. Access LogBox
$lbStart = Get-Ctrl "LogBox"
if ($lbStart) { 
    $lbStart.AppendText("`n[UPDATE] Checking for updates...`n") 
    $lbStart.ScrollToEnd()
}

$localVersionStr = $script:AppVersion
$runningAsExe = [bool]$script:WmtIsCompiledExe

# 2. Start Background Thread (Runspace)
$script:UpdateRunspace = (New-WmtPooledPowerShell -PoolKind UiSupport).AddScript({
        param($CurrentVer, $IsExe)
        try {
            $wmtTlsProtocols = [Net.ServicePointManager]::SecurityProtocol
            if ([int]$wmtTlsProtocols -ne 0) {
                [Net.ServicePointManager]::SecurityProtocol = $wmtTlsProtocols -bor [Net.SecurityProtocolType]::Tls12
            }
        }
        catch {}

        $jobRes = @{ Status = "Failed"; RemoteVersion = "0.0"; RemoteHash = ""; RemoteLastModifiedUtc = ""; Content = ""; Error = ""; ExeDownloadUrl = ""; RemoteBytes = $null; ExeAssetName = ""; ExeSha256 = ""; ChecksumStatus = "None" }

        try {
            if ($IsExe) {
                # For EXE: Check GitHub releases API
                $url = "https://api.github.com/repos/ios12checker/Windows-Maintenance-Tool/releases/latest"
                $req = Invoke-RestMethod -Uri $url -UseBasicParsing -TimeoutSec 10

                if ($req -and $req.tag_name) {
                    # Parse tag_name (format: v5, v6, v5.9, etc.)
                    $tagName = $req.tag_name
                    # Remove leading 'v' if present
                    $versionStr = $tagName -replace '^v', ''
                    $jobRes.RemoteVersion = $versionStr

                    # Look for EXE in release assets
                    if ($req.assets -and $req.assets.Count -gt 0) {
                        $exeAsset = $req.assets | Where-Object { $_.name -match '\.exe$' } | Select-Object -First 1
                        if ($exeAsset) {
                            $jobRes.ExeDownloadUrl = $exeAsset.browser_download_url
                            $jobRes.ExeAssetName = [string]$exeAsset.name

                            # Safety: find a published SHA256 checksum asset for this EXE
                            # (<exe>.sha256, SHA256SUMS / checksums.txt / hashes.txt)
                            $ckAsset = $req.assets | Where-Object { $_.name -ieq ($exeAsset.name + '.sha256') } | Select-Object -First 1
                            if (-not $ckAsset) {
                                $ckAsset = $req.assets | Where-Object { ($_.name -match '(?i)sha256|checksum|hashes') -and ($_.name -match '(?i)\.(txt|sha256)$') } | Select-Object -First 1
                            }
                            if ($ckAsset) {
                                $jobRes.ChecksumStatus = "Found"
                                try {
                                    $ckContent = (Invoke-WebRequest -Uri $ckAsset.browser_download_url -UseBasicParsing -TimeoutSec 10).Content
                                    if ($ckContent -isnot [string]) { $ckContent = [System.Text.Encoding]::UTF8.GetString([byte[]]$ckContent) }
                                    foreach ($ckLine in ($ckContent -split "\r?\n")) {
                                        $ckT = $ckLine.Trim()
                                        if (-not $ckT) { continue }
                                        # "sha256sum" style: <64-hex>  <name>   /   "name: hash" style
                                        $ckM = [regex]::Match($ckT, '^([0-9a-fA-F]{64})\s+\*?(.+)$')
                                        if ($ckM.Success) {
                                            $ckName = [IO.Path]::GetFileName($ckM.Groups[2].Value.Trim().Trim('*'))
                                            if ($ckName -ieq [string]$exeAsset.name) { $jobRes.ExeSha256 = $ckM.Groups[1].Value.ToLowerInvariant(); break }
                                        }
                                        $ckM = [regex]::Match($ckT, '^(.+?)\s*[:=]\s*([0-9a-fA-F]{64})$')
                                        if ($ckM.Success) {
                                            $ckName = [IO.Path]::GetFileName($ckM.Groups[1].Value.Trim().Trim('*'))
                                            if ($ckName -ieq [string]$exeAsset.name) { $jobRes.ExeSha256 = $ckM.Groups[2].Value.ToLowerInvariant(); break }
                                        }
                                    }
                                }
                                catch { $jobRes.ChecksumStatus = "Failed" }
                            }
                        }
                    }

                    if ($jobRes.ExeDownloadUrl) {
                        $jobRes.Status = "Success"
                    }
                    else {
                        $jobRes.Error = "Release found but no EXE asset found."
                    }
                }
                else {
                    $jobRes.Error = "No release found or missing tag_name."
                }
            }
            else {
                # For Script: Download and parse WMT-GUI.ps1
                $time = Get-Date -Format "yyyyMMddHHmmss"
                $url = "https://raw.githubusercontent.com/ios12checker/Windows-Maintenance-Tool/main/WMT-GUI.ps1?t=$time"

                # Shorter timeout for UI responsiveness
                $req = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 10

                # Safety: keep the RAW download bytes so the installed file can later be
                # verified byte-for-byte against the SHA256 of exactly what GitHub served
                $rawBytes = $null
                try { if ($req.RawContentStream -and $req.RawContentStream.Length -gt 0) { $rawBytes = $req.RawContentStream.ToArray() } } catch {}
                if (-not $rawBytes -or $rawBytes.Length -lt 200) {
                    if ($req.Content -is [byte[]]) { $rawBytes = [byte[]]$req.Content }
                    else { $rawBytes = [System.Text.Encoding]::UTF8.GetBytes([string]$req.Content) }
                }
                $jobRes.RemoteBytes = $rawBytes

                $content = [System.Text.Encoding]::UTF8.GetString($rawBytes)
                $jobRes.Content = $content
                try {
                    $lm = $req.Headers["Last-Modified"]
                    if ($lm) {
                        $jobRes.RemoteLastModifiedUtc = ([DateTime]::Parse($lm)).ToUniversalTime().ToString("o")
                    }
                }
                catch {}
                # SHA256 of the raw download - the hash the installed file must match
                $sha = [System.Security.Cryptography.SHA256]::Create()
                try {
                    $hashBytes = $sha.ComputeHash($rawBytes)
                    $jobRes.RemoteHash = ([System.BitConverter]::ToString($hashBytes)).Replace("-", "")
                }
                finally {
                    $sha.Dispose()
                }

                $versionPattern = '(\d+(?:\.\d+){0,3})'
                $appVersionRegex = '\$AppVersion\s*=\s*[^\d\r\n]*(\d+(?:\.\d+){0,3})'
                if ($content -match $appVersionRegex) {
                    $jobRes.RemoteVersion = $matches[1]
                    $jobRes.Status = "Success"
                }
                elseif ($content -match ("Windows Maintenance Tool.*v{0}" -f $versionPattern)) {
                    $jobRes.RemoteVersion = $matches[1]
                    $jobRes.Status = "Success"
                }
                else {
                    $jobRes.Error = "Version string not found."
                }
            }
        }
        catch {
            $jobRes.Error = $_.Exception.Message
        }
        return $jobRes
    }).AddArgument($localVersionStr).AddArgument($runningAsExe)

$script:UpdateAsyncResult = $script:UpdateRunspace.BeginInvoke()

# 3. Setup Timer
$script:UpdateTimer = $null
# Reset the per-check timeout counter. The shared poller persists across checks,
# so carrying this value forward causes later checks to time out prematurely.
$script:UpdateTicks = 0
Register-WmtUiPollOperation -Name "SelfUpdateCheck" -IntervalMs 500 -TestComplete { $false } -OnTick {
        $lb = Get-Ctrl "LogBox"
        $script:UpdateTicks++

        # A. Timeout Check (20s)
        if ($script:UpdateTicks -gt 40) {
            Unregister-WmtUiPollOperation -Name "SelfUpdateCheck"
            $timedOutUpdatePs = $script:UpdateRunspace
            $timedOutUpdateAsync = $script:UpdateAsyncResult
            $script:UpdateRunspace = $null
            $script:UpdateAsyncResult = $null
            try {
                if ($timedOutUpdatePs) {
                    Stop-WmtPowerShellInvocationAsync -PowerShell $timedOutUpdatePs -Invocation $timedOutUpdateAsync -Name "Self-update check timeout"
                }
            }
            catch {
                # Never synchronously dispose a still-active updater from the WPF thread.
                try {
                    if ($timedOutUpdatePs) {
                        Start-WmtPowerShellCleanupDetached -PowerShell $timedOutUpdatePs -Invocation $timedOutUpdateAsync -Name "Self-update check timeout"
                    }
                }
                catch {}
            }
            if ($lb) { $lb.AppendText("[UPDATE] Error: Request timed out.`n"); $lb.ScrollToEnd() }
            return
        }

        # B. Check Job Status
        if ($script:UpdateAsyncResult.IsCompleted) {
            Unregister-WmtUiPollOperation -Name "SelfUpdateCheck"

            try {
                $jobResult = $script:UpdateRunspace.EndInvoke($script:UpdateAsyncResult)
                $script:UpdateRunspace.Dispose()

                # Retrieve the actual object (EndInvoke returns a collection)
                if ($jobResult -is [System.Collections.ObjectModel.Collection[PSObject]]) {
                    $jobResult = $jobResult[0]
                }

                if ($jobResult.Status -eq "Success") {
                    $localVerText = [string]$script:AppVersion
                    $remoteVerText = [string]$jobResult.RemoteVersion
                    $localVer = ConvertTo-WmtVersion $localVerText
                    $remoteVer = ConvertTo-WmtVersion $remoteVerText

                    if ($lb) { 
                        $lb.AppendText("[UPDATE] Local: v$localVerText | Remote: v$remoteVerText`n")
                        $lb.ScrollToEnd()
                    }

                    if ($remoteVer -gt $localVer) {
                        if ($lb) {
                            $lb.AppendText(" -> Update Available!`n")
                            if ($jobResult.RemoteHash) { $lb.AppendText("[UPDATE] Remote SHA256: $($jobResult.RemoteHash)`n") }
                            $lb.ScrollToEnd()
                        }

                        # This callback runs after Start-UpdateCheckBackground returns;
                        # use persistent script state instead of a dead local closure.
                        if ($script:WmtIsCompiledExe) {
                            if ($lb) {
                                $lb.AppendText("[UPDATE] Newer EXE release available. Prompting user...`n")
                                if ($jobResult.ChecksumStatus -eq "Found" -and $jobResult.ExeSha256) { $lb.AppendText("[UPDATE] Release publishes a SHA256 checksum - the download will be verified against it.`n") }
                                elseif ($jobResult.ChecksumStatus -eq "Found") { $lb.AppendText("[UPDATE] Note: checksum file has no entry for this EXE - hash will be logged for manual verification.`n") }
                                elseif ($jobResult.ChecksumStatus -eq "Failed") { $lb.AppendText("[UPDATE] Note: release checksum file could not be downloaded - hash will be logged for manual verification.`n") }
                                $lb.ScrollToEnd()
                            }

                            $msg = "A new version is available!`n`nLocal Version:  v$localVerText`nRemote Version: v$remoteVerText`n`nDo you want to download and install the update now?"
                            $mbRes = [System.Windows.MessageBox]::Show($msg, "Update Available", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Information)
                            if ($mbRes -eq [System.Windows.MessageBoxResult]::Yes) {
                                $downloadUrl = [string]$jobResult.ExeDownloadUrl
                                $expectedHash = [string]$jobResult.ExeSha256
                                $checksumStatus = [string]$jobResult.ChecksumStatus
                                $currentExe = [string]$script:WmtProcessPath
                                $updateWindow = $window
                                $updateLogBox = $lb
                                $allowFinalCloseState = Get-Variable -Name WmtAllowFinalClose -Scope Script

                                $updateComplete = {
                                    param($Results)
                                    $result = @($Results | Where-Object { $_ -and $_.PSObject.Properties["CurrentExe"] } | Select-Object -Last 1)
                                    if ($result.Count -eq 0) { throw "The updater completed without a result." }
                                    $result = $result[0]

                                    if ($updateLogBox) {
                                        foreach ($line in @($result.LogLines)) {
                                            if (-not [string]::IsNullOrWhiteSpace([string]$line)) {
                                                $updateLogBox.AppendText("[UPDATE] $line`n")
                                            }
                                        }
                                        $updateLogBox.ScrollToEnd()
                                    }

                                    [System.Windows.MessageBox]::Show("Update installed successfully! The application will restart with the new version.", "Update Complete", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                                    Start-Process -FilePath ([string]$result.CurrentExe) -WorkingDirectory (Split-Path -Parent ([string]$result.CurrentExe))
                                    $allowFinalCloseState.Value = $true
                                    $updateWindow.Close()
                                }.GetNewClosure()

                                $updateFailed = {
                                    param($ErrorRecord)
                                    $message = if ($ErrorRecord -is [System.Exception]) { $ErrorRecord.Message } elseif ($ErrorRecord.Exception) { $ErrorRecord.Exception.Message } else { [string]$ErrorRecord }
                                    $errMsg = "Update failed: $message"
                                    if ($updateLogBox) {
                                        $updateLogBox.AppendText("[UPDATE] ERROR: $errMsg`n")
                                        $updateLogBox.ScrollToEnd()
                                    }
                                    [System.Windows.MessageBox]::Show("$errMsg`n`nPlease download the update manually from the Releases page.", "Update Failed", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
                                }.GetNewClosure()

                                Invoke-WmtUiBackgroundCommand -Name "SelfUpdateInstallExe" -Msg "Downloading and installing update..." -SuppressResultLog -Sb {
                                    param(
                                        [string]$DownloadUrl,
                                        [string]$ExpectedHash,
                                        [string]$ChecksumStatus,
                                        [string]$CurrentExe
                                    )

                                    $tempExe = $null
                                    $backupExe = $null
                                    $backupCreated = $false
                                    $updateApplied = $false
                                    $logLines = [System.Collections.Generic.List[string]]::new()

                                    try {
                                        if ([string]::IsNullOrWhiteSpace($DownloadUrl)) { throw "No download URL found for EXE." }
                                        if ([string]::IsNullOrWhiteSpace($CurrentExe) -or -not (Test-Path -LiteralPath $CurrentExe)) { throw "Could not resolve the running EXE path." }

                                        [void]$logLines.Add("Downloading new EXE from: $DownloadUrl")
                                        $tempExe = Join-Path ([System.IO.Path]::GetTempPath()) ("WMT-GUI-Update-" + [System.Guid]::NewGuid().ToString("N") + ".exe")
                                        Invoke-WebRequest -Uri $DownloadUrl -OutFile $tempExe -TimeoutSec 60 | Out-Null

                                        if (-not (Test-Path -LiteralPath $tempExe)) { throw "Failed to download update file." }
                                        $fileSize = (Get-Item -LiteralPath $tempExe).Length
                                        if ($fileSize -lt 1MB) { throw "Downloaded file is suspiciously small ($fileSize bytes). Update may have failed." }

                                        $fsPe = [System.IO.File]::OpenRead($tempExe)
                                        try { $peB0 = $fsPe.ReadByte(); $peB1 = $fsPe.ReadByte() } finally { $fsPe.Dispose() }
                                        if ($peB0 -ne 0x4D -or $peB1 -ne 0x5A) { throw "Downloaded file is not a Windows executable (MZ header missing). Update aborted." }

                                        $downloadHash = (Get-FileHash -LiteralPath $tempExe -Algorithm SHA256).Hash.ToLowerInvariant()
                                        [void]$logLines.Add("Downloaded EXE SHA256: $downloadHash")

                                        if (-not [string]::IsNullOrWhiteSpace($ExpectedHash)) {
                                            if ($downloadHash -ne $ExpectedHash.ToLowerInvariant()) {
                                                throw "SHA256 MISMATCH! The downloaded EXE does not match the release checksum ($ExpectedHash). Update aborted - nothing was replaced."
                                            }
                                            [void]$logLines.Add("SHA256 verified against the release checksum file.")
                                        }
                                        elseif ($ChecksumStatus -eq "None") {
                                            [void]$logLines.Add("Release publishes no SHA256 checksum file; downloaded hash is logged above.")
                                        }

                                        $backupExe = "$CurrentExe.backup"
                                        Copy-Item -LiteralPath $CurrentExe -Destination $backupExe -Force
                                        $backupCreated = $true
                                        [void]$logLines.Add("Backup created at: $backupExe")

                                        Copy-Item -LiteralPath $tempExe -Destination $CurrentExe -Force
                                        $installedHash = (Get-FileHash -LiteralPath $CurrentExe -Algorithm SHA256).Hash.ToLowerInvariant()
                                        if ($installedHash -ne $downloadHash) {
                                            throw "Installed EXE failed SHA256 verification (disk write did not match the download)."
                                        }
                                        $updateApplied = $true

                                        Remove-Item -LiteralPath $tempExe -Force -ErrorAction SilentlyContinue
                                        $tempExe = $null
                                        [void]$logLines.Add("Update installed and integrity verified.")

                                        [PSCustomObject]@{
                                            CurrentExe = $CurrentExe
                                            BackupExe  = $backupExe
                                            LogLines   = $logLines.ToArray()
                                        }
                                    }
                                    catch {
                                        if (-not $updateApplied -and $backupCreated -and $backupExe -and (Test-Path -LiteralPath $backupExe)) {
                                            Copy-Item -LiteralPath $backupExe -Destination $CurrentExe -Force -ErrorAction SilentlyContinue
                                        }
                                        if ($tempExe -and (Test-Path -LiteralPath $tempExe)) {
                                            Remove-Item -LiteralPath $tempExe -Force -ErrorAction SilentlyContinue
                                        }
                                        throw
                                    }
                                } -ArgumentList @($downloadUrl, $expectedHash, $checksumStatus, $currentExe) -OnComplete $updateComplete -OnError $updateFailed | Out-Null
                            }
                            return
                        }

                        # Use Dispatcher to show dialog on UI thread
                        $window.Dispatcher.Invoke([Action] {
                                $msg = "A new version is available!`n`nLocal Version:  v$localVerText`nRemote Version: v$remoteVerText`n`nDo you want to update now?"
                                $mbRes = [System.Windows.MessageBox]::Show($msg, "Update Available", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Information)

                                if ($mbRes -eq [System.Windows.MessageBoxResult]::Yes) {
                                    $scriptPath = $null
                                    $backupPath = $null
                                    $updateApplied = $false
                                    try {
                                        $remoteContent = [string]$jobResult.Content
                                        if ([string]::IsNullOrWhiteSpace($remoteContent) -or $remoteContent.Length -lt 200) {
                                            throw "Downloaded update content was empty or invalid."
                                        }
                                        $remoteContent = $remoteContent.TrimStart([char]0xFEFF)

                                        # Safety: structural check - refuse to overwrite the running script
                                        # with content that does not look like a WMT script
                                        if (($remoteContent -notmatch '\$AppVersion\s*=') -and ($remoteContent -notmatch 'Windows\s+Maintenance\s+Tool')) {
                                            throw "Downloaded update does not look like a WMT script (safety check failed)."
                                        }

                                        # The shared UI poll callback runs after Start-UpdateCheckBackground
                                        # returns, so resolve the script path from the startup-captured script scope.
                                        # $script:WmtScriptPath is captured at startup and remains valid when
                                        # WMT-GUI.ps1 is launched directly with powershell.exe -File (issue #161).
                                        $scriptPath = $script:WmtScriptPath
                                        if ([string]::IsNullOrWhiteSpace($scriptPath) -or -not (Test-Path $scriptPath)) {
                                            throw "Could not resolve script path for self-update."
                                        }

                                        $backupName = "$(Split-Path $scriptPath -Leaf).bak"
                                        $backupPath = Join-Path (Get-DataPath) $backupName
                                        Copy-Item -Path $scriptPath -Destination $backupPath -Force

                                        # Write byte-exact when the raw download is available, so the
                                        # installed file hashes identical to what GitHub served
                                        $wroteExactBytes = $false
                                        try {
                                            if ($jobResult.RemoteBytes) {
                                                [System.IO.File]::WriteAllBytes($scriptPath, [byte[]]$jobResult.RemoteBytes)
                                                $wroteExactBytes = $true
                                            }
                                        }
                                        catch { $wroteExactBytes = $false }
                                        if (-not $wroteExactBytes) {
                                            Set-Content -Path $scriptPath -Value $remoteContent -Encoding UTF8 -Force
                                        }

                                        # Safety: SHA256 verification of the installed file, with automatic
                                        # rollback to the backup when it does not match
                                        $expectedHash = [string]$jobResult.RemoteHash
                                        $verified = $false
                                        if ($wroteExactBytes -and $expectedHash) {
                                            $appliedHash = (Get-FileHash -LiteralPath $scriptPath -Algorithm SHA256).Hash
                                            $verified = ($appliedHash -eq $expectedHash)
                                            if ($lb) { $lb.AppendText("[UPDATE] Installed SHA256: $appliedHash (expected $expectedHash)`n"); $lb.ScrollToEnd() }
                                        }
                                        else {
                                            $verified = ((Test-Path $scriptPath) -and ((Get-Item $scriptPath).Length -gt 100KB))
                                            if ($expectedHash -and $lb) { $lb.AppendText("[UPDATE] Remote SHA256: $expectedHash (byte-exact verification unavailable - size check used)`n"); $lb.ScrollToEnd() }
                                        }
                                        if (-not $verified) {
                                            Copy-Item -Path $backupPath -Destination $scriptPath -Force
                                            throw "Update failed SHA256 verification - your previous version was restored from the backup."
                                        }
                                        $updateApplied = $true

                                        if ($lb) { $lb.AppendText("[UPDATE] Integrity verified. Update applied.`n"); $lb.ScrollToEnd() }

                                        [System.Windows.MessageBox]::Show("Update complete! Restarting...", "Updated", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information) | Out-Null
                                        Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$scriptPath`"" -WorkingDirectory (Split-Path -Parent $scriptPath)
                                        $script:WmtAllowFinalClose = $true
                                        $window.Close()
                                    }
                                    catch {
                                        # Safety net: restore the previous script when the update did not apply cleanly
                                        if (-not $updateApplied -and $backupPath -and (Test-Path $backupPath) -and $scriptPath -and (Test-Path $scriptPath)) {
                                            Copy-Item -Path $backupPath -Destination $scriptPath -Force -ErrorAction SilentlyContinue
                                        }
                                        $errMsg = "Auto-update failed: $($_.Exception.Message)"
                                        try { Write-GuiLog "[UPDATE] $errMsg" } catch {}

                                        $fallback = [System.Windows.MessageBox]::Show(
                                            "$errMsg`n`nOpen Releases page and update manually?",
                                            "Update Failed",
                                            [System.Windows.MessageBoxButton]::YesNo,
                                            [System.Windows.MessageBoxImage]::Warning
                                        )
                                        if ($fallback -eq [System.Windows.MessageBoxResult]::Yes) {
                                            Start-Process "https://github.com/ios12checker/Windows-Maintenance-Tool/releases"
                                        }
                                    }
                                }
                            })
                    }
                    else {
                        if ($lb) { $lb.AppendText(" -> System is up to date.`n"); $lb.ScrollToEnd() }
                    }
                }
                else {
                    if ($lb) { $lb.AppendText("[UPDATE] Failed: $($jobResult.Error)`n"); $lb.ScrollToEnd() }
                }
            }
            catch {
                if ($lb) { $lb.AppendText("[UPDATE] Processing Error: $($_.Exception.Message)`n"); $lb.ScrollToEnd() }
            }
        }
    } | Out-Null
}

function Start-UpdateRepair {
Invoke-WmtUiBackgroundCommand -Name "WindowsUpdateRepairQuick" -Msg "Repairing Windows Update..." -Sb {
    Stop-Service -Name wuauserv, bits, cryptsvc, msiserver -Force -ErrorAction SilentlyContinue
    $rnd = Get-Random
    if (Test-Path "$env:windir\SoftwareDistribution") { Rename-Item "$env:windir\SoftwareDistribution" "$env:windir\SoftwareDistribution.bak_$rnd" -ErrorAction SilentlyContinue }
    if (Test-Path "$env:windir\System32\catroot2") { Rename-Item "$env:windir\System32\catroot2" "$env:windir\System32\catroot2.bak_$rnd" -ErrorAction SilentlyContinue }
    netsh winsock reset | Out-Null
    Start-Service -Name wuauserv, bits, cryptsvc, msiserver -ErrorAction SilentlyContinue
    Write-Output "Windows Update repair completed."
} | Out-Null
}

function Start-NetRepair {
Invoke-WmtUiBackgroundCommand -Name "NetworkRepair" -Msg "Running Full Network Repair..." -Sb {
    ipconfig /release | Out-Null
    ipconfig /renew | Out-Null
    ipconfig /flushdns | Out-Null
    netsh winsock reset | Out-Null
    netsh int ip reset | Out-Null
    Write-Output "Network repair completed."
} | Out-Null
}

function Start-RegClean {
$bkDir = Join-Path (Get-DataPath) "RegistryBackups"
Invoke-WmtUiBackgroundCommand -Name "RegistryObsoleteClean" -Msg "Cleaning Registry..." -Sb {
    param($bkDir)
    if (!(Test-Path $bkDir)) { New-Item -Path $bkDir -ItemType Directory | Out-Null }
    $bkFile = "$bkDir\Backup_$(Get-Date -F 'yyyyMMdd_HHmm').reg"
    reg export "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall" $bkFile /y | Out-Null
    $keys = Get-ChildItem HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall | Where-Object { $_.PSChildName -match 'IE40|IE4Data|DirectDrawEx|DXM_Runtime|SchedulingAgent' }
    if ($keys) { foreach ($k in $keys) { Remove-Item $k.PSPath -Recurse -Force -ErrorAction SilentlyContinue; Write-Output "Removed: $($k.PSChildName)" } } else { Write-Output "No obsolete keys found." }
    Write-Output "Backup saved to: $bkFile"
} -ArgumentList $bkDir | Out-Null
}

function Start-XboxClean {
Invoke-WmtUiBackgroundCommand -Name "XboxCredentialCleanup" -Msg "Cleaning Xbox Credentials..." -Sb {
    Write-Output "Stopping Xbox Auth Manager..."
    Stop-Service -Name "XblAuthManager" -Force -ErrorAction SilentlyContinue
    $allCreds = (cmdkey /list) -split "\r?\n"
    $targets = @()
    foreach ($line in $allCreds) {
        if ($line -match '^\s*Target:.*(Xbl.*)$') { $targets += $matches[1] }
    }
    if ($targets.Count -eq 0) { Write-Output "No Xbox Live credentials found." }
    else {
        foreach ($t in $targets) { Write-Output "Deleting credential: $t"; cmdkey /delete:$t 2>$null }
        Write-Output "Deleted $($targets.Count) credential(s)."
    }
    Start-Service -Name "XblAuthManager" -ErrorAction SilentlyContinue
} | Out-Null
}

function Start-GpeditInstall {
$msg = "Install Local Group Policy Editor?`n`nThis enables the Group Policy Editor (gpedit.msc) on Windows Home editions by installing the built-in system packages.`n`nContinue?"
$res = Show-WmtMessageBox -Message $msg -Title "Confirm Install" -Button YesNo -Image Question
if ($res -ne [System.Windows.MessageBoxResult]::Yes) { return }

Invoke-WmtUiBackgroundCommand -Name "GpeditInstall" -Msg "Installing Group Policy Editor..." -Sb {
    $packageRoot = Join-Path $env:SystemRoot "servicing\Packages"
    if (-not (Test-Path $packageRoot)) { throw "Package directory not found: $packageRoot" }
    Write-Output "Searching packages in $packageRoot..."
    $clientTools = @(Get-ChildItem -LiteralPath $packageRoot -Filter "Microsoft-Windows-GroupPolicy-ClientTools-Package~*.mum" -File -ErrorAction SilentlyContinue)
    $clientExtensions = @(Get-ChildItem -LiteralPath $packageRoot -Filter "Microsoft-Windows-GroupPolicy-ClientExtensions-Package~*.mum" -File -ErrorAction SilentlyContinue)
    if (-not $clientTools -or -not $clientExtensions) {
        Write-Output "WARNING: Required GroupPolicy packages were not found."
        Write-Output "Ensure you are on a compatible Windows 10/11 version."
        return
    }
    $packages = @($clientTools + $clientExtensions) | Sort-Object Name -Unique
    foreach ($pkg in $packages) {
        Write-Output "Installing: $($pkg.Name)..."
        $proc = Start-Process dism.exe -ArgumentList "/online", "/norestart", "/add-package:`"$($pkg.FullName)`"" -NoNewWindow -Wait -PassThru
        $exitCode = [int]$proc.ExitCode
        try { $proc.Dispose() } catch {}
        if ($exitCode -ne 0) { Write-Output " -> Failed (Exit Code: $exitCode)" }
    }
    Write-Output "Installation Complete. Try running 'gpedit.msc'. (A reboot may be required)."
} | Out-Null
}

