# --- Tweaks Functions ---
function Set-Hags {
param([bool]$Enable)

if ($Enable) {
    Invoke-UiCommand {
        Set-WmtRegDword "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" "HwSchMode" 2
        Write-Output "Hardware-Accelerated GPU Scheduling (HAGS) enabled. Reboot required."

        Set-WmtBusyCursor
        Show-WmtMessageBox -Message "HAGS enabled successfully. Please restart your computer to apply the changes." -Title "HAGS Status" -Image Information | Out-Null
    } "Enabling HAGS..."
}
else {
    Invoke-UiCommand {
        Set-WmtRegDword "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" "HwSchMode" 1
        Write-Output "Hardware-Accelerated GPU Scheduling (HAGS) disabled. Reboot required."

        Set-WmtBusyCursor
        Show-WmtMessageBox -Message "HAGS disabled successfully. Please restart your computer to apply the changes." -Title "HAGS Status" -Image Information | Out-Null
    } "Disabling HAGS..."
}
}

function Get-WmtRegValue {
param(
    [string]$Path,
    [string]$Name,
    $Default = $null
)

if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Name)) { return $Default }

$item = Get-WmtRegistryKeyValuesCached -Path $Path
if ($item -and $item.PSObject.Properties[$Name]) {
    return $item.$Name
}
return $Default
}

# --- Registry write helpers (pure .NET Microsoft.Win32.Registry API) ---
# Every tweak write goes through these instead of the PowerShell registry provider.
# Benefits: no provider path parsing, no glob expansion of literal subkey names like
# '*' or '?', CreateSubKey builds the whole key chain in one call, and (Default)
# values are written via SetValue("") without the "(Default)" provider pseudo-name.
function Set-WmtRegDword {
param(
    [string]$Path,
    [string]$Name,
    [int]$Value
)

$parts = Convert-WmtRegistryPath -Path $Path
if (-not $parts) { return }
$baseKey = $null
$key = $null
try {
    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($parts.Hive, [Microsoft.Win32.RegistryView]::Default)
    $key = $baseKey.CreateSubKey($parts.SubPath)
    if ($key) { $key.SetValue($Name, $Value, [Microsoft.Win32.RegistryValueKind]::DWord) }
}
catch {}
finally {
    if ($key) { $key.Close() }
    if ($baseKey) { $baseKey.Close() }
}
}

function Set-WmtRegString {
param(
    [string]$Path,
    [string]$Name,
    [string]$Value
)

$parts = Convert-WmtRegistryPath -Path $Path
if (-not $parts) { return }
$baseKey = $null
$key = $null
try {
    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($parts.Hive, [Microsoft.Win32.RegistryView]::Default)
    $key = $baseKey.CreateSubKey($parts.SubPath)
    if ($key) { $key.SetValue($Name, $Value, [Microsoft.Win32.RegistryValueKind]::String) }
}
catch {}
finally {
    if ($key) { $key.Close() }
    if ($baseKey) { $baseKey.Close() }
}
}

function Set-WmtRegBinary {
param(
    [string]$Path,
    [string]$Name,
    [byte[]]$Value
)

$parts = Convert-WmtRegistryPath -Path $Path
if (-not $parts) { return }
$baseKey = $null
$key = $null
try {
    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($parts.Hive, [Microsoft.Win32.RegistryView]::Default)
    $key = $baseKey.CreateSubKey($parts.SubPath)
    if ($key) { $key.SetValue($Name, $Value, [Microsoft.Win32.RegistryValueKind]::Binary) }
}
catch {}
finally {
    if ($key) { $key.Close() }
    if ($baseKey) { $baseKey.Close() }
}
}

function Remove-WmtRegValue {
param(
    [string]$Path,
    [string]$Name
)

$parts = Convert-WmtRegistryPath -Path $Path
if (-not $parts) { return }
$baseKey = $null
$key = $null
try {
    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($parts.Hive, [Microsoft.Win32.RegistryView]::Default)
    $key = $baseKey.OpenSubKey($parts.SubPath, $true)
    if ($key) { $key.DeleteValue($Name, $false) }
}
catch {}
finally {
    if ($key) { $key.Close() }
    if ($baseKey) { $baseKey.Close() }
}
}

function New-WmtRegKey {
param([string]$Path)

# Creates the key (and any missing parents). Literal subkey names only.
$parts = Convert-WmtRegistryPath -Path $Path
if (-not $parts) { return }
$baseKey = $null
$key = $null
try {
    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($parts.Hive, [Microsoft.Win32.RegistryView]::Default)
    $key = $baseKey.CreateSubKey($parts.SubPath)
}
catch {}
finally {
    if ($key) { $key.Close() }
    if ($baseKey) { $baseKey.Close() }
}
}

function Set-WmtRegDefaultValue {
param(
    [string]$Path,
    [AllowNull()][AllowEmptyString()][string]$Value
)

# Sets the key's (Default) value, creating the key chain first if needed.
$parts = Convert-WmtRegistryPath -Path $Path
if (-not $parts) { return }
$text = $Value
if ($null -eq $text) { $text = "" }
$baseKey = $null
$key = $null
try {
    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($parts.Hive, [Microsoft.Win32.RegistryView]::Default)
    $key = $baseKey.CreateSubKey($parts.SubPath)
    if ($key) { $key.SetValue("", $text, [Microsoft.Win32.RegistryValueKind]::String) }
}
catch {}
finally {
    if ($key) { $key.Close() }
    if ($baseKey) { $baseKey.Close() }
}
}

function Remove-WmtRegKeyTree {
param([string]$Path)

# Deletes a key and its whole subtree. Missing keys are ignored.
$parts = Convert-WmtRegistryPath -Path $Path
if (-not $parts) { return }
$baseKey = $null
try {
    $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($parts.Hive, [Microsoft.Win32.RegistryView]::Default)
    $baseKey.DeleteSubKeyTree($parts.SubPath, $false)
}
catch {}
finally {
    if ($baseKey) { $baseKey.Close() }
}
}

function Restart-WmtExplorer {
try { Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue } catch {}
}

function Invoke-WmtUserSettingRefresh {
try {
    Start-Process -FilePath "$env:SystemRoot\System32\RUNDLL32.EXE" -ArgumentList "USER32.DLL,UpdatePerUserSystemParameters" -WindowStyle Hidden -ErrorAction SilentlyContinue | Out-Null
}
catch {}
}

function Test-WmtExplorerSingleClick {
$shellState = Get-WmtRegValue "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer" "ShellState"
return ($shellState -and $shellState.Length -gt 4 -and [int]$shellState[4] -eq 0x1E)
}

function Set-WmtExplorerClickMode {
param([bool]$SingleClick)

$path = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer"
New-WmtRegKey $path

$shellState = Get-WmtRegValue $path "ShellState"
if (-not $shellState -or $shellState.Length -lt 5) {
    $shellState = [byte[]](0x24, 0x00, 0x00, 0x00, 0x3E, 0x28, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
}

$shellState[4] = if ($SingleClick) { [byte]0x1E } else { [byte]0x3E }
Set-WmtRegBinary $path "ShellState" $shellState
Set-WmtRegDword $path "IconUnderline" $(if ($SingleClick) { 2 } else { 3 })
Restart-WmtExplorer
}

# Native Win32 mouse parameter functions — writes directly to the live system
# state AND updates the registry in one atomic call (no need for manual refresh).
if (-not ([System.Management.Automation.PSTypeName]'WmtNativeMouse.Params').Type) {
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

namespace WmtNativeMouse {
public class Params {
    // Overload for simple integers (used by Mouse Speed)
    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, uint pvParam, uint fWinIni);

    // Overload for integer arrays (used by Mouse Acceleration)
    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, int[] pvParam, uint fWinIni);

    private const uint SPI_SETMOUSE = 0x0004;
    private const uint SPI_SETMOUSESPEED = 0x0071;
    private const uint SPIF_UPDATEINIFILE = 0x01;
    private const uint SPIF_SENDCHANGE = 0x02;

    /// <summary>Set pointer speed (1-20, default 10). Updates live state + registry.</summary>
    public static void SetSpeed(uint speed) {
        speed = Math.Max(1u, Math.Min(20u, speed));
        SystemParametersInfo(SPI_SETMOUSESPEED, 0, speed, SPIF_UPDATEINIFILE | SPIF_SENDCHANGE);
    }

    /// <summary>Enable or disable enhanced pointer precision. Updates live state + registry.</summary>
    /// <param name="enable">true = acceleration ON, false = acceleration OFF</param>
    public static void SetAcceleration(bool enable) {
        int[] mouseParams = enable ? new int[] { 6, 10, 1 } : new int[] { 0, 0, 0 };
        SystemParametersInfo(SPI_SETMOUSE, 0, mouseParams, SPIF_UPDATEINIFILE | SPIF_SENDCHANGE);
    }
}
}
'@
}

function Set-WmtMouseSpeed {
param([int]$Speed)

$speed = [math]::Max(1, [math]::Min(20, $Speed))
[WmtNativeMouse.Params]::SetSpeed([uint32]$speed)
}

function Set-WmtMouseAcceleration {
param([bool]$Enable)

[WmtNativeMouse.Params]::SetAcceleration($Enable)
}

