                                                    </StackPanel>
                                                </Grid>
                                            </Border>
                                    </WrapPanel>
                                     <Border Margin="20,0,20,24" BorderBrush="{DynamicResource BorderBrush}" BorderThickness="0,1,0,0" Padding="10,12,10,0" HorizontalAlignment="Stretch">
                                        <Button Name="btnMyDeviceExport" Content="Export" Style="{StaticResource ActionBtn}" HorizontalAlignment="Stretch"/>
                                    </Border>
                                </StackPanel>
                            </ScrollViewer>

                            <!-- FIREWALL PANEL -->
            <Grid Name="pnlFirewall" Visibility="Collapsed">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- Header Card -->
                <Border Grid.Row="0" Style="{StaticResource CardStyle}" Margin="0,0,0,12">
                    <Grid>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="380"/>
                        </Grid.ColumnDefinitions>
                        <StackPanel>
                            <TextBlock Text="Firewall Manager" Style="{StaticResource SectionHeader}" Margin="0"/>
                            <TextBlock Name="lblFwStatus" Text="Ready" Foreground="{DynamicResource TextSecondary}" FontSize="13" Visibility="Collapsed"/>
                        </StackPanel>
                        <Border Grid.Column="1" Style="{StaticResource ModernSearchBoxStyle}" VerticalAlignment="Top">
                            <Grid>
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto"/>
                                    <ColumnDefinition Width="*"/>
                                    <ColumnDefinition Width="Auto"/>
                                </Grid.ColumnDefinitions>
                                <Path Grid.Column="0" Data="M9.5,3A6.5,6.5 0 0,1 16,9.5C16,11.11 15.41,12.59 14.44,13.73L14.71,14H15.5L20.5,19L19,20.5L14,15.5V14.71L13.73,14.44C12.59,15.41 11.11,16 9.5,16A6.5,6.5 0 0,1 3,9.5A6.5,6.5 0 0,1 9.5,3M9.5,5C7,5 5,7 5,9.5C5,12 7,14 9.5,14C12,14 14,12 14,9.5C14,7 12,5 9.5,5Z"
                                      Fill="{DynamicResource TextMuted}" Stretch="Uniform" Height="14" Width="14"
                                      VerticalAlignment="Center" Margin="12,0,6,0"/>
                                <TextBox Name="txtFwSearch" Grid.Column="1" Height="38"
                                         VerticalContentAlignment="Center" Text="Search rules..."
                                         Background="Transparent" BorderThickness="0"
                                         Padding="0,0,0,0" Margin="0"
                                         FontSize="14"
                                         Foreground="{DynamicResource TextSecondary}"
                                         CaretBrush="{DynamicResource TextPrimary}"
                                         SelectionBrush="{DynamicResource Accent}"
                                         ToolTip="Filter by name or port"/>
                                <Button Name="btnFwClearSearch" Grid.Column="2" Content="X"
                                        Width="28" Height="28" Margin="0,0,6,0"
                                        VerticalAlignment="Center" HorizontalAlignment="Center"
                                        Visibility="Collapsed" Cursor="Hand"
                                        ToolTip="Clear search"
                                        Style="{StaticResource SearchClearBtnStyle}"/>
                            </Grid>
                        </Border>
                    </Grid>
                </Border>

                <!-- Rules List Card -->
                <Border Grid.Row="1" Style="{StaticResource CardStyle}" Padding="0" Margin="0">
                    <ListView Name="lstFirewall" Background="Transparent" Foreground="{DynamicResource TextPrimary}" BorderThickness="0" AlternationCount="2"
                              VirtualizingStackPanel.IsVirtualizing="True" VirtualizingStackPanel.VirtualizationMode="Recycling" ScrollViewer.CanContentScroll="True">
                        <ListView.View>
                            <GridView>
                                <GridViewColumn Header="Rule Name" Width="360" DisplayMemberBinding="{Binding Name}"/>
                                <GridViewColumn Header="Direction" Width="70" DisplayMemberBinding="{Binding Direction}"/>
                                <GridViewColumn Header="Action" Width="70">
                                    <GridViewColumn.CellTemplate>
                                        <DataTemplate>
                                            <TextBlock Text="{Binding Action}" FontWeight="Bold">
                                                <TextBlock.Style>
                                                    <Style TargetType="TextBlock">
                                                        <Setter Property="Foreground" Value="{DynamicResource TextSecondary}"/>
                                                        <Style.Triggers>
                                                            <DataTrigger Binding="{Binding Action}" Value="Allow"><Setter Property="Foreground" Value="{DynamicResource Success}"/></DataTrigger>
                                                            <DataTrigger Binding="{Binding Action}" Value="Block"><Setter Property="Foreground" Value="{DynamicResource Danger}"/></DataTrigger>
                                                        </Style.Triggers>
                                                    </Style>
                                                </TextBlock.Style>
                                            </TextBlock>
                                        </DataTemplate>
                                    </GridViewColumn.CellTemplate>
                                </GridViewColumn>
                                <GridViewColumn Header="Status" Width="70">
                                    <GridViewColumn.CellTemplate>
                                        <DataTemplate>
                                            <TextBlock Text="{Binding Enabled}" FontWeight="Bold">
                                                <TextBlock.Style>
                                                    <Style TargetType="TextBlock">
                                                        <Setter Property="Foreground" Value="{DynamicResource TextSecondary}"/>
                                                        <Style.Triggers>
                                                            <DataTrigger Binding="{Binding Enabled}" Value="True"><Setter Property="Foreground" Value="{DynamicResource Success}"/></DataTrigger>
                                                            <DataTrigger Binding="{Binding Enabled}" Value="False"><Setter Property="Foreground" Value="{DynamicResource Danger}"/></DataTrigger>
                                                        </Style.Triggers>
                                                    </Style>
                                                </TextBlock.Style>
                                            </TextBlock>
                                        </DataTemplate>
                                    </GridViewColumn.CellTemplate>
                                </GridViewColumn>
                                <GridViewColumn Header="Protocol" Width="70" DisplayMemberBinding="{Binding Protocol}"/>
                                <GridViewColumn Header="Port" Width="90" DisplayMemberBinding="{Binding LocalPort}"/>
                            </GridView>
                        </ListView.View>
                    </ListView>
                </Border>

                <!-- Actions Card -->
                <Border Grid.Row="2" Style="{StaticResource CardStyle}" Margin="0,12,0,0">
                    <WrapPanel HorizontalAlignment="Left">
                        <Button Name="btnFwRefresh" Content="Reload" Style="{StaticResource ActionBtn}"/>
                        <Button Name="btnFwAdd" Content="Add Rule" Style="{StaticResource PositiveBtn}"/>
                        <Button Name="btnFwEdit" Content="Edit" Style="{StaticResource ActionBtn}"/>
                        <Button Name="btnFwEnable" Content="Enable" Style="{StaticResource ActionBtn}"/>
                        <Button Name="btnFwDisable" Content="Disable" Style="{StaticResource ActionBtn}"/>
                        <Button Name="btnFwDelete" Content="Delete" Style="{StaticResource DestructiveBtn}"/>
                        <Button Name="btnFwExport" Content="Export" Style="{StaticResource ActionBtn}"/>
                        <Button Name="btnFwImport" Content="Import" Style="{StaticResource ActionBtn}"/>
                        <Button Name="btnFwDefaults" Content="Defaults" Style="{StaticResource WarningBtn}"/>
                        <Button Name="btnFwPurge" Content="Delete All" Style="{StaticResource DestructiveBtn}"/>
                    </WrapPanel>
                </Border>
            </Grid>

            <!-- DRIVERS PANEL -->
            <Grid Name="pnlDrivers" Visibility="Collapsed">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- Header Card -->
                <Border Grid.Row="0" Style="{StaticResource CardStyle}" Margin="0,0,0,12">
                    <HeaderedContentControl Style="{StaticResource WmtPageHeaderStyle}">
                      <HeaderedContentControl.Header>
                       <Grid>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="*" MaxWidth="380"/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Text="Driver Management" Style="{StaticResource SectionHeader}" Margin="0,0,16,0"
                                   VerticalAlignment="Center" TextWrapping="NoWrap" TextTrimming="CharacterEllipsis"/>
                        <Border Grid.Column="1" Style="{StaticResource ModernSearchBoxStyle}" VerticalAlignment="Top">
                            <Grid>
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto"/>
                                    <ColumnDefinition Width="*"/>
                                    <ColumnDefinition Width="Auto"/>
                                </Grid.ColumnDefinitions>
                                <Path Grid.Column="0" Data="M9.5,3A6.5,6.5 0 0,1 16,9.5C16,11.11 15.41,12.59 14.44,13.73L14.71,14H15.5L20.5,19L19,20.5L14,15.5V14.71L13.73,14.44C12.59,15.41 11.11,16 9.5,16A6.5,6.5 0 0,1 3,9.5A6.5,6.5 0 0,1 9.5,3M9.5,5C7,5 5,7 5,9.5C5,12 7,14 9.5,14C12,14 14,12 14,9.5C14,7 12,5 9.5,5Z"
                                      Fill="{DynamicResource TextMuted}" Stretch="Uniform" Height="14" Width="14"
                                      VerticalAlignment="Center" Margin="12,0,6,0"/>
                                <TextBox Name="txtDrvSearch" Grid.Column="1" Height="38"
                                         VerticalContentAlignment="Center" Text="Search drivers..."
                                         Background="Transparent" BorderThickness="0"
                                         Padding="0,0,0,0" Margin="0"
                                         FontSize="14"
                                         Foreground="{DynamicResource TextSecondary}"
                                         CaretBrush="{DynamicResource TextPrimary}"
                                         SelectionBrush="{DynamicResource Accent}"
                                         ToolTip="Filter by status, class, provider, driver or store file name"/>
                                <Button Name="btnDrvClearSearch" Grid.Column="2" Content="X"
                                        Width="28" Height="28" Margin="0,0,6,0"
                                        VerticalAlignment="Center" HorizontalAlignment="Center"
                                        Visibility="Collapsed" Cursor="Hand"
                                        ToolTip="Clear search"
                                        Style="{StaticResource SearchClearBtnStyle}"/>
                            </Grid>
                        </Border>
                       </Grid>
                      </HeaderedContentControl.Header>
                      <StackPanel>
                        <TextBlock Name="lblDrvStatus" Text="Ready — the driver store loads when you open this page" Foreground="{DynamicResource TextSecondary}" FontSize="13" TextWrapping="Wrap"/>
                        <TextBlock Name="lblDrvLegend" FontSize="12" Margin="0,6,0,0" TextWrapping="Wrap">
                            <Run Text="Highlighting — click to filter:  " Foreground="{DynamicResource TextMuted}"/>
                            <Hyperlink TextDecorations="None" Cursor="Hand" Focusable="False" Foreground="{DynamicResource Success}"
                                       ToolTip="Show only packages in use. Click again to show all."><Run Text="● In Use   "/></Hyperlink>
                            <Hyperlink TextDecorations="None" Cursor="Hand" Focusable="False" Foreground="{DynamicResource Warning}"
                                       ToolTip="Show only superseded duplicate copies. Click again to show all."><Run Text="● Old   "/></Hyperlink>
                            <Hyperlink TextDecorations="None" Cursor="Hand" Focusable="False" Foreground="{DynamicResource Danger}"
                                       ToolTip="Show only packages with no device currently attached. Click again to show all."><Run Text="● Unattached   "/></Hyperlink>
                            <Hyperlink TextDecorations="None" Cursor="Hand" Focusable="False" Foreground="{DynamicResource TextSecondary}"
                                       ToolTip="Show only packages whose devices are disabled in Device Manager. Click again to show all."><Run Text="● Inactive (disabled in Device Manager)"/></Hyperlink>
                        </TextBlock>
                      </StackPanel>
                    </HeaderedContentControl>
                </Border>

                <!-- Driver List Card -->
                <Border Grid.Row="1" Style="{StaticResource CardStyle}" Padding="0" Margin="0">
                    <ListView Name="lstDrivers" Background="Transparent" Foreground="{DynamicResource TextPrimary}" BorderThickness="0" SelectionMode="Extended" AlternationCount="2" ItemContainerStyle="{StaticResource DrvItem}"
                              VirtualizingStackPanel.IsVirtualizing="True" VirtualizingStackPanel.VirtualizationMode="Recycling" ScrollViewer.CanContentScroll="True">
                        <ListView.View>
                            <GridView>
                                <GridViewColumn Header="Status" Width="92">
                                    <GridViewColumn.CellTemplate>
                                        <DataTemplate>
                                            <TextBlock Text="{Binding Status}" FontWeight="Bold" ToolTip="{Binding StatusTooltip}">
                                                <TextBlock.Style>
                                                    <Style TargetType="TextBlock">
                                                        <Setter Property="Foreground" Value="{DynamicResource TextSecondary}"/>
                                                        <Style.Triggers>
                                                            <DataTrigger Binding="{Binding Status}" Value="In Use"><Setter Property="Foreground" Value="{DynamicResource Success}"/></DataTrigger>
                                                            <DataTrigger Binding="{Binding Status}" Value="Old"><Setter Property="Foreground" Value="{DynamicResource Warning}"/></DataTrigger>
                                                            <DataTrigger Binding="{Binding Status}" Value="Unattached"><Setter Property="Foreground" Value="{DynamicResource Danger}"/></DataTrigger>
                                                            <DataTrigger Binding="{Binding Status}" Value="Inactive"><Setter Property="Foreground" Value="{DynamicResource TextMuted}"/></DataTrigger>
                                                        </Style.Triggers>
                                                    </Style>
                                                </TextBlock.Style>
                                            </TextBlock>
                                        </DataTemplate>
                                    </GridViewColumn.CellTemplate>
                                </GridViewColumn>
                                <GridViewColumn Header="Class" Width="120" DisplayMemberBinding="{Binding Class}"/>
                                <GridViewColumn Header="Provider" Width="150" DisplayMemberBinding="{Binding Provider}"/>
                                <GridViewColumn Header="Driver" Width="170" DisplayMemberBinding="{Binding OriginalName}"/>
                                <GridViewColumn Header="Store File" Width="95" DisplayMemberBinding="{Binding PublishedName}"/>
                                <GridViewColumn Header="Version" Width="115" DisplayMemberBinding="{Binding DisplayVer}"/>
                                <GridViewColumn Header="Date" Width="90" DisplayMemberBinding="{Binding DisplayDate}"/>
                                <GridViewColumn Header="Devices" Width="66">
                                    <GridViewColumn.CellTemplate>
                                        <DataTemplate>
                                            <TextBlock Text="{Binding DevicesText}" ToolTip="{Binding DevicesTooltip}" HorizontalAlignment="Right"/>
                                        </DataTemplate>
                                    </GridViewColumn.CellTemplate>
                                </GridViewColumn>
                            </GridView>
                        </ListView.View>
                    </ListView>
                </Border>

                <!-- Actions Card (all driver tools) -->
                <Border Grid.Row="2" Style="{StaticResource CardStyle}" Margin="0,12,0,0">
                    <WrapPanel HorizontalAlignment="Left">
                        <Button Name="btnDrvReload" Content="Reload" Style="{StaticResource AccentBtn}"/>
                        <Button Name="btnDrvReport" Content="Generate Report" Style="{StaticResource ActionBtn}" ToolTip="Create detailed driver list"/>
                        <Button Name="btnDrvBackup" Content="Export Drivers" Style="{StaticResource ActionBtn}" ToolTip="Backup all drivers to folder"/>
                        <Button Name="btnDrvGhost" Content="Remove Ghosts" Style="{StaticResource WarningBtn}" ToolTip="Remove disconnected devices"/>
                        <Button Name="btnDrvClean" Content="Clean Old" Style="{StaticResource WarningBtn}" ToolTip="Remove old driver versions"/>
                        <Button Name="btnDrvRestore" Content="Restore" Style="{StaticResource ActionBtn}" ToolTip="Restore from backup"/>
                        <Button Name="btnToggleDrvUpdates" Content="Disable Auto-Drivers" Style="{StaticResource ActionBtn}" ToolTip="Toggle automatic driver updates via Windows Update."/>
                        <Button Name="btnToggleDrvMeta" Content="Disable Metadata" Style="{StaticResource ActionBtn}" ToolTip="Toggle device metadata downloads from the internet. Blue = metadata disabled. Gray = metadata enabled (default)."/>
                    </WrapPanel>
                </Border>
            </Grid>

            <!-- CLEANUP PANEL -->
            <StackPanel Name="pnlCleanup" Visibility="Collapsed">
                <Border Style="{StaticResource CardStyle}">
                    <StackPanel>
                        <StackPanel Margin="0,0,0,20">
                            <TextBlock Text="System Cleanup" Style="{StaticResource SectionHeader}" Margin="0"/>
                        </StackPanel>
                        <TextBlock Text="CLEANUP TOOLS" Style="{StaticResource SubHeader}"/>
                        <WrapPanel>
                            <Button Name="btnCleanDisk" Content="Disk Cleanup" Style="{StaticResource ActionBtn}" ToolTip="Windows built-in cleanup utility"/>
                            <Button Name="btnCleanTemp" Content="Delete Temp Files" Style="{StaticResource ActionBtn}" ToolTip="Clear temp folders"/>
                            <Button Name="btnCleanShortcuts" Content="Fix Shortcuts" Style="{StaticResource ActionBtn}" ToolTip="Remove broken shortcuts"/>
                            <Button Name="btnCleanReg" Content="Clean Registry" Style="{StaticResource WarningBtn}" ToolTip="Remove obsolete registry entries"/>
                            <Button Name="btnCleanXbox" Content="Clean Xbox Data" Style="{StaticResource ActionBtn}" ToolTip="Clear Xbox app cache"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>

                <Border Style="{StaticResource CardStyle}">
                    <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                        <Border Width="48" Height="48" CornerRadius="8" Background="{DynamicResource BgElevated}" VerticalAlignment="Top" Margin="0,0,15,0">
                            <Viewbox Width="24" Height="24">
