                                </Canvas>
                            </Viewbox>
                        </Border>
                        <StackPanel Grid.Column="1">
                            <TextBlock Text="OneDrive" FontSize="16" FontWeight="SemiBold" Foreground="{DynamicResource TextPrimary}"/>
                            <TextBlock Text="Set all OneDrive files to 'Online Only' to immediately free up local disk space." FontSize="13" Foreground="{DynamicResource TextSecondary}" TextWrapping="Wrap" Margin="0,4,0,0" LineHeight="18"/>
                            <Button Name="btnCleanupOneDrive" Content="Free Up Space" Style="{StaticResource ActionBtn}" Margin="0,10,0,0" HorizontalAlignment="Left" Width="130"/>
                        </StackPanel>
                    </Grid>
                </Border>
            </StackPanel>

            <!-- UTILITIES PANEL -->
            <StackPanel Name="pnlUtils" Visibility="Collapsed">
                <!-- System Tools Card -->
                <Border Style="{StaticResource CardStyle}">
                    <StackPanel>
                        <StackPanel Margin="0,0,0,20">
                            <TextBlock Text="System Tools" Style="{StaticResource SectionHeader}" Margin="0"/>
                        </StackPanel>
                        <TextBlock Text="SYSTEM INFO &amp; MAINTENANCE" Style="{StaticResource SubHeader}"/>
                        <WrapPanel>
                            <Button Name="btnUtilSysInfo" Content="System Report" Style="{StaticResource ActionBtn}" ToolTip="Generate detailed system report"/>
                            <Button Name="btnUtilTrim" Content="Trim SSD" Style="{StaticResource ActionBtn}" ToolTip="Optimize SSD performance"/>
                            <Button Name="btnUtilCompact" Content="Compact Compression" Style="{StaticResource ActionBtn}" ToolTip="Compress/decompress NTFS folders or drives, track them, and schedule independent recompression through Windows Task Scheduler. WMT does not need to stay open."/>
                            <Button Name="btnUtilWinRE" Content="Check WinRE" Style="{StaticResource ActionBtn}" ToolTip="Checks Windows Recovery Environment status via reagentc /info"/>
                            <Button Name="btnUtilRestoreMgr" Content="Restore Manager" Style="{StaticResource ActionBtn}" ToolTip="List, create, and delete system restore points"/>
                            <Button Name="btnUtilStartupMgr" Content="Startup Manager" Style="{StaticResource ActionBtn}" ToolTip="Manage startup apps, tasks, context menu entries, and services"/>
                            <Button Name="btnUtilMas" Content="MAS Activation" Style="{StaticResource UtilityBtn}" ToolTip="Microsoft Activation Scripts"/>
                            <Button Name="btnTaskManager" Content="Task Scheduler" Style="{StaticResource ActionBtn}" ToolTip="Manage scheduled tasks"/>
                            <Button Name="btnCtxBuilder" Content="Context Menu" Style="{StaticResource ActionBtn}" ToolTip="Customize right-click menu"/>
                            <Button Name="btnUtilResetGPU" Content="Reset GPU" Style="{StaticResource WarningBtn}" ToolTip="Restart the GPU driver (Win+Ctrl+Shift+B). Screen will flash black briefly. Useful when the display freezes or artifacts appear."/>
                        </WrapPanel>
                    </StackPanel>
                </Border>

                <!-- Repairs Card -->
                <Border Style="{StaticResource CardStyle}">
                    <StackPanel>
                        <TextBlock Text="REPAIRS &amp; SETTINGS" Style="{StaticResource SubHeader}"/>
                        <WrapPanel>
                            <Button Name="btnUpdateRepair" Content="Reset Windows Update" Style="{StaticResource WarningBtn}" ToolTip="Fix Windows Update issues"/>
                            <Button Name="btnUpdateServices" Content="Restart Services" Style="{StaticResource ActionBtn}" ToolTip="Restart update-related services"/>
                            <Button Name="btnDotNetEnable" Content="Enable .NET RollForward" Style="{StaticResource ActionBtn}"/>
                            <Button Name="btnDotNetDisable" Content="Disable .NET RollForward" Style="{StaticResource ActionBtn}"/>
                            <Button Name="btnInstallGpedit" Content="Install Gpedit" Style="{StaticResource UtilityBtn}" ToolTip="Add Group Policy to Home editions"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
            </StackPanel>

            <!-- SUPPORT PANEL -->
            <StackPanel Name="pnlSupport" Visibility="Collapsed">
                <!-- Header Card -->
                <Border Style="{StaticResource CardStyle}">
                    <HeaderedContentControl Style="{StaticResource WmtPageHeaderStyle}">
                        <HeaderedContentControl.Header>
                            <StackPanel>
                                <TextBlock Text="Support &amp; Credits" Style="{StaticResource SectionHeader}" Margin="0" TextWrapping="Wrap"/>
                                <TextBlock Text="Windows Maintenance Tool v$AppVersion" FontSize="14" Foreground="{DynamicResource TextSecondary}" FontWeight="SemiBold" TextWrapping="Wrap"/>
                            </StackPanel>
                        </HeaderedContentControl.Header>
                        <WrapPanel>
                            <Button Name="btnStartWithWindows" Content="Start with Windows: Off" Style="{StaticResource ActionBtn}" Height="32" MinWidth="170" Margin="0,0,8,8" ToolTip="WMT does not launch at logon (no startup task, or task state: Disabled). Click to set the state to On."/>
                            <Button Name="btnLaunchMinimized" Content="Launch Minimized: Off" Style="{StaticResource ActionBtn}" Height="32" MinWidth="160" Margin="0,0,8,8" ToolTip="WMT starts with a visible window. Click to start hidden in the system tray instead."/>
                            <Button Name="btnDisableBgJobs" Content="Bg Jobs: On" Style="{StaticResource ActionBtn}" Height="32" MinWidth="130" Margin="0,0,8,8" ToolTip="Background auto-refresh ENABLED. My Device info and Tweaks states load automatically. Click to disable."/>
                            <Button Name="btnDisableUpdateScans" Content="Update Scans: On" Style="{StaticResource ActionBtn}" Height="32" MinWidth="150" Margin="0,0,8,8" ToolTip="Disable all automatic and tray-triggered update scans. Manual scans will still work. Click to toggle."/>
                            <Button Name="btnDebugMode" Content="Debug Logs: Off" Style="{StaticResource ActionBtn}" Height="32" MinWidth="135" Margin="0,0,8,8" ToolTip="Extra internal diagnostic error logging is disabled. Click to enable additional WMT troubleshooting logs."/>
                            <Button Name="btnToggleTheme" Content="Toggle Theme" Style="{StaticResource ActionBtn}" Height="32" MinWidth="112" Margin="0,0,8,8" ToolTip="Switch between dark and light theme"/>
                        </WrapPanel>
                    </HeaderedContentControl>
                </Border>

                <!-- Credits Card -->
                <Border Style="{StaticResource CardStyle}">
                    <StackPanel>
                        <TextBlock Text="CONTRIBUTORS" Style="{StaticResource SubHeader}"/>
                        <StackPanel Margin="0,8,0,0">
                            <StackPanel Orientation="Horizontal" Margin="0,4">
                                <TextBlock Text="Author: " Foreground="{DynamicResource TextSecondary}" Width="120"/>
                                <Button Name="btnCreditLilBatti" Content="Lil_Batti" Style="{StaticResource ActionBtn}" Height="26" Padding="8,2"/>
                            </StackPanel>
                            <StackPanel Orientation="Horizontal" Margin="0,4">
                                <TextBlock Text="GUI &amp; Features: " Foreground="{DynamicResource TextSecondary}" Width="120"/>
                                <Button Name="btnCreditChaython" Content="Chaython" Style="{StaticResource ActionBtn}" Height="26" Padding="8,2"/>
                            </StackPanel>
                        </StackPanel>
                        <TextBlock Text="MIT License - Copyright (c) 2026" Foreground="{DynamicResource TextMuted}" FontSize="11" Margin="0,16,0,0"/>
                    </StackPanel>
                </Border>

                <!-- Support Actions Card -->
                <Border Style="{StaticResource CardStyle}">
                    <StackPanel>
                        <TextBlock Text="GET INVOLVED" Style="{StaticResource SubHeader}"/>
                        <WrapPanel>
                            <Button Name="btnSupportDiscord" Content="Join Discord" Style="{StaticResource UtilityBtn}" ToolTip="Community support server"/>
                            <Button Name="btnSupportIssue" Content="Report Issue" Style="{StaticResource ActionBtn}" ToolTip="Submit bug reports on GitHub"/>
                            <Button Name="btnDonateIos12" Content="Sponsor Lil_Batti" Style="{StaticResource PositiveBtn}"/>
                            <Button Name="btnDonate" Content="Sponsor Chaython" Style="{StaticResource PositiveBtn}"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
            </StackPanel>

        </Grid>
    </Border>
</Grid>
</Window>
"@

# ==========================================
# 4. INIT & HELPERS
# ==========================================
$ErrorActionPreference = 'Stop'
try {
$window = New-WmtWindowFromFullXaml -Xaml $xaml -NoOwner
} catch {
Write-Host "FATAL: XAML load failed: $($_.Exception.Message)" -ForegroundColor Red
Write-Host "Inner: $(($_.Exception.InnerException).Message)" -ForegroundColor Yellow
[System.Windows.MessageBox]::Show("XAML load failed:\n$($_.Exception.Message)", 'WMT Startup Error', 'OK', 'Error') | Out-Null
exit 1
}
$ErrorActionPreference = 'SilentlyContinue'
$script:LogBox = $window.FindName("LogBox")
$script:WmtControlCache = @{}

function Get-Ctrl {
param([string]$Name)
if ([string]::IsNullOrWhiteSpace($Name)) { return $null }
if ($script:WmtControlCache.ContainsKey($Name)) { return $script:WmtControlCache[$Name] }

$ctrl = $window.FindName($Name)
if ($ctrl) { $script:WmtControlCache[$Name] = $ctrl }
return $ctrl
}

# --- THEME PALETTES ---
$script:CurrentTheme = "dark"
$script:ThemePalettes = @{
dark  = @{
    BgDark        = "#0D1117"
    BgPanel       = "#161B22"
    BgElevated    = "#21262D"
    BgHover       = "#30363D"
    BorderBrush   = "#30363D"
    BorderAccent  = "#58A6FF"
    Accent        = "#58A6FF"
    AccentHover   = "#79C0FF"
    TextPrimary   = "#E6EDF3"
    TextSecondary = "#8B949E"
    TextMuted     = "#6E7681"
    Success       = "#238636"
    SuccessHover  = "#2EA043"
    Danger        = "#DA3633"
    DangerHover   = "#F85149"
    Warning       = "#D29922"
    WarningHover  = "#E3B341"
    Info          = "#1F6FEB"
    AccentText    = "#0D1117"
    SuccessText   = "#F6FFFA"
    DangerText    = "#FFF5F5"
    WarningText   = "#0D1117"
    InfoText      = "#F0F6FC"
    LogText       = "#3FB950"
    DrvTintInUse    = "#0D238636"
    DrvTintOld      = "#1AD29922"
    DrvTintUnattached = "#1ADA3633"
    DrvTintInactive = "#128B949E"
}
light = @{
    BgDark        = "#F5F7FA"
    BgPanel       = "#FFFFFF"
    BgElevated    = "#EEF2F7"
    BgHover       = "#E2E8F0"
    BorderBrush   = "#CBD5E1"
    BorderAccent  = "#2563EB"
    Accent        = "#2563EB"
    AccentHover   = "#3B82F6"
    TextPrimary   = "#0F172A"
    TextSecondary = "#334155"
    TextMuted     = "#64748B"
    Success       = "#15803D"
    SuccessHover  = "#16A34A"
    Danger        = "#B91C1C"
    DangerHover   = "#DC2626"
    Warning       = "#B45309"
    WarningHover  = "#D97706"
    Info          = "#1D4ED8"
    AccentText    = "#FFFFFF"
    SuccessText   = "#FFFFFF"
    DangerText    = "#FFFFFF"
    WarningText   = "#FFFFFF"
    InfoText      = "#FFFFFF"
    LogText       = "#166534"
    DrvTintInUse    = "#1A15803D"
    DrvTintOld      = "#26B45309"
    DrvTintUnattached = "#26B91C1C"
    DrvTintInactive = "#1A64748B"
}
}

function Set-WmtTheme {
param([string]$Theme = "dark")
if (-not $script:ThemePalettes.ContainsKey($Theme)) { $Theme = "dark" }
$palette = $script:ThemePalettes[$Theme]

Set-WmtThemeResources -Element $window -Palette $palette

$window.Background = $window.Resources["BgDark"]
$window.Foreground = $window.Resources["TextPrimary"]

if ($script:WmtThemedElements) {
    foreach ($element in @($script:WmtThemedElements)) {
        try {
            if (-not $element -or [object]::ReferenceEquals($element, $window)) { continue }
            Set-WmtThemeResources -Element $element -Palette $palette
            if ($element -is [System.Windows.Window]) {
                $element.Background = $element.Resources["BgDark"]
                $element.Foreground = $element.Resources["TextPrimary"]
            }
        }
        catch {}
    }
}

$logBoxCtrl = Get-Ctrl "LogBox"
if ($logBoxCtrl) { $logBoxCtrl.Foreground = $palette.LogText }

$quickFindCtrl = Get-Ctrl "txtGlobalSearch"
if ($quickFindCtrl) { Set-WmtQuickFindForeground -TextBox $quickFindCtrl }

$toggleBtn = Get-Ctrl "btnToggleTheme"
if ($toggleBtn) {
    $toggleBtn.Content = if ($Theme -eq "dark") { "Light Mode" } else { "Dark Mode" }
}

if ($TabButtons) {
    foreach ($btnName in $TabButtons) {
        $btn = Get-Ctrl $btnName
        if (-not $btn) { continue }
        if ($btn.Tag -eq "Visible") {
            $btn.Background = $window.Resources["BgElevated"]
            $btn.Foreground = $window.Resources["TextPrimary"]
        }
        else {
            $btn.ClearValue([System.Windows.Controls.Button]::BackgroundProperty)
            $btn.Foreground = $window.Resources["TextSecondary"]
        }
    }
}

$script:CurrentTheme = $Theme
if ($script:WmtTrayMenu) { Set-WmtTrayMenuTheme -Menu $script:WmtTrayMenu }
}

function Set-WmtQuickFindForeground {
param([System.Windows.Controls.TextBox]$TextBox)

if (-not $TextBox) { return }
$resourceKey = if ($TextBox.Text -eq $script:QuickFindPlaceholder) { "TextMuted" } else { "TextPrimary" }
$TextBox.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty, $resourceKey)
}

function Set-WmtLogSearchForeground {
param([System.Windows.Controls.TextBox]$TextBox)

if (-not $TextBox) { return }
$resourceKey = if ($TextBox.Text -eq $script:LogSearchPlaceholder) { "TextMuted" } else { "TextPrimary" }
$TextBox.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty, $resourceKey)
}

function Show-WmtActivityLogHighlight {
param(
    [int]$Index,
    [int]$Length
)

if (-not $script:LogBox -or -not $script:LogSearchHighlightLayer) { return }
$layer = $script:LogSearchHighlightLayer
$layer.Children.Clear()
if ($Index -lt 0 -or $Length -le 0 -or $Index -ge $script:LogBox.Text.Length) { return }

try {
    # GetRectFromCharacterIndex is independent of keyboard focus, unlike TextBox selection rendering.
    $startRect = $script:LogBox.GetRectFromCharacterIndex($Index, $true)
    $endIndex = [Math]::Min($script:LogBox.Text.Length, $Index + $Length)
    $endRect = $script:LogBox.GetRectFromCharacterIndex($endIndex, $false)
    if ($startRect.IsEmpty) { return }

    $highlight = New-Object System.Windows.Shapes.Rectangle
    $highlight.Fill = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#B8F2C94C")
    $highlight.Stroke = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFF2C94C")
    $highlight.StrokeThickness = 1.0
    $highlight.RadiusX = 2
    $highlight.RadiusY = 2

    $left = [Math]::Max(0.0, $startRect.X - 1.0)
    $top = [Math]::Max(0.0, $startRect.Y - 1.0)
    $height = [Math]::Max(2.0, $startRect.Height + 2.0)

    if (-not $endRect.IsEmpty -and [Math]::Abs($endRect.Y - $startRect.Y) -lt 1.0) {
        $width = [Math]::Max(3.0, ($endRect.X - $startRect.X) + 2.0)
    }
    else {
        # Wrapped/multi-line matches get an obvious line-width highlight rather than disappearing.
        $width = [Math]::Max(3.0, $script:LogBox.ActualWidth - $left - 6.0)
    }

    $highlight.Width = $width
    $highlight.Height = $height
    [System.Windows.Controls.Canvas]::SetLeft($highlight, $left)
    [System.Windows.Controls.Canvas]::SetTop($highlight, $top)
    [void]$layer.Children.Add($highlight)
}
catch {
    try { $layer.Children.Clear() } catch {}
}
}

function Clear-WmtActivityLogHighlight {
$script:LogSearchMatchIndex = -1
$script:LogSearchMatchLength = 0
$script:LogSearchMatchQuery = ""
if ($script:LogSearchHighlightLayer) {
    try { $script:LogSearchHighlightLayer.Children.Clear() } catch {}
}
}

function Select-WmtActivityLogMatch {
param(
    [string]$Query,
    [switch]$Previous,
    [switch]$Restart
)

if (-not $script:LogBox -or [string]::IsNullOrWhiteSpace($Query)) { return $false }
$text = [string]$script:LogBox.Text
if ([string]::IsNullOrEmpty($text)) { return $false }

$comparison = [System.StringComparison]::OrdinalIgnoreCase
$index = -1
$sameQuery = ([string]$script:LogSearchMatchQuery -eq $Query)
$hasCurrentMatch = $sameQuery -and ($script:LogSearchMatchIndex -ge 0)

if ($Previous) {
    $start = if ($Restart -or -not $hasCurrentMatch) {
        $text.Length - 1
    }
    else {
        [Math]::Min($text.Length - 1, [Math]::Max(0, $script:LogSearchMatchIndex - 1))
    }
    if ($start -ge 0) { $index = $text.LastIndexOf($Query, $start, $comparison) }
    if ($index -lt 0 -and -not $Restart) { $index = $text.LastIndexOf($Query, $text.Length - 1, $comparison) }
}
else {
    $start = if ($Restart -or -not $hasCurrentMatch) {
        0
    }
    else {
        [Math]::Min($text.Length, $script:LogSearchMatchIndex + $script:LogSearchMatchLength)
    }
    $index = $text.IndexOf($Query, $start, $comparison)
    if ($index -lt 0 -and -not $Restart -and $start -gt 0) { $index = $text.IndexOf($Query, 0, $comparison) }
}

if ($index -lt 0) {
    Clear-WmtActivityLogHighlight
    return $false
}

# Search owns its own cursor. Never change LogBox.SelectionStart/SelectionLength;
# those are reserved for the user's normal mouse/keyboard text selection.
$script:LogSearchMatchIndex = $index
$script:LogSearchMatchLength = $Query.Length
$script:LogSearchMatchQuery = $Query
try {
    $lineIndex = $script:LogBox.GetLineIndexFromCharacterIndex($index)
    if ($lineIndex -ge 0) { $script:LogBox.ScrollToLine($lineIndex) }

    # Force layout after navigation, then draw a real overlay over the match.
    $script:LogBox.UpdateLayout()
    if ($script:LogSearchHighlightLayer) { $script:LogSearchHighlightLayer.UpdateLayout() }
    Show-WmtActivityLogHighlight -Index $index -Length $Query.Length
}
catch {
    Show-WmtActivityLogHighlight -Index $index -Length $Query.Length
}
return $true
}

function Get-WmtActivityLogReferenceAtPoint {
param(
    [System.Windows.Controls.TextBox]$TextBox,
    [System.Windows.Point]$Point
)

if (-not $TextBox) { return $null }
$charIndex = $TextBox.GetCharacterIndexFromPoint($Point, $true)
if ($charIndex -lt 0) { return $null }

$lineIndex = $TextBox.GetLineIndexFromCharacterIndex($charIndex)
if ($lineIndex -lt 0) { return $null }
$lineStart = $TextBox.GetCharacterIndexFromLineIndex($lineIndex)
$lineText = [string]$TextBox.GetLineText($lineIndex)
if ([string]::IsNullOrWhiteSpace($lineText)) { return $null }
$column = [Math]::Max(0, $charIndex - $lineStart)

# Web/file URIs are unambiguous and can be opened directly.
$uriMatches = [regex]::Matches($lineText, '(?i)\b(?:https?|file)://[^\s<>"'']+')
foreach ($match in $uriMatches) {
    $target = ([string]$match.Value).TrimEnd('.', ',', ';', ':', ')', ']', '}')
    $targetLength = $target.Length
    if ($column -ge $match.Index -and $column -lt ($match.Index + $targetLength)) {
        return [PSCustomObject]@{ Kind = "Uri"; Target = $target }
    }
}

# For Windows/UNC paths, start with the rest of the line and progressively
# trim trailing descriptive text until an existing file/folder remains.
$pathMatches = [regex]::Matches($lineText, '(?i)(?:[A-Z]:\\|\\\\)[^<>"\r\n|?*]+')
foreach ($match in $pathMatches) {
    if ($column -lt $match.Index -or $column -ge ($match.Index + $match.Length)) { continue }
    $raw = ([string]$match.Value).Trim()
    $relativeColumn = [Math]::Max(0, $column - $match.Index)
    for ($length = $raw.Length; $length -gt $relativeColumn; $length--) {
        $candidate = $raw.Substring(0, $length).Trim().TrimEnd(')', ']', '}', ',', ';', '.')
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        try {
            if (Test-Path -LiteralPath $candidate) {
                return [PSCustomObject]@{ Kind = "Path"; Target = $candidate }
            }
        }
        catch {}
    }
}

return $null
}

function Open-WmtActivityLogPath {
param([string]$Path)

if ([string]::IsNullOrWhiteSpace($Path)) { return }
if (Test-Path -LiteralPath $Path -PathType Container) {
    Start-Process -FilePath "explorer.exe" -ArgumentList "`"$Path`"" | Out-Null
    return
}
if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }

# Log contents are not trusted launch instructions. Only directly open a small
# allowlist of inert document/data formats; select every other file in Explorer.
$extension = [System.IO.Path]::GetExtension($Path).ToLowerInvariant()
$directOpenExtensions = @(
    ".txt", ".log", ".md", ".csv", ".tsv",
    ".json", ".xml", ".yaml", ".yml", ".ini", ".cfg", ".conf",
    ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp", ".ico",
    ".pdf"
)
if ($directOpenExtensions -contains $extension) {
    Start-Process -FilePath $Path | Out-Null
    return
}

Start-Process -FilePath "explorer.exe" -ArgumentList "/select,`"$Path`"" | Out-Null
}

function Open-WmtActivityLogReference {
param($Reference)

if (-not $Reference -or [string]::IsNullOrWhiteSpace([string]$Reference.Target)) { return }
$target = [string]$Reference.Target
try {
    if ([string]$Reference.Kind -eq "Uri") {
        if ($target -match '^(?i)file://') {
            $fileUri = [System.Uri]$target
            Open-WmtActivityLogPath -Path $fileUri.LocalPath
        }
        else {
            Start-Process $target | Out-Null
        }
        return
    }

    Open-WmtActivityLogPath -Path $target
}
catch {
    Write-GuiLog "Could not open log reference '$target': $($_.Exception.Message)"
}
}

function Set-WmtThemePreference {
param([string]$Theme = "dark")

if (-not $script:ThemePalettes.ContainsKey($Theme)) { $Theme = "dark" }
Set-WmtTheme -Theme $Theme

try {
    $settings = Get-WmtSettings
    $settings.Theme = $Theme
    Save-WmtSettings -Settings $settings
}
catch {}

$themeLabel = if ($Theme -eq "light") { "Light" } else { "Dark" }
Write-GuiLog "$themeLabel mode enabled."
}

function Update-MyDeviceResponsiveLayout {
$cards = Get-Ctrl "pnlMyDeviceCards"
$scroll = Get-Ctrl "pnlMyDevice"
if (-not $cards -or -not $scroll) { return }

$available = [double]$scroll.ViewportWidth
if ([double]::IsNaN($available) -or $available -le 0) { $available = [double]$scroll.ActualWidth }
if ([double]::IsNaN($available) -or $available -le 0) { $available = [double]$window.ActualWidth }
if ([double]::IsNaN($available) -or $available -le 0) { return }

$marginWidth = 40.0
$contentWidth = [math]::Max(320.0, $available - $marginWidth)
$minCardWidth = 330.0
$targetCardWidth = 410.0
$columns = [math]::Floor($contentWidth / $targetCardWidth)
if ($columns -lt 1) { $columns = 1 }
if ($columns -gt 4) { $columns = 4 }

while ($columns -gt 1 -and ($contentWidth / $columns) -lt $minCardWidth) {
    $columns--
}

$itemWidth = [math]::Floor($contentWidth / $columns)
$newItemWidth = [math]::Max($minCardWidth, $itemWidth)
$currentItemWidth = [double]$cards.ItemWidth
if ([double]::IsNaN($currentItemWidth) -or [math]::Abs($currentItemWidth - $newItemWidth) -ge 1) {
    $cards.ItemWidth = $newItemWidth
}
}

function Update-TweaksResponsiveLayout {
$cards = Get-Ctrl "pnlTweaksCards"
$scroll = Get-Ctrl "pnlTweaks"
if (-not $cards -or -not $scroll) { return }

$available = [double]$scroll.ViewportWidth
if ([double]::IsNaN($available) -or $available -le 0) { $available = [double]$scroll.ActualWidth }
if ([double]::IsNaN($available) -or $available -le 0) { $available = [double]$window.ActualWidth }
if ([double]::IsNaN($available) -or $available -le 0) { return }

$marginWidth = 40.0
$contentWidth = [math]::Max(320.0, $available - $marginWidth)
$minCardWidth = 330.0
$targetCardWidth = 410.0
$columns = [math]::Floor($contentWidth / $targetCardWidth)
if ($columns -lt 1) { $columns = 1 }
if ($columns -gt 4) { $columns = 4 }

while ($columns -gt 1 -and ($contentWidth / $columns) -lt $minCardWidth) {
    $columns--
}

$itemWidth = [math]::Floor($contentWidth / $columns)
$newItemWidth = [math]::Max($minCardWidth, $itemWidth)
$currentItemWidth = [double]$cards.ItemWidth
if ([double]::IsNaN($currentItemWidth) -or [math]::Abs($currentItemWidth - $newItemWidth) -ge 1) {
    $cards.ItemWidth = $newItemWidth
}
}

function Get-MyDeviceExportTextLines {
param($Control)

$lines = New-Object System.Collections.Generic.List[string]
if (-not $Control) { return @() }

if ($Control -is [System.Windows.Controls.TextBlock]) {
    $text = ([string]$Control.Text).Trim()
    if (-not [string]::IsNullOrWhiteSpace($text)) { [void]$lines.Add($text) }
}
elseif ($Control -is [System.Windows.Controls.TextBox]) {
    $text = ([string]$Control.Text).Trim()
    if (-not [string]::IsNullOrWhiteSpace($text)) { [void]$lines.Add($text) }
}
elseif ($Control -is [System.Windows.Controls.ContentControl]) {
    if ($Control.Content -is [string]) {
        $text = ([string]$Control.Content).Trim()
        if (-not [string]::IsNullOrWhiteSpace($text)) { [void]$lines.Add($text) }
    }
    elseif ($Control.Content -is [System.Windows.DependencyObject]) {
        foreach ($line in (Get-MyDeviceExportTextLines -Control $Control.Content)) { [void]$lines.Add($line) }
    }
}

if ($Control -is [System.Windows.Controls.Panel]) {
    foreach ($child in $Control.Children) {
        foreach ($line in (Get-MyDeviceExportTextLines -Control $child)) { [void]$lines.Add($line) }
    }
}
elseif ($Control -is [System.Windows.Controls.Decorator] -and $Control.Child) {
    foreach ($line in (Get-MyDeviceExportTextLines -Control $Control.Child)) { [void]$lines.Add($line) }
}

return $lines.ToArray()
}

function Add-MyDeviceExportSection {
param(
    [System.Collections.Generic.List[string]]$Lines,
    [string]$Title,
    [string[]]$TextControlNames = @(),
    [string[]]$PanelControlNames = @()
)

$sectionLines = New-Object System.Collections.Generic.List[string]

foreach ($name in $TextControlNames) {
    $ctrl = Get-Ctrl $name
    if ($ctrl -and $ctrl.Text) {
        $text = ([string]$ctrl.Text).Trim()
        if (-not [string]::IsNullOrWhiteSpace($text)) { [void]$sectionLines.Add($text) }
    }
}

foreach ($name in $PanelControlNames) {
    foreach ($line in (Get-MyDeviceExportTextLines -Control (Get-Ctrl $name))) {
        $text = ([string]$line).Trim()
        if (-not [string]::IsNullOrWhiteSpace($text)) { [void]$sectionLines.Add($text) }
    }
}

if ($sectionLines.Count -eq 0) { return }

if ($Lines.Count -gt 0) { [void]$Lines.Add("") }
[void]$Lines.Add($Title)
[void]$Lines.Add(("-" * $Title.Length))

$previous = $null
foreach ($line in $sectionLines) {
    if ($line -ne $previous) { [void]$Lines.Add($line) }
    $previous = $line
}
}

function Invoke-MyDeviceExport {
try {
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add("Windows Maintenance Tool - My Device Export")
    [void]$lines.Add("Generated: $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))")
    [void]$lines.Add("Computer: $env:COMPUTERNAME")

    Add-MyDeviceExportSection -Lines $lines -Title "Operating System" -TextControlNames @("txtDeviceOS")
    Add-MyDeviceExportSection -Lines $lines -Title "Network Info" -TextControlNames @("txtDeviceNetwork") -PanelControlNames @("pnlDeviceNetworkList")
    Add-MyDeviceExportSection -Lines $lines -Title "Processor (CPU)" -TextControlNames @("txtDeviceCPU")
    Add-MyDeviceExportSection -Lines $lines -Title "Battery / Power" -TextControlNames @("txtBatteryHealth", "txtBatteryCharge", "txtBatteryStatus", "txtPowerPlan", "txtBatteryTime", "txtPowerDraw", "txtPowerTotal", "txtPowerElectrical")
    Add-MyDeviceExportSection -Lines $lines -Title "Memory (RAM)" -TextControlNames @("txtDeviceRAM")
    Add-MyDeviceExportSection -Lines $lines -Title "Graphics (GPU)" -PanelControlNames @("pnlDeviceGPUList")
    Add-MyDeviceExportSection -Lines $lines -Title "Motherboard" -TextControlNames @("txtDeviceMotherboard")
    Add-MyDeviceExportSection -Lines $lines -Title "Storage Drives" -TextControlNames @("txtDeviceStorage") -PanelControlNames @("pnlDeviceStorageList")

    $outFile = Join-Path (Get-DataPath) ("MyDevice_{0}.txt" -f (Get-Date -Format "yyyy-MM-dd_HHmmss"))
    Set-Content -Path $outFile -Value $lines.ToArray() -Encoding UTF8

    Write-GuiLog "[My Device] Exported device summary to $outFile"
    Show-WmtMessageBox -Message "My Device export saved to:`n$outFile" -Title "Export Complete" -Image Information | Out-Null
}
catch {
    Write-GuiLog "[My Device] Export failed: $($_.Exception.Message)"
    Show-WmtMessageBox -Message "Failed to export My Device details:`n$($_.Exception.Message)" -Title "Export Failed" -Image Error | Out-Null
}
}

function Set-ButtonIcon {
param($BtnName, $PathData, $Text, $Tooltip = "", $Scale = 16, $Color = $null)
$btn = Get-Ctrl $BtnName
if (-not $btn) { return }

if ($Scale -is [string] -and $Scale -match '^#') {
    $Color = $Scale
    $Scale = 16
}

# Visuals
$sp = New-Object System.Windows.Controls.StackPanel; $sp.Orientation = "Horizontal"
$path = New-Object System.Windows.Shapes.Path
$path.Data = [System.Windows.Media.Geometry]::Parse($PathData)
if ([string]::IsNullOrWhiteSpace([string]$Color)) {
    $path.SetResourceReference([System.Windows.Shapes.Path]::FillProperty, "TextSecondary")
}
else {
    $path.Fill = New-WmtBrush $Color
}
$path.Stretch = "Uniform"; $path.Height = $Scale; $path.Width = $Scale; $path.Margin = "0,0,10,0"
$txt = New-Object System.Windows.Controls.TextBlock; $txt.Text = $Text; $txt.VerticalAlignment = "Center"
[void]$sp.Children.Add($path); [void]$sp.Children.Add($txt)
$btn.Content = $sp

# Tooltip
if ($Tooltip) { $btn.ToolTip = $Tooltip }
}

