            Set-WmtQuickFindForeground -TextBox $txtGlobalSearch
        }
    })
}
if ($bdQuickFind -and $txtGlobalSearch) {
$bdQuickFind.Add_MouseLeftButtonDown({ $txtGlobalSearch.Focus() })
