# Helper: if library sub-view is active, switch back to catalog list.
function Reset-WmtLibraryToCatalog {
    if ($brdLibraryList -and $brdLibraryList.Visibility -eq "Visible") {
        $brdLibraryList.Visibility = "Collapsed"
        if ($brdCatalogList) { $brdCatalogList.Visibility = "Visible" }
        if ($btnBackToCatalog) { $btnBackToCatalog.Visibility = "Collapsed" }
        if ($btnLibraryRefresh) { $btnLibraryRefresh.Visibility = "Collapsed" }
        if ($btnToggleFabAssets) { $btnToggleFabAssets.Visibility = "Collapsed" }
        if ($lblLibraryStatus) { $lblLibraryStatus.Text = "" }
        if ($btnCatalogInstall) { $btnCatalogInstall.ToolTip = "Install all selected applications using winget. May take several minutes depending on app size." }
        if ($btnCatalogSelectAll) { $btnCatalogSelectAll.ToolTip = "Select all visible applications in the list" }
        if ($btnCatalogClear) { $btnCatalogClear.ToolTip = "Unselect all applications" }
        if ($btnShowLibrary) { $btnShowLibrary.Style = ($window.FindResource("ActionBtn") -as [System.Windows.Style]) }
    }
}

# Only three main-window shortcuts: F5 refreshes the visible list, Ctrl+F
# focuses its search field, and Ctrl+Shift+F opens the global Quick Find.
# Reuse existing click handlers so all scan guards, state and logging stay intact.
$window.Add_PreviewKeyDown({
    param($keySender, $keyArgs)
    if ($keyArgs.Handled) { return }
    $key = $keyArgs.Key
    if ($key -ne [System.Windows.Input.Key]::F5 -and $key -ne [System.Windows.Input.Key]::F) { return }

    try {
        $modifiers = [int][System.Windows.Input.Keyboard]::Modifiers
        $control = [int][System.Windows.Input.ModifierKeys]::Control
        $controlShift = $control -bor [int][System.Windows.Input.ModifierKeys]::Shift

        if ($key -eq [System.Windows.Input.Key]::F5 -and $modifiers -eq 0) {
            $refreshButton = $null
            if ($pnlUpdates -and $pnlUpdates.IsVisible) {
                # Updates navigation alone never scans; F5 is an explicit user scan.
                if (Get-WmtUpdateScansDisabled) { return }
                $refreshButton = $btnWingetScan
            }
            elseif ($pnlCatalog -and $pnlCatalog.IsVisible) {
                if ($brdLibraryList -and $brdLibraryList.IsVisible) {
                    $refreshButton = $btnLibraryRefresh
                }
            }
            elseif ((Get-Ctrl "pnlFirewall").IsVisible) { $refreshButton = $btnFwRefresh }
            elseif ((Get-Ctrl "pnlDrivers").IsVisible) { $refreshButton = Get-Ctrl "btnDrvReload" }

            if ($refreshButton -and $refreshButton.IsVisible -and $refreshButton.IsEnabled) {
                $refreshButton.RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent))
                $keyArgs.Handled = $true
            }
            return
        }

        if ($key -ne [System.Windows.Input.Key]::F) { return }
        $searchBox = $null
        if ($modifiers -eq $controlShift) {
            $searchBox = $txtGlobalSearch
        }
        elseif ($modifiers -eq $control) {
            if (($LogBox -and $LogBox.IsKeyboardFocusWithin) -or
                ($txtLogSearch -and $txtLogSearch.IsKeyboardFocusWithin)) {
                $searchBox = $txtLogSearch
            }
            elseif ($pnlUpdates -and $pnlUpdates.IsVisible) { $searchBox = $txtWingetSearch }
            elseif ($pnlCatalog -and $pnlCatalog.IsVisible -and
                    $brdLibraryList -and $brdLibraryList.IsVisible) { $searchBox = $txtLibrarySearch }
            elseif ((Get-Ctrl "pnlFirewall").IsVisible) { $searchBox = $txtFwSearch }
            elseif ((Get-Ctrl "pnlDrivers").IsVisible) { $searchBox = Get-Ctrl "txtDrvSearch" }
            else { $searchBox = $txtGlobalSearch }
        }
        if ($searchBox -and $searchBox.IsVisible -and $searchBox.IsEnabled) {
            [void]$searchBox.Focus()
            $keyArgs.Handled = $true
        }
    }
    catch {
        try { Write-GuiLog "Keyboard shortcut failed: $($_.Exception.Message)" } catch {}
    }
})

# --- TABS LOGIC ---
foreach ($tabButton in $script:WmtTabButtonControls) {
$tabButton.Add_Click({
        param($s, $e)
        foreach ($panel in $script:WmtPanelControls) { $panel.Visibility = "Collapsed" }
        # Hide tweaks overlay when leaving tweaks tab
        $tweaksOverlay = Get-Ctrl "tweaksLoadingOverlay"
        if ($tweaksOverlay) { $tweaksOverlay.Visibility = "Collapsed" }
        # Reset library sub-view state if leaving the catalog while in library view.
        Reset-WmtLibraryToCatalog
        foreach ($btn in $script:WmtTabButtonControls) {
            $btn.ClearValue([System.Windows.Controls.Button]::BackgroundProperty)
            $btn.Foreground = $window.Resources["TextSecondary"]
            $btn.FontWeight = "Normal"
            $btn.Tag = "Collapsed"  # Hide indicator
        }
        $target = $script:WmtTabTargetByButton[[string]$s.Name]
        if ($target) { $target.Visibility = "Visible" }
        $s.Background = $window.Resources["BgElevated"]
        $s.Foreground = $window.Resources["TextPrimary"]
        $s.FontWeight = "SemiBold"
        $s.Tag = "Visible"  # Show indicator
        if ($s.Name -eq "btnTabFirewall") { Start-FirewallRuleLoad }
        # Drivers cache has a TTL; Start-DriverListLoad returns immediately while
        # it is fresh and transparently refreshes stale data in the background.
        if ($s.Name -eq "btnTabDrivers") { Start-DriverListLoad }
        # Navigating to Updates must not start a package scan, even when the
        # previous scan found zero updates. The list remains as-is until the
        # user clicks Check Package Updates or the configured auto-scan runs.
        if ($s.Name -eq "btnTabSupport") {
            # Re-check the real Task Scheduler state whenever the Support tab
            # is shown so the Start with Windows button always reflects off/on.
            try { Update-WmtStartWithWindowsButton } catch {}
        }
        if ($s.Name -eq "btnTabMyDevice") {
            Update-MyDeviceResponsiveLayout
            if (-not (Get-WmtDisableBackgroundJobs)) {
                if (-not $script:MyDeviceStatsStarted) {
                    $script:MyDeviceStatsStarted = $true
                    Update-MyDeviceStats
                }
                elseif ($script:MyDeviceStatsPreloadMode) {
                    $script:MyDeviceStatsPreloadMode = $false
                    $script:MyDeviceStatsMaxConcurrent = 4
                    Start-MyDeviceQueuedSections
                }
            }
            elseif (-not $script:MyDeviceStatsStarted) {
                # Background jobs disabled — do a one-time synchronous load
                $script:MyDeviceStatsStarted = $true
                Update-MyDeviceStats
            }
        }
        if ($s.Name -eq "btnTabTweaks") {
            Update-TweaksResponsiveLayout
            if (-not (Get-WmtDisableBackgroundJobs)) {
                # Start Tweak States background load on first Tweaks tab visit
                Start-TweakButtonStatesBackgroundUpdate
                Start-OptionalFeaturesBackgroundCheck
                # Auto-load AppX bloatware list on first visit (background, no busy cursor)
                if (-not $script:AppxListLoaded) {
                    $script:AppxListLoaded = $true
                    Start-AppxBackgroundLoad
                }
                if (-not $script:TweakStatesReady) { Set-TweakStatesLoadingOverlay -Visible $true }
            }
            elseif (-not $script:TweakStatesReady) {
                # Background jobs disabled — do a one-time synchronous load with error fallback
                Set-TweakStatesLoadingOverlay -Visible $true
                                # Explicitly set the initial state of the two loads
                                $script:OptionalFeaturesReady = $false
                $script:TweakStatesReady = $false
                                # Allows the UI to render the overlay before the heavy work begins
                                $window.Dispatcher.Invoke(
                    [System.Action]{},
                    [System.Windows.Threading.DispatcherPriority]::Render
                )
                $optionalFeaturesLoaded = $false
                $tweakStatesLoaded = $false
                try {
                    $sw = [System.Diagnostics.Stopwatch]::StartNew()
                    Update-OptionalFeaturesSynchronously                                        
                    $optionalFeaturesLoaded = $true                                     
                                        $script:OptionalFeaturesReady = $true
                    # Update the overlay immediately after the first load
                    Sync-WmtTweakOverlayHide                                    
                    Update-TweakButtonStates
                    $tweakStatesLoaded = $true
                    $script:TweakStatesReady = $true                                    
                                        # Update the overlay immediately after the second load
                    Sync-WmtTweakOverlayHide
                    $sw.Stop()
                    if ($sw.ElapsedMilliseconds -gt 3000) {
                        try { Write-GuiLog "[Tweak States] Synchronous load completed slowly ($($sw.ElapsedMilliseconds)ms). Consider enabling background jobs in Settings." } catch {}
                    }
                }
                catch {
                    $errMsg = $_.Exception.Message
                    try { Write-GuiLog "[Tweak States] ERROR: Failed to load tweak states: $errMsg" } catch {}
                    # Show error on overlay briefly before hiding
                    Show-TweakStatesLoadError -Message "Failed to load tweak states. Toggle buttons may show incorrect states. Click Retry or switch tabs and back. Error: $errMsg"
                }
                finally {
                    $script:OptionalFeaturesReady = $optionalFeaturesLoaded
                    $script:TweakStatesReady = $tweakStatesLoaded
                    Sync-WmtTweakOverlayHide
                }
            }
        }
    })
}

