if ($txtGlobalSearch) { $txtGlobalSearch.Add_TextChanged({
    $q = $txtGlobalSearch.Text
    if ($q.Length -gt 1 -and $q -ne $script:QuickFindPlaceholder) {
        if ($pnlNavButtons) { $pnlNavButtons.Visibility = "Collapsed" }
        if ($lstSearchResults) { $lstSearchResults.Visibility = "Visible"; $lstSearchResults.Items.Clear() }
        foreach ($entry in $script:WmtSearchIndexEntries) {
            if ($entry.Text.IndexOf($q, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                if ($lstSearchResults) { [void]$lstSearchResults.Items.Add($entry.Text) }
            }
        }
    }
    else { if ($pnlNavButtons) { $pnlNavButtons.Visibility = "Visible" }; if ($lstSearchResults) { $lstSearchResults.Visibility = "Collapsed" } }
}) }
if ($lstSearchResults) { $lstSearchResults.Add_SelectionChanged({
    if ($lstSearchResults.SelectedItem) {
        $match = $SearchIndex[$lstSearchResults.SelectedItem]

        # 1. Switch to the appropriate tab so the button is rendered and visible
        if ($match.Tab) {
            $tabBtn = Get-Ctrl $match.Tab
            if ($tabBtn) {
                $tabBtn.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))
            }
        }

        # 2. Fire the actual button's click event to launch the target function
        if ($match.ContainsKey("Action") -and $match.Action -is [scriptblock]) {
            & $match.Action
        }
        elseif ($match.Button) {
            $match.Button.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))
        }

        # Clear the search box after executing
        $txtGlobalSearch.Text = ""
        Set-WmtQuickFindForeground -TextBox $txtGlobalSearch
    }
}) }

# WINGET CONTEXT MENU (Right-Click)
$ctxMenu = New-WmtContextMenu -Items @()

if ($lstWinget) {
$lstWinget.Add_PreviewMouseRightButtonDown({
        param($s, $e)
        Set-WmtListViewRightClickSelection -ListView $s -OriginalSource $e.OriginalSource
    })

# Suppress the menu only when no row is selected (rows are selected by the
# PreviewMouseRightButtonDown handler above). The sender/event args must come
# from param(); the previous version referenced undefined variables and threw
# an exception on every right-click, which aborted the menu open.
$lstWinget.Add_ContextMenuOpening({
    param($s, $e)
    if (@($s.SelectedItems).Count -eq 0) { $e.Handled = $true }
})

$lstWinget.Add_PreviewKeyDown({
        param($s, $e)
        try {
            $modifiers = [System.Windows.Input.Keyboard]::Modifiers
            $hasControl = (($modifiers -band [System.Windows.Input.ModifierKeys]::Control) -eq [System.Windows.Input.ModifierKeys]::Control)
            if ($hasControl -and $e.Key -eq [System.Windows.Input.Key]::C) {
                if (Copy-WmtUpdateSelectedRowsToClipboard -ListView $s) {
                    $e.Handled = $true
                }
            }
            # Enter or Space toggles checkbox on selected rows
            if ($e.Key -eq [System.Windows.Input.Key]::Enter -or $e.Key -eq [System.Windows.Input.Key]::Space) {
                $selected = @($s.SelectedItems)
                if ($selected.Count -gt 0) {
                    $anyUnchecked = $false
                    foreach ($item in $selected) {
                        $currentVal = $false
                        try { if ($item.PSObject.Properties["IsChecked"]) { $currentVal = [bool]$item.IsChecked } } catch {}
                        if (-not $currentVal) { $anyUnchecked = $true; break }
                    }
                    foreach ($item in $selected) {
                        try {
                            if ($item.PSObject.Properties["IsChecked"]) {
                                $item.IsChecked = $anyUnchecked
                            }
                        }
                        catch {}
                    }
                    try { $s.Items.Refresh() } catch {}
                    $e.Handled = $true
                }
            }
        }
        catch {
            Write-GuiLog "ERROR: Key handler failed: $($_.Exception.Message)"
        }
    })

# Mouse drag multi-select: hold left button and drag to select a range
$script:WmtDragSelectStartIndex = -1
$lstWinget.Add_PreviewMouseLeftButtonDown({
        param($s, $e)
        try {
            $hitTest = $s.InputHitTest($e.GetPosition($s))
            if ($hitTest) {
                $container = $hitTest
                while ($container -and -not ($container -is [System.Windows.Controls.ListViewItem])) {
                    $container = [System.Windows.Media.VisualTreeHelper]::GetParent($container)
                }
                if ($container) {
                    $item = $s.ItemContainerGenerator.ItemFromContainer($container)
                    if ($item) {
                        $script:WmtDragSelectStartIndex = $s.Items.IndexOf($item)
                    }
                }
            }
        }
        catch {}
    })
$lstWinget.Add_PreviewMouseMove({
        param($s, $e)
        try {
            if ($script:WmtDragSelectStartIndex -lt 0) { return }
            if ($e.LeftButton -ne [System.Windows.Input.MouseButtonState]::Pressed) {
                $script:WmtDragSelectStartIndex = -1
                return
            }
            $hitTest = $s.InputHitTest($e.GetPosition($s))
            if (-not $hitTest) { return }
            $container = $hitTest
            while ($container -and -not ($container -is [System.Windows.Controls.ListViewItem])) {
                $container = [System.Windows.Media.VisualTreeHelper]::GetParent($container)
            }
            if (-not $container) { return }
            $item = $s.ItemContainerGenerator.ItemFromContainer($container)
            if (-not $item) { return }
            $currentIndex = $s.Items.IndexOf($item)
            if ($currentIndex -lt 0) { return }
            $start = [Math]::Min($script:WmtDragSelectStartIndex, $currentIndex)
            $end = [Math]::Max($script:WmtDragSelectStartIndex, $currentIndex)
            $s.SelectedItems.Clear()
            for ($i = $start; $i -le $end; $i++) {
                $s.SelectedItems.Add($s.Items[$i])
            }
            $e.Handled = $true
        }
        catch {}
    })
$lstWinget.Add_PreviewMouseLeftButtonUp({
        $script:WmtDragSelectStartIndex = -1
    })
}

