$ctxMenu.Add_Opened({
    $selected = @($lstWinget.SelectedItems)
    $checked = @(Get-WmtUpdateListCheckedItems)
    $actionable = @($lstWinget.Items | Where-Object { Test-WmtUpdateListActionableItem -Item $_ })
    $isSearch = Test-WmtPackageSearchMode
    $installedSelected = @($selected | Where-Object { Test-WmtPackageItemInstalled -Item $_ })
    $notInstalledSelected = @($selected | Where-Object { -not (Test-WmtPackageItemInstalled -Item $_) })
    $updateSelected = @($selected | Where-Object { Test-WmtPackageItemHasUpdate -Item $_ })

    $miInstall.Visibility = if ($isSearch -and $notInstalledSelected.Count -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miInstall.IsEnabled = ($notInstalledSelected.Count -gt 0)

    $miUpdate.Visibility = if (-not $isSearch -or $updateSelected.Count -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miUpdate.IsEnabled = if ($isSearch) { $updateSelected.Count -gt 0 } else { ($checked.Count -gt 0 -or $selected.Count -gt 0) }

    $miUpdateAll.Visibility = if ($isSearch) { [System.Windows.Visibility]::Collapsed } else { [System.Windows.Visibility]::Visible }
    $miUpdateAll.IsEnabled = (-not $isSearch -and $btnWingetUpdateAll -and $btnWingetUpdateAll.Visibility -eq [System.Windows.Visibility]::Visible)

    $miUninstall.Visibility = if (-not $isSearch -or $installedSelected.Count -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miUninstall.IsEnabled = if ($isSearch) { $installedSelected.Count -gt 0 } else { $selected.Count -gt 0 }

    $repairableSources = @("winget", "pip", "pip3", "npm", "npm (global)", "pnpm", "pnpm (global)", "chocolatey", "choco", "scoop", "gem", "ruby", "cargo", "rust", "dotnet", "psmodule", "composer")
    $repairableInstalled = @($installedSelected | Where-Object { ([string]$_.Source).Trim().ToLowerInvariant() -in $repairableSources })
    $miRepair.Visibility = if (-not $isSearch -or $repairableInstalled.Count -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miRepair.IsEnabled = if ($isSearch) { $repairableInstalled.Count -gt 0 } else { $selected.Count -gt 0 }

    $miCheckSelected.IsEnabled = ($selected.Count -gt 0)
    $miUncheckSelected.IsEnabled = ($selected.Count -gt 0)
    $miCheckAll.IsEnabled = ($actionable.Count -gt 0)
    $miUncheckAll.IsEnabled = ($actionable.Count -gt 0)
    $miCopyRow.IsEnabled = ($selected.Count -gt 0)

    $single = if ($selected.Count -eq 1) { $selected[0] } else { $null }
    $canShowManifest = ($single -and (Test-WingetManifestSupportedItem $single))
    $canShowChoco = ($single -and (Test-ChocoManifestSupportedItem $single))
    $canShowProviderMetadata = ($single -and (Test-WmtProviderMetadataSupportedItem $single))
    $packagePageUrl = if ($single) { Get-WmtPackagePageUrl -Item $single } else { $null }

    # Keep the specialized manifest actions, but only show them for the
    # provider they actually support. Generic metadata covers the rest.
    $miManifest.Visibility = if ($canShowManifest) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miManifest.IsEnabled = [bool]$canShowManifest
    $miChocoManifest.Visibility = if ($canShowChoco -and (Test-WmtPackageItemInstalled -Item $single)) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miChocoManifest.IsEnabled = ($canShowChoco -and (Test-WmtPackageItemInstalled -Item $single))
    # Replaced by the generic package-page item to avoid duplicate Chocolatey entries.
    $miChocoPage.Visibility = [System.Windows.Visibility]::Collapsed

    $miProviderMetadata.Visibility = if ($canShowProviderMetadata -and -not $canShowManifest) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miProviderMetadata.IsEnabled = [bool]$canShowProviderMetadata
    $miPackagePage.Visibility = if (-not [string]::IsNullOrWhiteSpace([string]$packagePageUrl)) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miPackagePage.IsEnabled = -not [string]::IsNullOrWhiteSpace([string]$packagePageUrl)
    if ($single) {
        $singleSource = ([string]$single.Source).Trim().ToLowerInvariant()
        $miPackagePage.Header = if ($singleSource -in @("steam","epic","legendary","gog","gogdl","msstore")) { "Open Store Page" } else { "Open Package Page" }
    }

    $canConfigureCustomUpdate = $false
    $hasCustomUpdateCommand = $false
    if ($single) {
        $selectedSource = ([string]$single.Source).Trim()
        $selectedId = ([string]$single.Id).Trim()
        $canConfigureCustomUpdate = (-not [string]::IsNullOrWhiteSpace($selectedSource) -and -not [string]::IsNullOrWhiteSpace($selectedId))
        if ($isSearch) { $canConfigureCustomUpdate = ($canConfigureCustomUpdate -and (Test-WmtPackageItemHasUpdate -Item $single)) }
        if ($canConfigureCustomUpdate) { $hasCustomUpdateCommand = -not [string]::IsNullOrWhiteSpace((Get-WmtCustomUpdateCommand -Source $selectedSource -Id $selectedId)) }
    }
    $miCustomUpdateCommand.Visibility = if ($canConfigureCustomUpdate) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miCustomUpdateCommand.IsEnabled = $canConfigureCustomUpdate
    $miCustomUpdateCommand.Header = if ($hasCustomUpdateCommand) { "Edit Custom Update Command..." } else { "Set Custom Update Command..." }
    $miClearCustomUpdateCommand.Visibility = if ($hasCustomUpdateCommand) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    $miClearCustomUpdateCommand.IsEnabled = $hasCustomUpdateCommand

    # Ignore is an update-scan concept, not a package-search action.
    $miIgnore.Visibility = if ($isSearch) { [System.Windows.Visibility]::Collapsed } else { [System.Windows.Visibility]::Visible }

    if ($canShowManifest) {
        $miManifest.ToolTip = "Show the winget manifest details for the selected package"
    }
})

# 8. Attach to List
$lstWinget.ContextMenu = $ctxMenu
$lstWinget.Add_SelectionChanged({
    try { Update-WmtPackageSearchActionButtons } catch {}
})

# 9. Double-click opens store page (Steam/Epic/GOG/Chocolatey) or app manifest
$lstWinget.Add_MouseDoubleClick({
    param($s, $e)
    try {
        $selected = @($s.SelectedItems)
        if ($selected.Count -ne 1) { return }
        $hitTest = $s.InputHitTest($e.GetPosition($s))
        if ($hitTest -is [System.Windows.Controls.CheckBox]) { return }
        $item = $selected[0]
        $url = Get-WmtPackagePageUrl -Item $item
        if (-not [string]::IsNullOrWhiteSpace([string]$url)) {
            Start-Process $url
        }
        elseif (Test-WmtProviderMetadataSupportedItem -Item $item) {
            Show-WmtPackageProviderMetadata -Item $item
        }
    }
    catch {}
})

# --- WINGET UNIFIED SEARCH BOX ---
# Get reference to the search box border for focus glow effect
$script:WingetSearchBorder = $txtWingetSearch.Parent  # The Grid inside the Border
if ($script:WingetSearchBorder -and $script:WingetSearchBorder.Parent -is [System.Windows.Controls.Border]) {
$script:WingetSearchBorder = $script:WingetSearchBorder.Parent
}

# Placeholder text helper
$txtWingetSearch.Add_GotFocus({
    if ($txtWingetSearch.Text -in @("Search packages...", "Search new packages...")) {
        $txtWingetSearch.Text = ""
        $txtWingetSearch.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty, "TextPrimary")
    }
    # Apply focus glow to the search border
    if ($script:WingetSearchBorder) {
        $script:WingetSearchBorder.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "Accent")
        $script:WingetSearchBorder.BorderThickness = [System.Windows.Thickness]::new(2)
    }
})
$txtWingetSearch.Add_LostFocus({
    # Restore placeholder if empty
    if ([string]::IsNullOrWhiteSpace($txtWingetSearch.Text)) {
        $txtWingetSearch.Text = "Search packages..."
        $txtWingetSearch.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty, "TextMuted")
    }
    # Remove focus glow
    if ($script:WingetSearchBorder) {
        $script:WingetSearchBorder.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BorderBrush")
        $script:WingetSearchBorder.BorderThickness = [System.Windows.Thickness]::new(1)
    }
})
$txtWingetSearch.Add_TextChanged({
    try {
        # Toggle clear button visibility
        $hasRealText = (-not [string]::IsNullOrWhiteSpace($txtWingetSearch.Text)) -and
                        ($txtWingetSearch.Text -notin @("Search packages...", "Search new packages..."))
        if ($btnWingetClearSearch) {
            $btnWingetClearSearch.Visibility = if ($hasRealText) { "Visible" } else { "Collapsed" }
        }
        # If the user starts typing and the only item is our status message, clear it
        if ($lstWinget -and $lstWinget.Items.Count -eq 1) {
            try {
                $firstName = ""
                $firstItem = $lstWinget.Items[0]
                if ($firstItem -is [string]) { $firstName = $firstItem }
                elseif ($firstItem.PSObject.Properties["Name"]) { $firstName = [string]$firstItem.Name }
                if ($firstName -eq "No updates available") { $lstWinget.Items.Clear() }
            } catch {}
        }
    } catch {}
})
$txtWingetSearch.Add_KeyDown({ param($s, $e)
    if ($e.Key -eq "Return") {
        $e.Handled = $true
        if (Test-WmtUpdateScanEngineBusy) {
            Write-GuiLog "Search blocked: an update scan or action is still running."
            return
        }
        if ($script:WmtPackageSearchActive) {
            Write-GuiLog "Search blocked: a search is already in progress."
            return
        }
        try {
            & $script:InvokeWingetSearch
        } catch {
            Write-GuiLog "Search error: $($_.Exception.Message)"
            # Ensure search state is recovered on any unhandled error
            $script:WmtPackageSearchActive = $false
            try { $txtWingetSearch.IsEnabled = $true; $txtWingetSearch.ToolTip = "" } catch {}
        }
    }
})

# Clear button click handler - restores previous scan results
$script:WingetSavedScanItems = $null
if ($btnWingetClearSearch) {
$btnWingetClearSearch.Add_Click({
    $txtWingetSearch.Text = "Search packages..."
    $txtWingetSearch.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty, "TextMuted")
    $btnWingetClearSearch.Visibility = "Collapsed"

    # Restore previous scan results if available
    if ($script:WingetSavedScanItems -and $script:WingetSavedScanItems.Count -gt 0) {
        $lstWinget.Items.Clear()
        foreach ($item in $script:WingetSavedScanItems) { [void]$lstWinget.Items.Add($item) }
        $lblWingetTitle.Text = "Package Updates"
        $lblWingetStatus.Text = "Ready"
        $lblWingetStatus.Visibility = "Visible"
        $btnWingetInstall.Visibility = "Collapsed"
        $btnWingetUpdateSel.Visibility = "Visible"
        if ($btnWingetUpdateAll) { $btnWingetUpdateAll.Visibility = "Visible" }
        if ($btnWingetUninstall) { $btnWingetUninstall.Visibility = "Visible" }
        $script:WmtPackageSearchActive = $false
    }
    $txtWingetSearch.Focus()
})
}

# Initialize placeholder color
$txtWingetSearch.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty, "TextMuted")

# 2. HELPER TO START JOB
$Script:StartWingetAction = {
param($ListItems, $ActionName, $CmdTemplate)
if (-not $ListItems -or $ListItems.Count -eq 0) { return }

$uniqueItems = @($ListItems | Select-Object -Property Source, Name, Id, Version, Available, VersionSort, AvailableSort, IsChecked, LibraryPath, InstallDir, ManifestPath, ExecutablePath, Platform, RawAvailable, WUIsOptional -Unique)
$actionSettings = Get-WmtSettings
$providerCapsForAction = Get-WmtProviderCapabilities
$globalHeadlessEnabled = [bool](Get-WmtUpdateSilentInstallEnabled -Settings $actionSettings)
foreach ($actionItem in @($uniqueItems)) {
    $providerKey = Get-WmtProviderKeyForPackageSource -Source ([string]$actionItem.Source)
    $logFilesEnabled = $true
    $headlessEnabled = $globalHeadlessEnabled
    if (-not [string]::IsNullOrWhiteSpace($providerKey) -and $providerCapsForAction.Contains($providerKey)) {
        $logFilesEnabled = Get-WmtProviderToggle -Settings $actionSettings -ProviderKey $providerKey -ToggleName "Logs"
        $headlessEnabled = Get-WmtEffectiveProviderHeadless -Settings $actionSettings -ProviderKey $providerKey
    }
    $actionItem | Add-Member -MemberType NoteProperty -Name "ProviderLogFilesEnabled" -Value ([bool]$logFilesEnabled) -Force
    $actionItem | Add-Member -MemberType NoteProperty -Name "ProviderHeadlessEnabled" -Value ([bool]$headlessEnabled) -Force
}
if ($ActionName -eq "Update") {
    $customSettings = $actionSettings
    foreach ($updateItem in $uniqueItems) {
        $customUpdateCommand = Get-WmtCustomUpdateCommand -Source ([string]$updateItem.Source) -Id ([string]$updateItem.Id) -Settings $customSettings
        $updateItem | Add-Member -MemberType NoteProperty -Name "CustomUpdateCommand" -Value $customUpdateCommand -Force
    }
}
$totalItems = $uniqueItems.Count

# UI Updates
$btnWingetScan.IsEnabled = $false
$txtWingetSearch.IsEnabled = $false
$txtWingetSearch.ToolTip = "Wait for the current action to finish."
$btnWingetUpdateSel.IsEnabled = $false
if ($btnWingetUpdateAll) { $btnWingetUpdateAll.IsEnabled = $false }
if ($btnWingetInstall) { $btnWingetInstall.IsEnabled = $false }
if ($btnWingetUninstall) { $btnWingetUninstall.IsEnabled = $false }
$lblWingetStatus.Text = "$ActionName in progress..."
$lblWingetStatus.Visibility = "Visible"
$script:WingetActiveAction = $ActionName
$script:WingetActionStartedAt = Get-Date
$script:WingetProgressTotal = $totalItems
$script:WingetProgressDone = 0
$script:WingetProgressSuccess = 0
$script:WingetProgressSkipped = 0
$script:WingetProgressFailed = 0
$script:WingetCurrentIndex = 0
$script:WingetCurrentPercent = 0
$script:WingetCurrentItemName = ""
$script:WingetCurrentItemSource = ""
$script:WingetCurrentItemStartedAt = $null
$script:WingetActionForcedTimeout = $false
$script:WingetCompletedIndexes = @{}
# Preserve the exact action-order package identities so RESULT:<index> can
# update only the row that actually completed instead of forcing a provider
# rescan while uninstall registry/provider state may still be settling.
$script:WingetActionItems = @($uniqueItems)
$script:WingetActionStoreUpdateOnly = (
    $ActionName -eq "Update" -and
    $totalItems -gt 0 -and
    @($uniqueItems | Where-Object { ([string]$_.Source).ToLowerInvariant() -eq "msstore" }).Count -eq $totalItems
)
$script:WingetActionHasStoreCli = @($uniqueItems | Where-Object { ([string]$_.Source).ToLowerInvariant() -eq "msstore" -and $ActionName -eq "Install" }).Count -gt 0
$script:WingetStoreResourcesInUseSeen = $false
$script:WingetStoreErrorLogSeen = @{}
$script:WingetStoreFallbackSeen = @{}
$script:WingetSteamOpenSeen = @{}
if ($pbWingetProgress) {
    $pbWingetProgress.Minimum = 0
    $pbWingetProgress.Maximum = [Math]::Max(1, $totalItems)
    $pbWingetProgress.Value = 0
    $pbWingetProgress.IsIndeterminate = $false
    $pbWingetProgress.Visibility = "Visible"
}
if ($lblWingetProgress) {
    $lblWingetProgress.Text = "0/$totalItems done | 0 success | 0 skipped | 0 failed"
    $lblWingetProgress.Visibility = "Visible"
}
if ($lblWingetLastResult) {
    $lblWingetLastResult.Text = ""
    $lblWingetLastResult.Visibility = "Collapsed"
}

$script:RefreshWingetProgressUi = {
    $total = [Math]::Max(1, [int]$script:WingetProgressTotal)
    $done = [Math]::Max(0, [int]$script:WingetProgressDone)
    $success = [Math]::Max(0, [int]$script:WingetProgressSuccess)
    $skipped = [Math]::Max(0, [int]$script:WingetProgressSkipped)
    $failed = [Math]::Max(0, [int]$script:WingetProgressFailed)
    $curIdx = [Math]::Max(0, [int]$script:WingetCurrentIndex)
    $curPct = [Math]::Max(0, [Math]::Min(100, [int]$script:WingetCurrentPercent))

    if ($pbWingetProgress) {
        $value = [double]$done
        if ($curIdx -gt 0 -and $done -lt $total) {
            $base = [Math]::Max($done, $curIdx - 1)
            $value = [Math]::Min([double]$total, [double]$base + ($curPct / 100.0))
        }
        $pbWingetProgress.Value = $value
    }

    if ($lblWingetProgress) {
        $running = ""
        if ($curIdx -gt 0 -and $done -lt $total) {
            $running = " | running $curIdx/$total"
            if ($curPct -gt 0) { $running += " ($curPct%)" }
        }
        $lblWingetProgress.Text = "$done/$total done | $success success | $skipped skipped | $failed failed$running"
    }
}
& $script:RefreshWingetProgressUi

$script:SetWingetLastResultUi = {
    param(
        [string]$ResultCode,
        [string]$PackageName,
        [int]$DoneIndex,
        [int]$TotalCount
    )
    if (-not $lblWingetLastResult) { return }

    $text = "Last: [$ResultCode] $DoneIndex/$TotalCount - $PackageName"
    $brush = [System.Windows.Media.Brushes]::LightGray
    switch ($ResultCode) {
        "SUCCESS" { $brush = [System.Windows.Media.Brushes]::LightGreen }
        "SKIPPED" { $brush = [System.Windows.Media.Brushes]::Gold }
        "CANCELLED" { $brush = [System.Windows.Media.Brushes]::Orange }
        "FAILED" { $brush = [System.Windows.Media.Brushes]::Tomato }
    }

    $lblWingetLastResult.Text = $text
    $lblWingetLastResult.Foreground = $brush
    $lblWingetLastResult.Visibility = "Visible"
}

# 1. Define the Job Arguments
$wingetIncludeUnknown = Get-WmtWingetIncludeUnknown -Settings (Get-WmtSettings)
$pythonExePath = "python.exe"
try {
    $resolvedPython = Get-Command "python.exe" -ErrorAction Stop
    if ($resolvedPython.Source) { $pythonExePath = [string]$resolvedPython.Source }
}
catch {}
$packageInstallLogRoot = ""
$needsPackageInstallLogRoot = ($ActionName -in @("Install", "Update", "Uninstall", "Repair")) -and (@($uniqueItems | Where-Object {
            [bool]$_.ProviderLogFilesEnabled
        }).Count -gt 0)
if ($needsPackageInstallLogRoot) {
    $packageInstallLogRoot = Join-Path (Get-DataPath) "package-install-logs"
    try { [void][System.IO.Directory]::CreateDirectory($packageInstallLogRoot) }
    catch {
        $packageInstallLogRoot = Join-Path $env:TEMP "WMT-PackageInstallLogs"
        try { [void][System.IO.Directory]::CreateDirectory($packageInstallLogRoot) } catch {}
    }
}

$jobArgs = @{
    Items                      = $uniqueItems
    ActionName                 = $ActionName
    CmdTemplate                = $CmdTemplate
    TempPath                   = $env:TEMP
    PackageInstallLogRoot      = $packageInstallLogRoot
    WingetIncludeUnknown       = $wingetIncludeUnknown
    SilentUpdateInstallEnabled = [bool](Get-WmtUpdateSilentInstallEnabled)
    PythonExePath              = $pythonExePath
    LegendaryExePath           = Get-WmtLegendaryExePath
    GogdlExePath               = Get-WmtGogdlExePath
    GogdlAuthConfigPath        = Get-WmtGogdlAuthConfigPath
}

# 2. Start the background worker on the shared in-process runspace pool.
# A thread-safe queue preserves the existing live LOG:/PROGRESS:/RESULT: protocol.
$wingetWorkerScript = {
    param($ArgsDict, $OutputQueue)

    $script:WmtActiveProviderTranscriptPath = ""

    function Write-WmtWorkerOutputItem {
        param(
            $Value,
            [switch]$SkipTranscriptMirror
        )

        if ($null -eq $Value) { return }
        $activeTranscript = ([string]$script:WmtActiveProviderTranscriptPath).Trim()
        if (-not $SkipTranscriptMirror -and
            -not [string]::IsNullOrWhiteSpace($activeTranscript) -and
            $Value -is [string] -and ([string]$Value) -like "LOG:*") {
            try {
                [System.IO.File]::AppendAllText(
                    $activeTranscript,
                    ("[{0}] {1}{2}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"), ([string]$Value).Substring(4), [Environment]::NewLine),
                    [System.Text.UTF8Encoding]::new($false)
                )
            }
            catch {}
        }
        $OutputQueue.Enqueue($Value)
    }

    function Write-Output {
        param(
            [Parameter(ValueFromPipeline = $true, Position = 0)]$InputObject,
            [switch]$NoEnumerate
        )
        process {
            if ($null -eq $InputObject) { return }
            if ($NoEnumerate) {
                Write-WmtWorkerOutputItem -Value $InputObject
                return
            }
            if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) {
                foreach ($outputItem in $InputObject) { Write-WmtWorkerOutputItem -Value $outputItem }
            }
            else {
                Write-WmtWorkerOutputItem -Value $InputObject
            }
        }
    }
    $items = $ArgsDict.Items
    $act = $ArgsDict.ActionName
    $tmpl = $ArgsDict.CmdTemplate
    $temp = $ArgsDict.TempPath
    $packageInstallLogRoot = [string]$ArgsDict.PackageInstallLogRoot
    $wingetIncludeUnknown = [bool]$ArgsDict.WingetIncludeUnknown
    $silentUpdateInstallEnabled = [bool]$ArgsDict.SilentUpdateInstallEnabled
    $pythonExePath = [string]$ArgsDict.PythonExePath
    $legendaryExePath = [string]$ArgsDict.LegendaryExePath
    $gogdlExePath = [string]$ArgsDict.GogdlExePath
    $gogdlAuthConfigPath = [string]$ArgsDict.GogdlAuthConfigPath

    [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)

    # --- ERROR DICTIONARY ---
    $ErrorCodes = @{
        "0" = "Success"
        "0x0" = "Success"
        "3010" = "Reboot Required"
        "1602" = "Cancelled by User"
        "1618" = "Another Installation in Progress"

        # WinGet-specific HRESULTs. Keep these aligned with
        # winget error --output / AppInstallerErrors.h.
        "0x8a150001" = "WinGet internal error"
        "0x8a150002" = "Invalid WinGet command-line arguments"
        "0x8a150003" = "WinGet command failed"
        "0x8a150004" = "Opening manifest failed"
        "0x8a150005" = "Cancellation signal received"
        "0x8a150006" = "Running installer through ShellExecute failed"
        "0x8a150007" = "Manifest version is newer than this WinGet client supports"
        "0x8a150008" = "Downloading installer failed"
        "0x8a150009" = "Cannot write to a higher-version source index"
        "0x8a15000a" = "WinGet source index integrity is compromised"
        "0x8a15000b" = "Configured WinGet source information is corrupt"
        "0x8a15000c" = "WinGet source name already exists"
        "0x8a15000d" = "Invalid WinGet source type"
        "0x8a15000e" = "Package is a bundle rather than a package"
        "0x8a15000f" = "Required source data is missing"
        "0x8a150010" = "No applicable installer for this system"
        "0x8a150011" = "Installer hash does not match the manifest"
        "0x8a150012" = "WinGet source name does not exist"
        "0x8a150013" = "WinGet source location is already configured"
        "0x8a150014" = "No packages found"
        "0x8a15008e" = "Upgrade uses a different install technology than the current installation"
        "0x80070002" = "File Not Found"; "0x80070003" = "Path Not Found"; "0x80070005" = "Access Denied"
        "0x80070490" = "Element Not Found"; "0x80072ee7" = "DNS Lookup Fail"; "0x80072f8f" = "SSL Cert Error"
        "0x80073d02" = "Resources Currently In Use"; "-2147009278" = "Resources Currently In Use"; "2147958018" = "Resources Currently In Use"
        "1603" = "Fatal MSI Error"
    }

    function New-WmtPackageDiagnosticStem {
        param(
            [string]$PackageId,
            [string]$ActionLabel
        )

        $root = ([string]$packageInstallLogRoot).Trim()
        if ([string]::IsNullOrWhiteSpace($root)) { $root = Join-Path $temp "WMT-PackageInstallLogs" }
        try { [void][System.IO.Directory]::CreateDirectory($root) }
        catch {
            $root = Join-Path $temp "WMT-PackageInstallLogs"
            try { [void][System.IO.Directory]::CreateDirectory($root) } catch {}
        }

        $safeId = ([string]$PackageId -replace '[^A-Za-z0-9._-]', '_').Trim('_')
        if ([string]::IsNullOrWhiteSpace($safeId)) { $safeId = "package" }
        $safeAction = ([string]$ActionLabel -replace '[^A-Za-z0-9._-]', '_').Trim('_')
        if ([string]::IsNullOrWhiteSpace($safeAction)) { $safeAction = "action" }
        $stamp = (Get-Date).ToString("yyyyMMdd-HHmmss-fff")
        return (Join-Path $root "$stamp-$safeAction-$safeId")
    }

    function Add-WmtPackageTranscriptLine {
        param(
            [string]$Path,
            [string]$Text
        )

        if ([string]::IsNullOrWhiteSpace($Path) -or $null -eq $Text) { return }
        try {
            [System.IO.File]::AppendAllText(
                $Path,
                ("[{0}] {1}{2}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"), [string]$Text, [Environment]::NewLine),
                [System.Text.UTF8Encoding]::new($false)
            )
        }
        catch {}
    }

    function ConvertTo-WmtTranscriptCommand {
        param(
            [string]$Command,
            [string]$TranscriptPath
        )

        if ([string]::IsNullOrWhiteSpace($Command) -or [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            return $Command
        }

        $commandBase64 = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($Command))
        $transcriptBase64 = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($TranscriptPath))
        $loggedCommandScript = @"
`$ErrorActionPreference = 'Continue'
`$commandText = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('$commandBase64'))
`$transcriptPath = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('$transcriptBase64'))
try {
    [System.IO.File]::AppendAllText(
        `$transcriptPath,
        ("[{0}] COMMAND: {1}{2}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"), `$commandText, [Environment]::NewLine),
        [System.Text.UTF8Encoding]::new(`$false)
    )
}
catch {}
# Windows PowerShell 5.1 Tee-Object -Append writes UTF-16 even when the
# transcript header is UTF-8. Write each captured line using the same UTF-8
# encoding as the parent WMT worker to keep the log readable/searchable.
`$transcriptUtf8 = [System.Text.UTF8Encoding]::new(`$false)
`$global:LASTEXITCODE = `$null
`$commandSucceeded = `$true
try {
    Invoke-Expression `$commandText *>&1 |
        ForEach-Object {
            `$line = [string]`$_
            try { [System.IO.File]::AppendAllText(`$transcriptPath, (`$line + [Environment]::NewLine), `$transcriptUtf8) } catch {}
            Write-Host `$line
        }
    `$commandSucceeded = `$?
}
catch {
    `$commandSucceeded = `$false
    `$errorText = `$_.Exception.Message
    try { [System.IO.File]::AppendAllText(`$transcriptPath, (`$errorText + [Environment]::NewLine), `$transcriptUtf8) } catch {}
    Write-Host `$errorText
}
`$exitCode = if (`$null -ne `$global:LASTEXITCODE) { [int]`$global:LASTEXITCODE } elseif (`$commandSucceeded) { 0 } else { 1 }
try {
    [System.IO.File]::AppendAllText(
        `$transcriptPath,
        ("[{0}] EXIT: {1}{2}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"), `$exitCode, [Environment]::NewLine),
        [System.Text.UTF8Encoding]::new(`$false)
    )
}
catch {}
exit `$exitCode
"@
        $encodedLoggedCommand = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($loggedCommandScript))
        return "powershell.exe -NoProfile -ExecutionPolicy Bypass -EncodedCommand $encodedLoggedCommand"
    }

    # A visible custom PowerShell override runs inside the WMT cmd window, but
    # its stdout/stderr must be captured from the actual child process. Piping
    # nested powershell.exe through Tee-Object is unreliable in Windows PS 5.1
    # (and Tee-Object -Append writes UTF-16 into our UTF-8 transcripts).
    function ConvertTo-WmtCapturedCustomPowerShellCommand {
        param(
            [string]$EncodedCommand,
            [string]$TranscriptPath
        )

        if ([string]::IsNullOrWhiteSpace($EncodedCommand) -or [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            return "powershell.exe -NoProfile -ExecutionPolicy Bypass -EncodedCommand $EncodedCommand"
        }

        $pathBase64 = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($TranscriptPath))
        $runner = @'
$ErrorActionPreference = 'Continue'
$transcriptPath = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('__WMT_LOG_PATH__'))
$utf8 = [System.Text.UTF8Encoding]::new($false)
$exitCode = 1
$proc = $null
$stderrCapture = [System.Text.StringBuilder]::new()
$stdoutTail = [System.Text.StringBuilder]::new()
try {
    $psi = [System.Diagnostics.ProcessStartInfo]::new()
    $psi.FileName = 'powershell.exe'
    $psi.Arguments = '-NoProfile -ExecutionPolicy Bypass -EncodedCommand __WMT_USER_COMMAND__'
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    try {
        $psi.StandardOutputEncoding = [Console]::OutputEncoding
        $psi.StandardErrorEncoding = [Console]::OutputEncoding
    } catch {}

    $proc = [System.Diagnostics.Process]::Start($psi)
    $outBuffer = New-Object char[] 4096
    $errBuffer = New-Object char[] 4096
    $outTask = $proc.StandardOutput.ReadAsync($outBuffer, 0, $outBuffer.Length)
    $errTask = $proc.StandardError.ReadAsync($errBuffer, 0, $errBuffer.Length)

    # Drain both native pipes while the child is running. Reading both at once
    # prevents a full stderr pipe from deadlocking an otherwise quiet installer.
    while (-not $proc.HasExited -or $outTask -or $errTask) {
        if ($outTask -and $outTask.IsCompleted) {
            $count = 0
            try { $count = [int]$outTask.GetAwaiter().GetResult() } catch {}
            if ($count -le 0) {
                $outTask = $null
            } else {
                $chunk = -join $outBuffer[0..($count - 1)]
                try { [System.IO.File]::AppendAllText($transcriptPath, $chunk, $utf8) } catch {}
                [void]$stdoutTail.Append($chunk)
                # Retain only recent stdout for deduping CLIXML Write-Host messages.
                if ($stdoutTail.Length -gt 262144) {
                    [void]$stdoutTail.Remove(0, $stdoutTail.Length - 262144)
                }
                [Console]::Out.Write($chunk)
                $outBuffer = New-Object char[] 4096
                $outTask = $proc.StandardOutput.ReadAsync($outBuffer, 0, $outBuffer.Length)
            }
        }
        if ($errTask -and $errTask.IsCompleted) {
            $count = 0
            try { $count = [int]$errTask.GetAwaiter().GetResult() } catch {}
            if ($count -le 0) {
                $errTask = $null
            } else {
                $chunk = -join $errBuffer[0..($count - 1)]
                # Windows PowerShell 5.1 serializes redirected host/progress
                # records as CLIXML on stderr. Buffer stderr separately so
                # markup never mixes with readable stdout in the package log.
                [void]$stderrCapture.Append($chunk)
                $errBuffer = New-Object char[] 4096
                $errTask = $proc.StandardError.ReadAsync($errBuffer, 0, $errBuffer.Length)
            }
        }
        if (-not (($outTask -and $outTask.IsCompleted) -or ($errTask -and $errTask.IsCompleted))) {
            Start-Sleep -Milliseconds 25
        }
    }
    $proc.WaitForExit()
    $exitCode = [int]$proc.ExitCode

    if ($stderrCapture.Length -gt 0) {
        $stderrText = $stderrCapture.ToString()
        if ($stderrText -match '^\s*#< CLIXML(?:\r?\n)') {
            try {
                # Keep external commands in their own process so custom 'exit'
                # statements and installer return codes behave as before.
                # Decode its PowerShell stream records to text rather than
                # pasting XML serialization or noisy download-progress records.
                # PowerShell/native child processes may write plain stderr
                # before or after the CLIXML envelope. Isolate the document
                # rather than parsing unrelated error text as XML.
                $xmlStart = $stderrText.IndexOf('<Objs', [System.StringComparison]::Ordinal)
                $xmlEnd = $stderrText.LastIndexOf('</Objs>', [System.StringComparison]::Ordinal)
                if ($xmlStart -lt 0 -or $xmlEnd -lt $xmlStart) { throw 'PowerShell stream envelope is incomplete.' }
                $xmlEnd += '</Objs>'.Length
                $xmlText = $stderrText.Substring($xmlStart, $xmlEnd - $xmlStart)
                $otherStderr = $stderrText.Substring(0, $xmlStart) + [Environment]::NewLine + $stderrText.Substring($xmlEnd)
                $otherStderr = [regex]::Replace($otherStderr, '(?m)^[ \t]*#< CLIXML[ \t]*\r?\n?', '')
                $xmlSettings = [System.Xml.XmlReaderSettings]::new()
                $xmlSettings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
                $xmlSettings.XmlResolver = $null
                $document = [System.Xml.XmlDocument]::new()
                $document.XmlResolver = $null
                $reader = [System.Xml.XmlReader]::Create([System.IO.StringReader]::new($xmlText), $xmlSettings)
                try { $document.Load($reader) } finally { $reader.Dispose() }
                if ($document.DocumentElement.LocalName -ne 'Objs') { throw 'Unexpected PowerShell stream format.' }
                $stdoutText = $stdoutTail.ToString()
                $errorLines = [System.Collections.Generic.List[string]]::new()
                foreach ($record in $document.DocumentElement.ChildNodes) {
                    if ($record.NodeType -eq [System.Xml.XmlNodeType]::Text -or
                        $record.NodeType -eq [System.Xml.XmlNodeType]::CDATA) {
                        $nativeText = ([string]$record.InnerText).Trim()
                        if (-not [string]::IsNullOrWhiteSpace($nativeText)) {
                            try { [System.IO.File]::AppendAllText($transcriptPath, ($nativeText + [Environment]::NewLine), $utf8) } catch {}
                            [Console]::Error.WriteLine($nativeText)
                        }
                        continue
                    }
                    if ($record.NodeType -ne [System.Xml.XmlNodeType]::Element) { continue }
                    $stream = if ($record.Attributes['S']) { [string]$record.Attributes['S'].Value } else { '' }
                    # Repeated CLIXML download progress is not useful in an
                    # installation report; keep warnings and errors instead.
                    if ($stream -eq 'progress') { continue }
                    $message = ''
                    if ($record.LocalName -eq 'Obj') {
                        $textNode = $null
                        if ($stream -eq 'error') {
                            # The serialized ErrorRecord.ToString often embeds the
                            # entire multiline command as well as the error. Prefer
                            # Exception.Message for a concise, actionable line.
                            $textNode = $record.SelectSingleNode(".//*[local-name()='Obj' and @N='Exception']//*[local-name()='S' and @N='Message']")
                        }
                        if (-not $textNode) {
                            $textNode = $record.SelectSingleNode("./*[local-name()='ToString']")
                        }
                        if (-not $textNode) {
                            $textNode = $record.SelectSingleNode(".//*[local-name()='S' and @N='Message']")
                        }
                        if ($textNode) { $message = $textNode.InnerText }
                    }
                    else { $message = $record.InnerText }
                    $message = [System.Xml.XmlConvert]::DecodeName([string]$message).Trim()
                    if ($stream -eq 'error' -and $message -match '(?m)\s:\s([^\r\n]+)\r?\n\s*\+\s*CategoryInfo') {
                        # Serialized ErrorRecord.ToString can prepend every
                        # line of the invoked multiline PowerShell script.
                        # Keep only the actual exception text before metadata.
                        $message = $matches[1].Trim()
                    }
                    if ([string]::IsNullOrWhiteSpace($message)) { continue }
                    if ($stream -eq 'error') {
                        # Windows PowerShell may serialize each line of an
                        # ErrorRecord separately, including the entire command
                        # source. Reassemble before choosing the real message.
                        [void]$errorLines.Add($message)
                        continue
                    }
                    # Write-Host is often present in both stdout and the
                    # information stream. Avoid writing the same text twice.
                    if ($stream -eq 'information' -and $stdoutText.Contains($message)) { continue }
                    $prefix = switch ($stream) {
                        'error'   { 'ERROR: ' }
                        'warning' { 'WARNING: ' }
                        'verbose' { 'VERBOSE: ' }
                        'debug'   { 'DEBUG: ' }
                        default   { '' }
                    }
                    $humanLine = $prefix + $message
                    try { [System.IO.File]::AppendAllText($transcriptPath, ($humanLine + [Environment]::NewLine), $utf8) } catch {}
                    if ($stream -in @('error', 'warning')) { [Console]::Error.WriteLine($humanLine) }
                    else { [Console]::Out.WriteLine($humanLine) }
                }
                if ($errorLines.Count -gt 0) {
                    $allErrors = [string]::Join([Environment]::NewLine, $errorLines)
                    $briefErrors = [regex]::Matches($allErrors, '(?m)\s:\s([^\r\n]+)\r?\n\s*\+\s*CategoryInfo')
                    $messagesToShow = [System.Collections.Generic.List[string]]::new()
                    if ($briefErrors.Count -gt 0) {
                        foreach ($match in $briefErrors) {
                            [void]$messagesToShow.Add($match.Groups[1].Value.Trim())
                        }
                    }
                    else {
                        foreach ($errorLine in $errorLines) { [void]$messagesToShow.Add($errorLine) }
                    }
                    foreach ($errorMessage in $messagesToShow) {
                        $humanError = 'ERROR: ' + $errorMessage
                        try { [System.IO.File]::AppendAllText($transcriptPath, ($humanError + [Environment]::NewLine), $utf8) } catch {}
                        [Console]::Error.WriteLine($humanError)
                    }
                }
                if (-not [string]::IsNullOrWhiteSpace($otherStderr)) {
                    $otherStderr = $otherStderr.Trim()
                    try { [System.IO.File]::AppendAllText($transcriptPath, ($otherStderr + [Environment]::NewLine), $utf8) } catch {}
                    [Console]::Error.WriteLine($otherStderr)
                }
            }
            catch {
                # Preserve full diagnostics if malformed CLIXML cannot be read,
                # but do not contaminate the primary human-readable log.
                $rawXmlPath = $transcriptPath + '.clixml'
                try { [System.IO.File]::WriteAllText($rawXmlPath, $stderrText, $utf8) } catch {}
                $errorLine = "PowerShell stream decode failed: $($_.Exception.Message). Raw output: $rawXmlPath"
                try { [System.IO.File]::AppendAllText($transcriptPath, ($errorLine + [Environment]::NewLine), $utf8) } catch {}
                [Console]::Error.WriteLine($errorLine)
            }
        }
        else {
            # Ordinary native stderr is already plain text and should remain
            # verbatim, including any useful compiler or installer diagnostics.
            try { [System.IO.File]::AppendAllText($transcriptPath, $stderrText, $utf8) } catch {}
            [Console]::Error.Write($stderrText)
        }
    }
} catch {
    $message = "Custom update output capture failed: $($_.Exception.Message)"
    try { [System.IO.File]::AppendAllText($transcriptPath, ($message + [Environment]::NewLine), $utf8) } catch {}
    [Console]::Error.WriteLine($message)
} finally {
    try { if ($proc) { $proc.Dispose() } } catch {}
}
try {
    [System.IO.File]::AppendAllText(
        $transcriptPath,
        ("{0}[{1}] EXIT: {2}{0}" -f [Environment]::NewLine, (Get-Date).ToString('yyyy-MM-dd HH:mm:ss.fff'), $exitCode),
        $utf8
    )
} catch {}
exit $exitCode
'@
        $runner = $runner.Replace('__WMT_USER_COMMAND__', $EncodedCommand).Replace('__WMT_LOG_PATH__', $pathBase64)
        # cmd.exe has an ~8191-character command-line limit. Store this verbose
        # native-stream runner in a short-lived .ps1 instead of nesting another
        # long -EncodedCommand in the visible CMD invocation.
        $runnerPath = Join-Path ([System.IO.Path]::GetTempPath()) ("WMT-CustomCapture-{0}.ps1" -f [guid]::NewGuid().ToString("N"))
        [System.IO.File]::WriteAllText($runnerPath, $runner, [System.Text.UTF8Encoding]::new($true))
        return [PSCustomObject]@{
            Command    = "powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"$runnerPath`""
            RunnerPath = $runnerPath
        }
    }

    function Copy-WmtLatestWingetDiagnosticLog {
        param(
            [string]$DestinationPath,
            [datetime]$Since
        )

        if ([string]::IsNullOrWhiteSpace($DestinationPath)) { return $false }

        $candidateDirs = @(
            (Join-Path $env:LOCALAPPDATA "Packages\Microsoft.DesktopAppInstaller_8wekyb3d8bbwe\LocalState\DiagOutputDir"),
            (Join-Path $env:LOCALAPPDATA "Microsoft\WinGet\Logs")
        ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and (Test-Path -LiteralPath $_ -PathType Container) }

        $cutoff = if ($Since -and $Since -ne [datetime]::MinValue) { $Since.AddSeconds(-10) } else { (Get-Date).AddMinutes(-10) }
        $latest = $null
        foreach ($dir in @($candidateDirs)) {
            try {
                $candidate = Get-ChildItem -LiteralPath $dir -File -Filter "*.log" -ErrorAction Stop |
                    Where-Object { $_.LastWriteTime -ge $cutoff } |
                    Sort-Object LastWriteTime -Descending |
                    Select-Object -First 1
                if ($candidate -and (-not $latest -or $candidate.LastWriteTime -gt $latest.LastWriteTime)) {
                    $latest = $candidate
                }
            }
            catch {}
        }

        if (-not $latest) { return $false }
        try {
            Copy-Item -LiteralPath $latest.FullName -Destination $DestinationPath -Force -ErrorAction Stop
            return $true
        }
        catch { return $false }
    }
    function Write-WmtInstallerFailureSummary {
        param(
            [string]$LogPath,
            [string]$PackageName,
            [string]$AttemptLabel = "installer"
        )

        if ([string]::IsNullOrWhiteSpace($LogPath)) { return }
        if (-not (Test-Path -LiteralPath $LogPath -PathType Leaf)) {
            Write-Output "LOG:[Installer] No $AttemptLabel log was produced at: $LogPath"
            return
        }

        Write-Output "LOG:[Installer] Detailed $AttemptLabel log: $LogPath"
        try {
            # MSI logs can be very large. Stream the file and keep only a small
            # rolling window instead of materializing the whole log in memory.
            $previousLines = [System.Collections.Generic.Queue[string]]::new()
            $return3Context = [System.Collections.Generic.List[string]]::new()
            $failureTail = [System.Collections.Generic.List[string]]::new()
            $captureAfterReturn3 = 0
            $sawAnyLine = $false

            foreach ($logLine in [System.IO.File]::ReadLines($LogPath)) {
                $sawAnyLine = $true
                $lineText = [string]$logLine

                if ($lineText -match '(?i)Return value 3') {
                    $return3Context.Clear()
                    foreach ($previousLine in $previousLines.ToArray()) {
                        [void]$return3Context.Add([string]$previousLine)
                    }
                    [void]$return3Context.Add($lineText)
                    $captureAfterReturn3 = 2
                }
                elseif ($captureAfterReturn3 -gt 0) {
                    [void]$return3Context.Add($lineText)
                    $captureAfterReturn3--
                }

                if ($lineText -match '(?i)(error\s+[0-9]{3,5}|installation failed|installer failed|fatal error|exception|customaction.+error|mainenginethread.+returning)') {
                    [void]$failureTail.Add($lineText)
                    if ($failureTail.Count -gt 12) { $failureTail.RemoveAt(0) }
                }

                $previousLines.Enqueue($lineText)
                while ($previousLines.Count -gt 12) { [void]$previousLines.Dequeue() }
            }

            if (-not $sawAnyLine) { return }

            $failureLines = @()
            if ($return3Context.Count -gt 0) {
                $failureLines = @($return3Context.ToArray())
                Write-Output "LOG:[Installer] MSI failure context for $PackageName (around Return value 3):"
            }
            else {
                $failureLines = @($failureTail.ToArray())
                if ($failureLines.Count -gt 0) {
                    Write-Output "LOG:[Installer] Failure indicators found in the $AttemptLabel log for ${PackageName}:"
                }
            }

            foreach ($failureLine in @($failureLines)) {
                $text = ([string]$failureLine).Trim()
                if (-not [string]::IsNullOrWhiteSpace($text)) {
                    if ($text.Length -gt 700) { $text = $text.Substring(0, 700) + "..." }
                    Write-Output "LOG:  [installer] $text"
                }
            }
        }
        catch {
            Write-Output "LOG:[Installer] Could not summarize $AttemptLabel log: $($_.Exception.Message)"
        }
    }

    function Test-WmtStoreUpdateScanPreferredItem {
        param(
            [string]$Name,
            [string]$Id
        )

        $text = (([string]$Name) + " " + ([string]$Id)).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { return $false }

        return ($text -match '(?i)(^|\b)(Microsoft\s+Store|Windows\s+Store|Store\s+Experience\s+Host|Store\s+Purchase\s+App)(\b|$)' -or
            $text -match '(?i)(Microsoft\.WindowsStore|Microsoft\.StorePurchaseApp|Microsoft\.Services\.Store\.Engagement|9WZDNCRFJBMP)')
    }

    function Get-WmtLegendaryCommandText {
        param([switch]$ForPowerShell)

        $exe = ([string]$legendaryExePath).Trim()
        if ([string]::IsNullOrWhiteSpace($exe) -or -not (Test-Path -LiteralPath $exe -PathType Leaf)) {
            try {
                $cmd = Get-Command legendary -ErrorAction SilentlyContinue
                if ($cmd -and $cmd.Source) { $exe = [string]$cmd.Source }
            }
            catch {}
        }
        if ([string]::IsNullOrWhiteSpace($exe)) { $exe = "legendary" }

        $safeExe = ([string]$exe).Replace('"', '')
        if ($ForPowerShell) { return "& `"$safeExe`"" }
        if ($safeExe -match '^[A-Za-z]:\\|^\\\\') { return "`"$safeExe`"" }
        return $safeExe
    }

    function Get-WmtGogdlCommandText {
        param([switch]$ForPowerShell)

        $exe = ([string]$gogdlExePath).Trim()
        if ([string]::IsNullOrWhiteSpace($exe) -or -not (Test-Path -LiteralPath $exe -PathType Leaf)) {
            try {
                foreach ($cmdName in @("gogdl", "gogdl.exe", "gogdl_windows_x86_64.exe")) {
                    $cmd = Get-Command $cmdName -ErrorAction SilentlyContinue
                    if ($cmd -and $cmd.Source) {
                        $exe = [string]$cmd.Source
                        break
                    }
                }
            }
            catch {}
        }
        if ([string]::IsNullOrWhiteSpace($exe)) { $exe = "gogdl" }

        $safeExe = ([string]$exe).Replace('"', '')
        if ($ForPowerShell) { return "& `"$safeExe`"" }
        if ($safeExe -match '^[A-Za-z]:\\|^\\\\') { return "`"$safeExe`"" }
        return $safeExe
    }

    function Invoke-WmtPortableProviderBinaryUpdate {
        param(
            [string]$ProviderKey,
            [string]$TargetPath,
            [ref]$Result
        )

        $Result.Value = [PSCustomObject]@{ ExitCode = 1 }
        $provider = ([string]$ProviderKey).Trim().ToLowerInvariant()
        $target = ([string]$TargetPath).Trim()
        $tmpPath = ""

        try {
            if ([string]::IsNullOrWhiteSpace($target) -or -not (Test-Path -LiteralPath $target -PathType Leaf)) {
                throw "Portable provider executable was not found at '$target'."
            }

            $isArm64 = (($env:PROCESSOR_ARCHITECTURE -eq "ARM64") -or ($env:PROCESSOR_ARCHITEW6432 -eq "ARM64"))
            $releaseApi = ""
            $assetCandidates = @()
            $displayName = $provider

            switch ($provider) {
                "legendary" {
                    $releaseApi = "https://api.github.com/repos/legendary-gl/legendary/releases/latest"
                    $preferredAsset = if ($isArm64) { "legendary_windows_arm64.exe" } else { "legendary_windows_x64.exe" }
                    $assetCandidates = @($preferredAsset, "legendary.exe")
                    $displayName = "Legendary"
                }
                "gogdl" {
                    $releaseApi = "https://api.github.com/repos/Heroic-Games-Launcher/heroic-gogdl/releases/latest"
                    $preferredAsset = if ($isArm64) { "gogdl_windows_arm64.exe" } else { "gogdl_windows_x86_64.exe" }
                    $assetCandidates = @($preferredAsset)
                    $displayName = "GOGDL"
                }
                default {
                    throw "Unsupported portable provider '$ProviderKey'."
                }
            }

            Write-Output "LOG:[Provider Update] Resolving latest $displayName portable release..."
            $headers = @{ "User-Agent" = "Windows-Maintenance-Tool" }
            $release = Invoke-RestMethod -Uri $releaseApi -Headers $headers -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop
            if (-not $release -or -not $release.assets) {
                throw "Latest release metadata did not contain downloadable assets."
            }

            $asset = $null
            foreach ($candidateName in $assetCandidates) {
                $asset = @($release.assets | Where-Object { ([string]$_.name) -ieq $candidateName } | Select-Object -First 1)
                if ($asset) { break }
            }
            if (-not $asset -or [string]::IsNullOrWhiteSpace([string]$asset.browser_download_url)) {
                throw "No matching Windows portable asset was found in release $([string]$release.tag_name)."
            }

            $targetDir = Split-Path -Parent $target
            if (-not (Test-Path -LiteralPath $targetDir -PathType Container)) {
                [void][System.IO.Directory]::CreateDirectory($targetDir)
            }
            $tmpPath = Join-Path $targetDir ("{0}.{1}.download" -f (Split-Path -Leaf $target), ([Guid]::NewGuid().ToString("N")))

            Write-Output "LOG:[Provider Update] Downloading $displayName $([string]$release.tag_name)..."
            Invoke-WebRequest -Uri ([string]$asset.browser_download_url) -Headers $headers -UseBasicParsing -OutFile $tmpPath -TimeoutSec 180 -ErrorAction Stop
            $download = Get-Item -LiteralPath $tmpPath -ErrorAction Stop
            if ($download.Length -lt 1MB) {
                throw "Downloaded provider binary is unexpectedly small ($($download.Length) bytes)."
            }

            Move-Item -LiteralPath $tmpPath -Destination $target -Force
            $tmpPath = ""
            try { Unblock-File -LiteralPath $target -ErrorAction SilentlyContinue } catch {}

            $installedText = ""
            try { $installedText = ((& $target --version 2>&1) | Out-String).Trim() } catch {}
            if ([string]::IsNullOrWhiteSpace($installedText)) {
                Write-Output "LOG:[Provider Update] $displayName provider binary was replaced successfully."
            }
            else {
                $installedLine = (@($installedText -split "`r?`n") | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1)
                Write-Output "LOG:[Provider Update] $displayName updated successfully: $installedLine"
            }

            $Result.Value = [PSCustomObject]@{ ExitCode = 0 }
        }
        catch {
            Write-Output "LOG:[Provider Update] $provider update failed: $($_.Exception.Message)"
            $Result.Value = [PSCustomObject]@{ ExitCode = 1 }
        }
        finally {
            if (-not [string]::IsNullOrWhiteSpace($tmpPath) -and (Test-Path -LiteralPath $tmpPath)) {
                try { Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue } catch {}
            }
        }
    }

    function Invoke-WmtStoreFallbackPage {
        param(
            [string]$PackageName,
            [string]$ActionLabel,
            [string]$Reason,
            [string]$ReasonText,
            [string]$StoreUri = "ms-windows-store://downloadsandupdates",
            [string]$WebUri = "https://apps.microsoft.com/home"
        )

        $fallbackUri = ([string]$StoreUri).Trim()
        $fallbackWebUri = ([string]$WebUri).Trim()
        if ([string]::IsNullOrWhiteSpace($fallbackUri)) { $fallbackUri = "ms-windows-store://downloadsandupdates" }
        if ([string]::IsNullOrWhiteSpace($fallbackWebUri)) { $fallbackWebUri = $fallbackUri }

        $fallbackId = [Guid]::NewGuid().ToString("N")
        $fallbackAckPath = Join-Path $temp "WMT_StoreCLI_$fallbackId.fallback_ack"
        try {
            $payload = [ordered]@{
                FallbackId  = $fallbackId
                AckPath     = $fallbackAckPath
                StoreUri    = $fallbackUri
                WebUri      = $fallbackWebUri
                PackageName = $PackageName
                ActionLabel = $ActionLabel
                Reason      = $Reason
                ReasonText  = $ReasonText
            }
            $json = $payload | ConvertTo-Json -Compress
            $encoded = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($json))
            $fallbackLine = "STORE_FALLBACK:$encoded"
            Write-Output $fallbackLine
        }
        catch {}

        $sentAt = Get-Date
        $ackDeadline = $sentAt.AddSeconds(4)
        $directFallbackAttempted = $false
        while ((Get-Date) -lt $ackDeadline) {
            if (Test-Path $fallbackAckPath) { break }

            $now = Get-Date
            if (-not $directFallbackAttempted -and (New-TimeSpan -Start $sentAt -End $now).TotalMilliseconds -ge 1500) {
                $directFallbackAttempted = $true
                $directOpened = $false
                try {
                    Start-Process -FilePath $fallbackUri
                    $directOpened = $true
                    Write-Output "LOG:[Store] Requested Microsoft Store page directly for $PackageName."
                }
                catch {
                    Write-Output "LOG:[Store] Direct Microsoft Store page launch failed: $($_.Exception.Message)"
                }

                if (-not $directOpened -and $fallbackWebUri -and $fallbackWebUri -ne $fallbackUri) {
                    try {
                        Start-Process -FilePath $fallbackWebUri
                        Write-Output "LOG:[Store] Requested Microsoft Store web page directly for $PackageName."
                    }
                    catch {
                        Write-Output "LOG:[Store] Direct Microsoft Store web page launch failed: $($_.Exception.Message)"
                    }
                }
            }

            Start-Sleep -Milliseconds 200
        }

        try { Remove-Item -Path $fallbackAckPath -Force -ErrorAction SilentlyContinue } catch {}
    }

    function Invoke-WmtStoreAppUpdateScan {
        param([string]$PackageName)

        $displayName = if ([string]::IsNullOrWhiteSpace($PackageName)) { "Microsoft Store apps" } else { $PackageName }
        $scanStarted = $false
        $reasonText = "WMT opened Microsoft Store Updates so Store apps can update while other installers continue."
        try {
            Write-Output "LOG:[Store] Starting Microsoft Store update scan for $displayName..."
            $appManagement = Get-CimInstance -Namespace "Root\cimv2\mdm\dmmap" -ClassName "MDM_EnterpriseModernAppManagement_AppManagement01" -ErrorAction Stop | Select-Object -First 1
            if (-not $appManagement) { throw "Store app-management provider returned no instances." }

            $scanResult = Invoke-CimMethod -InputObject $appManagement -MethodName "UpdateScanMethod" -ErrorAction Stop
            $returnValue = 0
            if ($scanResult -and $scanResult.PSObject.Properties["ReturnValue"]) {
                $returnValue = [int]$scanResult.ReturnValue
            }

            if ($returnValue -eq 0) {
                Write-Output "LOG:[Store] Microsoft Store app update scan started."
                $scanStarted = $true
                $reasonText = "WMT started a Microsoft Store app update scan and opened Microsoft Store Updates."
            }
            else {
                Write-Output "LOG:[Store] Microsoft Store app update scan returned code $returnValue."
                $reasonText = "WMT could not start the direct Store app update scan, so Microsoft Store Updates was opened instead."
            }
        }
        catch {
            Write-Output "LOG:[Store] Microsoft Store app update scan failed: $($_.Exception.Message)"
            $reasonText = "WMT could not start the direct Store app update scan, so Microsoft Store Updates was opened instead."
        }

        Invoke-WmtStoreFallbackPage -PackageName $displayName -ActionLabel "Update" -Reason "UpdateScan" -ReasonText $reasonText -StoreUri "ms-windows-store://downloadsandupdates" -WebUri "https://apps.microsoft.com/home"
        return [PSCustomObject]@{ ExitCode = 0; StoreUpdateScan = $scanStarted; StoreUpdatesDelegated = $true }
    }

    function Invoke-WmtStoreGuiUpdate {
        param(
            [string]$PackageName,
            [int]$TimeoutSeconds = 300,
            [ref]$Result
        )

        $Result.Value = $null
        $displayName = ([string]$PackageName).Trim()
        if ([string]::IsNullOrWhiteSpace($displayName)) {
            $Result.Value = [PSCustomObject]@{ ExitCode = 1; Message = "Package name is blank." }
            return
        }

        try {
            Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop
            Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop
        }
        catch {
            Write-Output "LOG:[Store GUI] UI Automation is unavailable: $($_.Exception.Message)"
            $Result.Value = [PSCustomObject]@{ ExitCode = 1; Message = "UI Automation is unavailable." }
            return
        }

        try { Start-Process "ms-windows-store://downloadsandupdates" -ErrorAction SilentlyContinue } catch {}

        $deadline = (Get-Date).AddSeconds([Math]::Max(30, $TimeoutSeconds))
        $startedAt = Get-Date
        $invoked = $false
        $checkForUpdatesInvoked = $false
        $lastStatus = ""
        $storeWindowMissingSince = $null
        $titleNameCondition = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::NameProperty, $displayName)
        $titleIdCondition = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, "ProductTitle")
        $titleCondition = New-Object System.Windows.Automation.AndCondition($titleNameCondition, $titleIdCondition)
        $actionButtonCondition = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, "ActionButton")
        $checkButtonCondition = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, "CheckForUpdatesButton")
        $root = [System.Windows.Automation.AutomationElement]::RootElement

        while ((Get-Date) -lt $deadline) {
            $storeWindow = @(
                $root.FindAll([System.Windows.Automation.TreeScope]::Children, [System.Windows.Automation.Condition]::TrueCondition) |
                Where-Object { ([string]$_.Current.Name) -eq "Microsoft Store" }
            ) | Select-Object -First 1

            if (-not $storeWindow) {
                if (-not $storeWindowMissingSince) { $storeWindowMissingSince = Get-Date }
                if (((Get-Date) - $storeWindowMissingSince).TotalSeconds -ge 20) {
                    Write-Output "LOG:[Store GUI] Microsoft Store window was unavailable for 20 seconds."
                    $Result.Value = [PSCustomObject]@{ ExitCode = 1; Message = "Microsoft Store window is unavailable." }
                    return
                }
                Start-Sleep -Milliseconds 500
                continue
            }
            $storeWindowMissingSince = $null

            $rows = New-Object System.Collections.Generic.List[object]
            foreach ($title in @($storeWindow.FindAll([System.Windows.Automation.TreeScope]::Descendants, $titleCondition))) {
                try {
                    $row = [System.Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($title)
                    if ($row -and $row.Current.ControlType -eq [System.Windows.Automation.ControlType]::Custom) {
                        [void]$rows.Add($row)
                    }
                }
                catch {}
            }

            $updateRow = @($rows | Where-Object { ([string]$_.Current.Name) -match '(?i),\s*Update available\b' } | Select-Object -First 1)
            $activeRow = @($rows | Where-Object { ([string]$_.Current.Name) -match '(?i),\s*(Downloading|Installing|Pending|Queued|Starting|Acquiring|Processing|Updating|Downloaded)\b' } | Select-Object -First 1)
            $finishedRow = @($rows | Where-Object { ([string]$_.Current.Name) -match '(?i),\s*(Modified moments ago|Updated|Installed)\b' } | Select-Object -First 1)

            if (-not $invoked -and $activeRow.Count -gt 0) {
                $invoked = $true
                Write-Output "LOG:[Store GUI] $displayName is already updating in Microsoft Store."
                Write-Output "LOG:  [store] Progress: 25%"
            }

            if (-not $invoked -and $updateRow.Count -gt 0) {
                try {
                    $actionButton = $updateRow[0].FindFirst([System.Windows.Automation.TreeScope]::Descendants, $actionButtonCondition)
                    if (-not $actionButton -or -not $actionButton.Current.IsEnabled) {
                        throw "The Update button is unavailable."
                    }

                    $invokePattern = $actionButton.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
                    $invokePattern.Invoke()
                    $invoked = $true
                    Write-Output "LOG:[Store GUI] Invoked the Microsoft Store Update button for $displayName."
                    Write-Output "LOG:  [store] Progress: 10%"
                    Start-Sleep -Seconds 1
                    continue
                }
                catch {
                    Write-Output "LOG:[Store GUI] Could not invoke Update for ${displayName}: $($_.Exception.Message)"
                    $Result.Value = [PSCustomObject]@{ ExitCode = 1; Message = $_.Exception.Message }
                    return
                }
            }

            if ($invoked) {
                if ($activeRow.Count -gt 0) {
                    $status = ([string]$activeRow[0].Current.Name).Trim()
                    if ($status -ne $lastStatus) {
                        $lastStatus = $status
                        Write-Output "LOG:[Store GUI] $status"
                        $progress = if ($status -match '(?i)Installing|Processing|Downloaded') { 85 } else { 50 }
                        Write-Output "LOG:  [store] Progress: $progress%"
                    }
                }
                elseif ($updateRow.Count -eq 0 -and ((Get-Date) - $startedAt).TotalSeconds -ge 2) {
                    Write-Output "LOG:  [store] Progress: 100%"
                    $Result.Value = [PSCustomObject]@{ ExitCode = 0; GuiUpdateInvoked = $true; Completed = $true }
                    return
                }
                elseif ($finishedRow.Count -gt 0) {
                    Write-Output "LOG:  [store] Progress: 100%"
                    $Result.Value = [PSCustomObject]@{ ExitCode = 0; GuiUpdateInvoked = $true; Completed = $true }
                    return
                }
            }
            elseif (-not $checkForUpdatesInvoked -and ((Get-Date) - $startedAt).TotalSeconds -ge 2) {
                try {
                    $checkButton = $storeWindow.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $checkButtonCondition)
                    if ($checkButton -and $checkButton.Current.IsEnabled) {
                        $checkPattern = $checkButton.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
                        $checkPattern.Invoke()
                        Write-Output "LOG:[Store GUI] Invoked Check for updates while locating $displayName."
                    }
                }
                catch {
                    Write-Output "LOG:[Store GUI] Check for updates could not be invoked: $($_.Exception.Message)"
                }
                $checkForUpdatesInvoked = $true
            }
            elseif ($checkForUpdatesInvoked -and ((Get-Date) - $startedAt).TotalSeconds -ge 15) {
                Write-Output "LOG:[Store GUI] No available Update button was found for $displayName; it may already be current."
                $Result.Value = [PSCustomObject]@{ ExitCode = 0; AlreadyCurrent = $true; Completed = $true }
                return
            }

            Start-Sleep -Milliseconds 750
        }

        Write-Output "LOG:[Store GUI] Timed out waiting for $displayName to finish updating."
        $Result.Value = [PSCustomObject]@{ ExitCode = 1; TimedOut = $true; Message = "Store GUI update timed out." }
    }

    # steam.exe and its main window stay open after updates, so completion is
    # confirmed through the same per-app manifest fields used by the Steam scan.
    function Get-WmtSteamActionManifestValue {
        param(
            [string]$Text,
            [string]$Key
        )

        if ([string]::IsNullOrWhiteSpace($Text) -or [string]::IsNullOrWhiteSpace($Key)) { return "" }
        $match = [regex]::Match($Text, ('"' + [regex]::Escape($Key) + '"\s+"([^"]*)"'))
        if ($match.Success) { return [string]$match.Groups[1].Value }
        return ""
    }

    function Get-WmtSteamActionManifestNumber {
        param(
            [string]$Text,
            [string]$Key
        )

        $value = Get-WmtSteamActionManifestValue -Text $Text -Key $Key
        $number = [long]0
        if ([long]::TryParse(([string]$value), [ref]$number)) { return $number }
        return [long]0
    }

    function Get-WmtSteamActionManifestState {
        param([string]$ManifestPath)

        if ([string]::IsNullOrWhiteSpace($ManifestPath) -or -not (Test-Path -LiteralPath $ManifestPath -PathType Leaf)) {
            return [PSCustomObject]@{ Readable = $false; ErrorMessage = "Steam app manifest was not found." }
        }

        try {
            $text = Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8 -ErrorAction Stop
            if ([string]::IsNullOrWhiteSpace($text)) { throw "Steam app manifest is empty." }

            $stateFlags = Get-WmtSteamActionManifestNumber -Text $text -Key "StateFlags"
            $bytesToDownload = Get-WmtSteamActionManifestNumber -Text $text -Key "BytesToDownload"
            $bytesDownloaded = Get-WmtSteamActionManifestNumber -Text $text -Key "BytesDownloaded"
            $bytesToStage = Get-WmtSteamActionManifestNumber -Text $text -Key "BytesToStage"
            $bytesStaged = Get-WmtSteamActionManifestNumber -Text $text -Key "BytesStaged"
            $buildId = Get-WmtSteamActionManifestValue -Text $text -Key "buildid"
            $targetBuildId = Get-WmtSteamActionManifestValue -Text $text -Key "TargetBuildID"

            $downloadRemaining = [Math]::Max([long]0, $bytesToDownload - $bytesDownloaded)
            $stageRemaining = [Math]::Max([long]0, $bytesToStage - $bytesStaged)
            $hasTargetBuild = (-not [string]::IsNullOrWhiteSpace($targetBuildId) -and $targetBuildId -ne "0" -and $targetBuildId -ne $buildId)
            $isPending = (
                ($stateFlags -ne 0 -and $stateFlags -ne 4) -or
                $downloadRemaining -gt 0 -or
                $stageRemaining -gt 0 -or
                $hasTargetBuild
            )

            $totalWork = [Math]::Max([long]0, $bytesToDownload) + [Math]::Max([long]0, $bytesToStage)
            $completedWork = [Math]::Min([Math]::Max([long]0, $bytesDownloaded), [Math]::Max([long]0, $bytesToDownload)) +
            [Math]::Min([Math]::Max([long]0, $bytesStaged), [Math]::Max([long]0, $bytesToStage))
            $progress = -1
            if ($totalWork -gt 0) {
                $progress = [int][Math]::Floor(($completedWork * 100.0) / $totalWork)
                if ($isPending -and $progress -ge 100) { $progress = 99 }
            }

            $status = if (-not $isPending) {
                "current"
            }
            elseif ($downloadRemaining -gt 0) {
                "{0:N1} MB download remaining" -f ($downloadRemaining / 1MB)
            }
            elseif ($stageRemaining -gt 0) {
                "{0:N1} MB staging remaining" -f ($stageRemaining / 1MB)
            }
            elseif ($hasTargetBuild) {
                "waiting for target build $targetBuildId"
            }
            else {
                "Steam state $stateFlags"
            }

            return [PSCustomObject]@{
                Readable          = $true
                IsPending         = $isPending
                StateFlags        = $stateFlags
                BuildId           = $buildId
                TargetBuildId     = $targetBuildId
                DownloadRemaining = $downloadRemaining
                StageRemaining    = $stageRemaining
                Progress          = $progress
                Status            = $status
            }
        }
        catch {
            return [PSCustomObject]@{ Readable = $false; ErrorMessage = $_.Exception.Message }
        }
    }

    function Wait-WmtSteamActionCompletion {
        param(
            [string]$ManifestPath,
            [string]$PackageName,
            [int]$TimeoutSeconds = 14400,
            [ref]$Result
        )

        $Result.Value = $null
        if ([string]::IsNullOrWhiteSpace($ManifestPath)) {
            Write-Output "LOG:[Steam] Cannot monitor $PackageName because its app manifest path is unavailable."
            $Result.Value = [PSCustomObject]@{ ExitCode = 2; Message = "Steam app manifest path is unavailable." }
            return
        }

        $deadline = (Get-Date).AddSeconds([Math]::Max(60, $TimeoutSeconds))
        $missingSince = $null
        $stableCompleteReads = 0
        $lastSignature = ""
        $lastProgress = -2
        $lastHeartbeat = Get-Date
        Write-Output "LOG:[Steam] Monitoring the app manifest for $PackageName update completion (timeout: 4 hours)."

        while ((Get-Date) -lt $deadline) {
            $state = Get-WmtSteamActionManifestState -ManifestPath $ManifestPath
            if (-not $state.Readable) {
                if (-not $missingSince) {
                    $missingSince = Get-Date
                    Write-Output "LOG:[Steam] Waiting for the app manifest to become readable for $PackageName."
                }
                elseif (((Get-Date) - $missingSince).TotalSeconds -ge 30) {
                    Write-Output "LOG:[Steam] App manifest remained unavailable for 30 seconds: $($state.ErrorMessage)"
                    $Result.Value = [PSCustomObject]@{ ExitCode = 1; Message = $state.ErrorMessage }
                    return
                }
                Start-Sleep -Seconds 1
                continue
            }

            $missingSince = $null
            $signature = "$($state.StateFlags)|$($state.BuildId)|$($state.TargetBuildId)|$($state.DownloadRemaining)|$($state.StageRemaining)"
            if ($signature -ne $lastSignature) {
                $lastSignature = $signature
                Write-Output "LOG:[Steam] $PackageName status: $($state.Status)."
            }

            if ($state.Progress -ge 0 -and $state.Progress -ne $lastProgress) {
                $lastProgress = $state.Progress
                Write-Output "LOG:  [steam] Progress: $($state.Progress)%"
            }

            if (-not $state.IsPending) {
                $stableCompleteReads++
                if ($stableCompleteReads -ge 3) {
                    Write-Output "LOG:  [steam] Progress: 100%"
                    $Result.Value = [PSCustomObject]@{ ExitCode = 0; Completed = $true; BuildId = $state.BuildId }
                    return
                }
            }
            else {
                $stableCompleteReads = 0
            }

            if (((Get-Date) - $lastHeartbeat).TotalSeconds -ge 30) {
                $lastHeartbeat = Get-Date
                Write-Output "LOG:[Steam] Still waiting for $PackageName to finish in Steam ($($state.Status))."
            }
            Start-Sleep -Seconds 1
        }

        Write-Output "LOG:[Steam] Timed out waiting for $PackageName to finish updating."
        $Result.Value = [PSCustomObject]@{ ExitCode = 1; TimedOut = $true; Message = "Steam update completion monitor timed out." }
    }

    function Close-WmtStoreGui {
        try {
            Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop
            Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop

            $root = [System.Windows.Automation.AutomationElement]::RootElement
            $storeWindow = @(
                $root.FindAll([System.Windows.Automation.TreeScope]::Children, [System.Windows.Automation.Condition]::TrueCondition) |
                Where-Object { ([string]$_.Current.Name) -eq "Microsoft Store" }
            ) | Select-Object -First 1
            if (-not $storeWindow) {
                Write-Output "LOG:[Store GUI] Microsoft Store window is already closed."
                return
            }

            $closeCondition = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, "Close")
            $closeButton = $storeWindow.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $closeCondition)
            if (-not $closeButton -or -not $closeButton.Current.IsEnabled) {
                throw "The Microsoft Store Close button is unavailable."
            }

            $closePattern = $closeButton.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
            $closePattern.Invoke()
            Write-Output "LOG:[Store GUI] Closed Microsoft Store after Store updates completed."
        }
        catch {
            Write-Output "LOG:[Store GUI] Could not close Microsoft Store: $($_.Exception.Message)"
        }
    }

    function Stop-WmtChildProcessTree {
        param([object]$Process)

        if (-not $Process) { return }
        $processId = 0
        try { $processId = [int]$Process.Id } catch {}

        try {
            $Process.Refresh()
            if ($Process.HasExited) { return }
        }
        catch { return }

        $killProc = $null
        try {
            $killInfo = New-Object System.Diagnostics.ProcessStartInfo
            $killInfo.FileName = "taskkill.exe"
            $killInfo.Arguments = "/PID $processId /T /F"
            $killInfo.UseShellExecute = $false
            $killInfo.CreateNoWindow = $true
            $killInfo.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Hidden
            $killProc = [System.Diagnostics.Process]::Start($killInfo)
            if ($killProc) {
                try { [void]$killProc.WaitForExit(5000) } catch {}
            }
        }
        catch {}
        finally {
            try { if ($killProc) { $killProc.Dispose() } } catch {}
        }

        # taskkill can launch successfully yet fail to terminate the target.
        # Verify the original process and force-kill it as a fallback.
        try {
            $Process.Refresh()
            if (-not $Process.HasExited) {
                try { $Process.Kill() } catch {}
                try { [void]$Process.WaitForExit(3000) } catch {}
            }
        }
        catch {
            if ($processId -gt 0) {
                try { Stop-Process -Id $processId -Force -ErrorAction SilentlyContinue } catch {}
            }
        }
    }

    function Get-WmtProcessTreeActivitySignature {
        param(
            [int]$RootProcessId,
            [string]$ProcessNamePattern = "",
            [switch]$ExcludeRootProcess
        )

        try {
            $processes = @(Get-CimInstance Win32_Process -ErrorAction Stop)
            $processIds = New-Object "System.Collections.Generic.HashSet[int]"
            $pendingIds = New-Object "System.Collections.Generic.Queue[int]"
            $pendingIds.Enqueue($RootProcessId)

            while ($pendingIds.Count -gt 0) {
                $currentId = $pendingIds.Dequeue()
                if (-not $processIds.Add($currentId)) { continue }
                foreach ($child in @($processes | Where-Object { [int]$_.ParentProcessId -eq $currentId })) {
                    $pendingIds.Enqueue([int]$child.ProcessId)
                }
            }

            $activityProcesses = @($processes | Where-Object {
                    $processIds.Contains([int]$_.ProcessId) -and
                    (-not $ExcludeRootProcess -or [int]$_.ProcessId -ne $RootProcessId)
                })
            if (-not [string]::IsNullOrWhiteSpace($ProcessNamePattern)) {
                $matchingProcesses = @($activityProcesses | Where-Object { ([string]$_.Name) -match $ProcessNamePattern })
                if ($matchingProcesses.Count -gt 0) { $activityProcesses = $matchingProcesses }
            }

            $activity = @($activityProcesses |
                Sort-Object ProcessId |
                ForEach-Object {
                    "$($_.ProcessId):$($_.KernelModeTime):$($_.UserModeTime):$($_.ReadTransferCount):$($_.WriteTransferCount):$($_.OtherTransferCount)"
                })
            return ($activity -join "|")
        }
        catch {
            return ""
        }
    }

    # Executes headless commands without blocking on a quiet stdout/stderr stream.
    function Invoke-WingetCmd {
        param(
            [string]$Command,
            [int]$TimeoutSeconds = 7200,
            [int]$IdleTimeoutSeconds = 0,
            [string]$ActivityProcessNamePattern = "",
            [string]$CommandLabel = "Command",
            [string]$TranscriptPath = "",
            [switch]$SuppressActiveTranscriptMirror,
            [ref]$Result
        )

        $Result.Value = $null
        if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "COMMAND: $Command"
        }

        $pInfo = New-Object System.Diagnostics.ProcessStartInfo
        $pInfo.FileName = "powershell.exe"
        $pInfo.Arguments = "-NoProfile -ExecutionPolicy Bypass -Command $Command"
        $pInfo.RedirectStandardOutput = $true
        $pInfo.RedirectStandardError = $true
        $pInfo.UseShellExecute = $false
        $pInfo.CreateNoWindow = $true
        $oem = [System.Text.Encoding]::GetEncoding([System.Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage)
        $pInfo.StandardOutputEncoding = $oem
        $pInfo.StandardErrorEncoding = $oem
        $proc = $null
        try {
            $proc = [System.Diagnostics.Process]::Start($pInfo)

        function Write-WmtCommandOutputChunk {
            param(
                [string]$Text,
                [string]$Prefix
            )

            if ([string]::IsNullOrWhiteSpace($Text)) { return }
            $transcriptPrefix = if ($Prefix -eq "!") { "STDERR:" } else { "STDOUT:" }
            foreach ($line in @($Text -split "\r\n|\r|\n")) {
                $trimmed = ([string]$line).Trim()
                if (-not [string]::IsNullOrWhiteSpace($trimmed)) {
                    if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                        Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "$transcriptPrefix $trimmed"
                    }
                    $skipTranscriptMirror = (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) -or [bool]$SuppressActiveTranscriptMirror
                    Write-WmtWorkerOutputItem -Value "LOG:  $Prefix $trimmed" -SkipTranscriptMirror:$skipTranscriptMirror
                }
            }
        }

        # Read raw chunks so progress output that uses carriage returns cannot fill the pipe and deadlock.
        $outBuffer = New-Object char[] 4096
        $errBuffer = New-Object char[] 4096
        $outTask = $proc.StandardOutput.ReadAsync($outBuffer, 0, $outBuffer.Length)
        $errTask = $proc.StandardError.ReadAsync($errBuffer, 0, $errBuffer.Length)
        $startedAt = Get-Date
        $lastHeartbeat = $startedAt
        $timedOut = $false
        $timeoutReason = ""
        $timeoutTreeSignature = ""
        $lastActivityAt = $startedAt
        $lastActivitySignature = ""
        $nextActivityCheck = $startedAt
        while (-not $proc.HasExited) {
            $now = Get-Date
            while ($outTask -and $outTask.IsCompleted) {
                $outCount = 0
                try { $outCount = [int]$outTask.GetAwaiter().GetResult() } catch {}
                if ($outCount -le 0) {
                    $outTask = $null
                    break
                }
                Write-WmtCommandOutputChunk -Text (-join $outBuffer[0..($outCount - 1)]) -Prefix ">"
                $outBuffer = New-Object char[] 4096
                $outTask = $proc.StandardOutput.ReadAsync($outBuffer, 0, $outBuffer.Length)
            }
            while ($errTask -and $errTask.IsCompleted) {
                $errCount = 0
                try { $errCount = [int]$errTask.GetAwaiter().GetResult() } catch {}
                if ($errCount -le 0) {
                    $errTask = $null
                    break
                }
                Write-WmtCommandOutputChunk -Text (-join $errBuffer[0..($errCount - 1)]) -Prefix "!"
                $errBuffer = New-Object char[] 4096
                $errTask = $proc.StandardError.ReadAsync($errBuffer, 0, $errBuffer.Length)
            }
            if ($TimeoutSeconds -gt 0 -and (($now - $startedAt).TotalSeconds -ge $TimeoutSeconds)) {
                $timedOut = $true
                $timeoutReason = "total runtime"
                Write-Output "LOG:$CommandLabel timed out after $TimeoutSeconds seconds. Stopping its process tree."
                $timeoutTreeSignature = Get-WmtProcessTreeActivitySignature -RootProcessId $proc.Id
                Stop-WmtChildProcessTree -Process $proc
                break
            }
            if ($IdleTimeoutSeconds -gt 0 -and $now -ge $nextActivityCheck) {
                $activitySignature = Get-WmtProcessTreeActivitySignature -RootProcessId $proc.Id -ProcessNamePattern $ActivityProcessNamePattern
                if (-not [string]::IsNullOrWhiteSpace($activitySignature)) {
                    if ($activitySignature -ne $lastActivitySignature) {
                        $lastActivitySignature = $activitySignature
                        $lastActivityAt = $now
                    }
                    elseif (($now - $lastActivityAt).TotalSeconds -ge $IdleTimeoutSeconds) {
                        $timedOut = $true
                        $timeoutReason = "no process activity"
                        Write-Output "LOG:$CommandLabel showed no process activity for $IdleTimeoutSeconds seconds. Stopping its process tree."
                        $timeoutTreeSignature = Get-WmtProcessTreeActivitySignature -RootProcessId $proc.Id
                        Stop-WmtChildProcessTree -Process $proc
                        break
                    }
                }
                $nextActivityCheck = $now.AddSeconds(15)
            }
            if (($now - $lastHeartbeat).TotalSeconds -ge 15) {
                Write-Output "LOG:$CommandLabel still running..."
                $lastHeartbeat = $now
            }
            Start-Sleep -Milliseconds 100
        }

        try { [void]$proc.WaitForExit(5000) } catch {}
        try {
            $proc.Refresh()
            if (-not $proc.HasExited) {
                try { $proc.Kill() } catch {}
                try { [void]$proc.WaitForExit(2000) } catch {}
            }
        }
        catch {}

        $terminationFailed = $false
        if ($timedOut) {
            try { $proc.Refresh(); $terminationFailed = -not $proc.HasExited }
            catch { $terminationFailed = $true }
            # If enumeration fails we cannot prove child installers were terminated.
            if ([string]::IsNullOrWhiteSpace($timeoutTreeSignature)) {
                $terminationFailed = $true
            }
            else {
                foreach ($processEntry in @($timeoutTreeSignature -split '\|')) {
                    $treeProcessId = 0
                    if (-not [int]::TryParse(([string]$processEntry -split ':', 2)[0], [ref]$treeProcessId)) { $terminationFailed = $true; continue }
                    try {
                        $survivor = Get-Process -Id $treeProcessId -ErrorAction SilentlyContinue
                        if ($survivor -and -not $survivor.HasExited) { $terminationFailed = $true }
                    }
                    catch { $terminationFailed = $true }
                }
            }
            if ($terminationFailed) {
                Write-Output "LOG:WARNING: $CommandLabel could not confirm termination of every child process; aborting the remaining package batch."
            }
        }

        $drainDeadline = (Get-Date).AddSeconds(5)
        while (($outTask -or $errTask) -and (Get-Date) -lt $drainDeadline) {
            if ($outTask -and $outTask.IsCompleted) {
                $outCount = 0
                try { $outCount = [int]$outTask.GetAwaiter().GetResult() } catch {}
                if ($outCount -le 0) { $outTask = $null }
                else {
                    Write-WmtCommandOutputChunk -Text (-join $outBuffer[0..($outCount - 1)]) -Prefix ">"
                    $outBuffer = New-Object char[] 4096
                    $outTask = $proc.StandardOutput.ReadAsync($outBuffer, 0, $outBuffer.Length)
                }
            }
            if ($errTask -and $errTask.IsCompleted) {
                $errCount = 0
                try { $errCount = [int]$errTask.GetAwaiter().GetResult() } catch {}
                if ($errCount -le 0) { $errTask = $null }
                else {
                    Write-WmtCommandOutputChunk -Text (-join $errBuffer[0..($errCount - 1)]) -Prefix "!"
                    $errBuffer = New-Object char[] 4096
                    $errTask = $proc.StandardError.ReadAsync($errBuffer, 0, $errBuffer.Length)
                }
            }
            if (($outTask -and -not $outTask.IsCompleted) -or ($errTask -and -not $errTask.IsCompleted)) {
                Start-Sleep -Milliseconds 50
            }
        }

        if ($timedOut) {
            if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "EXIT: 124 ($timeoutReason)"
            }
            $Result.Value = [PSCustomObject]@{ ExitCode = 124; TimedOut = $true; TimeoutReason = $timeoutReason; TerminationFailed = $terminationFailed }
            return
        }
        $exitCode = [int]$proc.ExitCode
        if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "EXIT: $exitCode"
        }
        $Result.Value = [PSCustomObject]@{
            ExitCode          = $exitCode
            TimedOut          = $false
            TimeoutReason     = ""
            TerminationFailed = $false
        }
        }
        finally {
            try { if ($proc) { $proc.Dispose() } } catch {}
        }
    }

    # Pip can remain alive indefinitely when launched with ProcessStartInfo from inside a background PowerShell worker.
    # Direct native invocation lets the job host drain pip's output reliably while remaining headless.
    function Invoke-WmtPipDirect {
        param(
            [string]$PythonPath,
            [object[]]$ArgumentList,
            [string]$TranscriptPath = "",
            [int]$TimeoutSeconds = 600
        )

        if ([string]::IsNullOrWhiteSpace($PythonPath)) { $PythonPath = "python.exe" }

        function ConvertTo-WmtNativeArgument {
            param([string]$Value)

            if ($null -eq $Value -or $Value.Length -eq 0) { return '""' }
            if ($Value -notmatch '[\s"]') { return $Value }

            $builder = [System.Text.StringBuilder]::new()
            [void]$builder.Append('"')
            $backslashes = 0
            foreach ($ch in $Value.ToCharArray()) {
                if ($ch -eq [char]92) {
                    $backslashes++
                    continue
                }
                if ($ch -eq [char]34) {
                    for ($i = 0; $i -lt (($backslashes * 2) + 1); $i++) { [void]$builder.Append([char]92) }
                    [void]$builder.Append([char]34)
                    $backslashes = 0
                    continue
                }
                for ($i = 0; $i -lt $backslashes; $i++) { [void]$builder.Append([char]92) }
                $backslashes = 0
                [void]$builder.Append($ch)
            }
            for ($i = 0; $i -lt ($backslashes * 2); $i++) { [void]$builder.Append([char]92) }
            [void]$builder.Append('"')
            return $builder.ToString()
        }

        $nativeArgs = @($ArgumentList | ForEach-Object { ConvertTo-WmtNativeArgument -Value ([string]$_) }) -join " "
        $displayArgs = $nativeArgs
        if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "COMMAND: $PythonPath $displayArgs"
        }

        $proc = $null
        try {
            $pInfo = [System.Diagnostics.ProcessStartInfo]::new()
            $pInfo.FileName = $PythonPath
            $pInfo.Arguments = $nativeArgs
            $pInfo.RedirectStandardOutput = $true
            $pInfo.RedirectStandardError = $true
            $pInfo.UseShellExecute = $false
            $pInfo.CreateNoWindow = $true
            try { $pInfo.StandardOutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch {}
            try { $pInfo.StandardErrorEncoding = [System.Text.UTF8Encoding]::new($false) } catch {}

            $proc = [System.Diagnostics.Process]::Start($pInfo)
            if (-not $proc) { throw "Python/pip process failed to start." }

            $outTask = $proc.StandardOutput.ReadToEndAsync()
            $errTask = $proc.StandardError.ReadToEndAsync()
            $timeoutMs = if ($TimeoutSeconds -gt 0) { [Math]::Min([int]::MaxValue, [int64]$TimeoutSeconds * 1000) } else { [int]::MaxValue }
            $exited = $proc.WaitForExit([int]$timeoutMs)
            $timedOut = -not $exited
            $terminationFailed = $false
            $timeoutReason = ""

            if ($timedOut) {
                $timeoutReason = "Pip exceeded the $TimeoutSeconds-second runtime limit"
                Stop-WmtChildProcessTree -Process $proc
                try { [void]$proc.WaitForExit(5000) } catch {}
                try {
                    $proc.Refresh()
                    if (-not $proc.HasExited) {
                        try { $proc.Kill() } catch {}
                        try { [void]$proc.WaitForExit(3000) } catch {}
                        try { $proc.Refresh() } catch {}
                    }
                    $terminationFailed = -not $proc.HasExited
                }
                catch { $terminationFailed = $true }
            }
            else {
                try { $proc.WaitForExit() } catch {}
            }

            $drainDeadline = (Get-Date).AddSeconds(5)
            while (((-not $outTask.IsCompleted) -or (-not $errTask.IsCompleted)) -and (Get-Date) -lt $drainDeadline) {
                Start-Sleep -Milliseconds 50
            }

            $outputLines = [System.Collections.Generic.List[string]]::new()
            if ($outTask.IsCompleted) {
                try {
                    $stdout = [string]$outTask.GetAwaiter().GetResult()
                    foreach ($line in @($stdout -split "\r?\n")) {
                        if (-not [string]::IsNullOrWhiteSpace($line)) { [void]$outputLines.Add($line) }
                    }
                }
                catch {}
            }
            if ($errTask.IsCompleted) {
                try {
                    $stderr = [string]$errTask.GetAwaiter().GetResult()
                    foreach ($line in @($stderr -split "\r?\n")) {
                        if (-not [string]::IsNullOrWhiteSpace($line)) { [void]$outputLines.Add($line) }
                    }
                }
                catch {}
            }

            if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                foreach ($outputLine in @($outputLines)) {
                    Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text ("OUTPUT: " + [string]$outputLine)
                }
            }

            if ($timedOut) {
                if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                    Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "EXIT: timed out ($timeoutReason)"
                }
                return [PSCustomObject]@{
                    ExitCode          = 124
                    OutputLines       = @($outputLines)
                    TimedOut          = $true
                    TimeoutReason     = $timeoutReason
                    TerminationFailed = $terminationFailed
                }
            }

            $normalizedExit = [int]$proc.ExitCode
            if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "EXIT: $normalizedExit"
            }
            return [PSCustomObject]@{
                ExitCode          = $normalizedExit
                OutputLines       = @($outputLines)
                TimedOut          = $false
                TimeoutReason     = ""
                TerminationFailed = $false
            }
        }
        catch {
            if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text ("ERROR: " + $_.Exception.Message)
                Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "EXIT: 1"
            }
            return [PSCustomObject]@{
                ExitCode          = 1
                OutputLines       = @($_.Exception.Message)
                TimedOut          = $false
                TimeoutReason     = ""
                TerminationFailed = $false
            }
        }
        finally {
            try { if ($proc) { $proc.Dispose() } } catch {}
        }
    }

    function Invoke-WingetLive {
        param(
            [string]$ArgsLine,
            [int]$TimeoutSeconds = 7200,
            [int]$IdleTimeoutSeconds = 900,
            [string]$TranscriptPath = ""
        )

        if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "COMMAND: winget $ArgsLine"
        }

        $pInfo = New-Object System.Diagnostics.ProcessStartInfo
        $pInfo.FileName = "winget"
        $pInfo.Arguments = $ArgsLine
        $pInfo.RedirectStandardOutput = $true
        $pInfo.RedirectStandardError = $true
        $pInfo.UseShellExecute = $false
        $pInfo.CreateNoWindow = $true
        $pInfo.StandardOutputEncoding = [System.Text.UTF8Encoding]::new($false)
        $pInfo.StandardErrorEncoding = [System.Text.UTF8Encoding]::new($false)
        $proc = $null
        try {
            $proc = [System.Diagnostics.Process]::Start($pInfo)

        $state = [PSCustomObject]@{ LastLine = ""; LastPct = -1; MeaningfulActivity = $false }
        function Write-WmtWingetLiveLine {
            param(
                [string]$Line,
                [bool]$IsError,
                [object]$State
            )

            $trimmed = ([string]$Line).Trim()
            $State.MeaningfulActivity = $false
            if ([string]::IsNullOrWhiteSpace($trimmed)) { return }
            if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                $transcriptPrefix = if ($IsError) { "STDERR:" } else { "STDOUT:" }
                Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "$transcriptPrefix $trimmed"
            }
            if ($trimmed -match '^[-\\|/]$') { return }
            $State.MeaningfulActivity = $true
            if ($trimmed -match "(\d+)%") {
                $pct = [int]$matches[1]
                if ($pct -ne $State.LastPct) {
                    $State.LastPct = $pct
                    Write-WmtWorkerOutputItem -Value "LOG:  [winget] Progress: $pct%" -SkipTranscriptMirror:(-not [string]::IsNullOrWhiteSpace($TranscriptPath))
                }
                return
            }
            if ($trimmed -ne $State.LastLine) {
                $State.LastLine = $trimmed

                # When a detailed transcript is enabled, keep the Activity box
                # focused on actionable status instead of mirroring winget help,
                # banners, option lists, and other verbose CLI chatter.
                $showInActivity = [string]::IsNullOrWhiteSpace($TranscriptPath) -or $IsError -or
                    ($trimmed -match '(?i)(error|failed|failure|not recognized|not found|no installed package|no package found|successfully|cancelled|canceled|reboot|required|requires|resources.+in use|another installation|hash mismatch)')
                if ($showInActivity) {
                    $prefix = if ($IsError) { "!" } else { ">" }
                    Write-WmtWorkerOutputItem -Value "LOG:  $prefix $trimmed" -SkipTranscriptMirror:(-not [string]::IsNullOrWhiteSpace($TranscriptPath))
                }
            }
        }

        $outTask = $proc.StandardOutput.ReadLineAsync()
        $errTask = $proc.StandardError.ReadLineAsync()
        $startedAt = Get-Date
        $lastBeat = $startedAt
        $lastActivityAt = $startedAt
        $lastActivitySignature = ""
        $nextActivityCheck = $startedAt
        $timedOut = $false
        $timeoutReason = ""

        while (-not $proc.HasExited) {
            $now = Get-Date
            while ($outTask -and $outTask.IsCompleted) {
                $line = $null
                try { $line = $outTask.GetAwaiter().GetResult() } catch {}
                if ($null -eq $line) {
                    $outTask = $null
                    break
                }
                Write-WmtWingetLiveLine -Line $line -IsError:$false -State $state
                if ($state.MeaningfulActivity) { $lastActivityAt = $now }
                $outTask = $proc.StandardOutput.ReadLineAsync()
            }
            while ($errTask -and $errTask.IsCompleted) {
                $line = $null
                try { $line = $errTask.GetAwaiter().GetResult() } catch {}
                if ($null -eq $line) {
                    $errTask = $null
                    break
                }
                Write-WmtWingetLiveLine -Line $line -IsError:$true -State $state
                if ($state.MeaningfulActivity) { $lastActivityAt = $now }
                $errTask = $proc.StandardError.ReadLineAsync()
            }

            if ($TimeoutSeconds -gt 0 -and (($now - $startedAt).TotalSeconds -ge $TimeoutSeconds)) {
                $timedOut = $true
                $timeoutReason = "Winget exceeded the $TimeoutSeconds-second runtime limit"
                Write-Output "LOG:$timeoutReason. Stopping its process tree."
                Stop-WmtChildProcessTree -Process $proc
                break
            }
            if ($IdleTimeoutSeconds -gt 0 -and $now -ge $nextActivityCheck) {
                $activitySignature = Get-WmtProcessTreeActivitySignature -RootProcessId $proc.Id -ExcludeRootProcess
                if (-not [string]::IsNullOrWhiteSpace($activitySignature) -and $activitySignature -ne $lastActivitySignature) {
                    $lastActivitySignature = $activitySignature
                    $lastActivityAt = $now
                }
                elseif (($now - $lastActivityAt).TotalSeconds -ge $IdleTimeoutSeconds) {
                    $timedOut = $true
                    $timeoutReason = "Winget showed no output or process activity for $IdleTimeoutSeconds seconds"
                    Write-Output "LOG:$timeoutReason. Stopping its process tree."
                    Stop-WmtChildProcessTree -Process $proc
                    break
                }
                $nextActivityCheck = $now.AddSeconds(15)
            }
            if (($now - $lastBeat).TotalSeconds -ge 15) {
                Write-Output "LOG:  [winget] still running..."
                $lastBeat = $now
            }
            Start-Sleep -Milliseconds 100
        }

        try { [void]$proc.WaitForExit(5000) } catch {}
        $terminationFailed = $false
        if ($timedOut) {
            try {
                $proc.Refresh()
                if (-not $proc.HasExited) {
                    try { $proc.Kill() } catch {}
                    try { [void]$proc.WaitForExit(3000) } catch {}
                    try { $proc.Refresh() } catch {}
                }
                $terminationFailed = -not $proc.HasExited
            }
            catch {
                $terminationFailed = $true
            }
            if ($terminationFailed) {
                Write-Output "LOG:WARNING: Winget still appears to be running after the timeout termination attempt."
            }
        }
        $drainDeadline = (Get-Date).AddSeconds(5)
        while (($outTask -or $errTask) -and (Get-Date) -lt $drainDeadline) {
            if ($outTask -and $outTask.IsCompleted) {
                $line = $null
                try { $line = $outTask.GetAwaiter().GetResult() } catch {}
                if ($null -eq $line) { $outTask = $null }
                else {
                    Write-WmtWingetLiveLine -Line $line -IsError:$false -State $state
                    $outTask = $proc.StandardOutput.ReadLineAsync()
                }
            }
            if ($errTask -and $errTask.IsCompleted) {
                $line = $null
                try { $line = $errTask.GetAwaiter().GetResult() } catch {}
                if ($null -eq $line) { $errTask = $null }
                else {
                    Write-WmtWingetLiveLine -Line $line -IsError:$true -State $state
                    $errTask = $proc.StandardError.ReadLineAsync()
                }
            }
            if (($outTask -and -not $outTask.IsCompleted) -or ($errTask -and -not $errTask.IsCompleted)) {
                Start-Sleep -Milliseconds 50
            }
        }

        if ($timedOut) {
            if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
                Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "EXIT: timed out ($timeoutReason)"
            }
            return [PSCustomObject]@{
                ExitCode          = 124
                TimedOut          = $true
                TimeoutReason     = $timeoutReason
                TerminationFailed = $terminationFailed
            }
        }
        $exitCode = [int]$proc.ExitCode
        if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            Add-WmtPackageTranscriptLine -Path $TranscriptPath -Text "EXIT: $exitCode"
        }
        return [PSCustomObject]@{
            ExitCode          = $exitCode
            TimedOut          = $false
            TimeoutReason     = ""
            TerminationFailed = $false
        }
        }
        finally {
            try { if ($proc) { $proc.Dispose() } } catch {}
        }
    }

    function Invoke-VisibleCmd {
        param(
            [string]$command,
            [string]$title,
            [int]$HoldSeconds = 0,
            [int]$TimeoutSeconds = 7200,
            [string]$TranscriptPath = ""
        )

        if (-not [string]::IsNullOrWhiteSpace($TranscriptPath)) {
            $command = ConvertTo-WmtTranscriptCommand -Command $command -TranscriptPath $TranscriptPath
        }
        if ([string]::IsNullOrWhiteSpace($title)) { $title = "WMT Package Update" }
        $safeTitle = ((($title -replace '"', '') -replace '[\r\n]', ' ') -replace '[&|<>^%!]', ' ').Trim()
        if ($HoldSeconds -gt 0) {
            $cmdLine = "/v:on /c title $safeTitle && $command & set WMT_EXIT=!ERRORLEVEL! & echo. & echo Exit code: !WMT_EXIT! & timeout /t $HoldSeconds /nobreak >nul & exit /b !WMT_EXIT!"
        }
        else {
            $cmdLine = "/c title $safeTitle && $command"
        }

        $proc = $null
        try {
            $proc = Start-Process -FilePath "cmd.exe" -ArgumentList $cmdLine -PassThru -WindowStyle Normal
            $startedAt = Get-Date
            $lastHeartbeat = $startedAt
            while (-not $proc.HasExited) {
                $now = Get-Date
                if ($TimeoutSeconds -gt 0 -and ($now - $startedAt).TotalSeconds -ge $TimeoutSeconds) {
                    Write-Output "LOG:Visible installer exceeded the $TimeoutSeconds-second runtime limit. Stopping its process tree."
                    Stop-WmtChildProcessTree -Process $proc
                    return [PSCustomObject]@{ ExitCode = 124; TimedOut = $true; TimeoutReason = "visible installer runtime limit" }
                }
                if (($now - $lastHeartbeat).TotalSeconds -ge 30) {
                    Write-Output "LOG:Visible installer still running..."
                    $lastHeartbeat = $now
                }
                Start-Sleep -Milliseconds 500
            }

            $exitCode = [int]$proc.ExitCode
            return [PSCustomObject]@{
                ExitCode = $exitCode
                TimedOut = $false
            }
        }
        finally {
            try { if ($proc) { $proc.Dispose() } } catch {}
        }
    }

    function Invoke-WmtUserModeRetry {
        param(
            [string]$Command,
            [string]$ActionLabel,
            [string]$PackageName,
            [string]$TempPath,
            [int]$TimeoutSeconds = 14400,
            [string]$TranscriptPath = ""
        )

        $rand = [Guid]::NewGuid().ToString("N")
        $batchPath = Join-Path $TempPath "WMT_UserRetry_$rand.cmd"
        $resultPath = Join-Path $TempPath "WMT_UserRetry_$rand.exit"
        $batchLeaf = Split-Path -Leaf $batchPath
        $safeTitle = ((("$ActionLabel $PackageName (User Mode)" -replace '"', '') -replace '[\r\n]', ' ') -replace '[&|<>^%!]', ' ').Trim()
        if ([string]::IsNullOrWhiteSpace($safeTitle)) { $safeTitle = "WMT User Mode Retry" }
        $safePackageName = (([string]$PackageName -replace '[\r\n]', ' ') -replace '[&|<>^%!]', ' ').Trim()
        if ([string]::IsNullOrWhiteSpace($safePackageName)) { $safePackageName = "package" }
        $effectiveCommand = if ([string]::IsNullOrWhiteSpace($TranscriptPath)) { $Command } else { ConvertTo-WmtTranscriptCommand -Command $Command -TranscriptPath $TranscriptPath }

        $batchContent = @"
@echo off
setlocal
title $safeTitle
echo WMT-GUI: Re-launching $safePackageName in user mode...
echo.
echo If an installer window appears, please click through it.
echo.
$effectiveCommand
set "WMT_EXIT=%ERRORLEVEL%"
> "$resultPath" echo %WMT_EXIT%
echo.
echo Done. Exit code: %WMT_EXIT%
exit /b %WMT_EXIT%
"@

        try {
            Set-Content -LiteralPath $batchPath -Value $batchContent -Encoding Ascii -Force
            Start-Process "explorer.exe" -ArgumentList "`"$batchPath`""
        }
        catch {
            try { Remove-Item -LiteralPath $batchPath, $resultPath -Force -ErrorAction SilentlyContinue } catch {}
            return [PSCustomObject]@{ ExitCode = 1; LaunchFailed = $true; TimedOut = $false; Message = $_.Exception.Message }
        }

        $startedAt = Get-Date
        $launchDeadline = $startedAt.AddSeconds(15)
        $deadline = $startedAt.AddSeconds([Math]::Max(60, $TimeoutSeconds))
        $lastHeartbeat = $startedAt
        $wrapperSeen = $false
        $wrapperProcessId = 0
        $wrapperProcess = $null
        $timedOut = $false

        while (-not (Test-Path -LiteralPath $resultPath -PathType Leaf)) {
            if ($wrapperSeen) {
                try {
                    $wrapperProcess.Refresh()
                    if ($wrapperProcess.HasExited) { break }
                }
                catch { break }
            }
            else {
                $wrapperInfo = $null
                try {
                    $wrapperInfo = Get-CimInstance Win32_Process -Filter "Name = 'cmd.exe'" -ErrorAction SilentlyContinue |
                    Where-Object { ([string]$_.CommandLine) -like "*$batchLeaf*" } |
                    Select-Object -First 1
                }
                catch {}

                if ($wrapperInfo) {
                    $wrapperProcessId = [int]$wrapperInfo.ProcessId
                    try { $wrapperProcess = Get-Process -Id $wrapperProcessId -ErrorAction Stop } catch { $wrapperProcess = $null }
                    if ($wrapperProcess) { $wrapperSeen = $true }
                }
                elseif ((Get-Date) -ge $launchDeadline) {
                    break
                }
            }

            $now = Get-Date
            if ($now -ge $deadline) {
                $timedOut = $true
                try { if ($wrapperProcess) { Stop-WmtChildProcessTree -Process $wrapperProcess } } catch {}
                break
            }
            if (($now - $lastHeartbeat).TotalSeconds -ge 30) {
                Write-Output "LOG:User-mode retry for $PackageName still running..."
                $lastHeartbeat = $now
            }
            Start-Sleep -Milliseconds 500
        }

        $exitCode = 1
        $resultCaptured = $false
        if (Test-Path -LiteralPath $resultPath -PathType Leaf) {
            try {
                $resultText = (Get-Content -LiteralPath $resultPath -Raw -ErrorAction Stop).Trim()
                $parsedExitCode = 1
                if ([int]::TryParse($resultText, [ref]$parsedExitCode)) {
                    $exitCode = $parsedExitCode
                    $resultCaptured = $true
                }
                else {
                    $unsignedExitCode = [uint32]0
                    if ([uint32]::TryParse($resultText, [ref]$unsignedExitCode)) {
                        $exitCode = [BitConverter]::ToInt32([BitConverter]::GetBytes($unsignedExitCode), 0)
                        $resultCaptured = $true
                    }
                }
            }
            catch {}
        }

        try { Remove-Item -LiteralPath $batchPath, $resultPath -Force -ErrorAction SilentlyContinue } catch {}
        return [PSCustomObject]@{
            ExitCode       = $exitCode
            LaunchFailed   = (-not $wrapperSeen -and -not $resultCaptured)
            TimedOut       = $timedOut
            ResultCaptured = $resultCaptured
        }
    }

    function Invoke-StoreCliInteractive {
        param(
            [string[]]$ArgumentList,
            [string]$PackageName,
            [string]$TempPath,
            [string]$ActionLabel = "Update",
            [string]$StoreFallbackUri = "",
            [string]$StoreFallbackWebUri = "",
            [string]$TranscriptPath = "",
            [bool]$Headless = $false
        )

        $cmdProc = $null
        $sendKeysProc = $null
        $rand = [Guid]::NewGuid().ToString("N")
        $batPath = Join-Path $TempPath "WMT_StoreCLI_$rand.cmd"
        $resultPath = Join-Path $TempPath "WMT_StoreCLI_$rand.exit"
        $statusPath = Join-Path $TempPath "WMT_StoreCLI_$rand.status"
        $resourcesInUsePath = Join-Path $TempPath "WMT_StoreCLI_$rand.resources"
        $screenPath = Join-Path $TempPath "WMT_StoreCLI_$rand.screen"
        $transcriptPath = ([string]$TranscriptPath).Trim()
        $temporaryTranscriptPath = ""
        if ([string]::IsNullOrWhiteSpace($transcriptPath)) {
            $transcriptPath = Join-Path $TempPath "WMT_StoreCLI_$rand.transcript"
            $temporaryTranscriptPath = $transcriptPath
        }
        $fallbackAckPath = Join-Path $TempPath "WMT_StoreCLI_$rand.fallback_ack"
        $runnerPath = Join-Path $TempPath "WMT_StoreCLI_$rand.run.ps1"
        $sendKeysPath = Join-Path $TempPath "WMT_StoreCLI_$rand.ps1"
        $sendKeysProc = $null
        $safeTitle = (((($PackageName -replace '"', '') -replace '[\r\n]', ' ') -replace '[&|<>^%!]', ' ')).Trim()
        if ([string]::IsNullOrWhiteSpace($safeTitle)) { $safeTitle = "Microsoft Store App" }
        $windowTitle = "WMT Store CLI - $safeTitle"
        $displayAction = if ($ActionLabel -eq "Install") { "Installing" } else { "Updating" }

        function Get-WmtStoreCliExitResult {
            param(
                [string]$ResultPath,
                [object]$Process
            )

            if ($ResultPath -and (Test-Path $ResultPath)) {
                $exitText = (Get-Content -Path $ResultPath -Raw -ErrorAction SilentlyContinue).Trim()
                $exitHexMatch = [regex]::Match($exitText, '(?i)0x[0-9a-f]{8}')
                if ($exitHexMatch.Success) {
                    $exitCodeUInt = [Convert]::ToUInt32($exitHexMatch.Value.Substring(2), 16)
                    $exitCode = [BitConverter]::ToInt32([BitConverter]::GetBytes($exitCodeUInt), 0)
                    return [PSCustomObject]@{ Found = $true; ExitCode = $exitCode }
                }
                $exitMatch = [regex]::Match($exitText, '-?\d+')
                $exitCode = 1
                if ($exitMatch.Success -and [int]::TryParse($exitMatch.Value, [ref]$exitCode)) {
                    return [PSCustomObject]@{ Found = $true; ExitCode = $exitCode }
                }
                $exitCodeUInt = [uint32]0
                if ($exitMatch.Success -and [uint32]::TryParse($exitMatch.Value, [ref]$exitCodeUInt)) {
                    $exitCode = [BitConverter]::ToInt32([BitConverter]::GetBytes($exitCodeUInt), 0)
                    return [PSCustomObject]@{ Found = $true; ExitCode = $exitCode }
                }
                return [PSCustomObject]@{ Found = $true; ExitCode = 1 }
            }

            if ($Process -and $Process.HasExited) {
                $exitCode = 1
                try { $exitCode = [int]$Process.ExitCode } catch {}
                return [PSCustomObject]@{ Found = $true; ExitCode = $exitCode }
            }

            return [PSCustomObject]@{ Found = $false; ExitCode = 1 }
        }

        function Clear-WmtStoreCliTempFiles {
            param([string[]]$Paths)

            $pending = @($Paths | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -Unique)
            for ($attempt = 0; $attempt -lt 4 -and $pending.Count -gt 0; $attempt++) {
                foreach ($path in @($pending)) {
                    try { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue } catch {}
                }

                $pending = @($pending | Where-Object {
                        try { Test-Path -LiteralPath $_ } catch { $false }
                    })
                if ($pending.Count -gt 0 -and $attempt -lt 3) {
                    Start-Sleep -Milliseconds (100 * ($attempt + 1))
                }
            }
        }

        function Stop-WmtStoreCliProcessTree {
            param(
                [object]$Process,
                [object]$HelperProcess
            )

            if ($Process) {
                try {
                    if (-not $Process.HasExited) {
                        & "$env:SystemRoot\System32\taskkill.exe" /PID $Process.Id /T /F 2>$null | Out-Null
                        try { [void]$Process.WaitForExit(2000) } catch {}
                    }
                }
                catch {
                    try { Stop-Process -Id $Process.Id -Force -ErrorAction SilentlyContinue } catch {}
                }
            }

            if ($HelperProcess) {
                try {
                    if (-not $HelperProcess.HasExited) {
                        Stop-Process -Id $HelperProcess.Id -Force -ErrorAction SilentlyContinue
                        try { [void]$HelperProcess.WaitForExit(1000) } catch {}
                    }
                }
                catch {}
            }
        }

        function Show-WmtStoreCliWindow {
            param([object]$Process)

            if (-not $Process) { return }
            try {
                if (-not ('WmtStoreCliWindow' -as [type])) {
                    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;

public static class WmtStoreCliWindow {
[DllImport("user32.dll")]
public static extern bool SetForegroundWindow(IntPtr hWnd);

[DllImport("user32.dll")]
public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
}
"@
                }

                $handle = [IntPtr]::Zero
                for ($i = 0; $i -lt 10; $i++) {
                    try { $Process.Refresh() } catch {}
                    try { $handle = $Process.MainWindowHandle } catch { $handle = [IntPtr]::Zero }
                    if ($handle -ne [IntPtr]::Zero) { break }
                    Start-Sleep -Milliseconds 100
                }
                if ($handle -ne [IntPtr]::Zero) {
                    [void][WmtStoreCliWindow]::ShowWindowAsync($handle, 9)
                    [void][WmtStoreCliWindow]::SetForegroundWindow($handle)
                }
            }
            catch {}
        }

        function Test-WmtStoreCliResourcesInUseText {
            param([string]$Text)

            return (([string]$Text) -match '(?is)(0x80073d02|resources\s+(?:it\s+)?modifies\s+are\s+currently\s+in\s+use|resources[\s\S]{0,240}currently\s+in\s+use)')
        }

        function Invoke-WmtStoreCliFallback {
            param(
                [string]$Reason,
                [string]$ReasonText,
                [string]$StoreUri,
                [string]$WebUri
            )

            $fallbackUri = ([string]$StoreUri).Trim()
            $fallbackWebUri = ([string]$WebUri).Trim()
            if ([string]::IsNullOrWhiteSpace($fallbackUri)) { $fallbackUri = "ms-windows-store://home" }
            if ([string]::IsNullOrWhiteSpace($fallbackWebUri)) { $fallbackWebUri = $fallbackUri }

            try {
                $payload = [ordered]@{
                    FallbackId  = $rand
                    AckPath     = $fallbackAckPath
                    StoreUri    = $fallbackUri
                    WebUri      = $fallbackWebUri
                    PackageName = $PackageName
                    ActionLabel = $ActionLabel
                    Reason      = $Reason
                    ReasonText  = $ReasonText
                }
                $json = $payload | ConvertTo-Json -Compress
                $encoded = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($json))
                $fallbackLine = "STORE_FALLBACK:$encoded"
                Write-Output $fallbackLine
            }
            catch {}

            $sentAt = Get-Date
            $ackDeadline = $sentAt.AddSeconds(6)
            $directFallbackAttempted = $false
            while ((Get-Date) -lt $ackDeadline) {
                if (Test-Path $fallbackAckPath) { break }

                $now = Get-Date
                if (-not $directFallbackAttempted -and (New-TimeSpan -Start $sentAt -End $now).TotalMilliseconds -ge 1500) {
                    $directFallbackAttempted = $true
                    $directOpened = $false
                    try {
                        Start-Process -FilePath $fallbackUri
                        $directOpened = $true
                        Write-Output "LOG:[Store CLI] Requested Microsoft Store fallback page directly for $PackageName."
                    }
                    catch {
                        Write-Output "LOG:[Store CLI] Direct Microsoft Store fallback launch failed: $($_.Exception.Message)"
                    }

                    if (-not $directOpened -and $fallbackWebUri -and $fallbackWebUri -ne $fallbackUri) {
                        try {
                            Start-Process -FilePath $fallbackWebUri
                            Write-Output "LOG:[Store CLI] Requested Microsoft Store web fallback page directly for $PackageName."
                        }
                        catch {
                            Write-Output "LOG:[Store CLI] Direct Microsoft Store web fallback launch failed: $($_.Exception.Message)"
                        }
                    }
                }

                Start-Sleep -Milliseconds 200
            }

            return [PSCustomObject]@{
                StoreUri = $fallbackUri
                WebUri   = $fallbackWebUri
                Reason   = $Reason
                Acked    = (Test-Path $fallbackAckPath)
            }
        }

        $sendKeysContent = @'
param(
[int]$TargetPid,
[string]$PackageName,
[string]$StatusPath,
[string]$ResourcesInUsePath,
[string]$ScreenPath
)

Add-Type -TypeDefinition @"
using System;
using System.Collections.Generic;
using System.Text;
using System.Runtime.InteropServices;

public static class WmtConsoleInput {
private const int STD_INPUT_HANDLE = -10;
private const int STD_OUTPUT_HANDLE = -11;
private const ushort KEY_EVENT = 0x0001;
private const ushort VK_DOWN = 0x28;
private const ushort VK_RETURN = 0x0D;
private const ushort VK_Y = 0x59;

[DllImport("kernel32.dll", SetLastError = true)]
private static extern bool FreeConsole();

[DllImport("kernel32.dll", SetLastError = true)]
private static extern bool AttachConsole(uint dwProcessId);

[DllImport("kernel32.dll", SetLastError = true)]
private static extern IntPtr GetStdHandle(int nStdHandle);

[DllImport("kernel32.dll", SetLastError = true)]
private static extern bool WriteConsoleInput(IntPtr hConsoleInput, INPUT_RECORD[] lpBuffer, uint nLength, out uint lpNumberOfEventsWritten);

[DllImport("kernel32.dll", SetLastError = true)]
private static extern bool GetConsoleScreenBufferInfo(IntPtr hConsoleOutput, out CONSOLE_SCREEN_BUFFER_INFO lpConsoleScreenBufferInfo);

[DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
private static extern bool ReadConsoleOutputCharacter(IntPtr hConsoleOutput, StringBuilder lpCharacter, uint nLength, COORD dwReadCoord, out uint lpNumberOfCharsRead);

[StructLayout(LayoutKind.Sequential)]
private struct COORD {
    public short X;
    public short Y;
    public COORD(short x, short y) { X = x; Y = y; }
}

[StructLayout(LayoutKind.Sequential)]
private struct SMALL_RECT {
    public short Left;
    public short Top;
    public short Right;
    public short Bottom;
}

[StructLayout(LayoutKind.Sequential)]
private struct CONSOLE_SCREEN_BUFFER_INFO {
    public COORD dwSize;
    public COORD dwCursorPosition;
    public ushort wAttributes;
    public SMALL_RECT srWindow;
    public COORD dwMaximumWindowSize;
}

[StructLayout(LayoutKind.Explicit, CharSet = CharSet.Unicode)]
private struct INPUT_RECORD {
    [FieldOffset(0)] public ushort EventType;
    [FieldOffset(4)] public KEY_EVENT_RECORD KeyEvent;
}

[StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
private struct KEY_EVENT_RECORD {
    [MarshalAs(UnmanagedType.Bool)] public bool bKeyDown;
    public ushort wRepeatCount;
    public ushort wVirtualKeyCode;
    public ushort wVirtualScanCode;
    public char UnicodeChar;
    public uint dwControlKeyState;
}

private static INPUT_RECORD Key(char ch, ushort vk, bool down) {
    INPUT_RECORD record = new INPUT_RECORD();
    record.EventType = KEY_EVENT;
    record.KeyEvent.bKeyDown = down;
    record.KeyEvent.wRepeatCount = 1;
    record.KeyEvent.wVirtualKeyCode = vk;
    record.KeyEvent.wVirtualScanCode = 0;
    record.KeyEvent.UnicodeChar = ch;
    record.KeyEvent.dwControlKeyState = 0;
    return record;
}

private static bool Attach(uint pid) {
    FreeConsole();
    return AttachConsole(pid);
}

private static bool WriteInput(uint pid, INPUT_RECORD[] records) {
    if (!Attach(pid)) { return false; }
    IntPtr input = GetStdHandle(STD_INPUT_HANDLE);
    if (input == IntPtr.Zero || input == new IntPtr(-1)) { return false; }
    uint written = 0;
    return WriteConsoleInput(input, records, (uint)records.Length, out written);
}

public static bool SendYes(uint pid) {
    INPUT_RECORD[] records = new INPUT_RECORD[] {
        Key('y', VK_Y, true),
        Key('y', VK_Y, false),
        Key('\r', VK_RETURN, true),
        Key('\r', VK_RETURN, false)
    };
    return WriteInput(pid, records);
}

public static bool SendMenuSelection(uint pid, int downCount) {
    if (downCount < 0) { downCount = 0; }
    List<INPUT_RECORD> records = new List<INPUT_RECORD>();
    for (int i = 0; i < downCount; i++) {
        records.Add(Key('\0', VK_DOWN, true));
        records.Add(Key('\0', VK_DOWN, false));
    }
    records.Add(Key('\r', VK_RETURN, true));
    records.Add(Key('\r', VK_RETURN, false));
    return WriteInput(pid, records.ToArray());
}

public static string ReadScreen(uint pid) {
    if (!Attach(pid)) { return ""; }
    IntPtr output = GetStdHandle(STD_OUTPUT_HANDLE);
    if (output == IntPtr.Zero || output == new IntPtr(-1)) { return ""; }

    CONSOLE_SCREEN_BUFFER_INFO info;
    if (!GetConsoleScreenBufferInfo(output, out info)) { return ""; }

    int width = Math.Max(1, (int)info.dwSize.X);
    int height = Math.Max(1, (int)info.dwSize.Y);
    int length = Math.Min(width * height, 200000);
    StringBuilder raw = new StringBuilder(new string(' ', length));
    uint read = 0;
    if (!ReadConsoleOutputCharacter(output, raw, (uint)length, new COORD(0, 0), out read)) { return ""; }

    string text = raw.ToString();
    StringBuilder lines = new StringBuilder(text.Length + height);
    for (int i = 0; i < text.Length; i += width) {
        int count = Math.Min(width, text.Length - i);
        lines.AppendLine(text.Substring(i, count).TrimEnd());
    }
    return lines.ToString();
}
}
"@

function Get-WmtStoreCliNameKey {
param([string]$Value)

$text = ([string]$Value).ToLowerInvariant().Trim()
$text = $text -replace '^\s*(microsoft|xbox)\s+', ''
$text = $text -replace '\s*\((microsoft\s+store\s+edition|store\s+edition)\)\s*$', ''
return ($text -replace '[^a-z0-9]+', '')
}

function Get-WmtStoreCliMenuOptions {
param([string]$ScreenText)

$clean = ([string]$ScreenText) -replace "`0", ""
$lines = $clean -split "`r?`n"
$start = -1
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match '(?i)select a product') { $start = $i }
}
if ($start -lt 0) { return @() }

$options = New-Object System.Collections.Generic.List[object]
for ($i = $start + 1; $i -lt $lines.Count; $i++) {
    $line = ([string]$lines[$i]).TrimEnd()
    if ($line -match '(?i)would you like|ready to|download|install|update available') { break }
    if ($line -notmatch '^\s*>?\s*(.+?)\s*$') { continue }

    $candidate = $matches[1].Trim()
    if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
    if ($candidate -match '(?i)^(publisher:|do not select|select a product|skip$)') { continue }

    $next = if (($i + 1) -lt $lines.Count) { ([string]$lines[$i + 1]).Trim() } else { "" }
    if ($next -notmatch '(?i)^publisher:\s*') { continue }

    [void]$options.Add([PSCustomObject]@{
            Index     = $options.Count
            Name      = $candidate
            Publisher = ($next -replace '(?i)^publisher:\s*', '').Trim()
        })
}

return $options.ToArray()
}

$targetKey = Get-WmtStoreCliNameKey $PackageName
$menuSelected = $false
$yesSent = $false
$resourcesInUseSent = $false
$deadline = (Get-Date).AddSeconds(90)

function Set-WmtStoreCliStatus {
param(
    [string]$Status,
    [string]$Detail = ""
)

if ([string]::IsNullOrWhiteSpace($StatusPath)) { return }
try {
    $line = "$Status|$Detail|$((Get-Date).ToString('o'))"
    Set-Content -Path $StatusPath -Value $line -Encoding Ascii -Force
    if ($Status -eq "RESOURCES_IN_USE" -and -not [string]::IsNullOrWhiteSpace($ResourcesInUsePath)) {
        Set-Content -Path $ResourcesInUsePath -Value $line -Encoding Ascii -Force
    }
}
catch {}
}

while ((Get-Date) -lt $deadline) {
if (-not (Get-Process -Id $TargetPid -ErrorAction SilentlyContinue)) { break }

$screen = ""
try { $screen = [WmtConsoleInput]::ReadScreen([uint32]$TargetPid) } catch {}
$cleanScreen = ([string]$screen) -replace "`0", ""
if (-not [string]::IsNullOrWhiteSpace($ScreenPath)) {
    try { Set-Content -Path $ScreenPath -Value $cleanScreen -Encoding UTF8 -Force } catch {}
}

if (-not $menuSelected -and $cleanScreen -match '(?i)select a product') {
    $options = @(Get-WmtStoreCliMenuOptions -ScreenText $cleanScreen)
    $matchingOptions = @($options | Where-Object { (Get-WmtStoreCliNameKey $_.Name) -eq $targetKey })
    if ($matchingOptions.Count -gt 1) {
        $preferred = @($matchingOptions | Where-Object { [string]$_.Publisher -match '(?i)\bMicrosoft\b|\bXbox\b' })
        if ($preferred.Count -eq 1) { $matchingOptions = $preferred }
    }
    if ($matchingOptions.Count -eq 1) {
        try { [void][WmtConsoleInput]::SendMenuSelection([uint32]$TargetPid, [int]$matchingOptions[0].Index) } catch {}
        $menuSelected = $true
        Set-WmtStoreCliStatus "MENU_SELECTED" $matchingOptions[0].Name
        Start-Sleep -Milliseconds 700
        continue
    }
    elseif ($matchingOptions.Count -gt 1) {
        Set-WmtStoreCliStatus "MENU_AMBIGUOUS" $PackageName
    }
    elseif ($options.Count -gt 0) {
        Set-WmtStoreCliStatus "MENU_NO_MATCH" $PackageName
    }
}

if (-not $yesSent -and $cleanScreen -match '(?i)(would you like to apply|would you like to install|would you like to update|do you want to (?:apply|install|update)|update all|\[[yn]/[yn]\]|\([yn]/[yn]\)|\(y\):)') {
    try { [void][WmtConsoleInput]::SendYes([uint32]$TargetPid) } catch {}
    $yesSent = $true
    Set-WmtStoreCliStatus "ACCEPTED" $PackageName
}

if (-not $resourcesInUseSent -and $cleanScreen -match '(?is)(0x80073d02|resources\s+(?:it\s+)?modifies\s+are\s+currently\s+in\s+use|resources[\s\S]{0,240}currently\s+in\s+use)') {
    $resourcesInUseSent = $true
    Set-WmtStoreCliStatus "RESOURCES_IN_USE" $PackageName
}
elseif ($cleanScreen -match '(?i)ready\s+to\s+download' -and $cleanScreen -match '\b0\s*%') {
    Set-WmtStoreCliStatus "READY0" $PackageName
}
elseif ($cleanScreen -match '(\d{1,3})\s*%') {
    $pct = [Math]::Min(100, [Math]::Max(0, [int]$matches[1]))
    Set-WmtStoreCliStatus "PROGRESS" ([string]$pct)
}

Start-Sleep -Milliseconds 700
}
'@

        $storeArgsJson = @($ArgumentList) | ConvertTo-Json -Compress
        $storeArgsEncoded = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($storeArgsJson))
        $runnerContent = @"
`$storeArgsJson = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('$storeArgsEncoded'))
`$storeArgs = @(`$storeArgsJson | ConvertFrom-Json)
`$transcriptPath = @'
$transcriptPath
'@
`$exitCode = 1
try { Start-Transcript -Path `$transcriptPath -Append -Force | Out-Null } catch {}
try {
& store @storeArgs
if (`$null -ne `$global:LASTEXITCODE) { `$exitCode = [int]`$global:LASTEXITCODE } else { `$exitCode = 0 }
}
catch {
Write-Host `$_.Exception.Message
`$exitCode = 1
}
try { Stop-Transcript | Out-Null } catch {}
exit `$exitCode
"@

        $batContent = @"
@echo off
title $windowTitle
echo WMT-GUI: $displayAction $safeTitle with Microsoft Store CLI...
echo Auto-selecting matching Store CLI prompts and accepting updates without taking focus...
echo.
powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$runnerPath"
set "WMT_EXIT=%ERRORLEVEL%"
echo.
echo Store CLI exit code: %WMT_EXIT%
> "$resultPath" echo %WMT_EXIT%
timeout /t 3 /nobreak >nul
exit /b %WMT_EXIT%
"@

        try {
            Set-Content -Path $runnerPath -Value $runnerContent -Encoding UTF8 -Force
            Set-Content -Path $sendKeysPath -Value $sendKeysContent -Encoding Ascii -Force
            Set-Content -Path $batPath -Value $batContent -Encoding Ascii -Force
            $storeWindowStyle = if ($Headless) { "Hidden" } else { "Normal" }
            $storeWindowLabel = if ($Headless) { "headless" } else { "interactive" }
            Write-Output "LOG:[Store CLI] Launching $storeWindowLabel $($ActionLabel.ToLowerInvariant()) window for: $PackageName"
            $cmdProc = Start-Process -FilePath "cmd.exe" -ArgumentList "/c `"$batPath`"" -PassThru -WindowStyle $storeWindowStyle
            if (-not $Headless) { Show-WmtStoreCliWindow $cmdProc }
            $safePackageArg = ([string]$PackageName).Replace('"', '')
            $sendKeysProc = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$sendKeysPath`" -TargetPid $($cmdProc.Id) -PackageName `"$safePackageArg`" -StatusPath `"$statusPath`" -ResourcesInUsePath `"$resourcesInUsePath`" -ScreenPath `"$screenPath`"" -WindowStyle Hidden -PassThru
            Write-Output "LOG:  [store] Progress: 5%"

            $storeCliTimeoutMinutes = if ($ArgumentList.Count -eq 1 -and ([string]$ArgumentList[0]).Trim().ToLowerInvariant() -eq "updates") { 10 } else { 3 }
            $deadline = (Get-Date).AddMinutes($storeCliTimeoutMinutes)
            $lastBeat = Get-Date
            $storeProgress = 5
            $lastStatusLine = ""
            $readyZeroSince = $null
            $storeCliStartedAt = Get-Date
            $storeCliResourcesInUse = $false
            $storeCliResourcesInUseLogged = $false
            while ((Get-Date) -lt $deadline) {
                $result = Get-WmtStoreCliExitResult -ResultPath $resultPath -Process $cmdProc
                if ($result.Found) {
                    if ($cmdProc -and -not $cmdProc.HasExited) {
                        try { [void]$cmdProc.WaitForExit(5000) } catch {}
                    }
                    if (Test-Path $resourcesInUsePath) {
                        $storeCliResourcesInUse = $true
                    }
                    elseif (Test-Path $statusPath) {
                        $finalStatusLine = (Get-Content -Path $statusPath -Raw -ErrorAction SilentlyContinue).Trim()
                        if ($finalStatusLine -match '^RESOURCES_IN_USE\|') { $storeCliResourcesInUse = $true }
                    }
                    if (-not $storeCliResourcesInUse -and (Test-Path $screenPath)) {
                        $finalScreenText = Get-Content -Path $screenPath -Raw -ErrorAction SilentlyContinue
                        if (Test-WmtStoreCliResourcesInUseText $finalScreenText) {
                            $storeCliResourcesInUse = $true
                        }
                    }
                    if (-not $storeCliResourcesInUse -and (Test-Path $transcriptPath)) {
                        $finalTranscriptText = Get-Content -Path $transcriptPath -Raw -ErrorAction SilentlyContinue
                        if (Test-WmtStoreCliResourcesInUseText $finalTranscriptText) {
                            $storeCliResourcesInUse = $true
                        }
                    }
                    if ($storeCliResourcesInUse -and -not $storeCliResourcesInUseLogged) {
                        $resourcesInUseLog = "LOG:[Store CLI] Error 0x80073d02: The package could not be installed because resources it modifies are currently in use. Close the app and related Store/Xbox windows, then try again."
                        Write-Output $resourcesInUseLog
                        $storeCliResourcesInUseLogged = $true
                    }
                    $exitCode = [int]$result.ExitCode
                    if ($storeCliResourcesInUse -and ($exitCode -eq 0 -or $exitCode -eq 1)) {
                        $exitCode = -2147009278
                    }
                    Clear-WmtStoreCliTempFiles @($resultPath, $statusPath, $resourcesInUsePath, $screenPath, $fallbackAckPath, $sendKeysPath, $runnerPath, $batPath, $temporaryTranscriptPath)
                    return [PSCustomObject]@{ ExitCode = $exitCode; ResourcesInUse = $storeCliResourcesInUse }
                }

                $now = Get-Date
                if (-not $storeCliResourcesInUse -and (Test-Path $transcriptPath)) {
                    $transcriptText = Get-Content -Path $transcriptPath -Raw -ErrorAction SilentlyContinue
                    if (Test-WmtStoreCliResourcesInUseText $transcriptText) {
                        $resourcesInUseLog = "LOG:[Store CLI] Error 0x80073d02: The package could not be installed because resources it modifies are currently in use. Close the app and related Store/Xbox windows, then try again."
                        Write-Output $resourcesInUseLog
                        $storeCliResourcesInUse = $true
                        $storeCliResourcesInUseLogged = $true
                    }
                }
                if ((Test-Path $resourcesInUsePath) -and -not $storeCliResourcesInUse) {
                    $resourcesInUseLog = "LOG:[Store CLI] Error 0x80073d02: The package could not be installed because resources it modifies are currently in use. Close the app and related Store/Xbox windows, then try again."
                    Write-Output $resourcesInUseLog
                    $storeCliResourcesInUse = $true
                    $storeCliResourcesInUseLogged = $true
                }
                if (Test-Path $statusPath) {
                    $statusLine = (Get-Content -Path $statusPath -Raw -ErrorAction SilentlyContinue).Trim()
                    if ($statusLine -and $statusLine -ne $lastStatusLine) {
                        $lastStatusLine = $statusLine
                        $parts = @($statusLine -split '\|', 3)
                        $status = if ($parts.Count -gt 0) { $parts[0] } else { "" }
                        $detail = if ($parts.Count -gt 1) { $parts[1] } else { "" }

                        switch ($status) {
                            "MENU_SELECTED" {
                                Write-Output "LOG:[Store CLI] Selected matching product: $detail"
                                break
                            }
                            "MENU_AMBIGUOUS" {
                                Write-Output "LOG:[Store CLI] Product picker had multiple exact matches for '$detail'."
                                break
                            }
                            "MENU_NO_MATCH" {
                                Write-Output "LOG:[Store CLI] Product picker had no exact match for '$detail'."
                                break
                            }
                            "ACCEPTED" {
                                Write-Output "LOG:[Store CLI] Accepted Store CLI confirmation prompt."
                                break
                            }
                            "RESOURCES_IN_USE" {
                                if (-not $storeCliResourcesInUse) {
                                    $resourcesInUseLog = "LOG:[Store CLI] Error 0x80073d02: The package could not be installed because resources it modifies are currently in use. Close the app and related Store/Xbox windows, then try again."
                                    Write-Output $resourcesInUseLog
                                }
                                $storeCliResourcesInUse = $true
                                $storeCliResourcesInUseLogged = $true
                                break
                            }
                            "READY0" {
                                if (-not $readyZeroSince) {
                                    $readyZeroSince = $now
                                    Write-Output "LOG:[Store CLI] Store download broker is at Ready to Download 0%; watching for progress..."
                                }
                                break
                            }
                            "PROGRESS" {
                                $readyZeroSince = $null
                                $pct = 0
                                if ([int]::TryParse($detail, [ref]$pct) -and $pct -ne $storeProgress) {
                                    $storeProgress = $pct
                                    Write-Output "LOG:  [store] Progress: $storeProgress%"
                                }
                                break
                            }
                        }
                    }
                }

                $installExceededFallbackWindow = ($ActionLabel -eq "Install" -and (New-TimeSpan -Start $storeCliStartedAt -End $now).TotalSeconds -ge 30)
                $readyZeroExceededFallbackWindow = ($readyZeroSince -and (New-TimeSpan -Start $readyZeroSince -End $now).TotalSeconds -ge 30)
                if (-not $storeCliResourcesInUse -and ($installExceededFallbackWindow -or $readyZeroExceededFallbackWindow)) {
                    $fallbackReason = if ($installExceededFallbackWindow) { "InstallTimeout" } else { "ReadyToDownload0" }
                    $fallbackReasonText = if ($installExceededFallbackWindow) {
                        "Store CLI did not finish the install within 30 seconds"
                    }
                    else {
                        "Store CLI remained at Ready to Download 0% for 30 seconds"
                    }
                    Write-Output "LOG:[Store CLI] $fallbackReasonText; opening Microsoft Store fallback page."
                    Stop-WmtStoreCliProcessTree -Process $cmdProc -HelperProcess $sendKeysProc
                    $fallbackResult = Invoke-WmtStoreCliFallback -Reason $fallbackReason -ReasonText $fallbackReasonText -StoreUri $StoreFallbackUri -WebUri $StoreFallbackWebUri
                    Clear-WmtStoreCliTempFiles @($resultPath, $statusPath, $resourcesInUsePath, $screenPath, $fallbackAckPath, $sendKeysPath, $runnerPath, $batPath, $temporaryTranscriptPath)
                    return [PSCustomObject]@{
                        ExitCode                  = -2
                        StoreFallbackOpened       = $true
                        StoreFallbackReason       = $fallbackResult.Reason
                        StalledReadyToDownload    = ($fallbackResult.Reason -eq "ReadyToDownload0")
                        StoreFallbackUri          = $fallbackResult.StoreUri
                        StoreFallbackAcknowledged = $fallbackResult.Acked
                    }
                }

                if ((New-TimeSpan -Start $lastBeat -End $now).TotalSeconds -ge 15) {
                    Write-Output "LOG:[Store CLI] Waiting for interactive $($ActionLabel.ToLowerInvariant()) to finish ($storeCliTimeoutMinutes-minute Store CLI timeout)..."
                    $storeProgress = [Math]::Min(90, $storeProgress + 10)
                    Write-Output "LOG:  [store] Progress: $storeProgress%"
                    $lastBeat = $now
                }
                Start-Sleep -Milliseconds 500
            }

            Write-Output "LOG:[Store CLI] Timed out waiting for the interactive $($ActionLabel.ToLowerInvariant()) window."
            Stop-WmtStoreCliProcessTree -Process $cmdProc -HelperProcess $sendKeysProc
            Clear-WmtStoreCliTempFiles @($resultPath, $statusPath, $resourcesInUsePath, $screenPath, $fallbackAckPath, $sendKeysPath, $runnerPath, $batPath, $temporaryTranscriptPath)
            return [PSCustomObject]@{ ExitCode = -1 }
        }
        catch {
            Write-Output "LOG:[Store CLI] Interactive launch failed: $($_.Exception.Message)"
            Stop-WmtStoreCliProcessTree -Process $cmdProc -HelperProcess $sendKeysProc
            Clear-WmtStoreCliTempFiles @($resultPath, $statusPath, $resourcesInUsePath, $screenPath, $fallbackAckPath, $sendKeysPath, $runnerPath, $batPath, $temporaryTranscriptPath)
            return [PSCustomObject]@{ ExitCode = 1 }
        }
        finally {
            try { if ($sendKeysProc) { $sendKeysProc.Dispose() } } catch {}
            try { if ($cmdProc) { $cmdProc.Dispose() } } catch {}
        }
    }

    function Get-StoreCliProductId {
        param([string]$Value)

        $text = ([string]$Value).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { return "" }

        $matchPatterns = @(
            '(?i)(?:product\s*id|productid|product-id)\s*[:=]\s*((?:9[A-Z0-9]{9,19}|XP[A-Z0-9]{8,18}))',
            '(?i)(?:/detail/|productid=)((?:9[A-Z0-9]{9,19}|XP[A-Z0-9]{8,18}))',
            '(?i)\b((?:9[A-Z0-9]{9,19}|XP[A-Z0-9]{8,18}))\b'
        )

        foreach ($pattern in $matchPatterns) {
            $match = [regex]::Match($text, $pattern)
            if ($match.Success) { return $match.Groups[1].Value.ToUpperInvariant() }
        }

        return ""
    }

    function Invoke-WmtWindowsUpdateInstall {
        param([object]$Item)

        $targetRaw = ([string]$Item.Id).Trim()
        $targetName = ([string]$Item.Name).Trim()
        if ([string]::IsNullOrWhiteSpace($targetRaw) -and [string]::IsNullOrWhiteSpace($targetName)) {
            Write-Output "LOG:[Windows Update] Selected update has no usable identity."
            return [PSCustomObject]@{ ExitCode = 1 }
        }

        $targetParts = @($targetRaw -split '\|', 2)
        $targetId = if ($targetParts.Count -gt 0) { ([string]$targetParts[0]).Trim() } else { $targetRaw }
        $targetRevision = -1
        if ($targetParts.Count -gt 1) { [void][int]::TryParse(([string]$targetParts[1]).Trim(), [ref]$targetRevision) }
        $completedIdentity = if ($targetRevision -ge 0) { "$targetId|$targetRevision" } else { $targetRaw }

        function Get-WmtWuOperationResultDetail {
            param(
                [object]$OperationResult,
                [int]$Index = 0
            )

            $aggregateCode = 0
            $itemCode = 0
            $hResult = 0
            $itemRebootRequired = $false
            try { $aggregateCode = [int]$OperationResult.ResultCode } catch {}

            $itemResult = $null
            try { $itemResult = $OperationResult.GetUpdateResult($Index) } catch {}
            if ($itemResult) {
                try { $itemCode = [int]$itemResult.ResultCode } catch { $itemCode = $aggregateCode }
                try { $hResult = [int]$itemResult.HResult } catch {}
                try { $itemRebootRequired = [bool]$itemResult.RebootRequired } catch {}
            }
            else {
                $itemCode = $aggregateCode
                try { $hResult = [int]$OperationResult.HResult } catch {}
            }

            $hResultUnsigned = [BitConverter]::ToUInt32([BitConverter]::GetBytes([int]$hResult), 0)
            return [PSCustomObject]@{
                AggregateCode      = $aggregateCode
                ItemCode           = $itemCode
                HResultHex         = ("0x{0:X8}" -f $hResultUnsigned)
                ItemRebootRequired = $itemRebootRequired
            }
        }

        try {
            Write-Output "LOG:[Windows Update] Preparing selected update: $targetName"
            $session = New-Object -ComObject Microsoft.Update.Session
            $searcher = $session.CreateUpdateSearcher()
            try { $searcher.Online = $true } catch {}
            $result = $searcher.Search("IsInstalled=0 and IsHidden=0")
            if (-not $result -or -not $result.Updates) {
                Write-Output "LOG:[Windows Update] No pending updates were returned."
                return [PSCustomObject]@{ ExitCode = 0; CompletedWindowsUpdateId = $completedIdentity }
            }

            $updatesToInstall = New-Object -ComObject Microsoft.Update.UpdateColl
            for ($wuIndex = 0; $wuIndex -lt $result.Updates.Count; $wuIndex++) {
                $update = $result.Updates.Item($wuIndex)
                if (-not $update) { continue }

                $updateId = ""
                $revision = -1
                try { $updateId = ([string]$update.Identity.UpdateID).Trim() } catch {}
                try { $revision = [int]$update.Identity.RevisionNumber } catch {}
                $title = ""
                try { $title = ([string]$update.Title).Trim() } catch {}

                $idMatches = (-not [string]::IsNullOrWhiteSpace($targetId) -and $updateId -eq $targetId)
                $revisionMatches = ($targetRevision -lt 0 -or $revision -eq $targetRevision)
                $nameMatches = ([string]::IsNullOrWhiteSpace($targetId) -and -not [string]::IsNullOrWhiteSpace($targetName) -and $title -eq $targetName)

                if (($idMatches -and $revisionMatches) -or $nameMatches) {
                    $updateRebootRequired = $false
                    try { $updateRebootRequired = [bool]$update.RebootRequired } catch {}
                    if ($updateRebootRequired) {
                        Write-Output "LOG:[Windows Update] $title is already pending a reboot; skipping another install attempt."
                        return [PSCustomObject]@{ ExitCode = 3010; CompletedWindowsUpdateId = $completedIdentity }
                    }
                    try {
                        if (-not [bool]$update.EulaAccepted) { $update.AcceptEula() }
                    }
                    catch {
                        Write-Output "LOG:[Windows Update] Could not accept EULA for ${title}: $($_.Exception.Message)"
                    }
                    [void]$updatesToInstall.Add($update)
                    break
                }
            }

            if ($updatesToInstall.Count -eq 0) {
                Write-Output "LOG:[Windows Update] $targetName is no longer offered, already installed, or hidden."
                return [PSCustomObject]@{ ExitCode = 0; CompletedWindowsUpdateId = $completedIdentity }
            }

            Write-Output "LOG:[Windows Update] Downloading $($updatesToInstall.Count) update(s)..."
            $downloader = $session.CreateUpdateDownloader()
            $downloader.Updates = $updatesToInstall
            $downloadResult = $downloader.Download()
            $downloadDetail = Get-WmtWuOperationResultDetail -OperationResult $downloadResult
            $isDownloaded = $false
            try { $isDownloaded = [bool]$updatesToInstall.Item(0).IsDownloaded } catch {}
            Write-Output "LOG:[Windows Update] Download result: aggregate $($downloadDetail.AggregateCode), item $($downloadDetail.ItemCode), HRESULT $($downloadDetail.HResultHex), downloaded $isDownloaded"
            if ($downloadDetail.ItemCode -ne 2 -and -not $isDownloaded) {
                Write-Output "LOG:[Windows Update] Download failed for the selected update."
                return [PSCustomObject]@{ ExitCode = 1 }
            }

            Write-Output "LOG:[Windows Update] Installing $($updatesToInstall.Count) update(s)..."
            $installer = $session.CreateUpdateInstaller()
            $installer.Updates = $updatesToInstall
            $installResult = $installer.Install()
            $rebootRequired = $false
            $installDetail = Get-WmtWuOperationResultDetail -OperationResult $installResult
            try { $rebootRequired = [bool]$installResult.RebootRequired } catch { $rebootRequired = $false }
            $rebootRequired = ($rebootRequired -or $installDetail.ItemRebootRequired)
            Write-Output "LOG:[Windows Update] Install result: aggregate $($installDetail.AggregateCode), item $($installDetail.ItemCode), HRESULT $($installDetail.HResultHex), reboot required $rebootRequired"

            if ($installDetail.ItemCode -eq 2) {
                if ($rebootRequired) { return [PSCustomObject]@{ ExitCode = 3010; CompletedWindowsUpdateId = $completedIdentity } }
                return [PSCustomObject]@{ ExitCode = 0; CompletedWindowsUpdateId = $completedIdentity }
            }

            Write-Output "LOG:[Windows Update] The selected update did not report a clean successful result."
            return [PSCustomObject]@{ ExitCode = 1 }
        }
        catch {
            Write-Output "LOG:[Windows Update] Install failed: $($_.Exception.Message)"
            return [PSCustomObject]@{ ExitCode = 1 }
        }
    }

    $storeUpdateTotal = @($items | Where-Object { $act -eq "Update" -and ([string]$_.Source).ToLowerInvariant() -eq "msstore" }).Count
    $storeUpdateDone = 0
    if ($storeUpdateTotal -gt 0) {
        Write-Output "LOG:[Store] Microsoft Store updates will be invoked and monitored through the Store GUI."
    }

    $total = @($items).Count
    $index = 0
    foreach ($item in $items) {
        $index++
        $id = $item.Id
        $name = $item.Name
        $src = $item.Source
        $srcKey = ([string]$src).ToLowerInvariant()
        $providerLogFilesEnabled = $true
        if ($item.PSObject.Properties["ProviderLogFilesEnabled"]) {
            $providerLogFilesEnabled = [bool]$item.ProviderLogFilesEnabled
        }
        $providerHeadlessEnabled = $silentUpdateInstallEnabled
        if ($item.PSObject.Properties["ProviderHeadlessEnabled"]) {
            $providerHeadlessEnabled = [bool]$item.ProviderHeadlessEnabled
        }
        $cmd = ""
        $userCmd = ""
        $displayCmd = ""
        $isCustomUpdateCommand = $false
        $commandOwnsProviderTranscript = $false
        $pipArguments = $null
        $wingetArgs = $null
        $wingetArgsWithoutInstallerLog = $null
        $wingetUserCmdWithoutInstallerLog = $null
        $wingetTranscriptPath = ""
        $wingetInstallerLogPath = ""
        $wingetRetryInstallerLogPath = ""
        $providerTranscriptPath = ""
        $providerDiagnosticStem = ""
        $providerLogKey = $srcKey
        switch ($srcKey) {
            "pip3" { $providerLogKey = "pip" }
            "npm (global)" { $providerLogKey = "npm" }
            "pnpm (global)" { $providerLogKey = "pnpm" }
            "ruby" { $providerLogKey = "gem" }
            "rust" { $providerLogKey = "cargo" }
            "choco" { $providerLogKey = "chocolatey" }
        }
        $providerLogKey = (($providerLogKey -replace '[^A-Za-z0-9._-]', '_').Trim('_')).ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($providerLogKey)) { $providerLogKey = "provider" }
        $providerLogLabel = if ([string]::IsNullOrWhiteSpace([string]$src)) { $providerLogKey } else { [string]$src }
        if ($providerLogFilesEnabled -and $act -in @("Install", "Update", "Uninstall", "Repair")) {
            $providerDiagnosticStem = New-WmtPackageDiagnosticStem -PackageId ([string]$id) -ActionLabel $act
            $providerTranscriptPath = "$providerDiagnosticStem-$providerLogKey.log"
            $script:WmtActiveProviderTranscriptPath = $providerTranscriptPath
            Add-WmtPackageTranscriptLine -Path $providerTranscriptPath -Text "PROVIDER: $providerLogLabel"
            Add-WmtPackageTranscriptLine -Path $providerTranscriptPath -Text "PACKAGE: $name ($id)"
            Add-WmtPackageTranscriptLine -Path $providerTranscriptPath -Text "ACTION: $act"
            Write-Output "LOG:[Diagnostics] $providerLogLabel $act log will be written to: $providerTranscriptPath"
        }
        else {
            $script:WmtActiveProviderTranscriptPath = ""
        }
        $wingetAttemptStartedAt = [datetime]::MinValue
        $storeCliArgs = $null
        $windowsUpdateItem = $null
        $storeForceUpdateScan = $false
        $storeFallbackUri = ""
        $storeFallbackWebUri = ""
        $skipReason = $null
        Write-Output "PROGRESS:${index}/${total}:$name"
        Write-Output "ITEM_SOURCE:$srcKey"

        if ($act -eq "Update" -and ([string]$src).ToLowerInvariant() -eq "msstore" -and [string]::IsNullOrWhiteSpace(([string]$item.CustomUpdateCommand))) {
            $storeGuiResult = $null
            Invoke-WmtStoreGuiUpdate -PackageName $name -Result ([ref]$storeGuiResult)
            if ($storeGuiResult -and $storeGuiResult.ExitCode -eq 0) {
                if ($storeGuiResult.AlreadyCurrent) {
                    Write-Output "LOG:[$act][$index/$total] SUCCESS: $name (Microsoft Store reports no available Update button)"
                }
                else {
                    Write-Output "LOG:[$act][$index/$total] SUCCESS: $name (updated through Microsoft Store GUI)"
                }
                Write-Output "RESULT:${index}:SUCCESS:$name"
            }
            else {
                Write-Output "LOG:[$act][$index/$total] FAILED: $name (Microsoft Store GUI update did not complete)"
                Write-Output "RESULT:${index}:FAILED:$name"
            }
            $storeUpdateDone++
            if ($storeUpdateDone -ge $storeUpdateTotal) {
                Close-WmtStoreGui
            }
            if (-not [string]::IsNullOrWhiteSpace($providerTranscriptPath) -and (Test-Path -LiteralPath $providerTranscriptPath -PathType Leaf)) {
                Write-Output "LOG:[Diagnostics] $providerLogLabel log saved: $providerTranscriptPath"
            }
            continue
        }

        # --- COMMAND GENERATION ---
        $customUpdateCommand = ""
        if ($act -eq "Update" -and $item.PSObject.Properties["CustomUpdateCommand"]) {
            $customUpdateCommand = ([string]$item.CustomUpdateCommand).Trim()
        }
        if (-not [string]::IsNullOrWhiteSpace($customUpdateCommand)) {
            $expandedCustomCommand = $customUpdateCommand
            $expandedCustomCommand = $expandedCustomCommand.Replace("{id}", [string]$id)
            $expandedCustomCommand = $expandedCustomCommand.Replace("{name}", [string]$name)
            $expandedCustomCommand = $expandedCustomCommand.Replace("{source}", [string]$src)
            $expandedCustomCommand = $expandedCustomCommand.Replace("{version}", [string]$item.Version)
            $expandedCustomCommand = $expandedCustomCommand.Replace("{available}", [string]$item.Available)

            # -EncodedCommand avoids quoting damage when the custom command contains
            # quotes, pipes, ampersands, subexpressions, URLs, etc.
            $encodedCustomCommand = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($expandedCustomCommand))
            $cmd = "powershell.exe -NoProfile -ExecutionPolicy Bypass -EncodedCommand $encodedCustomCommand"
            $userCmd = $cmd
            $displayCmd = $expandedCustomCommand
            $isCustomUpdateCommand = $true
            Write-Output "LOG:[Custom Update] Using saved PowerShell override for $name ($src / $id)."
        }
        elseif ($tmpl) {
            $cmd = $tmpl -f $id
            $userCmd = $cmd -replace "--disable-interactivity", "" 
        }
        else {
            # --- WINGET ---
            if ($src -eq "winget") {
                # winget uninstall does not accept --accept-package-agreements.
                # Keep source-agreement/interactivity flags common, and add the
                # package-agreement flag only to commands that support it.
                $baseFlags = "--accept-source-agreements --disable-interactivity"
                $baseUserFlags = "--accept-source-agreements"
                $packageFlags = "$baseFlags --accept-package-agreements"
                $packageUserFlags = "$baseUserFlags --accept-package-agreements"
                if ($providerLogFilesEnabled) {
                    $baseFlags += " --verbose-logs"
                    $baseUserFlags += " --verbose-logs"
                    $packageFlags += " --verbose-logs"
                    $packageUserFlags += " --verbose-logs"
                }
                $includeUnknownFlag = if ($wingetIncludeUnknown) { " --include-unknown" } else { "" }

                if ($providerLogFilesEnabled -and $act -in @("Install", "Update", "Uninstall", "Repair")) {
                    $diagnosticStem = if (-not [string]::IsNullOrWhiteSpace($providerDiagnosticStem)) { $providerDiagnosticStem } else { New-WmtPackageDiagnosticStem -PackageId ([string]$id) -ActionLabel $act }
                    $wingetTranscriptPath = if (-not [string]::IsNullOrWhiteSpace($providerTranscriptPath)) { $providerTranscriptPath } else { "$diagnosticStem-winget.log" }
                    $providerTranscriptPath = $wingetTranscriptPath
                    $script:WmtActiveProviderTranscriptPath = $providerTranscriptPath
                    if ($act -in @("Install", "Update")) {
                        $wingetInstallerLogPath = "$diagnosticStem-installer.log"
                        $wingetRetryInstallerLogPath = "$diagnosticStem-retry-installer.log"
                    }
                }

                if ($act -eq "Install") {
                    $wingetArgsWithoutInstallerLog = "install --id `"$id`" $packageFlags"
                    $wingetUserCmdWithoutInstallerLog = "winget install --id `"$id`" $packageUserFlags"
                    $wingetArgs = if ($wingetInstallerLogPath) { "$wingetArgsWithoutInstallerLog --log `"$wingetInstallerLogPath`"" } else { $wingetArgsWithoutInstallerLog }
                    $cmd = "winget $wingetArgs"
                    $userCmd = if ($wingetRetryInstallerLogPath) { "$wingetUserCmdWithoutInstallerLog --log `"$wingetRetryInstallerLogPath`"" } else { $wingetUserCmdWithoutInstallerLog }
                }
                if ($act -eq "Update") {
                    $wingetArgsWithoutInstallerLog = "upgrade --id `"$id`"$includeUnknownFlag $packageFlags"
                    $wingetUserCmdWithoutInstallerLog = "winget upgrade --id `"$id`"$includeUnknownFlag $packageUserFlags"
                    $wingetArgs = if ($wingetInstallerLogPath) { "$wingetArgsWithoutInstallerLog --log `"$wingetInstallerLogPath`"" } else { $wingetArgsWithoutInstallerLog }
                    $cmd = "winget $wingetArgs"
                    $userCmd = if ($wingetRetryInstallerLogPath) { "$wingetUserCmdWithoutInstallerLog --log `"$wingetRetryInstallerLogPath`"" } else { $wingetUserCmdWithoutInstallerLog }
                }
                if ($act -eq "Uninstall") {
                    $wingetArgs = "uninstall --id `"$id`" $baseFlags"
                    $cmd = "winget $wingetArgs"
                    $userCmd = "winget uninstall --id `"$id`" $baseUserFlags"
                }
                if ($act -eq "Repair") {
                    $wingetArgs = "repair --id `"$id`" $packageFlags"
                    $cmd = "winget $wingetArgs"
                    $userCmd = "winget repair --id `"$id`" $packageUserFlags"
                }
            }
            # --- MICROSOFT STORE ---
            elseif ($src -eq "msstore") {
                $safeStoreId = Get-StoreCliProductId $id
                $preferStoreUpdateScan = Test-WmtStoreUpdateScanPreferredItem -Name $name -Id $id
                if ($act -eq "Install" -and $preferStoreUpdateScan) {
                    $storeForceUpdateScan = $true
                    $storeFallbackUri = "ms-windows-store://downloadsandupdates"
                    $storeFallbackWebUri = "https://apps.microsoft.com/home"
                    $cmd = "Microsoft Store app update scan"
                    $userCmd = "PowerShell MDM_EnterpriseModernAppManagement UpdateScanMethod"
                }
                elseif ($act -eq "Install") {
                    if ($safeStoreId) {
                        $storeCliArgs = [string[]]@("install", $safeStoreId)
                        if ($preferStoreUpdateScan) {
                            $storeFallbackUri = "ms-windows-store://downloadsandupdates"
                            $storeFallbackWebUri = "https://apps.microsoft.com/home"
                        }
                        else {
                            $storeFallbackUri = "ms-windows-store://pdp/?ProductId=$safeStoreId"
                            $storeFallbackWebUri = "https://apps.microsoft.com/detail/$safeStoreId"
                        }
                    }
                    else {
                        $storeTarget = ([string]$name).Replace('"', '').Trim()
                        if ([string]::IsNullOrWhiteSpace($storeTarget)) {
                            $rawStoreId = ([string]$id).Trim()
                            if ([string]::IsNullOrWhiteSpace($rawStoreId)) { $rawStoreId = "(blank)" }
                            $skipReason = "Store CLI needs a product ID or package name, but this row has ID '$rawStoreId' and no usable name."
                        }
                        else {
                            $storeCliArgs = [string[]]@("install", $storeTarget)
                            $escapedStoreTarget = [System.Uri]::EscapeDataString($storeTarget)
                            if ($preferStoreUpdateScan) {
                                $storeFallbackUri = "ms-windows-store://downloadsandupdates"
                                $storeFallbackWebUri = "https://apps.microsoft.com/home"
                            }
                            else {
                                $storeFallbackUri = "ms-windows-store://search/?query=$escapedStoreTarget"
                                $storeFallbackWebUri = "https://apps.microsoft.com/search?query=$escapedStoreTarget"
                            }
                            Write-Output "LOG:[Store CLI] Product ID unavailable for '$name'; using Store CLI's product picker with automatic exact-match selection."
                        }
                    }
                    $cmd = "store $storeCliArgs"
                    $userCmd = $cmd
                }
                if ($act -eq "Uninstall") {
                    $flags = "--accept-source-agreements --disable-interactivity"
                    $userFlags = "--accept-source-agreements"
                    if ($providerLogFilesEnabled) {
                        $flags += " --verbose-logs"
                        $userFlags += " --verbose-logs"
                    }
                    $wingetArgs = "uninstall --id `"$id`" --source msstore $flags"
                    if ($providerLogFilesEnabled -and -not [string]::IsNullOrWhiteSpace($providerTranscriptPath)) {
                        $wingetTranscriptPath = $providerTranscriptPath
                    }
                    $cmd = "winget $wingetArgs"
                    $userCmd = "winget uninstall --id `"$id`" --source msstore $userFlags"
                }
            }
            # --- WINDOWS UPDATE ---
            elseif ($srcKey -eq "windowsupdate") {
                if ($act -eq "Update") {
                    $windowsUpdateItem = $item
                    $cmd = "Windows Update COM install"
                    $userCmd = "Microsoft.Update.Session install selected update"
                }
                elseif ($act -eq "Install") {
                    $skipReason = "Windows Update items can only be updated from this list; use Refresh All to rescan offered updates."
                }
                elseif ($act -eq "Uninstall") {
                    $skipReason = "Windows Update uninstall is not supported here. Use Windows Update history if you need to remove an update."
                }
            }
            # --- STEAM GAMES ---
            elseif (([string]$src).ToLowerInvariant() -eq "steam") {
                if ($act -eq "Update") {
                    # Steam game updates have to be handled by the Steam client.
                    # Use steam://validate/<AppID> to validate/update individual apps.
                    # Falls back to downloads page if AppID is not available.
                    $steamUri = if (-not [string]::IsNullOrWhiteSpace([string]$id)) { "steam://validate/$id" } else { "steam://open/downloads" }
                    $steamRunUri = if (-not [string]::IsNullOrWhiteSpace([string]$id)) { "steam://rungameid/$id" } else { "" }

                    Write-Output "LOG:[Steam] Requesting validation for $name (AppID: $id)."
                    try {
                        $steamPayload = [ordered]@{
                            Uri         = $steamUri
                            RunUri      = $steamRunUri
                            PackageName = $name
                            AppId       = $id
                        }
                        $steamJson = $steamPayload | ConvertTo-Json -Compress
                        $steamEncoded = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($steamJson))
                        $steamOpenLine = "STEAM_OPEN:$steamEncoded"
                        Write-Output $steamOpenLine
                    }
                    catch {
                        Write-Output "LOG:[Steam] Could not prepare Steam request: $($_.Exception.Message)"
                    }

                    Write-Output "LOG:[Steam] Steam launch was delegated to the headless GUI launcher."

                    $steamResult = $null
                    Wait-WmtSteamActionCompletion -ManifestPath ([string]$item.ManifestPath) -PackageName $name -Result ([ref]$steamResult)
                    if ($steamResult -and $steamResult.ExitCode -eq 0) {
                        Write-Output "LOG:[$act][$index/$total] SUCCESS: $name (Steam manifest confirms update completion)"
                        Write-Output "RESULT:${index}:SUCCESS:$name"
                    }
                    elseif ($steamResult -and $steamResult.ExitCode -eq 2) {
                        Write-Output "LOG:[$act][$index/$total] SKIPPED: $name (opened Steam updater, but completion cannot be monitored)"
                        Write-Output "RESULT:${index}:SKIPPED:$name"
                    }
                    else {
                        Write-Output "LOG:[$act][$index/$total] FAILED: $name (Steam update completion was not confirmed)"
                        Write-Output "RESULT:${index}:FAILED:$name"
                    }
                    if (-not [string]::IsNullOrWhiteSpace($providerTranscriptPath) -and (Test-Path -LiteralPath $providerTranscriptPath -PathType Leaf)) {
                        Write-Output "LOG:[Diagnostics] $providerLogLabel log saved: $providerTranscriptPath"
                    }
                    continue
                }
                elseif ($act -eq "Install") {
                    $cmd = "Start-Process `"steam://install/$id`""
                    $userCmd = "Open Steam install prompt for app $id"
                }
                elseif ($act -eq "Uninstall") {
                    $skipReason = "Steam game uninstall should be handled from the Steam client."
                }
            }
            # --- LEGENDARY / EPIC GAMES ---
            elseif ($src -eq "legendary") {
                if ($act -eq "Update" -and ([string]$id) -eq "__wmt_provider_legendary__") {
                    $providerUpdateResult = $null
                    Invoke-WmtPortableProviderBinaryUpdate -ProviderKey "legendary" -TargetPath $legendaryExePath -Result ([ref]$providerUpdateResult)
                    if ($providerUpdateResult -and $providerUpdateResult.ExitCode -eq 0) {
                        Write-Output "LOG:[$act][$index/$total] SUCCESS: $name"
                        Write-Output "RESULT:${index}:SUCCESS:$name"
                    }
                    else {
                        Write-Output "LOG:[$act][$index/$total] FAILED: $name"
                        Write-Output "RESULT:${index}:FAILED:$name"
                    }
                    if (-not [string]::IsNullOrWhiteSpace($providerTranscriptPath) -and (Test-Path -LiteralPath $providerTranscriptPath -PathType Leaf)) {
                        Write-Output "LOG:[Diagnostics] $providerLogLabel log saved: $providerTranscriptPath"
                    }
                    continue
                }

                $legendaryCommand = Get-WmtLegendaryCommandText -ForPowerShell:($act -ne "Update" -or $providerHeadlessEnabled)
                # Legendary's downloader timeout does not control Epic API metadata calls.
                # Give the API the same 30-second tolerance used by WMT's library/install paths
                # instead of Legendary's 10-second default.
                $legendaryGlobalArgs = "--api-timeout 30"
                $legendaryHeadlessArgs = "--max-workers 4 --dl-timeout 30 --skip-sdl --skip-dlcs"
                if ($act -eq "Install") { $skipReason = "Epic/Legendary installs must use WMT's interactive game installer." }
                if ($act -eq "Update") { $cmd = "$legendaryCommand $legendaryGlobalArgs -y update `"$id`" --update-only $legendaryHeadlessArgs" }
                if ($act -eq "Uninstall") { $cmd = "$legendaryCommand $legendaryGlobalArgs -y uninstall `"$id`"" }
                $displayCmd = $cmd

                if ($providerLogFilesEnabled -and $act -in @("Update", "Uninstall") -and -not [string]::IsNullOrWhiteSpace($cmd)) {
                    if ([string]::IsNullOrWhiteSpace($providerTranscriptPath)) {
                        $diagnosticStem = New-WmtPackageDiagnosticStem -PackageId ([string]$id) -ActionLabel $act
                        $providerTranscriptPath = "$diagnosticStem-legendary.log"
                        $script:WmtActiveProviderTranscriptPath = $providerTranscriptPath
                    }

                    $legendaryLogExe = ([string]$legendaryExePath).Trim()
                    if ([string]::IsNullOrWhiteSpace($legendaryLogExe) -or -not (Test-Path -LiteralPath $legendaryLogExe -PathType Leaf)) {
                        try {
                            $legendaryLogCmd = Get-Command legendary -ErrorAction SilentlyContinue
                            if ($legendaryLogCmd -and $legendaryLogCmd.Source) { $legendaryLogExe = [string]$legendaryLogCmd.Source }
                        }
                        catch {}
                    }
                    if (-not [string]::IsNullOrWhiteSpace($legendaryLogExe)) {
                        $exePs = ([string]$legendaryLogExe).Replace("'", "''")
                        $idPs = ([string]$id).Replace("'", "''")
                        $logPs = ([string]$providerTranscriptPath).Replace("'", "''")
                        $legendaryArgsText = if ($act -eq "Update") { $legendaryGlobalArgs + " -y update '" + $idPs + "' --update-only " + $legendaryHeadlessArgs } else { $legendaryGlobalArgs + " -y uninstall '" + $idPs + "'" }
                        $loggedScript = "& '" + $exePs + "' " + $legendaryArgsText + " 2>&1 | Tee-Object -FilePath '" + $logPs + "' -Append | ForEach-Object { Write-Host `$_ }; `$wmtLegendaryExit = if (`$null -eq `$LASTEXITCODE) { 1 } else { [int]`$LASTEXITCODE }; try { [System.IO.File]::AppendAllText('" + $logPs + "', ('[' + (Get-Date).ToString('yyyy-MM-dd HH:mm:ss.fff') + '] EXIT: ' + `$wmtLegendaryExit + [Environment]::NewLine), [System.Text.UTF8Encoding]::new(`$false)) } catch {}; exit `$wmtLegendaryExit"
                        $encodedLoggedScript = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($loggedScript))
                        $cmd = "powershell.exe -NoProfile -ExecutionPolicy Bypass -EncodedCommand $encodedLoggedScript"
                        $commandOwnsProviderTranscript = $true
                    }
                }
                $userCmd = $cmd
            }
            # --- GOGDL / GOG GAMES ---
            elseif ($src -eq "gogdl") {
                if ($act -eq "Update" -and ([string]$id) -eq "__wmt_provider_gogdl__") {
                    $providerUpdateResult = $null
                    Invoke-WmtPortableProviderBinaryUpdate -ProviderKey "gogdl" -TargetPath $gogdlExePath -Result ([ref]$providerUpdateResult)
                    if ($providerUpdateResult -and $providerUpdateResult.ExitCode -eq 0) {
                        Write-Output "LOG:[$act][$index/$total] SUCCESS: $name"
                        Write-Output "RESULT:${index}:SUCCESS:$name"
                    }
                    else {
                        Write-Output "LOG:[$act][$index/$total] FAILED: $name"
                        Write-Output "RESULT:${index}:FAILED:$name"
                    }
                    if (-not [string]::IsNullOrWhiteSpace($providerTranscriptPath) -and (Test-Path -LiteralPath $providerTranscriptPath -PathType Leaf)) {
                        Write-Output "LOG:[Diagnostics] $providerLogLabel log saved: $providerTranscriptPath"
                    }
                    continue
                }

                if ($act -eq "Update") {
                    $installDir = ([string]$item.InstallDir).Trim()
                    if ([string]::IsNullOrWhiteSpace($installDir)) {
                        $skipReason = "GOG install path was not available."
                    }
                    elseif (-not (Test-Path -LiteralPath $installDir -PathType Container)) {
                        $skipReason = "GOG install path no longer exists: $installDir"
                    }
                    else {
                        $gogdlCommand = Get-WmtGogdlCommandText -ForPowerShell:$providerHeadlessEnabled
                        $platform = ([string]$item.Platform).Trim().ToLowerInvariant()
                        if ($platform -notin @("windows", "osx", "linux")) { $platform = "windows" }
                        $authConfig = ([string]$gogdlAuthConfigPath).Trim()
                        $authCandidates = @($authConfig)
                        if (-not [string]::IsNullOrWhiteSpace($env:APPDATA)) {
                            $authCandidates += (Join-Path $env:APPDATA "heroic\gog_store\auth.json")
                            $authCandidates += (Join-Path $env:APPDATA "Heroic\gog_store\auth.json")
                        }
                        $resolvedAuthConfig = ""
                        foreach ($candidateAuth in $authCandidates) {
                            if ([string]::IsNullOrWhiteSpace([string]$candidateAuth)) { continue }
                            if (-not (Test-Path -LiteralPath ([string]$candidateAuth) -PathType Leaf)) { continue }
                            try {
                                $gogClientId = "46899977096215655"
                                $authText = [System.IO.File]::ReadAllText([string]$candidateAuth).TrimStart([char]0xFEFF)
                                $authJson = $authText | ConvertFrom-Json -ErrorAction Stop
                                $credentials = $null
                                $clientProperty = $authJson.PSObject.Properties[$gogClientId]
                                if ($clientProperty) {
                                    $credentials = $clientProperty.Value
                                }
                                elseif (-not [string]::IsNullOrWhiteSpace([string]$authJson.access_token) -or
                                    -not [string]::IsNullOrWhiteSpace([string]$authJson.refresh_token)) {
                                    if (-not $authJson.PSObject.Properties["loginTime"]) {
                                        $loginTime = [Math]::Floor(([DateTime]::UtcNow - [DateTime]'1970-01-01').TotalSeconds)
                                        $authJson | Add-Member -MemberType NoteProperty -Name "loginTime" -Value $loginTime -Force
                                    }
                                    $wrappedAuth = @{}
                                    $wrappedAuth[$gogClientId] = $authJson
                                    $authText = $wrappedAuth | ConvertTo-Json -Depth 10
                                    $credentials = $authJson
                                }
                                if (-not $credentials -or
                                    ([string]::IsNullOrWhiteSpace([string]$credentials.access_token) -and
                                    [string]::IsNullOrWhiteSpace([string]$credentials.refresh_token))) {
                                    continue
                                }

                                $preferredAuthPath = ([string]$gogdlAuthConfigPath).Trim()
                                if (-not [string]::IsNullOrWhiteSpace($preferredAuthPath)) {
                                    $preferredAuthDir = Split-Path -Parent $preferredAuthPath
                                    if ($preferredAuthDir -and -not (Test-Path -LiteralPath $preferredAuthDir)) {
                                        [void][System.IO.Directory]::CreateDirectory($preferredAuthDir)
                                    }
                                    [System.IO.File]::WriteAllText($preferredAuthPath, $authText, [System.Text.UTF8Encoding]::new($false))
                                    $resolvedAuthConfig = $preferredAuthPath
                                }
                                else {
                                    $resolvedAuthConfig = [string]$candidateAuth
                                }
                                break
                            }
                            catch {}
                        }
                        if ([string]::IsNullOrWhiteSpace($resolvedAuthConfig)) {
                            $skipReason = "GOGDL auth.json was missing or invalid. Reinstall the GOGDL provider or sign into GOG again."
                        }
                        else {
                            $cmd = "$gogdlCommand --auth-config-path `"$resolvedAuthConfig`" update `"$id`" --path `"$installDir`" --os $platform --max-workers 4"
                            $userCmd = $cmd
                        }
                    }
                }
                elseif ($act -eq "Install") {
                    $skipReason = "GOG/GOGDL installs must use WMT's interactive game installer."
                }
                elseif ($act -eq "Uninstall") {
                    $skipReason = "GOG game uninstall should be handled from GOG Galaxy, Heroic, or Apps & Features."
                }
            }
            # --- SCOOP (Likely requires User Mode) ---
            elseif ($src -eq "scoop") {
                if ($act -eq "Install") { $cmd = "scoop install `"$id`"" }
                if ($act -eq "Update") { $cmd = "scoop update `"$id`"" }
                if ($act -eq "Uninstall") { $cmd = "scoop uninstall `"$id`"" }
                if ($act -eq "Repair") { $cmd = "scoop reset `"$id`"" }
                $userCmd = $cmd # Scoop commands are same for user
            }
            # --- RUBY GEMS ---
            elseif ($src -eq "ruby" -or $src -eq "gem") {
                if ($act -eq "Install") { $cmd = "gem install `"$id`"" }
                if ($act -eq "Update") { $cmd = "gem update `"$id`"" }
                if ($act -eq "Uninstall") { $cmd = "gem uninstall `"$id`"" }
                if ($act -eq "Repair") { $cmd = "gem pristine `"$id`"" }
                $userCmd = $cmd
            }
            # --- RUST CARGO ---
            elseif ($src -eq "cargo" -or $src -eq "rust") {
                if ($act -eq "Install") { $cmd = "cargo install `"$id`"" }
                if ($act -eq "Update") { $cmd = "cargo install --force `"$id`"" } # Cargo needs force to overwrite/update binaries
                if ($act -eq "Uninstall") { $cmd = "cargo uninstall `"$id`"" }
                if ($act -eq "Repair") { $cmd = "cargo install --force `"$id`"" }
                $userCmd = $cmd
            }
            # --- .NET GLOBAL TOOLS ---
            elseif ($src -eq "dotnet") {
                if ($act -eq "Install") { $cmd = "dotnet tool install --global `"$id`"" }
                if ($act -eq "Update") { $cmd = "dotnet tool update --global `"$id`"" }
                if ($act -eq "Uninstall") { $cmd = "dotnet tool uninstall --global `"$id`"" }
                if ($act -eq "Repair") { $cmd = "dotnet tool install --global `"$id`" --force" }
                $userCmd = $cmd
            }
            # --- POWERSHELL MODULES ---
            elseif ($src -eq "psmodule") {
                if ($act -eq "Install") { $cmd = "powershell -NoProfile -ExecutionPolicy Bypass -Command `"Install-Module -Name '$id' -Scope CurrentUser -Force -AllowClobber`"" }
                if ($act -eq "Update") { $cmd = "powershell -NoProfile -ExecutionPolicy Bypass -Command `"Update-Module -Name '$id' -Force`"" }
                if ($act -eq "Uninstall") { $cmd = "powershell -NoProfile -ExecutionPolicy Bypass -Command `"Uninstall-Module -Name '$id' -AllVersions -Force`"" }
                if ($act -eq "Repair") { $cmd = "powershell -NoProfile -ExecutionPolicy Bypass -Command `"Install-Module -Name '$id' -Scope CurrentUser -Force -AllowClobber`"" }
                $userCmd = $cmd
            }
            # --- PHP COMPOSER GLOBAL PACKAGES ---
            elseif ($src -eq "composer") {
                if ($act -eq "Install") { $cmd = "composer global require `"$id`" --no-interaction" }
                if ($act -eq "Update") { $cmd = "composer global update `"$id`" --with-all-dependencies --no-interaction" }
                if ($act -eq "Uninstall") { $cmd = "composer global remove `"$id`" --no-interaction" }
                if ($act -eq "Repair") { $cmd = "composer reinstall `"$id`" --no-interaction" }
                $userCmd = $cmd
            }
            # --- PYTHON PIP ---
            elseif ($src -eq "pip" -or $src -eq "pip3") {
                $pipSafetyFlags = "--disable-pip-version-check --no-input --timeout 30 --retries 2"
                if ($act -eq "Install") {
                    $cmd = "python -m pip $pipSafetyFlags install `"$id`""
                    $pipArguments = @("-m", "pip", "--disable-pip-version-check", "--no-input", "--timeout", "30", "--retries", "2", "install", [string]$id)
                }
                if ($act -eq "Update") {
                    $cmd = "python -m pip $pipSafetyFlags install --upgrade `"$id`""
                    $pipArguments = @("-m", "pip", "--disable-pip-version-check", "--no-input", "--timeout", "30", "--retries", "2", "install", "--upgrade", [string]$id)
                }
                if ($act -eq "Uninstall") {
                    $cmd = "python -m pip --disable-pip-version-check --no-input uninstall -y `"$id`""
                    $pipArguments = @("-m", "pip", "--disable-pip-version-check", "--no-input", "uninstall", "-y", [string]$id)
                }
                if ($act -eq "Repair") {
                    $cmd = "python -m pip $pipSafetyFlags install --force-reinstall `"$id`""
                    $pipArguments = @("-m", "pip", "--disable-pip-version-check", "--no-input", "--timeout", "30", "--retries", "2", "install", "--force-reinstall", [string]$id)
                }
                $userCmd = $cmd
            }
            # --- NODE NPM & PNPM ---
            elseif ($src -eq "npm") {
                if ($act -eq "Install") { $cmd = "npm install `"$id`"" }
                if ($act -eq "Update") { $cmd = "npm update `"$id`"" }
                if ($act -eq "Uninstall") { $cmd = "npm uninstall `"$id`"" }
                if ($act -eq "Repair") { $cmd = "npm install `"$id`" --force" }
                $userCmd = $cmd
            }
            elseif ($src -eq "npm (global)") {
                if ($act -eq "Install") { $cmd = "npm install -g `"$id`"" }
                if ($act -eq "Update") { $cmd = "npm update -g `"$id`"" }
                if ($act -eq "Uninstall") { $cmd = "npm uninstall -g `"$id`"" }
                if ($act -eq "Repair") { $cmd = "npm install -g `"$id`" --force" }
                $userCmd = $cmd
            }
            elseif ($src -eq "pnpm") {
                if ($act -eq "Install") { $cmd = "pnpm install `"$id`"" }
                if ($act -eq "Update") { $cmd = "pnpm update `"$id`"" }
                if ($act -eq "Uninstall") { $cmd = "pnpm remove `"$id`"" }
                if ($act -eq "Repair") { $cmd = "pnpm rebuild `"$id`"" }
                $userCmd = $cmd
            }
            elseif ($src -eq "pnpm (global)") {
                if ($act -eq "Install") { $cmd = "pnpm add -g `"$id`"" }
                if ($act -eq "Update") { $cmd = "pnpm update -g `"$id`"" }
                if ($act -eq "Uninstall") { $cmd = "pnpm remove -g `"$id`"" }
                if ($act -eq "Repair") { $cmd = "pnpm rebuild `"$id`"" }
                $userCmd = $cmd
            }
            # --- CHOCOLATEY ---
            elseif ($src -eq "chocolatey" -or $src -eq "choco") {
                if ($act -eq "Install") { $cmd = "choco install `"$id`" -y" }
                if ($act -eq "Update") { $cmd = "choco upgrade `"$id`" -y" }
                if ($act -eq "Uninstall") { $cmd = "choco uninstall `"$id`" -y" }
                if ($act -eq "Repair") { $cmd = "choco install `"$id`" -y --force" }
                $userCmd = $cmd
            }
        }

        if ($skipReason) {
            Write-Output "LOG:[$act][$index/$total] SKIPPED: $name - $skipReason"
            Write-Output "RESULT:${index}:SKIPPED:$name"
            continue
        }

        if ($cmd) {
            Write-Output "LOG:[$act][$index/$total] Starting: $name ($src)..."
            $commandForLog = if (-not [string]::IsNullOrWhiteSpace($displayCmd)) { $displayCmd } else { $cmd }
            if ($wingetArgs -and -not [string]::IsNullOrWhiteSpace($wingetTranscriptPath)) {
                Write-Output "LOG:[$act] Running WinGet for: $name"
            }
            else {
                Write-Output "LOG:[$act] Command: $commandForLog"
            }

            # 1. RUN COMMAND (First Attempt - Admin)
            # UX: normal installs and updates run one-by-one in visible windows unless
            # the effective provider Headless setting is enabled. Provider-owned GUI
            # paths (Store, Steam, Windows Update COM) are handled separately.
            $isPipUpdate = (($src -eq "pip" -or $src -eq "pip3") -and $act -eq "Update")
            $isChocoUpdate = (($src -eq "chocolatey" -or $src -eq "choco") -and $act -eq "Update")
            $isPythonUpdate = ($act -eq "Update" -and (([string]$id -match "(?i)\bpython([0-9\.]*)\b") -or ([string]$name -match "(?i)\bpython([0-9\.]*)\b")))
            $useVisibleWindow = (
                $act -in @("Install", "Update") -and
                -not $providerHeadlessEnabled -and
                -not $storeCliArgs -and
                -not $storeForceUpdateScan -and
                -not $windowsUpdateItem -and
                $srcKey -ne "steam"
            )

            if ($wingetArgs) { $wingetAttemptStartedAt = Get-Date }

            if ($useVisibleWindow) {
                $windowTag = switch -Regex ($src) {
                    "^(winget)$" { "Winget"; break }
                    "^(msstore)$" { "MSStore"; break }
                    "^(pip|pip3)$" { "PIP"; break }
                    "^(npm|npm \(global\))$" { "NPM"; break }
                    "^(pnpm|pnpm \(global\))$" { "PNPM"; break }
                    "^(chocolatey|choco)$" { "Chocolatey"; break }
                    "^(scoop)$" { "Scoop"; break }
                    "^(gem|ruby)$" { "RubyGem"; break }
                    "^(cargo|rust)$" { "Cargo"; break }
                    "^(steam)$" { "Steam"; break }
                    "^(legendary)$" { "Legendary"; break }
                    "^(gogdl)$" { "GOGDL"; break }
                    "^(windowsupdate)$" { "WindowsUpdate"; break }
                    default { "Package" }
                }
                if ($isCustomUpdateCommand) { $windowTag = "Custom" }
                elseif ($isPipUpdate) { $windowTag = "PIP" }
                elseif ($isChocoUpdate) { $windowTag = "Chocolatey" }
                elseif ($isPythonUpdate) { $windowTag = "Python" }
                Write-Output "LOG:[$act] Launching visible $windowTag window for: $name"
                try {
                    $holdSeconds = if ($src -eq "msstore") { 5 } else { 0 }
                    # Custom overrides use a native stdout/stderr reader that mirrors
                    # their child output to this visible window and the UTF-8 log.
                    # Never wrap that runner in Tee-Object a second time.
                    $visibleCommand = $cmd
                    $customCaptureRunnerPath = ""
                    if ($isCustomUpdateCommand -and -not [string]::IsNullOrWhiteSpace($providerTranscriptPath)) {
                        $nativeCapture = ConvertTo-WmtCapturedCustomPowerShellCommand -EncodedCommand $encodedCustomCommand -TranscriptPath $providerTranscriptPath
                        $visibleCommand = [string]$nativeCapture.Command
                        $customCaptureRunnerPath = [string]$nativeCapture.RunnerPath
                    }
                    $visibleTranscriptPath = if ($isCustomUpdateCommand -or $srcKey -in @("winget", "legendary")) { "" } else { $providerTranscriptPath }
                    $p = Invoke-VisibleCmd $visibleCommand "WMT $windowTag $act - $name" -HoldSeconds $holdSeconds -TranscriptPath $visibleTranscriptPath

                    # Normalize a missing/failed visible process result. The final
                    # result line below reports the failure once, without duplicate chatter.
                    if ($null -eq $p -or $null -eq $p.ExitCode -or $p.ExitCode -ne 0) {
                        $exitCode = if ($p -and $null -ne $p.ExitCode) { $p.ExitCode } else { 1 }
                        $p = [PSCustomObject]@{ ExitCode = $exitCode }
                    }
                }
                catch {
                    if ($src -eq "msstore" -or $src -eq "gogdl") {
                        Write-Output "LOG:[$act] $windowTag action window was interrupted."
                        $p = [PSCustomObject]@{ ExitCode = 1 }
                    }
                    else {
                        Write-Output "LOG:[$act] Visible window forcefully closed or interrupted."
                        $p = [PSCustomObject]@{ ExitCode = 1 }
                    }
                }
                finally {
                    # The generated runner carries the encoded custom command.
                    # Never leave it behind in the user's TEMP folder.
                    if (-not [string]::IsNullOrWhiteSpace($customCaptureRunnerPath)) {
                        try { Remove-Item -LiteralPath $customCaptureRunnerPath -Force -ErrorAction SilentlyContinue } catch {}
                    }
                }

                if ($wingetArgs -and -not [string]::IsNullOrWhiteSpace($wingetTranscriptPath)) {
                    [void](Copy-WmtLatestWingetDiagnosticLog -DestinationPath $wingetTranscriptPath -Since $wingetAttemptStartedAt)
                }
            }
            elseif ($wingetArgs) {
                Write-Output "LOG:[$act] Running winget with live output..."
                $p = Invoke-WingetLive $wingetArgs -TranscriptPath $wingetTranscriptPath
            }
            elseif ($storeForceUpdateScan) {
                $p = Invoke-WmtStoreAppUpdateScan -PackageName $name
            }
            elseif ($storeCliArgs) {
                $p = Invoke-StoreCliInteractive -ArgumentList $storeCliArgs -PackageName $name -TempPath $temp -ActionLabel $act -StoreFallbackUri $storeFallbackUri -StoreFallbackWebUri $storeFallbackWebUri -TranscriptPath $providerTranscriptPath
            }
            elseif ($windowsUpdateItem) {
                $p = Invoke-WmtWindowsUpdateInstall -Item $windowsUpdateItem
                if ($p -and $p.ExitCode -in @(0, 3010) -and $p.PSObject.Properties["CompletedWindowsUpdateId"]) {
                    $completedWindowsUpdateId = ([string]$p.CompletedWindowsUpdateId).Trim()
                    if (-not [string]::IsNullOrWhiteSpace($completedWindowsUpdateId)) {
                        Write-Output "WINDOWS_UPDATE_COMPLETED:$completedWindowsUpdateId"
                    }
                }
            }
            elseif ($pipArguments) {
                Write-Output "LOG:[$act] Running pip directly with $pythonExePath..."
                $p = Invoke-WmtPipDirect -PythonPath $pythonExePath -ArgumentList $pipArguments -TranscriptPath $providerTranscriptPath -TimeoutSeconds 600
                foreach ($pipLine in @($p.OutputLines)) {
                    if (-not [string]::IsNullOrWhiteSpace([string]$pipLine)) {
                        Write-WmtWorkerOutputItem -Value "LOG:  > $pipLine" -SkipTranscriptMirror:(-not [string]::IsNullOrWhiteSpace($providerTranscriptPath))
                    }
                }
            }
            else {
                Write-Output "LOG:[$act] Running... (this may take a while)"
                $commandTimeoutSeconds = if ($isPipUpdate -or ($srcKey -in @("pip", "pip3"))) { 600 } elseif ($srcKey -in @("legendary", "gogdl")) { 43200 } else { 7200 }
                $commandIdleTimeoutSeconds = if ($srcKey -eq "legendary") { 900 } elseif ($srcKey -eq "gogdl") { 300 } else { 0 }
                $activityProcessNamePattern = switch ($srcKey) {
                    "legendary" { '^legendary(?:\.exe)?$' }
                    "gogdl" { '^(?:gogdl|gogdl_windows_x86_64)(?:\.exe)?$' }
                    default { "" }
                }
                $commandLabel = if ($isPipUpdate -or ($src -eq "pip" -or $src -eq "pip3")) { "Pip $act for $name" } else { "$src $act for $name" }
                if ($srcKey -in @("legendary", "gogdl")) {
                    $idleMinutes = [Math]::Round($commandIdleTimeoutSeconds / 60, 1)
                    Write-Output "LOG:[$src] Inactivity watchdog enabled: stop after $idleMinutes minutes without downloader CPU or I/O activity."
                }
                $p = $null
                $headlessTranscriptPath = if ($commandOwnsProviderTranscript) { "" } else { $providerTranscriptPath }
                Invoke-WingetCmd -Command $cmd -TimeoutSeconds $commandTimeoutSeconds -IdleTimeoutSeconds $commandIdleTimeoutSeconds -ActivityProcessNamePattern $activityProcessNamePattern -CommandLabel $commandLabel -TranscriptPath $headlessTranscriptPath -SuppressActiveTranscriptMirror:$commandOwnsProviderTranscript -Result ([ref]$p)
            }
            if (-not $wingetArgs) { Write-Output "LOG:[$act][$index/$total] Process completed with exit code: $($p.ExitCode)" }
            if (-not [string]::IsNullOrWhiteSpace($providerTranscriptPath) -and (Test-Path -LiteralPath $providerTranscriptPath -PathType Leaf)) {
                Write-Output "LOG:[Diagnostics] $providerLogLabel log saved: $providerTranscriptPath"
            }

            $hex = "0x{0:x}" -f $p.ExitCode

            # Some manifests explicitly mark --log unsupported. Do not turn
            # diagnostics into a new install failure: if WinGet rejects the
            # logging option itself, retry once without --log while preserving
            # WinGet verbose diagnostics and the WMT transcript.
            if ($wingetArgsWithoutInstallerLog -and $wingetInstallerLogPath -and $hex -eq "0x8a150002") {
                Write-Output "LOG:[Diagnostics] WinGet rejected the installer --log option for $name. Retrying without --log."
                $wingetArgs = $wingetArgsWithoutInstallerLog
                $cmd = "winget $wingetArgs"
                $userCmd = $wingetUserCmdWithoutInstallerLog
                if ($useVisibleWindow) {
                    $p = Invoke-VisibleCmd $cmd "WMT Winget Retry Without Installer Log - $name"
                }
                else {
                    $p = Invoke-WingetLive $wingetArgs -TranscriptPath $wingetTranscriptPath
                }
                $hex = "0x{0:x}" -f $p.ExitCode
            }

            # --- AUTO-FIX: SOURCE CORRUPTION ---
            if ($wingetArgs -and $hex -eq "0x8a15000b") {
                Write-Output "LOG:[$act] WARNING: Detected Winget Source Corruption. Auto-fixing..."
                $fixP = $null
                Invoke-WingetCmd -Command "winget source reset --force" -Result ([ref]$fixP)
                if ($fixP.ExitCode -eq 0) {
                    Write-Output "LOG:[$act][$index/$total] Sources reset. Retrying $name..."
                    if ($wingetArgs) {
                        if ($useVisibleWindow) {
                            $retryCmd = "winget $wingetArgs"
                            $p = Invoke-VisibleCmd $retryCmd "WMT Winget Retry - $name"
                        }
                        else {
                            $p = Invoke-WingetLive $wingetArgs -TranscriptPath $wingetTranscriptPath
                        }
                    }
                    else {
                        $p = $null
                        Invoke-WingetCmd -Command $cmd -Result ([ref]$p)
                    }
                    $hex = "0x{0:x}" -f $p.ExitCode 
                }
            }

            # --- CHECK FINAL RESULT ---
            if ($p.ExitCode -eq 0) {
                Write-Output "LOG:[$act][$index/$total] SUCCESS: $name"
                Write-Output "RESULT:${index}:SUCCESS:$name"
            }
            elseif ($p.ExitCode -eq 3010) {
                Write-Output "LOG:[$act][$index/$total] SUCCESS: $name (Reboot Required to complete)"
                Write-Output "RESULT:${index}:SUCCESS:$name"
            }
            elseif ($p.ExitCode -eq 1602) {
                Write-Output "LOG:[$act][$index/$total] CANCELLED: $name (by User)"
                Write-Output "RESULT:${index}:CANCELLED:$name"
            }
            else {
                # --- FAILURE HANDLING ---
                $dec = "$($p.ExitCode)"
                $errDesc = "Unknown Error"

                if ($ErrorCodes.ContainsKey($hex)) { $errDesc = $ErrorCodes[$hex] }
                elseif ($ErrorCodes.ContainsKey($dec)) { $errDesc = $ErrorCodes[$dec] }

                if ($wingetInstallerLogPath -and $hex -ne "0x8a15008e") {
                    Write-WmtInstallerFailureSummary -LogPath $wingetInstallerLogPath -PackageName $name -AttemptLabel "installer"
                }
                if (-not [string]::IsNullOrWhiteSpace($wingetTranscriptPath) -and (Test-Path -LiteralPath $wingetTranscriptPath -PathType Leaf)) {
                    Write-Output "LOG:[Diagnostics] Details saved: $wingetTranscriptPath"
                }

                # Known non-retry outcomes: avoid opening fallback user-mode consoles.
                if ($hex -eq "0x8a150010") {
                    Write-Output "LOG:[$act][$index/$total] SKIPPED [$hex] ${errDesc} - $name"
                    Write-Output "RESULT:${index}:SKIPPED:$name"
                    continue
                }
                if ($hex -eq "0x8a15000b") {
                    Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (source reset did not recover the source; no user-mode retry)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }
                if ($hex -eq "0x8a15008e") {
                    $currentVersionText = ([string]$item.Version).Trim()
                    $availableVersionText = ([string]$item.Available).Trim()
                    $versionTransition = if ($currentVersionText -and $availableVersionText) { "$currentVersionText -> $availableVersionText" } else { "current -> available" }
                    Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name ($versionTransition)"
                    Write-Output "LOG:[WinGet] This upgrade requires uninstall + reinstall because the installer technology changed; WMT did not auto-remove the existing install."
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }
                if ($dec -eq "1618") {
                    Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (another installer is already running; no user-mode retry)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }
                if ($p.PSObject.Properties["TimedOut"] -and $p.TimedOut) {
                    $timeoutReason = if ($p.PSObject.Properties["TimeoutReason"] -and -not [string]::IsNullOrWhiteSpace([string]$p.TimeoutReason)) { [string]$p.TimeoutReason } else { "timeout" }
                    $terminationFailed = [bool]($p.PSObject.Properties["TerminationFailed"] -and $p.TerminationFailed)
                    if ($terminationFailed) {
                        Write-Output "LOG:[$act][$index/$total] FAILED: $name ($timeoutReason; Winget could not be confirmed terminated)"
                        Write-Output "RESULT:${index}:FAILED:$name"
                        Write-Output "LOG:[$act] Aborting the remaining batch so another package action cannot overlap the surviving Winget process."
                        for ($remainingIndex = $index + 1; $remainingIndex -le $total; $remainingIndex++) {
                            $remainingItem = @($items)[$remainingIndex - 1]
                            $remainingName = if ($remainingItem -and $remainingItem.Name) { [string]$remainingItem.Name } else { "Unstarted item $remainingIndex" }
                            Write-Output "LOG:[$act][$remainingIndex/$total] FAILED: $remainingName (not started because the previous Winget process may still be running)"
                            Write-Output "RESULT:${remainingIndex}:FAILED:$remainingName"
                        }
                        break
                    }
                    Write-Output "LOG:[$act][$index/$total] FAILED: $name ($timeoutReason; no user-mode retry)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }

                if ($useVisibleWindow) {
                    Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (see visible window output)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }
                if ($storeCliArgs) {
                    $storeResourcesInUse = (
                        ($hex -eq "0x80073d02") -or
                        ($dec -eq "-2147009278") -or
                        ($dec -eq "2147958018") -or
                        ($p.PSObject.Properties["ResourcesInUse"] -and $p.ResourcesInUse)
                    )
                    if ($storeResourcesInUse) {
                        if (-not ($p.PSObject.Properties["ResourcesInUse"] -and $p.ResourcesInUse)) {
                            $resourcesInUseLog = "LOG:[Store CLI] Error 0x80073d02: The package could not be installed because resources it modifies are currently in use. Close the app and related Store/Xbox windows, then try again."
                            Write-Output $resourcesInUseLog
                        }
                        Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (Microsoft Store says resources are currently in use; close the app and related Store/Xbox windows, then try again)"
                    }
                    elseif (($p.PSObject.Properties["StoreFallbackOpened"] -and $p.StoreFallbackOpened) -or ($p.PSObject.Properties["StalledReadyToDownload"] -and $p.StalledReadyToDownload)) {
                        Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (Store CLI isn't working; opened Microsoft Store so the item can be downloaded or updated directly)"
                    }
                    else {
                        Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (Store CLI action failed)"
                    }
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }
                if ($storeForceUpdateScan) {
                    Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (could not start Microsoft Store app update scan)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }
                if ($srcKey -eq "pip" -or $srcKey -eq "pip3") {
                    Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (pip user-mode retry disabled)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }
                if ($providerHeadlessEnabled) {
                    Write-Output "LOG:[$act][$index/$total] FAILED [$hex] ${errDesc} - $name (headless mode; interactive user-mode retry suppressed)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                    continue
                }

                if ($dec -eq "1603") {
                    Write-Output "LOG:[$act] Initial attempt failed (1603) for $name. Retrying in interactive user mode..."
                }
                else {
                    Write-Output "LOG:[$act] Initial attempt failed [$hex] $errDesc for $name. Retrying in user mode..."
                }

                # --- RETRY AS USER (Fallback) ---
                # Handles Scoop (needs user rights) and Spotify (hates Admin)
                if (-not [string]::IsNullOrWhiteSpace($userCmd)) {
                    Write-Output "LOG:[$act] User-mode retry command: $userCmd"
                }
                $retryResult = Invoke-WmtUserModeRetry -Command $userCmd -ActionLabel $act -PackageName $name -TempPath $temp -TranscriptPath $providerTranscriptPath
                if ($retryResult.TimedOut) {
                    Write-Output "LOG:[$act][$index/$total] FAILED: $name (user-mode retry timed out and was stopped)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                }
                elseif ($retryResult.LaunchFailed) {
                    Write-Output "LOG:[$act][$index/$total] FAILED: $name (user-mode retry could not be started)"
                    Write-Output "RESULT:${index}:FAILED:$name"
                }
                elseif ($retryResult.ExitCode -eq 0) {
                    Write-Output "LOG:[$act][$index/$total] SUCCESS: $name (user-mode retry completed)"
                    Write-Output "RESULT:${index}:SUCCESS:$name"
                }
                elseif ($retryResult.ExitCode -eq 3010) {
                    Write-Output "LOG:[$act][$index/$total] SUCCESS: $name (user-mode retry completed; reboot required)"
                    Write-Output "RESULT:${index}:SUCCESS:$name"
                }
                elseif ($retryResult.ExitCode -eq 1602) {
                    Write-Output "LOG:[$act][$index/$total] CANCELLED: $name (user-mode retry cancelled by user)"
                    Write-Output "RESULT:${index}:CANCELLED:$name"
                }
                else {
                    $retryHex = "0x{0:x}" -f $retryResult.ExitCode
                    $retryDescription = "Unknown Error"
                    if ($ErrorCodes.ContainsKey($retryHex)) { $retryDescription = $ErrorCodes[$retryHex] }
                    elseif ($ErrorCodes.ContainsKey("$($retryResult.ExitCode)")) { $retryDescription = $ErrorCodes["$($retryResult.ExitCode)"] }
                    Write-Output "LOG:[$act][$index/$total] FAILED [$retryHex] ${retryDescription} - $name (user-mode retry)"
                    if ($wingetRetryInstallerLogPath) {
                        Write-WmtInstallerFailureSummary -LogPath $wingetRetryInstallerLogPath -PackageName $name -AttemptLabel "user-mode retry installer"
                    }
                    Write-Output "RESULT:${index}:FAILED:$name"
                }
            }
        }
        else {
            Write-Output "LOG:[$act][$index/$total] SKIPPED: No command generated for source '$src' ($name)"
            Write-Output "RESULT:${index}:SKIPPED:$name"
        }
    }
}

$script:WingetOutputQueue = [System.Collections.Concurrent.ConcurrentQueue[object]]::new()
$script:WingetJob = New-WmtPooledPowerShell
[void]$script:WingetJob.AddScript($wingetWorkerScript.ToString()).AddArgument($jobArgs).AddArgument($script:WingetOutputQueue)
$script:WingetAsyncResult = $script:WingetJob.BeginInvoke()

# 3. Shared UI monitor for live update output and completion
try { Unregister-WmtUiPollOperation -Name "WingetAction" } catch {}
$script:WingetTimer = $null
$script:ProcessWingetLines = {
    param($lines)
    foreach ($line in $lines) {
        if ($line -match "^STEAM_OPEN:(.+)$") {
            $payload = $null
            try {
                $json = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($matches[1].Trim()))
                $payload = $json | ConvertFrom-Json
            }
            catch {
                Write-GuiLog "[Steam] Could not decode Steam launch request: $($_.Exception.Message)"
            }

            $steamUri = "steam://open/downloads"
            $steamRunUri = ""
            $packageName = $script:WingetCurrentItemName
            $appId = ""
            if ($payload) {
                if (-not [string]::IsNullOrWhiteSpace([string]$payload.Uri)) { $steamUri = [string]$payload.Uri }
                if (-not [string]::IsNullOrWhiteSpace([string]$payload.RunUri)) { $steamRunUri = [string]$payload.RunUri }
                if (-not [string]::IsNullOrWhiteSpace([string]$payload.PackageName)) { $packageName = [string]$payload.PackageName }
                if (-not [string]::IsNullOrWhiteSpace([string]$payload.AppId)) { $appId = [string]$payload.AppId }
            }
            if ([string]::IsNullOrWhiteSpace($packageName)) { $packageName = "Steam" }
            Write-GuiLog "[Steam] Received STEAM_OPEN request for $packageName ($steamUri)."

            # Prevent spamming the same Steam URL multiple times during bulk runs.
            if (-not $script:WingetSteamOpenSeen) { $script:WingetSteamOpenSeen = @{} }
            $seenKey = if (-not [string]::IsNullOrWhiteSpace($appId)) { "$steamUri|$appId" } else { $steamUri }
            if ($script:WingetSteamOpenSeen.ContainsKey($seenKey)) { continue }
            $script:WingetSteamOpenSeen[$seenKey] = $true

            function Find-WmtSteamExeForLaunch {
                $candidates = New-Object System.Collections.Generic.List[string]
                $addCandidate = {
                    param([string]$Path)
                    if ([string]::IsNullOrWhiteSpace($Path)) { return }
                    try {
                        $expanded = [Environment]::ExpandEnvironmentVariables(([string]$Path).Trim())
                        if ((Test-Path -LiteralPath $expanded -PathType Leaf) -and -not $candidates.Contains($expanded)) {
                            [void]$candidates.Add($expanded)
                        }
                    }
                    catch {}
                }
                foreach ($registryPath in @(
                        "HKCU:\Software\Valve\Steam",
                        "HKLM:\SOFTWARE\WOW6432Node\Valve\Steam",
                        "HKLM:\SOFTWARE\Valve\Steam"
                    )) {
                    try {
                        $props = Get-ItemProperty -LiteralPath $registryPath -ErrorAction Stop
                        if ($props.PSObject.Properties["SteamExe"]) { & $addCandidate ([string]$props.SteamExe) }
                        foreach ($propName in @("SteamPath", "InstallPath")) {
                            if ($props.PSObject.Properties[$propName]) {
                                & $addCandidate (Join-Path ([string]$props.$propName) "steam.exe")
                            }
                        }
                    }
                    catch {}
                }
                foreach ($path in @(
                        "${env:ProgramFiles(x86)}\Steam\steam.exe",
                        "${env:ProgramFiles}\Steam\steam.exe"
                    )) { & $addCandidate $path }
                return @($candidates) | Select-Object -First 1
            }

            function Invoke-WmtSteamHeadlessLauncher {
                param(
                    [string]$Uri,
                    [string]$Label
                )

                if ([string]::IsNullOrWhiteSpace($Uri)) { return $false }
                $steamExe = Find-WmtSteamExeForLaunch
                if ([string]::IsNullOrWhiteSpace($steamExe)) {
                    Write-GuiLog "[Steam] Headless launch skipped because steam.exe was not found."
                    return $false
                }

                try {
                    $isValidationUri = $Uri -match '^(?i)steam://validate/'
                    $psi = New-Object System.Diagnostics.ProcessStartInfo
                    $psi.FileName = $steamExe
                    $psi.Arguments = if ($isValidationUri) { "`"$Uri`"" } else { "-silent -minimized `"$Uri`"" }
                    $psi.UseShellExecute = $false
                    $psi.CreateNoWindow = $true
                    $psi.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Hidden
                    [void][System.Diagnostics.Process]::Start($psi)

                    $launchText = if ($isValidationUri) { "steam.exe $Uri" } else { "steam.exe -silent -minimized $Uri" }
                    Write-GuiLog "[Steam] Started headless Steam launcher for $Label`: $launchText"
                    return $true
                }
                catch {
                    Write-GuiLog "[Steam] Headless Steam launch failed for $Label`: $($_.Exception.Message)"
                }

                return $false
            }

            function Open-WmtSteamUriFromGui {
                param(
                    [string]$Uri,
                    [string]$Label,
                    [switch]$PreferSteamExe
                )

                if ([string]::IsNullOrWhiteSpace($Uri)) { return $false }

                Write-GuiLog "[Steam] Launch request received for $Label ($Uri)."

                if (Invoke-WmtSteamHeadlessLauncher -Uri $Uri -Label $Label) { return $true }

                return $false
            }

            $opened = Open-WmtSteamUriFromGui -Uri $steamUri -Label $packageName -PreferSteamExe
            if (-not $opened -and $steamUri -ne "steam://open/downloads") {
                $opened = Open-WmtSteamUriFromGui -Uri "steam://open/downloads" -Label "Steam Downloads" -PreferSteamExe
            }

            if ($opened) {
                Write-GuiLog "[Steam] Opened Steam updater for $packageName."
                if (-not [string]::IsNullOrWhiteSpace($steamRunUri)) {
                    Write-GuiLog "[Steam] If the download does not start automatically, click Update/Resume in Steam Downloads for app $appId."
                }
            }
            else {
                Write-GuiLog "[Steam] Could not open Steam. Start Steam manually and open Downloads to finish updating $packageName."
            }
            continue
        }
        if ($line -match "^STORE_FALLBACK:(.+)$") {
            $payload = $null
            try {
                $json = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($matches[1].Trim()))
                $payload = $json | ConvertFrom-Json
            }
            catch {}

            $storeUri = ""
            $webUri = ""
            $ackPath = ""
            $fallbackId = ""
            $reason = ""
            $reasonText = ""
            $packageName = $script:WingetCurrentItemName
            if ($payload) {
                $storeUri = ([string]$payload.StoreUri).Trim()
                $webUri = ([string]$payload.WebUri).Trim()
                $ackPath = ([string]$payload.AckPath).Trim()
                $fallbackId = ([string]$payload.FallbackId).Trim()
                $reason = ([string]$payload.Reason).Trim()
                $reasonText = ([string]$payload.ReasonText).Trim()
                if (-not [string]::IsNullOrWhiteSpace([string]$payload.PackageName)) {
                    $packageName = [string]$payload.PackageName
                }
            }
            if ([string]::IsNullOrWhiteSpace($packageName)) { $packageName = "this Microsoft Store item" }
            if ([string]::IsNullOrWhiteSpace($storeUri)) { $storeUri = "ms-windows-store://home" }
            if ([string]::IsNullOrWhiteSpace($webUri)) { $webUri = $storeUri }
            if ([string]::IsNullOrWhiteSpace($fallbackId)) { $fallbackId = "$storeUri|$packageName|$reason" }

            if (-not $script:WingetStoreFallbackSeen) { $script:WingetStoreFallbackSeen = @{} }
            if ($script:WingetStoreFallbackSeen.ContainsKey($fallbackId)) {
                continue
            }
            $script:WingetStoreFallbackSeen[$fallbackId] = $true

            $isStoreUpdateRequest = ($reason -eq "UpdateScan" -or $reason -eq "UpdateScanFailed")
            $opened = $false
            try {
                Start-Process $storeUri
                $opened = $true
                if ($isStoreUpdateRequest) {
                    Write-GuiLog "[Store] Opened Microsoft Store Updates for $packageName."
                }
                else {
                    Write-GuiLog "[Store CLI] Opened Microsoft Store fallback page for $packageName."
                }
            }
            catch {
                Write-GuiLog "[Store CLI] Could not open Microsoft Store URI: $($_.Exception.Message)"
            }
            if (-not $opened -and $webUri -and $webUri -ne $storeUri) {
                try {
                    Start-Process $webUri
                    $opened = $true
                    if ($isStoreUpdateRequest) {
                        Write-GuiLog "[Store] Opened Microsoft Store web Updates page for $packageName."
                    }
                    else {
                        Write-GuiLog "[Store CLI] Opened Microsoft Store web fallback page for $packageName."
                    }
                }
                catch {
                    Write-GuiLog "[Store CLI] Could not open Microsoft Store web fallback: $($_.Exception.Message)"
                }
            }
            if (-not [string]::IsNullOrWhiteSpace($ackPath)) {
                try {
                    $ack = "opened=$opened|$((Get-Date).ToString('o'))"
                    Set-Content -Path $ackPath -Value $ack -Encoding Ascii -Force
                }
                catch {}
            }

            if ($isStoreUpdateRequest) {
                if (-not [string]::IsNullOrWhiteSpace($reasonText)) {
                    Write-GuiLog "[Store] $reasonText"
                }
                continue
            }

            if ([string]::IsNullOrWhiteSpace($reasonText)) {
                if ($reason -eq "InstallTimeout") {
                    $reasonText = "Store CLI did not finish the install within 30 seconds"
                }
                else {
                    $reasonText = "Store CLI stayed at Ready to Download 0% for more than 30 seconds"
                }
            }
            $msg = "Store CLI isn't working for $packageName. $reasonText.`r`n`r`nA Microsoft Store page was opened so you can download or update it directly."
            [System.Windows.MessageBox]::Show($msg, "Microsoft Store CLI Stalled", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
            continue
        }
        if ($line -match "^WINDOWS_UPDATE_COMPLETED:(.+)$") {
            $completedWindowsUpdateId = ([string]$matches[1]).Trim()
            if (-not [string]::IsNullOrWhiteSpace($completedWindowsUpdateId)) {
                if (-not $script:WmtCompletedWindowsUpdateIds) { $script:WmtCompletedWindowsUpdateIds = @{} }
                if (-not $script:WmtCompletedWindowsUpdateIds.ContainsKey($completedWindowsUpdateId)) {
                    $script:WmtCompletedWindowsUpdateIds[$completedWindowsUpdateId] = $true
                    Write-GuiLog "[Windows Update] This exact update revision will be suppressed from later scans during this Windows session."
                }
            }
            continue
        }
        if ($line -match "^RESULT:(\d+):(SUCCESS|SKIPPED|FAILED|CANCELLED):(.*)$") {
            $doneIndex = [int]$matches[1]
            $result = $matches[2]
            $resultName = $matches[3]
            if (-not $script:WingetCompletedIndexes.ContainsKey($doneIndex)) {
                $script:WingetCompletedIndexes[$doneIndex] = $true
                $script:WingetProgressDone++
                if ($result -eq "SUCCESS") {
                    $script:WingetProgressSuccess++

                    # A successful uninstall is authoritative: the worker only emits
                    # SUCCESS after a zero/reboot-required provider exit code. Remove
                    # that exact package from the visible list instead of immediately
                    # rescanning providers, which can race registry/package metadata
                    # propagation and briefly re-add the just-uninstalled package.
                    if (([string]$script:WingetActiveAction).Trim() -eq "Uninstall") {
                        $actionItems = @($script:WingetActionItems)
                        $actionItem = if ($doneIndex -ge 1 -and $doneIndex -le $actionItems.Count) {
                            $actionItems[$doneIndex - 1]
                        }
                        else { $null }

                        if ($actionItem) {
                            $targetSource = ([string]$actionItem.Source).Trim().ToLowerInvariant()
                            $targetId = ([string]$actionItem.Id).Trim()
                            $targetName = ([string]$actionItem.Name).Trim()

                            $matchesUninstalledItem = {
                                param($candidate)
                                if (-not $candidate -or -not $candidate.PSObject.Properties["Source"]) { return $false }

                                $candidateSource = ([string]$candidate.Source).Trim().ToLowerInvariant()
                                if (-not [string]::IsNullOrWhiteSpace($targetSource) -and $candidateSource -ne $targetSource) { return $false }

                                $candidateId = ([string]$candidate.Id).Trim()
                                $candidateName = ([string]$candidate.Name).Trim()
                                if (-not [string]::IsNullOrWhiteSpace($targetId) -and -not [string]::IsNullOrWhiteSpace($candidateId)) {
                                    return ($candidateId -eq $targetId)
                                }
                                return (-not [string]::IsNullOrWhiteSpace($targetName) -and $candidateName -eq $targetName)
                            }

                            if ($lstWinget) {
                                $itemsToRemove = @($lstWinget.Items | Where-Object { & $matchesUninstalledItem $_ })
                                foreach ($visibleItem in $itemsToRemove) {
                                    try { $lstWinget.Items.Remove($visibleItem) } catch {}
                                }
                            }

                            # Search mode keeps a snapshot of the update list for the
                            # Clear Search button. Keep that snapshot consistent too,
                            # otherwise the removed package can reappear without a scan.
                            if ($script:WingetSavedScanItems) {
                                $script:WingetSavedScanItems = @(
                                    $script:WingetSavedScanItems | Where-Object { -not (& $matchesUninstalledItem $_) }
                                )
                            }
                        }
                    }
                }
                elseif ($result -eq "SKIPPED") {
                    $script:WingetProgressSkipped++
                }
                else {
                    $script:WingetProgressFailed++
                }
                if ($doneIndex -eq $script:WingetCurrentIndex) { $script:WingetCurrentPercent = 0 }
                & $script:SetWingetLastResultUi $result $resultName $doneIndex $script:WingetProgressTotal
                & $script:RefreshWingetProgressUi
            }
            continue
        }
        if ($line -match "^ITEM_SOURCE:(.*)$") {
            $script:WingetCurrentItemSource = ([string]$matches[1]).Trim().ToLowerInvariant()
            $script:WingetCurrentItemStartedAt = Get-Date
            continue
        }
        if ($line -match "^PROGRESS:(\d+)/(\d+):(.+)$") {
            $i = [int]$matches[1]
            $t = [int]$matches[2]
            $n = $matches[3]
            $script:WingetCurrentIndex = $i
            $script:WingetCurrentPercent = 0
            $script:WingetCurrentItemName = $n
            $lblWingetStatus.Text = "$($script:WingetActiveAction) ${i}/${t}: $n"
            & $script:RefreshWingetProgressUi
            continue
        }
        if ($line -match "^LOG:(.*)") {
            $logMsg = $matches[1].Trim()
            if ($logMsg -match "^\[Store CLI\]\s+Error 0x80073d02:") {
                $script:WingetStoreResourcesInUseSeen = $true
                if ($script:WingetStoreErrorLogSeen.ContainsKey($logMsg)) { continue }
                $script:WingetStoreErrorLogSeen[$logMsg] = $true
            }
            if ($logMsg -match "^\[(?:winget|store)\]\s+Progress:\s*(\d+)%$") {
                $script:WingetCurrentPercent = [int]$matches[1]
                & $script:RefreshWingetProgressUi
            }
            # RESULT:<index>:<status>:<name> is the canonical completion
            # protocol. Do not infer completion from human-readable LOG lines:
            # those are emitted first and can otherwise consume the index before
            # RESULT arrives, skipping result-specific behavior such as removing
            # a successfully uninstalled package from the visible list.
            Write-GuiLog $logMsg
        }
    }
}

$script:DrainWingetOutputQueue = {
    $batch = [System.Collections.Generic.List[object]]::new()
    if ($script:WingetOutputQueue) {
        $queuedItem = $null
        while ($script:WingetOutputQueue.TryDequeue([ref]$queuedItem)) {
            [void]$batch.Add($queuedItem)
            $queuedItem = $null
        }
    }
    if ($batch.Count -gt 0) { & $script:ProcessWingetLines $batch.ToArray() }
}

Register-WmtUiPollOperation -Name "WingetAction" -TestComplete { $false } -OnTick {
        try {
            if (-not $script:WingetJob) {
                Unregister-WmtUiPollOperation -Name "WingetAction"
                return
            }
            & $script:DrainWingetOutputQueue
            if ($script:WingetAsyncResult -and -not $script:WingetAsyncResult.IsCompleted -and $script:WingetActionStartedAt -and $script:WingetCurrentItemName) {
                try {
                    $elapsed = (Get-Date) - $script:WingetActionStartedAt
                    $elapsedText = $elapsed.ToString("mm\:ss", [System.Globalization.CultureInfo]::InvariantCulture)
                    $curIdx = [Math]::Max(1, $script:WingetCurrentIndex)
                    $lblWingetStatus.Text = "$($script:WingetActiveAction) ${curIdx}/$($script:WingetProgressTotal): $($script:WingetCurrentItemName)  (${elapsedText})"
                }
                catch {}
            }
            if ($script:WingetAsyncResult -and $script:WingetAsyncResult.IsCompleted) {
                try {
                    $finalOutput = @($script:WingetJob.EndInvoke($script:WingetAsyncResult))
                    if ($finalOutput.Count -gt 0) { & $script:ProcessWingetLines $finalOutput }
                }
                catch {
                    if (-not $script:WingetActionForcedTimeout) { throw }
                }
                & $script:DrainWingetOutputQueue
                try { $script:WingetJob.Dispose() } catch {}
                $script:WingetJob = $null
                $script:WingetAsyncResult = $null
                $script:WingetOutputQueue = $null
                Unregister-WmtUiPollOperation -Name "WingetAction"
                if ($script:WingetActiveAction) {
                    if ($script:WingetProgressDone -lt $script:WingetProgressTotal) {
                        $missing = $script:WingetProgressTotal - $script:WingetProgressDone
                        $script:WingetProgressDone = $script:WingetProgressTotal
                        if ($script:WingetActionForcedTimeout) {
                            $script:WingetProgressFailed += $missing
                            $missingName = if ([string]::IsNullOrWhiteSpace($script:WingetCurrentItemName)) { "Pip item" } else { $script:WingetCurrentItemName }
                            & $script:SetWingetLastResultUi "FAILED" $missingName $script:WingetProgressTotal $script:WingetProgressTotal
                            Write-GuiLog "[$($script:WingetActiveAction)] FAILED: $missing item(s) stopped after the pip action timeout."
                        }
                        elseif ($script:WingetActionHasStoreCli) {
                            $script:WingetProgressFailed += $missing
                            $missingName = if ([string]::IsNullOrWhiteSpace($script:WingetCurrentItemName)) { "Microsoft Store item" } else { $script:WingetCurrentItemName }
                            & $script:SetWingetLastResultUi "FAILED" $missingName $script:WingetProgressTotal $script:WingetProgressTotal
                            if (-not $script:WingetStoreResourcesInUseSeen) {
                                try {
                                    $cutoff = if ($script:WingetActionStartedAt) { $script:WingetActionStartedAt.AddSeconds(-5) } else { (Get-Date).AddMinutes(-10) }
                                    $storeTempFiles = @(
                                        Get-ChildItem -Path $env:TEMP -Filter "WMT_StoreCLI_*.resources" -File -ErrorAction SilentlyContinue
                                        Get-ChildItem -Path $env:TEMP -Filter "WMT_StoreCLI_*.screen" -File -ErrorAction SilentlyContinue
                                        Get-ChildItem -Path $env:TEMP -Filter "WMT_StoreCLI_*.transcript" -File -ErrorAction SilentlyContinue
                                    ) | Where-Object { $_.LastWriteTime -ge $cutoff }
                                    foreach ($storeTempFile in $storeTempFiles) {
                                        $storeTempText = Get-Content -Path $storeTempFile.FullName -Raw -ErrorAction SilentlyContinue
                                        if ($storeTempText -match '(?is)(0x80073d02|resources\s+(?:it\s+)?modifies\s+are\s+currently\s+in\s+use|resources[\s\S]{0,240}currently\s+in\s+use)') {
                                            $script:WingetStoreResourcesInUseSeen = $true
                                            $resourcesInUseLog = "[Store CLI] Error 0x80073d02: The package could not be installed because resources it modifies are currently in use. Close the app and related Store/Xbox windows, then try again."
                                            if (-not $script:WingetStoreErrorLogSeen.ContainsKey($resourcesInUseLog)) {
                                                $script:WingetStoreErrorLogSeen[$resourcesInUseLog] = $true
                                                Write-GuiLog $resourcesInUseLog
                                            }
                                            break
                                        }
                                    }
                                }
                                catch {}
                            }
                            if ($script:WingetStoreResourcesInUseSeen) {
                                Write-GuiLog "[$($script:WingetActiveAction)] FAILED: $missing Store CLI item(s) ended after Microsoft Store reported 0x80073d02 resources currently in use."
                            }
                            else {
                                Write-GuiLog "[$($script:WingetActiveAction)] FAILED: $missing Store CLI item(s) ended without a result. This usually means Store CLI was stopped after a stalled or cancelled update."
                            }
                        }
                        else {
                            # Some non-Store installers close their consoles without a reliable exit event.
                            Write-GuiLog "[$($script:WingetActiveAction)] Notice: $missing item(s) completed silently without a standard success flag."
                        }
                    }
                    if ($script:WingetProgressFailed -gt 0) {
                        $lblWingetStatus.Text = "$($script:WingetActiveAction) completed with failures. $($script:WingetProgressDone)/$($script:WingetProgressTotal) done."
                        Write-GuiLog "[$($script:WingetActiveAction)] Completed with $($script:WingetProgressFailed) failure(s)."
                    }
                    else {
                        $lblWingetStatus.Text = "$($script:WingetActiveAction) completed. $($script:WingetProgressDone)/$($script:WingetProgressTotal) done."
                        Write-GuiLog "[$($script:WingetActiveAction)] Completed."
                    }
                }

                $script:WingetCurrentIndex = 0
                $script:WingetCurrentPercent = 0
                $script:WingetCurrentItemSource = ""
                $script:WingetCurrentItemStartedAt = $null
                & $script:RefreshWingetProgressUi

                $btnWingetScan.IsEnabled = $true
                $txtWingetSearch.IsEnabled = $true
                $txtWingetSearch.ToolTip = ""
                $btnWingetUpdateSel.IsEnabled = $true
                if ($btnWingetUpdateAll) { $btnWingetUpdateAll.IsEnabled = $true }
                if ($btnWingetInstall) { $btnWingetInstall.IsEnabled = $true }
                if ($btnWingetUninstall) { $btnWingetUninstall.IsEnabled = $true }

                $nonSuccessCount = $script:WingetProgressSkipped + $script:WingetProgressFailed
                $completedActionName = ([string]$script:WingetActiveAction).Trim()
                $completedUninstall = ($completedActionName -eq "Uninstall")

                # Confirmed uninstall results already remove their exact rows above.
                # Do not immediately rescan after uninstall: provider/registry state
                # can lag behind the uninstall process exit and make a removed package
                # appear to come back. Failed/skipped/uncertain rows stay visible.
                $shouldRefreshAfterAction = (-not $completedUninstall) -and ($script:WingetProgressSuccess -gt 0 -or $nonSuccessCount -eq 0)

                if ($completedUninstall) {
                    if ($script:WingetProgressSuccess -gt 0) {
                        Write-GuiLog "Uninstall finished. $($script:WingetProgressSuccess) confirmed uninstall(s) removed from the package list; no immediate rescan was started."
                    }
                    elseif ($nonSuccessCount -gt 0) {
                        Write-GuiLog "Uninstall finished without a confirmed success. Package rows were left unchanged."
                    }
                    else {
                        Write-GuiLog "Uninstall finished without an explicit result. Package rows were left unchanged; refresh later to verify provider state."
                    }
                }
                elseif ($script:WingetProgressSuccess -gt 0) {
                    Write-GuiLog "Action finished. $($script:WingetProgressSuccess) explicit success(es). Refreshing package list..."
                }
                elseif (-not $shouldRefreshAfterAction) {
                    Write-GuiLog "Action finished with no applied updates. Package list was not refreshed."
                }
                else {
                    Write-GuiLog "Action finished. Refreshing package list to verify changes..."
                }

                $autoInstallCompleted = [bool]$script:WmtAutoInstallActive
                if ($autoInstallCompleted) {
                    Show-WmtBackgroundInstallNotification -Status Completed `
                        -TotalCount $script:WingetProgressTotal `
                        -SuccessCount $script:WingetProgressSuccess `
                        -SkippedCount $script:WingetProgressSkipped `
                        -FailedCount $script:WingetProgressFailed
                }

                # Clear action ownership before starting the verification scan.
                $script:WmtAutoInstallActive = $false
                $script:WingetActiveAction = $null
                $script:WingetActionItems = @()
                $script:WingetActionStoreUpdateOnly = $false
                $script:WingetActionForcedTimeout = $false

                # Installs/updates still verify via a normal refresh. Successful
                # uninstalls update the visible list directly and intentionally skip
                # the immediate scan to avoid stale provider/registry state.
                if ($shouldRefreshAfterAction -and $btnWingetScan) {
                    if (Test-WmtAnyProviderAutoUpdateEnabled -Settings (Get-WmtSettings)) {
                        $script:WmtAutoInstallSuppressNextScan = $true
                    }
                    $btnWingetScan.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))
                }
            }
        }
        catch {
            Reset-WmtUpdateUiAfterMonitorError -Context "Update completion monitor failed" -Exception $_.Exception -ErrorRecord $_
        }
    } | Out-Null
}

# 3. EVENT HANDLERS
# ==========================================
# Provider capability + per-provider toggle helpers
# ==========================================

# Static capability matrix. Search = provider exposes a search/library-search
# capability in the Providers panel. Library = the provider's owned/licensed
# games can be enumerated for the live library search box.
function Get-WmtProviderCapabilities {
return [ordered]@{
    winget        = @{ Search = $true; Library = $false }
    msstore       = @{ Search = $true; Library = $false }
    windowsupdate = @{ Search = $false; Library = $false }
    pip           = @{ Search = $true; Library = $false }
    npm           = @{ Search = $true; Library = $false }
    pnpm          = @{ Search = $true; Library = $false }
    chocolatey    = @{ Search = $true; Library = $false }
    scoop         = @{ Search = $true; Library = $false }
    gem           = @{ Search = $true; Library = $false }
    cargo         = @{ Search = $true; Library = $false }
    dotnet        = @{ Search = $true; Library = $false }
    psmodule      = @{ Search = $true; Library = $false }
    composer      = @{ Search = $true; Library = $false }
    steam         = @{ Search = $true; Library = $false }
    legendary     = @{ Search = $true; Library = $true }
    gogdl         = @{ Search = $true; Library = $true }
}
}

function Get-WmtProviderToggleDefaults {
param([string]$ProviderKey)

$caps = Get-WmtProviderCapabilities
$key = ([string]$ProviderKey).Trim().ToLowerInvariant()
$cap = if ($caps.Contains($key)) { $caps[$key] } else { @{ Search = $false; Library = $false } }
return [ordered]@{
    Search = [bool]$cap.Search
    Scan   = $true
    Logs   = $true
}
}

function Get-WmtProviderToggles {
param($Settings)

if (-not $Settings) { $Settings = Get-WmtSettings }

$toggles = [ordered]@{}

# Helper: get a value from either an IDictionary or a PSObject.
function Get-WmtToggleValue($Obj, [string]$Name) {
    if (-not $Obj) { return $null }
    if ($Obj -is [System.Collections.IDictionary]) {
        if ($Obj.Contains($Name)) { return $Obj[$Name] }
        return $null
    }
    try {
        if ($Obj.PSObject.Properties[$Name]) { return $Obj.$Name }
    }
    catch {}
    return $null
}

# Helper: enumerate key-value pairs from either an IDictionary or a PSObject.
function Get-WmtToggleEntries($Obj) {
    $result = @()
    if (-not $Obj) { return $result }
    if ($Obj -is [System.Collections.IDictionary]) {
        foreach ($k in @($Obj.Keys)) {
            $result += [PSCustomObject]@{ Name = [string]$k; Value = $Obj[$k] }
        }
    }
    else {
        try {
            foreach ($prop in @($Obj.PSObject.Properties)) {
                $result += [PSCustomObject]@{ Name = [string]$prop.Name; Value = $prop.Value }
            }
        }
        catch {}
    }
    return $result
}

try {
    $raw = $null
    if ($Settings -is [System.Collections.IDictionary]) {
        if ($Settings.Contains("ProviderToggles")) { $raw = $Settings["ProviderToggles"] }
    }
    else {
        try {
            if ($Settings.PSObject.Properties["ProviderToggles"]) { $raw = $Settings.ProviderToggles }
        }
        catch {}
    }

    if ($raw) {
        foreach ($entry_item in (Get-WmtToggleEntries $raw)) {
            $k = ([string]$entry_item.Name).Trim().ToLowerInvariant()
            if ([string]::IsNullOrWhiteSpace($k)) { continue }
            $defaults = Get-WmtProviderToggleDefaults -ProviderKey $k
            $t = [ordered]@{
                Search = [bool]$defaults.Search
                Scan   = [bool]$defaults.Scan
                Logs   = [bool]$defaults.Logs
            }
            $val = $entry_item.Value
            $s = Get-WmtToggleValue $val "Search"
            if ($null -ne $s) { $t["Search"] = [bool]$s }
            $sc = Get-WmtToggleValue $val "Scan"
            if ($null -ne $sc) { $t["Scan"] = [bool]$sc }
            $lg = Get-WmtToggleValue $val "Logs"
            if ($null -ne $lg) { $t["Logs"] = [bool]$lg }
            $toggles[$k] = $t
        }
    }
}
catch {
    Write-GuiLog "Failed to read ProviderToggles: $($_.Exception.Message)"
}

# Ensure every known provider has an entry.
foreach ($key in @((Get-WmtProviderCapabilities).Keys)) {
    if (-not $toggles.Contains($key)) {
        $toggles[$key] = (Get-WmtProviderToggleDefaults -ProviderKey $key)
    }
    else {
        $defaults = Get-WmtProviderToggleDefaults -ProviderKey $key
        if (-not $defaults.Search) { $toggles[$key]["Search"] = $false }
    }
}

return $toggles
}

function Set-WmtProviderToggles {
param($Toggles)

function Get-WmtProviderToggleInputValue {
    param($Value, [string]$Name, [bool]$Default)

    if (-not $Value) { return $Default }
    if ($Value -is [System.Collections.IDictionary]) {
        if ($Value.Contains($Name)) { return [bool]$Value[$Name] }
        foreach ($candidateKey in @($Value.Keys)) {
            if ([string]::Equals([string]$candidateKey, $Name, [System.StringComparison]::OrdinalIgnoreCase)) {
                return [bool]$Value[$candidateKey]
            }
        }
        return $Default
    }

    try {
        $property = @($Value.PSObject.Properties | Where-Object {
                [string]::Equals($_.Name, $Name, [System.StringComparison]::OrdinalIgnoreCase)
            } | Select-Object -First 1)
        if ($property.Count -gt 0) { return [bool]$property[0].Value }
    }
    catch {}
    return $Default
}

$settings = Get-WmtSettings
$clean = [ordered]@{}
if ($Toggles) {
    $toggleEntries = @()
    if ($Toggles -is [System.Collections.IDictionary]) {
        foreach ($key in @($Toggles.Keys)) {
            $toggleEntries += [PSCustomObject]@{ Name = [string]$key; Value = $Toggles[$key] }
        }
    }
    else {
        try {
            foreach ($property in @($Toggles.PSObject.Properties)) {
                $toggleEntries += [PSCustomObject]@{ Name = [string]$property.Name; Value = $property.Value }
            }
        }
        catch {}
    }

    foreach ($toggleEntry in $toggleEntries) {
        $k = ([string]$toggleEntry.Name).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($k)) { continue }
        $val = $toggleEntry.Value
        $defaults = Get-WmtProviderToggleDefaults -ProviderKey $k
        $entry = [ordered]@{
            Search = if ($defaults.Search) { Get-WmtProviderToggleInputValue -Value $val -Name "Search" -Default ([bool]$defaults.Search) } else { $false }
            Scan   = Get-WmtProviderToggleInputValue -Value $val -Name "Scan" -Default ([bool]$defaults.Scan)
            Logs   = Get-WmtProviderToggleInputValue -Value $val -Name "Logs" -Default ([bool]$defaults.Logs)
        }
        $clean[$k] = $entry
    }
}

if ($settings -is [System.Collections.IDictionary]) {
    $settings["ProviderToggles"] = $clean
}
elseif ($settings.PSObject.Properties["ProviderToggles"]) {
    $settings.ProviderToggles = $clean
}
else {
    $settings | Add-Member -MemberType NoteProperty -Name "ProviderToggles" -Value $clean -Force
}
Save-WmtSettings -Settings $settings
}

function Get-WmtProviderToggle {
param($Settings, [string]$ProviderKey, [string]$ToggleName)

if (-not $Settings) { $Settings = Get-WmtSettings }
$toggles = Get-WmtProviderToggles -Settings $Settings
$key = ([string]$ProviderKey).Trim().ToLowerInvariant()
$name = ([string]$ToggleName).Trim()
if (-not $toggles.Contains($key)) { return $false }
$entry = $toggles[$key]
if ($entry -is [System.Collections.IDictionary]) {
    if (-not $entry.Contains($name)) { return $false }
    return [bool]$entry[$name]
}
if (-not $entry.PSObject.Properties[$name]) { return $false }
return [bool]$entry.$name
}

function Get-WmtProviderToggleOverride {
param(
    $Settings,
    [string]$ProviderKey,
    [string]$ToggleName
)

if (-not $Settings) { $Settings = Get-WmtSettings }
$key = ([string]$ProviderKey).Trim().ToLowerInvariant()
$name = ([string]$ToggleName).Trim()
$result = [PSCustomObject]@{ IsSet = $false; Value = $false }
if ([string]::IsNullOrWhiteSpace($key) -or [string]::IsNullOrWhiteSpace($name)) { return $result }

$raw = Get-WmtSettingsMember -Settings $Settings -Name "ProviderExecutionOverrides" -Default $null
if (-not $raw) { return $result }

$entry = $null
if ($raw -is [System.Collections.IDictionary]) {
    if ($raw.Contains($key)) { $entry = $raw[$key] }
    else {
        foreach ($candidateKey in @($raw.Keys)) {
            if ([string]::Equals([string]$candidateKey, $key, [System.StringComparison]::OrdinalIgnoreCase)) {
                $entry = $raw[$candidateKey]
                break
            }
        }
    }
}
else {
    try {
        $property = @($raw.PSObject.Properties | Where-Object { [string]::Equals($_.Name, $key, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
        if ($property.Count -gt 0) { $entry = $property[0].Value }
    }
    catch {}
}
if (-not $entry) { return $result }

if ($entry -is [System.Collections.IDictionary]) {
    if ($entry.Contains($name)) {
        $result.IsSet = $true
        $result.Value = [bool]$entry[$name]
    }
}
else {
    try {
        $property = @($entry.PSObject.Properties | Where-Object { [string]::Equals($_.Name, $name, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
        if ($property.Count -gt 0) {
            $result.IsSet = $true
            $result.Value = [bool]$property[0].Value
        }
    }
    catch {}
}
return $result
}

function Get-WmtEffectiveProviderHeadless {
param($Settings, [string]$ProviderKey)

if (-not $Settings) { $Settings = Get-WmtSettings }
$key = ([string]$ProviderKey).Trim().ToLowerInvariant()

# Headless is a scan/update execution preference. A provider excluded from scans
# is effectively not headless, even if it has a saved override.
if (-not (Get-WmtProviderToggle -Settings $Settings -ProviderKey $key -ToggleName "Scan")) { return $false }

# Store/Steam own their update UI, while Windows Update installs through the
# Windows Update Agent COM API. None of these providers has a separate
# interactive-console mode for WMT's Headless switch to control.
if ($key -in @("msstore", "steam", "windowsupdate")) { return $false }

$fallback = [bool](Get-WmtUpdateSilentInstallEnabled -Settings $Settings)
$override = Get-WmtProviderToggleOverride -Settings $Settings -ProviderKey $key -ToggleName "Headless"
if ($override.IsSet) { return [bool]$override.Value }
return $fallback
}

function Get-WmtEffectiveProviderAutoUpdate {
param($Settings, [string]$ProviderKey)

if (-not $Settings) { $Settings = Get-WmtSettings }
$key = ([string]$ProviderKey).Trim().ToLowerInvariant()
if (-not (Get-WmtProviderToggle -Settings $Settings -ProviderKey $key -ToggleName "Scan")) { return $false }

$fallback = [bool](Get-WmtUpdateAutoInstallEnabled -Settings $Settings)
$override = Get-WmtProviderToggleOverride -Settings $Settings -ProviderKey $key -ToggleName "AutoUpdate"
if ($override.IsSet) { return [bool]$override.Value }
return $fallback
}

function Test-WmtAnyProviderAutoUpdateEnabled {
param($Settings)

if (-not $Settings) { $Settings = Get-WmtSettings }
$providerKeys = @(Get-WmtSettingsMember -Settings $Settings -Name "EnabledProviders" -Default @())
if ($providerKeys.Count -eq 0) { $providerKeys = @((Get-WmtProviderCapabilities).Keys) }

foreach ($providerKey in @($providerKeys | Select-Object -Unique)) {
    if (Get-WmtEffectiveProviderAutoUpdate -Settings $Settings -ProviderKey ([string]$providerKey)) { return $true }
}
return $false
}

function Get-WmtProviderKeyForPackageSource {
param([string]$Source)

$sourceKey = ([string]$Source).Trim().ToLowerInvariant()
switch ($sourceKey) {
    "pip3" { return "pip" }
    "npm (global)" { return "npm" }
    "pnpm (global)" { return "pnpm" }
    "choco" { return "chocolatey" }
    "ruby" { return "gem" }
    "rust" { return "cargo" }
    default { return $sourceKey }
}
}

# ==========================================
# Library enumeration for Legendary / GOGDL
# ==========================================

function Get-WmtLegendaryLibrary {
param([switch]$Force)

if (-not $Force -and $script:WmtLegendaryLibraryCache) { return $script:WmtLegendaryLibraryCache }

$result = New-Object System.Collections.Generic.List[object]

$exe = Get-WmtLegendaryExePath
if ([string]::IsNullOrWhiteSpace($exe) -or -not (Test-Path -LiteralPath $exe -PathType Leaf)) {
    try {
        $cmd = Get-Command legendary -ErrorAction SilentlyContinue
        if ($cmd -and $cmd.Source) { $exe = [string]$cmd.Source }
    }
    catch {}
}
if ([string]::IsNullOrWhiteSpace($exe) -or -not (Test-Path -LiteralPath $exe -PathType Leaf)) {
    $script:WmtLegendaryLibraryCache = $result.ToArray()
    return $script:WmtLegendaryLibraryCache
}

try {
    # Try JSON output first (much more reliable than text parsing).
    # Drain stdout/stderr concurrently so provider output cannot fill one pipe
    # and deadlock while WMT is waiting on the other.
    $ueFlag = ""
    try { if (-not (Get-WmtHideLegendaryUeAssets)) { $ueFlag = " --include-ue" } } catch {}
    $procResult = Invoke-WmtLegendaryLibraryJson -LegendaryExe $exe -IncludeUe:($ueFlag -ne "") -ForceRefresh:([bool]$Force) -TimeoutMs 30000
    $stdout = [string]$procResult.Json
    $stderr = [string]$procResult.StdErr

    if ($procResult.TimedOut) { Write-GuiLog "Legendary library fetch timed out after 30 seconds." }
    if ($procResult.Error) { Write-GuiLog ([string]$procResult.Error) }
    if ($procResult.ExitCode -ne 0 -and $stderr) { Write-GuiLog "Legendary library fetch failed (exit $($procResult.ExitCode)): $($stderr.Trim())" }
    if ($procResult.OfflineFallback) { Write-GuiLog "Legendary: using local cached catalog ($($procResult.CachedCount) entries; $($procResult.MissingTitles) titles awaiting metadata)." }

    # Legendary deliberately separates owned-library metadata ("list") from
    # local installation records ("list-installed"). Merge them by app_name.
    $installedByApp = @{}
    $installedQuerySucceeded = $false
    try {
        $installedResult = Invoke-WmtLegendaryInstalledData -LegendaryExe $exe -TimeoutMs 30000
        if ($installedResult.ExitCode -eq 0) {
            $installedQuerySucceeded = $true
            foreach ($installedGame in @($installedResult.Rows)) {
                $installedId = ([string]$installedGame.'App name').Trim()
                if ([string]::IsNullOrWhiteSpace($installedId)) { continue }
                $installedByApp[$installedId.ToLowerInvariant()] = [PSCustomObject]@{
                    Id               = $installedId
                    Title            = ([string]$installedGame.'App title').Trim()
                    Version          = ([string]$installedGame.'Installed version').Trim()
                    AvailableVersion = ([string]$installedGame.'Available version').Trim()
                    InstallPath      = ([string]$installedGame.'Install path').Trim()
                    Platform         = ([string]$installedGame.Platform).Trim()
                }
            }
        }
    }
    catch {}

    $parsed = $false

    # Attempt 1: JSON parsing (legendary >= 0.20.x supports --json)
    if (-not $parsed -and -not [string]::IsNullOrWhiteSpace($stdout)) {
        try {
            $json = $stdout | ConvertFrom-Json -ErrorAction Stop
            if ($json) {
                $items = @($json)
                foreach ($game in $items) {
                    $title = [string]$game.app_title
                    if ([string]::IsNullOrWhiteSpace($title)) { $title = [string]$game.title }
                    if ([string]::IsNullOrWhiteSpace($title)) { continue }
                    $gameId = ([string]$game.app_name).Trim()
                    $installedRecord = if ([string]::IsNullOrWhiteSpace($gameId)) { $null } else { $installedByApp[$gameId.ToLowerInvariant()] }
                    $isInstalled = ($null -ne $installedRecord)
                    $installedVer = if ($installedRecord) { [string]$installedRecord.Version } else { "" }
                    $latestVer = [string]$game.app_version
                    if ($isInstalled -and [string]::IsNullOrWhiteSpace($installedVer)) { $installedVer = $latestVer }
                    # Tag UE/Fab assets (namespace 'ue', legendary's own skip
                    # marker). 'namespace' is not a top-level JSON key (it is a
                    # Python property there); it lives in asset_infos (per
                    # platform) and in the EGS metadata blob.
                    $legIsUe = [bool]$game.is_ue
                    try {
                        if ($game.PSObject.Properties["asset_infos"] -and $game.asset_infos) {
                            foreach ($aiProp in @($game.asset_infos.PSObject.Properties)) {
                                # Object form: read .namespace directly. String form:
                                # legendary serializes GameAsset objects via str() (json
                                # default=str), so the value arrives as a Python repr - match
                                # the namespace field inside that text instead.
                                if ($aiProp.Value -is [string]) {
                                    if ($aiProp.Value -match "(?i)namespace\s*=\s*'ue'") { $legIsUe = $true; break }
                                }
                                elseif (([string]$aiProp.Value.namespace) -eq 'ue') { $legIsUe = $true; break }
                            }
                        }
                    } catch {}
                    if (-not $legIsUe) {
                        try {
                            if ($game.PSObject.Properties["metadata"] -and $game.metadata -and $game.metadata.PSObject.Properties["namespace"] -and ([string]$game.metadata.namespace) -eq 'ue') { $legIsUe = $true }
                        } catch {}
                    }
                    $result.Add([PSCustomObject]@{
                            Provider         = "legendary"
                            Title            = $title
                            Id               = [string]$game.app_name
                            Version          = $latestVer
                            InstalledVersion = $installedVer
                            IsInstalled      = $isInstalled
                            InstallPath      = if ($installedRecord) { [string]$installedRecord.InstallPath } else { "" }
                            Platform         = if ($installedRecord) { [string]$installedRecord.Platform } else { "" }
                            Source           = "legendary"
                            Kind             = "Library"
                            IsUe             = $legIsUe
                        })
                }
                if ($result.Count -gt 0) { $parsed = $true }
            }
        }
        catch {
            # JSON parse failed � fall through to text parsing
        }
    }

    # Attempt 2: Text parsing fallback.
    # Format:  * Game Title (App name: app_name | Version: version)
    # Legendary separates the fields with a pipe, not a comma (all
    # releases since 2020); the pattern accepts both so the app name
    # never swallows the " | Version: ..." tail.
    if (-not $parsed) {
        # The text output carries no UE/Fab marker, so tag each row from
        # legendary's own side data (assets.json namespace set plus the
        # per-game metadata files) and the name heuristics - the same chain
        # the JSON path and the library scan worker use.
        $ueAppNames = @{}
        $ueAssetsFiles = @()
        try { if ($env:LEGENDARY_CONFIG_PATH) { $ueAssetsFiles += (Join-Path $env:LEGENDARY_CONFIG_PATH "assets.json") } } catch {}
        try { if ($env:XDG_CONFIG_HOME) { $ueAssetsFiles += (Join-Path $env:XDG_CONFIG_HOME "legendary\assets.json") } } catch {}
        try { if ($env:USERPROFILE) { $ueAssetsFiles += (Join-Path $env:USERPROFILE ".config\legendary\assets.json") } } catch {}
        try { if ($env:USERPROFILE) { $ueAssetsFiles += (Join-Path $env:USERPROFILE ".legendary\assets.json") } } catch {}
        try { if ($env:APPDATA) { $ueAssetsFiles += (Join-Path $env:APPDATA "heroic\legendaryConfig\legendary\assets.json") } } catch {}
        foreach ($ueAssetsFile in $ueAssetsFiles) {
            if (-not (Test-Path -LiteralPath $ueAssetsFile -PathType Leaf)) { continue }
            try {
                $assetsJson = [System.IO.File]::ReadAllText($ueAssetsFile) | ConvertFrom-Json -ErrorAction Stop
                foreach ($platformProp in @($assetsJson.PSObject.Properties)) {
                    $uePlatformAssets = @()
                    if ($platformProp.Value -is [System.Collections.IEnumerable] -and $platformProp.Value -isnot [string] -and $platformProp.Value -isnot [System.Management.Automation.PSCustomObject]) {
                        $uePlatformAssets = @($platformProp.Value)
                    }
                    elseif ($platformProp.Value -and $platformProp.Value.PSObject) {
                        $uePlatformAssets = @($platformProp.Value.PSObject.Properties | ForEach-Object { $_.Value })
                    }
                    foreach ($asset in @($uePlatformAssets)) {
                        if (([string]$asset.namespace) -eq 'ue') {
                            $ueKey = ([string]$asset.app_name).Trim().ToLowerInvariant()
                            if ($ueKey) { $ueAppNames[$ueKey] = $true }
                        }
                    }
                }
            }
            catch {}
        }
        $ueMetaRoots = @()
        try { if ($env:LEGENDARY_CONFIG_PATH) { $ueMetaRoots += (Join-Path $env:LEGENDARY_CONFIG_PATH "metadata") } } catch {}
        try { if ($env:XDG_CONFIG_HOME) { $ueMetaRoots += (Join-Path $env:XDG_CONFIG_HOME "legendary\metadata") } } catch {}
        try { if ($env:USERPROFILE) { $ueMetaRoots += (Join-Path $env:USERPROFILE ".config\legendary\metadata") } } catch {}
        try { if ($env:USERPROFILE) { $ueMetaRoots += (Join-Path $env:USERPROFILE ".legendary\metadata") } } catch {}
        try { if ($env:APPDATA) { $ueMetaRoots += (Join-Path $env:APPDATA "heroic\legendaryConfig\legendary\metadata") } } catch {}
        $regex = [regex]'\*+\s*(?<title>.+?)\s*\(\s*App(?:\s+name)?\s*:\s*(?<app>[^,|)]+?)\s*(?:[,|]\s*Version\s*:\s*(?<version>[^,|)]+?))?\s*(?:[,|]\s*[^)]*)?\)'
        foreach ($match in $regex.Matches($stdout)) {
            $title = $match.Groups["title"].Value.Trim()
            $app = $match.Groups["app"].Value.Trim()
            $ver = if ($match.Groups["version"].Success) { $match.Groups["version"].Value.Trim() } else { "" }
            if ([string]::IsNullOrWhiteSpace($title)) { continue }
            $legIsUe = ($ueAppNames.ContainsKey($app.ToLowerInvariant()) -or $app -match '^UE[_-]?\d' -or $title -match '^\s*(Unreal Engine|UE[_-]?\d)' -or $app -match '^[0-9a-fA-F]{32}$' -or $app -match '(?i)^[A-Za-z0-9][A-Za-z0-9_-]{8,}V\d+$' -or $app -match '(?i)(?:^|_)(?:5\.\d+)$' -or $title -match '(?i)\b(plugin|materials?|vfx|assets?|environment|\benv\b|sample|pack|props?|textures?|shaders?|animations?|sounds?|characters?|icvfx|metahumans?|importer|dialogue\s+tree|production\s+test)\b')
            if (-not $legIsUe -and $ueMetaRoots.Count -gt 0) {
                foreach ($ueMetaRoot in $ueMetaRoots) {
                    $ueMetaCandidate = Join-Path $ueMetaRoot "$app.json"
                    if (-not (Test-Path -LiteralPath $ueMetaCandidate -PathType Leaf)) { continue }
                    try {
                        $ueMetaJson = [System.IO.File]::ReadAllText($ueMetaCandidate) | ConvertFrom-Json -ErrorAction Stop
                        if ($ueMetaJson -and $ueMetaJson.metadata -and $ueMetaJson.metadata.PSObject.Properties["namespace"] -and ([string]$ueMetaJson.metadata.namespace) -eq 'ue') { $legIsUe = $true }
                    }
                    catch {}
                    break
                }
            }
            $installedRecord = if ([string]::IsNullOrWhiteSpace($app)) { $null } else { $installedByApp[$app.ToLowerInvariant()] }
            $result.Add([PSCustomObject]@{
                    Provider         = "legendary"
                    Title            = $title
                    Id               = $app
                    Version          = $ver
                    InstalledVersion = if ($installedRecord) { [string]$installedRecord.Version } else { "" }
                    IsInstalled      = ($null -ne $installedRecord)
                    InstallPath      = if ($installedRecord) { [string]$installedRecord.InstallPath } else { "" }
                    Platform         = if ($installedRecord) { [string]$installedRecord.Platform } else { "" }
                    Source           = "legendary"
                    Kind             = "Library"
                    IsUe             = $legIsUe
                })
        }
    }

    if ($installedQuerySucceeded -and $installedByApp.Count -gt 0) {
        $seenIds = @{}
        foreach ($existing in $result.ToArray()) {
            $existingId = ([string]$existing.Id).Trim()
            if (-not [string]::IsNullOrWhiteSpace($existingId)) { $seenIds[$existingId.ToLowerInvariant()] = $true }
        }
        foreach ($installedRecord in @($installedByApp.Values)) {
            $installedId = ([string]$installedRecord.Id).Trim()
            if ([string]::IsNullOrWhiteSpace($installedId) -or $seenIds.ContainsKey($installedId.ToLowerInvariant())) { continue }
            $title = ([string]$installedRecord.Title).Trim()
            if ([string]::IsNullOrWhiteSpace($title)) { $title = $installedId }
            $latest = ([string]$installedRecord.AvailableVersion).Trim()
            if ([string]::IsNullOrWhiteSpace($latest)) { $latest = [string]$installedRecord.Version }
            $result.Add([PSCustomObject]@{
                    Provider         = "legendary"
                    Title            = $title
                    Id               = $installedId
                    Version          = $latest
                    InstalledVersion = [string]$installedRecord.Version
                    IsInstalled      = $true
                    InstallPath      = [string]$installedRecord.InstallPath
                    Platform         = [string]$installedRecord.Platform
                    Source           = "legendary"
                    Kind             = "Library"
                    IsUe             = $false
                })
        }
    }

    if ($result.Count -eq 0 -and -not [string]::IsNullOrWhiteSpace($stderr)) {
        Write-GuiLog "Legendary owned-library enumeration produced no results. Local installed-game enumeration also returned no rows. stderr: $(([string]$stderr).Trim())"
    }
}
catch {
    Write-GuiLog "Legendary library enumeration failed: $($_.Exception.Message)"
}

$cacheFile = Join-Path (Get-DataPath) "legendary_library.json"
$mergeWarning = Merge-WmtLegendaryCachedDetails -Rows $result.ToArray() -CacheFile $cacheFile -PreserveTitles:([bool]$procResult.OfflineFallback) -PreserveInstalledState:(-not $installedQuerySucceeded)
if ($mergeWarning) { Write-GuiLog $mergeWarning }
$script:WmtLegendaryLibraryCache = $result.ToArray()

# Write to cache file for use by the search runspace.
# Guard: never wipe an existing cache with an empty result (e.g. legendary
# failed mid-scan on a network outage) — keep the last good list instead.
try {
    $cacheFile = Join-Path (Get-DataPath) "legendary_library.json"
    if ($result.Count -gt 0 -or -not (Test-Path -LiteralPath $cacheFile -PathType Leaf)) {
        Set-WmtJsonCacheFile -Path $cacheFile -InputObject $script:WmtLegendaryLibraryCache -Depth 3
    }
}
catch {
    Write-GuiLog "Failed to write Legendary library cache: $($_.Exception.Message)"
}

return $script:WmtLegendaryLibraryCache
}

function Get-WmtGogLibrary {
param([switch]$Force)

if (-not $Force -and $script:WmtGogLibraryCache) { return $script:WmtGogLibraryCache }

$result = New-Object System.Collections.Generic.List[object]

$authPath = Get-WmtGogdlAuthConfigPath
if ([string]::IsNullOrWhiteSpace($authPath) -or -not (Test-Path -LiteralPath $authPath -PathType Leaf)) {
    $heroicAuthPath = Join-Path $env:APPDATA "heroic\gog_store\auth.json"
    if ($heroicAuthPath -and (Test-Path -LiteralPath $heroicAuthPath -PathType Leaf)) { $authPath = $heroicAuthPath }
}
if ([string]::IsNullOrWhiteSpace($authPath) -or -not (Test-Path -LiteralPath $authPath -PathType Leaf)) {
    $script:WmtGogLibraryCache = $result.ToArray()
    return $script:WmtGogLibraryCache
}

try {
    $text = [System.IO.File]::ReadAllText($authPath).TrimStart([char]0xFEFF)
    $json = $text | ConvertFrom-Json -ErrorAction Stop
    $gogClientId = "46899977096215655"
    $creds = $null
    $clientProp = $json.PSObject.Properties[$gogClientId]
    if ($clientProp) { $creds = $clientProp.Value }
    elseif (-not [string]::IsNullOrWhiteSpace([string]$json.access_token)) { $creds = $json }
    if (-not $creds -or [string]::IsNullOrWhiteSpace([string]$creds.access_token)) {
        $script:WmtGogLibraryCache = $result.ToArray()
        return $script:WmtGogLibraryCache
    }

    $token = [string]$creds.access_token
    try {
        $wmtTlsProtocols = [Net.ServicePointManager]::SecurityProtocol
        if ([int]$wmtTlsProtocols -ne 0) {
            [Net.ServicePointManager]::SecurityProtocol = $wmtTlsProtocols -bor [Net.SecurityProtocolType]::Tls12
        }
    }
    catch {}

    $page = 1
    $totalPages = 1
    while ($page -le $totalPages -and $page -le 50) {
        $url = "https://embed.gog.com/account/getFilteredProducts?mediaType=1&page=$page"
        $headers = @{
            "Authorization" = "Bearer $token"
            "User-Agent"    = "Windows-Maintenance-Tool"
        }
        $resp = $null
        try {
            $resp = Invoke-RestMethod -Uri $url -Headers $headers -UseBasicParsing -ErrorAction Stop -TimeoutSec 20
        }
        catch {
            Write-GuiLog "GOG library page $page fetch failed: $($_.Exception.Message)"
            break
        }
        if (-not $resp) { break }
        if ($resp.totalPages) { $totalPages = [int]$resp.totalPages }
        if ($resp.products) {
            foreach ($prod in @($resp.products)) {
                $title = [string]$prod.title
                if ([string]::IsNullOrWhiteSpace($title)) { continue }
                $result.Add([PSCustomObject]@{
                        Provider = "gogdl"
                        Title    = $title
                        Id       = [string]$prod.id
                        Version  = [string]$prod.version
                        Source   = "gogdl"
                        Kind     = "Library"
                    })
            }
        }
        $page++
    }
}
catch {
    Write-GuiLog "GOG library enumeration failed: $($_.Exception.Message)"
}

$script:WmtGogLibraryCache = $result.ToArray()

# Write to cache file for use by the search runspace.
try {
    $cacheFile = Join-Path (Get-DataPath) "gog_library.json"
    if ($result.Count -gt 0 -or -not (Test-Path -LiteralPath $cacheFile -PathType Leaf)) {
        Set-WmtJsonCacheFile -Path $cacheFile -InputObject $script:WmtGogLibraryCache -Depth 3
    }
}
catch {
    Write-GuiLog "Failed to write GOG library cache: $($_.Exception.Message)"
}

return $script:WmtGogLibraryCache
}

function Get-WmtSteamLibrary {
param([switch]$Force)

if (-not $Force -and $script:WmtSteamLibraryCache) { return $script:WmtSteamLibraryCache }

$result = [System.Collections.Generic.List[object]]::new()

# Read Steam roots/manifests/ownership through the shared helper layer.
$steamInstall = @(Get-WmtSteamInstallRoots | Select-Object -First 1)[0]
if (-not $steamInstall) {
    $script:WmtSteamLibraryCache = $result.ToArray()
    return $script:WmtSteamLibraryCache
}

try {
    $installedApps = @{}
    foreach ($manifest in @(Get-WmtSteamInstalledManifests)) {
        $installedApps[[string]$manifest.Id] = @{ Name=[string]$manifest.Name; BuildId=[string]$manifest.BuildId }
    }
    $ownedAppIds = [System.Collections.Generic.List[string]]::new()
    foreach ($aid in @(Get-WmtSteamOwnedAppIds -SteamRoot $steamInstall)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$aid) -and -not $ownedAppIds.Contains([string]$aid)) { [void]$ownedAppIds.Add([string]$aid) }
    }

    # Step 3: Resolve names for owned apps not in appmanifests.
    # Use the Steam GetAppList API cache (steam_applist.json) if available.
    $appNames = @{}
    $appListFile = Join-Path (Get-DataPath) "steam_applist.json"
    if (Test-Path -LiteralPath $appListFile -PathType Leaf) {
        try {
            $appListText = [System.IO.File]::ReadAllText($appListFile)
            $appList = $appListText | ConvertFrom-Json -ErrorAction Stop
            if ($appList) {
                foreach ($entry in @($appList)) {
                    $aid = [string]$entry.appid
                    $aname = [string]$entry.name
                    if (-not [string]::IsNullOrWhiteSpace($aid) -and -not [string]::IsNullOrWhiteSpace($aname)) {
                        $appNames[$aid] = $aname
                    }
                }
            }
        }
        catch {}
    }

    # Step 4: Combine owned + installed into result.
    $seenIds = @{}
    if ($ownedAppIds.Count -gt 0) {
        foreach ($aid in $ownedAppIds) {
            if ($seenIds.ContainsKey($aid)) { continue }
            $seenIds[$aid] = $true
            if ($installedApps.ContainsKey($aid)) {
                $info = $installedApps[$aid]
                $result.Add([PSCustomObject]@{
                        Provider         = "steam"
                        Title            = [string]$info.Name
                        Id               = $aid
                        Version          = [string]$info.BuildId
                        Source           = "steam"
                        Kind             = "Library"
                        IsInstalled      = $true
                        InstalledVersion = if (-not [string]::IsNullOrWhiteSpace([string]$info.BuildId) -and [string]$info.BuildId -ne "0") { "Build " + [string]$info.BuildId } else { "Installed" }
                    })
            }
            else {
                $name = if ($appNames.ContainsKey($aid)) { $appNames[$aid] } else { "Steam App $aid" }
                $result.Add([PSCustomObject]@{
                        Provider         = "steam"
                        Title            = $name
                        Id               = $aid
                        Version          = ""
                        Source           = "steam"
                        Kind             = "Library"
                        IsInstalled      = $false
                        InstalledVersion = "Not installed"
                    })
            }
        }
    }
    else {
        # No localconfig.vdf found � fall back to installed games only.
        foreach ($aid in @($installedApps.Keys)) {
            if ($seenIds.ContainsKey($aid)) { continue }
            $seenIds[$aid] = $true
            $info = $installedApps[$aid]
            $result.Add([PSCustomObject]@{
                    Provider         = "steam"
                    Title            = [string]$info.Name
                    Id               = $aid
                    Version          = [string]$info.BuildId
                    Source           = "steam"
                    Kind             = "Library"
                    IsInstalled      = $true
                    InstalledVersion = if (-not [string]::IsNullOrWhiteSpace([string]$info.BuildId) -and [string]$info.BuildId -ne "0") { "Build " + [string]$info.BuildId } else { "Installed" }
                })
        }
    }
}
catch {
    Write-GuiLog "Steam library enumeration failed: $($_.Exception.Message)"
}

$script:WmtSteamLibraryCache = $result.ToArray()

# Write to cache file.
try {
    $cacheFile = Join-Path (Get-DataPath) "steam_library.json"
    if ($result.Count -gt 0 -or -not (Test-Path -LiteralPath $cacheFile -PathType Leaf)) {
        Set-WmtJsonCacheFile -Path $cacheFile -InputObject $script:WmtSteamLibraryCache -Depth 3
    }
    else {
        Write-GuiLog "Steam library refresh returned no games; keeping the existing cache."
    }
}
catch {
    Write-GuiLog "Failed to write Steam library cache: $($_.Exception.Message)"
}

return $script:WmtSteamLibraryCache
}

function Get-WmtSteamAppList {
# Downloads the Steam app ID list (games + DLC) from a GitHub-hosted
# mirror and caches it to steam_applist.json with a 7-day expiry.
# This is a single download (~25MB total) that contains every Steam
# app ID + name, much faster than per-app API calls.
param([switch]$Force)

$cacheFile = Join-Path (Get-DataPath) "steam_applist.json"
$appNames = @{}

# Load existing cache if not forcing refresh.
if (-not $Force -and (Test-Path -LiteralPath $cacheFile -PathType Leaf)) {
    try {
        $age = (Get-Date) - (Get-Item -LiteralPath $cacheFile).LastWriteTime
        if ($age.TotalDays -lt 7) {
            $cacheText = [System.IO.File]::ReadAllText($cacheFile)
            $cache = $cacheText | ConvertFrom-Json -ErrorAction Stop
            if ($cache) {
                foreach ($entry in @($cache)) {
                    $aid = [string]$entry.appid
                    $aname = [string]$entry.name
                    if (-not [string]::IsNullOrWhiteSpace($aid) -and -not [string]::IsNullOrWhiteSpace($aname)) {
                        $appNames[$aid] = $aname
                    }
                }
            }
            return $appNames
        }
    }
    catch {}
}

# Download from GitHub.
try {
    try {
        $wmtTlsProtocols = [Net.ServicePointManager]::SecurityProtocol
        if ([int]$wmtTlsProtocols -ne 0) {
            [Net.ServicePointManager]::SecurityProtocol = $wmtTlsProtocols -bor [Net.SecurityProtocolType]::Tls12
        }
    }
    catch {}
    Write-GuiLog "Downloading Steam app ID list..."

    $gamesUrl = "https://raw.githubusercontent.com/jsnli/steamappidlist/master/data/games_appid.json"
    $dlcUrl = "https://raw.githubusercontent.com/jsnli/steamappidlist/master/data/dlc_appid.json"

    $gamesResp = Invoke-RestMethod -Uri $gamesUrl -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop
    $dlcResp = Invoke-RestMethod -Uri $dlcUrl -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop

    $allApps = [System.Collections.Generic.List[object]]::new()
    if ($gamesResp) {
        foreach ($e in @($gamesResp)) {
            $ea = [string]$e.appid
            $en = [string]$e.name
            if (-not [string]::IsNullOrWhiteSpace($ea) -and -not [string]::IsNullOrWhiteSpace($en)) {
                $appNames[$ea] = $en
                [void]$allApps.Add([PSCustomObject]@{ appid = $ea; name = $en })
            }
        }
    }
    if ($dlcResp) {
        foreach ($e in @($dlcResp)) {
            $ea = [string]$e.appid
            $en = [string]$e.name
            if (-not [string]::IsNullOrWhiteSpace($ea) -and -not [string]::IsNullOrWhiteSpace($en) -and -not $appNames.ContainsKey($ea)) {
                $appNames[$ea] = $en
                [void]$allApps.Add([PSCustomObject]@{ appid = $ea; name = $en })
            }
        }
    }

    # Save only a useful refresh over an existing cache. If this is the first
    # fetch, an empty cache is still allowed so callers have a valid JSON file.
    $allAppsArray = $allApps.ToArray()
    if ($allAppsArray.Count -gt 0 -or -not (Test-Path -LiteralPath $cacheFile -PathType Leaf)) {
        Set-WmtJsonCacheFile -Path $cacheFile -InputObject $allAppsArray -Depth 1
        Write-GuiLog "Steam app list cached: $($appNames.Count) apps."
    }
    else {
        Write-GuiLog "Steam app list refresh returned no apps; keeping the existing cache."
    }
}
catch {
    Write-GuiLog "Steam app list download failed: $($_.Exception.Message)"
}

return $appNames
}

function Clear-WmtLibraryCaches {
$script:WmtLegendaryLibraryCache = $null
$script:WmtGogLibraryCache = $null
$script:WmtSteamLibraryCache = $null
try {
    $dataPath = Get-DataPath
    $legFile = Join-Path $dataPath "legendary_library.json"
    $gogFile = Join-Path $dataPath "gog_library.json"
    $steamFile = Join-Path $dataPath "steam_library.json"
    $steamAppFile = Join-Path $dataPath "steam_applist.json"
    if (Test-Path -LiteralPath $legFile) { Remove-Item -LiteralPath $legFile -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $gogFile) { Remove-Item -LiteralPath $gogFile -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $steamFile) { Remove-Item -LiteralPath $steamFile -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $steamAppFile) { Remove-Item -LiteralPath $steamAppFile -Force -ErrorAction SilentlyContinue }
}
catch {}
}

# ==========================================
# Catalog search helpers (per-provider)
# ==========================================

function Invoke-WmtSearchProcess {
param(
    [string]$FilePath,
    [string]$Arguments,
    [int]$TimeoutMs = 15000
)
try {
    $result = Invoke-WmtProcess -FilePath $FilePath -Arguments $Arguments -TimeoutMs $TimeoutMs -Encoding UTF8 -KillTree
    return [string]$result.StdOut
}
catch { return "" }
}

function Get-WmtScoopSearch {
param([string]$Query, [int]$TimeoutSeconds = 15)
$result = New-Object System.Collections.Generic.List[object]
$exe = Get-Command scoop -ErrorAction SilentlyContinue
if (-not $exe) { return $result.ToArray() }
$stdout = Invoke-WmtSearchProcess -FilePath "powershell.exe" -Arguments "-NoProfile -Command scoop search `"$Query`"" -TimeoutMs ($TimeoutSeconds * 1000)
$inResults = $false
foreach ($line in $stdout -split "`r?`n") {
    $line = $line.Trim()
    if ($line -match "^Name\s") { $inResults = $true; continue }
    if (-not $inResults) { continue }
    if ($line -match "^-+") { continue }
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    $cols = $line -split '\s{2,}|\t'
    if ($cols.Count -ge 2) {
        $result.Add([PSCustomObject]@{ Provider = "scoop"; Title = $cols[0]; Id = $cols[0]; Version = if ($cols.Count -ge 2) { $cols[1] } else { "" }; Source = "Scoop"; Kind = "Catalog" })
    }
}
return $result.ToArray()
}

function Get-WmtCargoSearch {
param([string]$Query, [int]$TimeoutSeconds = 15)
$result = New-Object System.Collections.Generic.List[object]
$exe = Get-Command cargo -ErrorAction SilentlyContinue
if (-not $exe) { return $result.ToArray() }
$stdout = Invoke-WmtSearchProcess -FilePath $exe.Source -Arguments "search `"$Query`"" -TimeoutMs ($TimeoutSeconds * 1000)
foreach ($line in $stdout -split "`r?`n") {
    $line = $line.Trim()
    if ($line -match '^(?<name>\S+)\s*=\s*"(?<version>[^"]*)"') {
        $result.Add([PSCustomObject]@{ Provider = "cargo"; Title = $matches["name"]; Id = $matches["name"]; Version = $matches["version"]; Source = "crates.io"; Kind = "Catalog" })
    }
}
return $result.ToArray()
}

function Get-WmtGemSearch {
param([string]$Query, [int]$TimeoutSeconds = 20)
$result = New-Object System.Collections.Generic.List[object]
$exe = Get-Command gem -ErrorAction SilentlyContinue
if (-not $exe) { return $result.ToArray() }
$stdout = Invoke-WmtSearchProcess -FilePath $exe.Source -Arguments "search `"$Query`" --remote" -TimeoutMs ($TimeoutSeconds * 1000)
foreach ($line in $stdout -split "`r?`n") {
    $line = $line.Trim()
    if ($line -match '^(?<name>\S+)\s+\((?<version>[^)]+)\)') {
        $result.Add([PSCustomObject]@{ Provider = "gem"; Title = $matches["name"]; Id = $matches["name"]; Version = $matches["version"]; Source = "RubyGems"; Kind = "Catalog" })
    }
}
return $result.ToArray()
}

function Get-WmtSteamSearch {
param([string]$Query, [int]$TimeoutSeconds = 15)
$result = New-Object System.Collections.Generic.List[object]
if ([string]::IsNullOrWhiteSpace($Query)) { return $result.ToArray() }
try {
    try {
        $wmtTlsProtocols = [Net.ServicePointManager]::SecurityProtocol
        if ([int]$wmtTlsProtocols -ne 0) {
            [Net.ServicePointManager]::SecurityProtocol = $wmtTlsProtocols -bor [Net.SecurityProtocolType]::Tls12
        }
    }
    catch {}
    $encoded = [Uri]::EscapeDataString($Query)
    $url = "https://store.steampowered.com/api/storesearch/?term=$encoded&l=english&cc=US"
    $resp = Invoke-RestMethod -Uri $url -UseBasicParsing -TimeoutSec $TimeoutSeconds -ErrorAction Stop
    if ($resp -and $resp.total -gt 0) {
        foreach ($item in @($resp.items)) {
            $result.Add([PSCustomObject]@{ Provider = "steam"; Title = [string]$item.name; Id = [string]$item.id; Version = ""; Source = "Steam Store"; Kind = "Catalog" })
        }
    }
}
catch {}
return $result.ToArray()
}

function Get-WmtProviderCatalogSearch {
param([string]$ProviderKey, [string]$Query, [int]$TimeoutSeconds = 15)

$key = ([string]$ProviderKey).Trim().ToLowerInvariant()
$query = ([string]$Query).Trim()
if ([string]::IsNullOrWhiteSpace($query)) { return @() }

switch ($key) {
    "scoop" { return @(Get-WmtScoopSearch -Query $query -TimeoutSeconds $TimeoutSeconds) }
    "cargo" { return @(Get-WmtCargoSearch -Query $query -TimeoutSeconds $TimeoutSeconds) }
    "gem" { return @(Get-WmtGemSearch -Query $query -TimeoutSeconds $TimeoutSeconds) }
    "steam" { return @(Get-WmtSteamSearch -Query $query -TimeoutSeconds $TimeoutSeconds) }
    default { return @() }
}
}

# ==========================================
# Windows Update category toggle helpers
# ==========================================

function Get-WmtWuCategoryToggles {
param($Settings)
if (-not $Settings) { $Settings = Get-WmtSettings }
$defaults = [ordered]@{
    Updates  = $true
    Optional = $true
    Driver   = $true
    Security = $true
    Insider  = $false
}
try {
    $raw = $null
    if ($Settings -is [System.Collections.IDictionary]) {
        if ($Settings.Contains("WuCategoryToggles")) { $raw = $Settings["WuCategoryToggles"] }
    }
    else {
        try { if ($Settings.PSObject.Properties["WuCategoryToggles"]) { $raw = $Settings.WuCategoryToggles } } catch {}
    }
    if ($raw) {
        foreach ($prop in @($raw.PSObject.Properties)) {
            $k = ([string]$prop.Name).Trim()
            if ($defaults.Contains($k)) { $defaults[$k] = [bool]$prop.Value }
        }
    }
}
catch {}
return $defaults
}

function Set-WmtWuCategoryToggles {
param($Toggles)
$settings = Get-WmtSettings
if ($settings -is [System.Collections.IDictionary]) {
    $settings["WuCategoryToggles"] = $Toggles
}
elseif ($settings.PSObject.Properties["WuCategoryToggles"]) {
    $settings.WuCategoryToggles = $Toggles
}
else {
    $settings | Add-Member -MemberType NoteProperty -Name "WuCategoryToggles" -Value $Toggles -Force
}
Save-WmtSettings -Settings $settings
}

function Update-WmtProviderPathEnvironment {
    try {
        $machinePath = [Environment]::GetEnvironmentVariable("Path", "Machine")
        $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
        $pathParts = New-Object System.Collections.Generic.List[string]
        $seenPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($pathValue in @($machinePath, $userPath, $env:Path)) {
            foreach ($part in @(([string]$pathValue) -split ";")) {
                $trimmed = $part.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trimmed) -and $seenPaths.Add($trimmed)) {
                    [void]$pathParts.Add($trimmed)
                }
            }
        }
        $env:Path = $pathParts -join ";"
    }
    catch {}
}

function Show-ProviderManager {
# 1. Load Current Settings
$settings = Get-WmtSettings
if (-not $settings.EnabledProviders) {
    $settings | Add-Member -MemberType NoteProperty -Name "EnabledProviders" -Value @("winget", "msstore", "windowsupdate", "pip", "npm", "pnpm", "dotnet", "psmodule", "composer", "chocolatey", "scoop", "gem", "cargo", "steam", "legendary", "gogdl") -Force
}
$enabled = $settings.EnabledProviders
$providerToggles = Get-WmtProviderToggles -Settings $settings
$providerCapabilities = Get-WmtProviderCapabilities

# 2. Provider definitions are needed BEFORE building the XAML so we can
# generate per-provider rows that include the Search/Scan/Headless/AutoUpdate toggles.
$providerDefinitions = @(
    [PSCustomObject]@{ Key = "winget"; DisplayName = "Winget"; Commands = [string[]]@("winget"); Label = "lblProviderWingetStatus"; Button = "btnProviderWingetAction"; LockedOn = $true; ToolTip = "Windows Package Manager" },
    [PSCustomObject]@{ Key = "msstore"; DisplayName = "Store CLI"; Commands = [string[]]@("store"); Label = "lblProviderMsStoreStatus"; Button = "btnProviderMsStoreAction"; LockedOn = $false; ToolTip = "Microsoft Store Apps via store.exe" },
    [PSCustomObject]@{ Key = "windowsupdate"; DisplayName = "Windows Update"; Commands = [string[]]@("powershell"); Label = "lblWindowsUpdateStatus"; Button = "btnProviderWindowsUpdateAction"; LockedOn = $false; ToolTip = "Windows Update Agent. Scans both regular and optional Windows updates, including drivers when offered." },
    [PSCustomObject]@{ Key = "pip"; DisplayName = "Python (Pip)"; Commands = [string[]]@("pip", "pip3"); Label = "lblPipStatus"; Button = "btnProviderPipAction"; LockedOn = $false; ToolTip = "Python package manager" },
    [PSCustomObject]@{ Key = "npm"; DisplayName = "Node (Npm)"; Commands = [string[]]@("npm"); Label = "lblNpmStatus"; Button = "btnProviderNpmAction"; LockedOn = $false; ToolTip = "Node.js package manager" },
    [PSCustomObject]@{ Key = "pnpm"; DisplayName = "pnpm"; Commands = [string[]]@("pnpm"); Label = "lblPnpmStatus"; Button = "btnProviderPnpmAction"; LockedOn = $false; ToolTip = "Fast Node.js package manager" },
    [PSCustomObject]@{ Key = "chocolatey"; DisplayName = "Chocolatey"; Commands = [string[]]@("choco"); Label = "lblChocoStatus"; Button = "btnProviderChocoAction"; LockedOn = $false; ToolTip = "Chocolatey package manager" },
    [PSCustomObject]@{ Key = "scoop"; DisplayName = "Scoop"; Commands = [string[]]@("scoop"); Label = "lblScoopStatus"; Button = "btnProviderScoopAction"; LockedOn = $false; ToolTip = "Scoop command-line installer" },
    [PSCustomObject]@{ Key = "gem"; DisplayName = "Ruby (Gem)"; Commands = [string[]]@("gem"); Label = "lblGemStatus"; Button = "btnProviderGemAction"; LockedOn = $false; ToolTip = "RubyGems package manager" },
    [PSCustomObject]@{ Key = "cargo"; DisplayName = "Rust (Cargo)"; Commands = [string[]]@("cargo"); Label = "lblCargoStatus"; Button = "btnProviderCargoAction"; LockedOn = $false; ToolTip = "Rust package manager" },
    [PSCustomObject]@{ Key = "dotnet"; DisplayName = ".NET Tools"; Commands = [string[]]@("dotnet"); Label = "lblDotnetStatus"; Button = "btnProviderDotnetAction"; LockedOn = $false; ToolTip = ".NET global tools installed with dotnet tool install -g" },
    [PSCustomObject]@{ Key = "psmodule"; DisplayName = "PS Modules"; Commands = [string[]]@("powershell", "pwsh"); Label = "lblPsModuleStatus"; Button = "btnProviderPsModuleAction"; LockedOn = $false; ToolTip = "PowerShell modules installed from PSGallery with PowerShellGet" },
    [PSCustomObject]@{ Key = "composer"; DisplayName = "Composer"; Commands = [string[]]@("composer"); Label = "lblComposerStatus"; Button = "btnProviderComposerAction"; LockedOn = $false; ToolTip = "PHP Composer global packages" },
    [PSCustomObject]@{ Key = "steam"; DisplayName = "Steam Games"; Commands = [string[]]@("steam", "steam.exe"); RegistryPaths = [string[]]@("HKCU:\Software\Valve\Steam", "HKLM:\SOFTWARE\WOW6432Node\Valve\Steam", "HKLM:\SOFTWARE\Valve\Steam"); Label = "lblSteamStatus"; Button = "btnProviderSteamAction"; LockedOn = $false; ToolTip = "Steam game updates detected from local Steam manifests. Updates are delegated to Steam Downloads." },
    [PSCustomObject]@{ Key = "legendary"; DisplayName = "Legendary"; Commands = [string[]]@("legendary", "legendary.exe"); LocalPaths = [string[]]@(Get-WmtLegendaryExePath); Label = "lblLegendaryStatus"; Button = "btnProviderLegendaryAction"; LockedOn = $false; ToolTip = "Legendary CLI for Epic Games Store game updates." },
    [PSCustomObject]@{ Key = "gogdl"; DisplayName = "GOGDL"; Commands = [string[]]@("gogdl", "gogdl.exe", "gogdl_windows_x86_64.exe"); LocalPaths = [string[]]@(Get-WmtGogdlExePath); Label = "lblGogdlStatus"; Button = "btnProviderGogdlAction"; LockedOn = $false; ToolTip = "GOGDL updates installed GOG games through Heroic's gogdl downloader." }
)

function Format-WmtProviderRowXaml {
    param($Provider)

    $key = [string]$Provider.Key
    $name = [string]$Provider.DisplayName
    $tip = [string]$Provider.ToolTip
    $locked = [bool]$Provider.LockedOn
    $caps = $providerCapabilities[$key]
    $searchSupported = [bool]$caps.Search

    $chkAttr = if ($locked) { 'IsChecked="True" IsEnabled="False"' } else { '' }
    $searchEnabled = if ($searchSupported) { 'True' } else { 'False' }
    $t = $providerToggles[$key]
    $searchVal = if ($t -is [System.Collections.IDictionary]) { $t["Search"] } else { $t.Search }
    $scanVal = if ($t -is [System.Collections.IDictionary]) { $t["Scan"] } else { $t.Scan }
    $logsVal = if ($t -is [System.Collections.IDictionary]) { $t["Logs"] } else { $t.Logs }
    $headVal = Get-WmtEffectiveProviderHeadless -Settings $settings -ProviderKey $key
    $autoVal = Get-WmtEffectiveProviderAutoUpdate -Settings $settings -ProviderKey $key
    $searchIsChecked = if ($searchSupported -and [bool]$searchVal) { 'True' } else { 'False' }
    $scanIsChecked = if ([bool]$scanVal) { 'True' } else { 'False' }
    $logsIsChecked = if ([bool]$logsVal) { 'True' } else { 'False' }
    $headlessIsChecked = if ([bool]$headVal) { 'True' } else { 'False' }
    $autoIsChecked = if ([bool]$autoVal) { 'True' } else { 'False' }

    $searchToolTip = if ($searchSupported) {
        "Allow searching this provider's catalog or owned library from the WMT search box."
    }
    else {
        "This provider does not expose a search capability."
    }

    # Winget gets a 5th toggle: "Include unknown" (--include-unknown flag).
    $includeUnknownToggle = ""
    if ($key -eq "winget") {
        $includeUnknownToggle = '<ToggleButton Name="chkIncludeUnknown" Content="Include unknown" Margin="0,0,8,0" Padding="10,3" MinWidth="80" ToolTip="Adds --include-unknown to winget scans. Only applies when Winget is enabled."/>'
    }

    # Windows Update gets an extra row of category toggle buttons.
    $wuCategorySection = ""
    if ($key -eq "windowsupdate") {
        $wuCategorySection = @"
                <StackPanel Orientation="Horizontal" Margin="30,6,0,0">
                    <TextBlock Text="Categories:" FontWeight="SemiBold" Margin="0,0,8,0" VerticalAlignment="Center"/>
                    <ToggleButton Name="btnWuCatUpdates" Content="Updates" Margin="0,0,8,0" Padding="10,3" MinWidth="60" ToolTip="Regular Windows updates (important and recommended)"/>
                    <ToggleButton Name="btnWuCatOptional" Content="Optional" Margin="0,0,8,0" Padding="10,3" MinWidth="60" ToolTip="Optional updates that are not automatically installed"/>
                    <ToggleButton Name="btnWuCatDriver" Content="Driver" Margin="0,0,8,0" Padding="10,3" MinWidth="60" ToolTip="Driver updates from Windows Update"/>
                    <ToggleButton Name="btnWuCatSecurity" Content="Security" Margin="0,0,8,0" Padding="10,3" MinWidth="60" ToolTip="Security updates (Critical, Important, Moderate severity)"/>
                    <ToggleButton Name="btnWuCatInsider" Content="Insider" Margin="0,0,8,0" Padding="10,3" MinWidth="60" ToolTip="Insider Preview, beta, dev channel, and canary builds"/>
                </StackPanel>
"@
    }

    $row = @"
        <Border Background="{DynamicResource BgElevated}" BorderThickness="0" CornerRadius="8" Padding="10" Margin="0,0,0,10" ToolTip="$tip">
            <StackPanel>
                <Grid>
                    <Grid.ColumnDefinitions><ColumnDefinition Width="30"/><ColumnDefinition Width="130"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                    <CheckBox Name="chk$key" $chkAttr Grid.Column="0" VerticalAlignment="Center"/>
                    <TextBlock Name="lbl${key}Name" Text="$name" FontWeight="Bold" Grid.Column="1" VerticalAlignment="Center"/>
                    <TextBlock Name="$($Provider.Label)" Text="Checking..." Grid.Column="2" VerticalAlignment="Center"/>
                    <Button Name="$($Provider.Button)" Content="Install" Width="78" Height="26" Grid.Column="3" Margin="8,0,0,0"/>
                </Grid>
                <StackPanel Orientation="Horizontal" Margin="30,6,0,0">
                    <ToggleButton Name="chk${key}Search"     Content="Search"     Margin="0,0,8,0" Padding="10,3" MinWidth="60" IsChecked="$searchIsChecked"    IsEnabled="$searchEnabled" ToolTip="$searchToolTip"/>
                    <ToggleButton Name="chk${key}Scan"       Content="Scan"       Margin="0,0,8,0" Padding="10,3" MinWidth="60" IsChecked="$scanIsChecked"       ToolTip="Include this provider in update scans. Disabling also disables Headless and Auto-update for this provider."/>
                    <ToggleButton Name="chk${key}Logs"       Content="Log files"  Margin="0,0,8,0" Padding="10,3" MinWidth="68" IsChecked="$logsIsChecked"       ToolTip="Allow WMT to request and keep persistent diagnostic/install log files for this provider. On-screen Activity Log messages are unaffected; providers may still keep mandatory internal logs."/>
                    <ToggleButton Name="chk${key}Headless"   Content="Headless: inherit"   Margin="0,0,8,0" Padding="10,3" MinWidth="112" IsThreeState="True" IsChecked="$headlessIsChecked"   ToolTip="Three-state setting: On = force headless, Off = force interactive, inherit = use the global Headless setting. Requires Scan."/>
                    <ToggleButton Name="chk${key}AutoUpdate" Content="Auto-update: inherit" Margin="0,0,8,0" Padding="10,3" MinWidth="126" IsThreeState="True" IsChecked="$autoIsChecked"       ToolTip="Three-state setting: On = force auto-update, Off = disable it, inherit = use the global Auto-install setting. Requires Scan."/>
                    $includeUnknownToggle
                </StackPanel>
                $wuCategorySection
            </StackPanel>
        </Border>
"@
    return $row
}

$providerRowsXaml = ""
foreach ($p in $providerDefinitions) {
    $providerRowsXaml += (Format-WmtProviderRowXaml -Provider $p) + "`r`n"
}

# 3. Define UI
[xml]$pXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    Title="Package Manager Settings" Height="860" Width="760" WindowStartupLocation="CenterScreen" ResizeMode="NoResize"
    Background="{DynamicResource BgDark}" Foreground="{DynamicResource TextPrimary}">
<Window.Resources>
    <Style TargetType="TextBlock"><Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/><Setter Property="VerticalAlignment" Value="Center"/></Style>
    <Style TargetType="CheckBox">
        <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Setter Property="Margin" Value="0,0,10,0"/>
        <Style.Triggers>
            <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.35"/>
                <Setter Property="TextBlock.TextDecorations" Value="Strikethrough"/>
            </Trigger>
        </Style.Triggers>
    </Style>
    <Style TargetType="Button">
        <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
        <Setter Property="Background" Value="{DynamicResource BgElevated}"/>
        <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="Padding" Value="12,0"/>
    </Style>
    <Style TargetType="TextBox">
        <Setter Property="Foreground" Value="#111827"/>
        <Setter Property="Background" Value="#FFFFFF"/>
        <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
        <Setter Property="Padding" Value="6,4"/>
    </Style>
    <Style TargetType="ListBox">
        <Setter Property="Foreground" Value="{DynamicResource TextPrimary}"/>
        <Setter Property="Background" Value="{DynamicResource BgDark}"/>
        <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
    </Style>
</Window.Resources>
<Grid Margin="20">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>

    <StackPanel Grid.Row="0">
        <TextBlock Text="Manage Package Providers" FontSize="18" FontWeight="Bold" Margin="0,0,0,4"/>
        <TextBlock Text="Select which package managers to scan, and configure per-provider Search / Scan / Log files / Headless / Auto-update options. The Log files setting controls persistent provider diagnostics; on-screen Activity Log messages remain available." Foreground="{DynamicResource TextSecondary}" Margin="0,0,0,0" TextWrapping="Wrap"/>
    </StackPanel>

    <ScrollViewer Grid.Row="1" Margin="0,12,0,0" VerticalScrollBarVisibility="Auto">
        <StackPanel>
        <Border Background="{DynamicResource BgElevated}" BorderThickness="0" CornerRadius="10" Padding="12" Margin="0,0,0,14"
                ToolTip="Configure automatic update scans, installation behavior, and background operation.">
            <Grid>
                <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                <Grid.ColumnDefinitions><ColumnDefinition Width="150"/><ColumnDefinition Width="220"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                <TextBlock Text="Auto scan" FontWeight="Bold" Grid.Row="0" Grid.Column="0"/>
                <ComboBox Name="cmbAutoScanInterval" Grid.Row="0" Grid.Column="1" Height="28" Width="210" HorizontalAlignment="Left" SelectedValuePath="Tag">
                    <ComboBoxItem Content="Disabled" Tag="0"/>
                    <ComboBoxItem Content="Every 1 minute (test)" Tag="1"/>
                    <ComboBoxItem Content="Every 15 minutes" Tag="15"/>
                    <ComboBoxItem Content="Every 30 minutes" Tag="30"/>
                    <ComboBoxItem Content="Every 1 hour" Tag="60"/>
                    <ComboBoxItem Content="Every 2 hours" Tag="120"/>
                    <ComboBoxItem Content="Every 4 hours" Tag="240"/>
                    <ComboBoxItem Content="Every 8 hours" Tag="480"/>
                    <ComboBoxItem Content="Every 12 hours" Tag="720"/>
                    <ComboBoxItem Content="Every day" Tag="1440"/>
                </ComboBox>
                <CheckBox Name="chkUpdateNotifications" Grid.Row="0" Grid.Column="2" Content="Native notifications" Margin="12,0,0,0"
                          ToolTip="Show a Windows notification when an automatic background scan finds updates or fails."/>
                <CheckBox Name="chkRunInTrayOnClose" Grid.Row="1" Grid.Column="0" Grid.ColumnSpan="3" Content="Run in system tray when closed" Margin="0,8,0,0"
                          ToolTip="When enabled, closing the main window hides WMT to the system tray so background scans and notifications can continue."/>
                <CheckBox Name="chkReduceRamInTray" Grid.Row="2" Grid.Column="0" Grid.ColumnSpan="3" Content="Reduce RAM while hidden in tray" Margin="0,8,0,0"
                          ToolTip="Aggressive low-memory tray mode. While hidden, WMT cancels UI-only preload work, unloads reloadable page data, releases idle PowerShell runspaces, compacts managed memory, and re-trims after background jobs finish. Scheduled updates/cleaning remain available; UI data reloads on demand when reopened."/>
                <CheckBox Name="chkUpdateSilentInstall" Grid.Row="3" Grid.Column="0" Grid.ColumnSpan="3" Content="Run update/install commands headless. ⚠ Experimental!" Margin="0,8,0,0"
                          ToolTip="Hide CLI, PowerShell, and cmd update windows. Providers that require their own GUI, including Steam validation and Microsoft Store GUI updates, can still appear."/>
                <CheckBox Name="chkUpdateAutoInstall" Grid.Row="4" Grid.Column="0" Grid.ColumnSpan="3" Content="Automatically install available updates after scans" Margin="0,8,0,0"
                          ToolTip="After each completed scan, automatically update listed packages without confirmation. Packages known to risk an automatic restart are skipped."/>
                <TextBlock Grid.Row="5" Grid.Column="0" Grid.ColumnSpan="3" Margin="0,8,0,0"
                           Text="When update scans and background jobs are enabled, WMT scans once on launch even if the auto-scan interval is disabled. Scheduled scans run while open or hidden in the tray. Auto install may run after completed scans; restart-risk packages are skipped. Per-provider Headless / Auto-update options above override these global settings."
                           Foreground="{DynamicResource TextSecondary}" FontStyle="Italic" TextWrapping="Wrap"/>
            </Grid>
        </Border>

        $providerRowsXaml
        </StackPanel>
    </ScrollViewer>

    <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right">
        <Button Name="btnSave" Content="Save &amp; Close" Background="{DynamicResource Accent}" Width="120" Height="30" Foreground="{DynamicResource AccentText}"/>
    </StackPanel>
</Grid>
</Window>
"@
$win = New-WmtWindowFromFullXaml -Xaml $pXaml

function Get-WinCtrl($name) { $win.FindName($name) }

$cmbAutoScanInterval = Get-WinCtrl "cmbAutoScanInterval"
$chkUpdateNotifications = Get-WinCtrl "chkUpdateNotifications"
$chkRunInTrayOnClose = Get-WinCtrl "chkRunInTrayOnClose"
$chkReduceRamInTray = Get-WinCtrl "chkReduceRamInTray"
$chkUpdateSilentInstall = Get-WinCtrl "chkUpdateSilentInstall"
$chkUpdateAutoInstall = Get-WinCtrl "chkUpdateAutoInstall"
$chkIncludeUnknown = Get-WinCtrl "chkIncludeUnknown"
$btnWuCatUpdates = Get-WinCtrl "btnWuCatUpdates"
$btnWuCatOptional = Get-WinCtrl "btnWuCatOptional"
$btnWuCatDriver = Get-WinCtrl "btnWuCatDriver"
$btnWuCatSecurity = Get-WinCtrl "btnWuCatSecurity"
$btnWuCatInsider = Get-WinCtrl "btnWuCatInsider"

# Map provider key -> checkbox control objects (filled in below per provider).
$providerControls = @{}

$providerInstallState = @{}
if (-not $script:WmtProviderActionMonitors) { $script:WmtProviderActionMonitors = @{} }
$providerActionMonitors = $script:WmtProviderActionMonitors
if (-not $script:WmtProviderActionLastStatus) { $script:WmtProviderActionLastStatus = @{} }
$providerActionStatusCache = $script:WmtProviderActionLastStatus


function Get-WmtProviderActionScript {
    param(
        [string]$ProviderKey,
        [string]$Action
    )

    $installing = ($Action -eq "Install")
    $body = switch ($ProviderKey) {
        "winget" {
            if ($installing) {
                @'
Write-Host "Registering App Installer for winget..."
try {
Add-AppxPackage -RegisterByFamilyName -MainPackage Microsoft.DesktopAppInstaller_8wekyb3d8bbwe -ErrorAction Stop
}
catch {
Write-Warning $_.Exception.Message
}
if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
Start-Process "ms-windows-store://pdp/?ProductId=9NBLGGH4NNS1"
throw "Winget is still not available. App Installer was opened in Microsoft Store."
}
winget source reset --force
winget source update
winget --version
'@
            }
            else {
                @'
if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw "Winget was not found." }
winget source reset --force
winget source update
winget upgrade --id Microsoft.AppInstaller --accept-source-agreements --accept-package-agreements --disable-interactivity
winget --version
'@
            }
            break
        }
        "msstore" {
            @'
Write-Host "Opening Microsoft Store Updates..."
try {
$appManagement = Get-CimInstance -Namespace "Root\cimv2\mdm\dmmap" -ClassName "MDM_EnterpriseModernAppManagement_AppManagement01" -ErrorAction Stop | Select-Object -First 1
if ($appManagement) {
    [void](Invoke-CimMethod -InputObject $appManagement -MethodName "UpdateScanMethod" -ErrorAction Stop)
    Write-Host "Requested a Microsoft Store app update scan."
}
}
catch {
Write-Warning "Direct Store update scan failed: $($_.Exception.Message)"
}
Start-Process "ms-windows-store://downloadsandupdates"
if (Get-Command store -ErrorAction SilentlyContinue) {
store --help
}
else {
Write-Host "Update Microsoft Store from the opened Store updates page, then reopen WMT."
}
'@
            break
        }
        "windowsupdate" {
            @'
Write-Host "Opening Windows Update optional updates..."
try {
Start-Process "ms-settings:windowsupdate-optionalupdates"
}
catch {
Write-Warning "Optional updates page failed: $($_.Exception.Message)"
Start-Process "ms-settings:windowsupdate"
}
Write-Host "Windows Update is built into Windows. WMT will scan it through Microsoft.Update.Session when the provider is enabled."
'@
            break
        }
        "pip" {
            if ($installing) {
                @'
if (-not (Get-Command python -ErrorAction SilentlyContinue) -and -not (Get-Command py -ErrorAction SilentlyContinue)) {
if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw "Python install needs winget or an existing Python launcher." }
$pythonIds = @("Python.Python.3.13", "Python.Python.3.12", "Python.Python.3.11")
$installedPython = $false
foreach ($pythonId in $pythonIds) {
    Write-Host "Trying $pythonId..."
    winget install --id $pythonId --exact --accept-source-agreements --accept-package-agreements --disable-interactivity
    if ($LASTEXITCODE -eq 0) { $installedPython = $true; break }
}
if (-not $installedPython) { throw "Could not install Python with winget." }
Update-WmtProviderPathEnvironment
}
if (Get-Command py -ErrorAction SilentlyContinue) {
py -3 -m ensurepip --upgrade
py -3 -m pip install --upgrade pip setuptools wheel
py -3 -m pip --version
}
elseif (Get-Command python -ErrorAction SilentlyContinue) {
python -m ensurepip --upgrade
python -m pip install --upgrade pip setuptools wheel
python -m pip --version
}
else {
throw "Python was installed, but the launcher is not visible in this session yet. Open a new terminal and retry."
}
'@
            }
            else {
                @'
if (Get-Command py -ErrorAction SilentlyContinue) {
py -3 -m ensurepip --upgrade
py -3 -m pip install --upgrade pip setuptools wheel
py -3 -m pip --version
}
elseif (Get-Command python -ErrorAction SilentlyContinue) {
python -m ensurepip --upgrade
python -m pip install --upgrade pip setuptools wheel
python -m pip --version
}
else {
throw "Python was not found."
}
'@
            }
            break
        }
        "npm" {
            if ($installing) {
                @'
if (-not (Get-Command npm -ErrorAction SilentlyContinue)) {
if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw "Node.js install needs winget." }
winget install --id OpenJS.NodeJS.LTS --exact --accept-source-agreements --accept-package-agreements --disable-interactivity
Update-WmtProviderPathEnvironment
}
if (Get-Command npm -ErrorAction SilentlyContinue) {
npm install -g npm@latest
npm --version
