`$tokenUrl     = "https://auth.gog.com/token"

Write-Host "WMT: GOG Authentication" -ForegroundColor Cyan
Write-Host ""
Write-Host "Step 1: Opening GOG login page in your browser..." -ForegroundColor Yellow
