Write-Host ""

`$redirected = ""
while ([string]::IsNullOrWhiteSpace(`$redirected)) {
`$redirected = (Read-Host "Paste redirect URL").Trim()
if ([string]::IsNullOrWhiteSpace(`$redirected)) { Write-Warning "Please paste the full redirect URL from your browser." }
}

