    Initialize-FirewallRuleDetails -Rule $rule -Synchronous

    # 1. Open existing dialog with the selected rule
    $result = Show-RuleDialog "Edit Firewall Rule" $rule

    # 2. If user clicked 'Save' (result is not null)
